// بيانات السور
Object.assign(quranData, {
    19: { // سورة مريم
        name: "مريم",
        basmalaTafsir: ``,
        verses: [
            { text: "كٓهيعٓصٓ", tafsir: `أي أن « كاف » « هاء » « ياء » « عين » « صاد » هي التي يركب منها هذا القرآن ، فإن القرآن مركب من هذه الحروف وأمثالها ، وهنا حذف الخبر ، بخلاف مثل ( الم ، ذلِكَ الْكِتابُ ) وقد عرفت أن في فواتح السور أقوالا وما ذكرناه أحدها ، وهناك قول آخر أنها رموز ولا تنافي بين القولين ولا بين سائر الأقوال ، و قد ورد أن « كاف » اسم كربلاء و « هاء » هلاك العترة و « ياء » يزيد و « عين » عطش الآل عليهم‌السلام و « صاد » صبرهم (1) ، فهي كالرموز اللاسلكية التي تختار لمعرفة الطرفين دون سواهم لحكمة. [3] هذا الذي نريد بيانه ( ذِكْرُ ) وخبر ( رَحْمَتِ رَبِّكَ ) ل ( عَبْدَهُ زَكَرِيَّا ) النبي عليه‌السلام والمراد برحمة الله له استجابته دعاء زكريا حين سأله الولد ، فقد تفضل عليه سبحانه بيحيى عليه‌السلام . [4] وقد كانت الرحمة ( إِذْ نادى ) حين دعا زكريا ( رَبَّهُ نِداءً خَفِيًّا ) دعاء في خفية لم يجهر به ، ولعل سر الإخفاء ، أن الناس لو علموا بأنه يطلب الولد سخروا منه ؟ ، كيف يسأل الولد وهو شيخ فان ؟ ، أم كيف بقي في نفسه بقايا من طلب الملذات ..؟` },
            { text: "ذِكْرُ رَحْمَتِ رَبِّكَ عَبْدَهُۥ زَكَرِيَّآ", tafsir: `` },
            { text: "إِذْ نَادَىٰ رَبَّهُۥ نِدَآءً خَفِيًّا", tafsir: `` },
            { text: "قَالَ رَبِّ إِنِّى وَهَنَ ٱلْعَظْمُ مِنِّى وَٱشْتَعَلَ ٱلرَّأْسُ شَيْبًا وَلَمْ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيًّا", tafsir: `زكريا في دعائه يا ( رَبِّ إِنِّي وَهَنَ الْعَظْمُ مِنِّي ) أي ضعف عظمي ، وإسناد الضعف إلى العظم ، أبلغ في الدلالة على الضعف ، إذ العظم الذي هو أصلب شيء في الجسم ، إذا ضعف ضعفت سائر ( 1) بحار الأنوار : ج 88 ص 9. وَاشْتَعَلَ الرَّأْسُ شَيْباً وَلَمْ أَكُنْ بِدُعائِكَ رَبِّ شَقِيًّا (4) وَإِنِّي خِفْتُ الْمَوالِيَ مِنْ وَرائِي وَكانَتِ امْرَأَتِي عاقِراً فَهَبْ لِي مِنْ لَدُنْكَ وَلِيًّا (5) يَرِثُنِي وَيَرِثُ مِن ْ آلِ يَعْقُوبَ الأشياء ( وَاشْتَعَلَ الرَّأْسُ شَيْباً ) فإن الشيب والبياض ، إذا ظهر في الرأس وغمرها ، كانت الرأس كالمشتعل في التلألؤ والبريق ، وهذا أبلغ ، من « اشتعل الشيب في الرأس » ( وَلَمْ أَكُنْ بِدُعائِكَ ) بدعوتي إياك فيما مضى ، يا ( رَبِّ شَقِيًّا ) مخيبا محروما ، فإنك قد عودتني الإجابة فيما مضى ، يا ( رَبِّ شَقِيًّا ) مخيبا محروما ، فإنك قد عودتني الإجابة فيما مضى ، وأنا في سن الشباب والقوة ، فلا بد أنك لا تحرمني هذا الدعاء وأنا في حال المشيب والضعف. [6] وإذ ذكر عليه‌السلام حاله المستحق للترحم ورجائه الذي عوده باريه باستجابة دعائه بين ما يخشاه وما يطلبه ( وَإِنِّي ) يا رب ( خِفْتُ الْمَوالِيَ ) جمع مولى ، وهو الأولى بالتصرف في الأموال بعد الإنسان بالإرث ، ( مِنْ وَرائِي ) أي من خلفي الذين يرثونني ، أخشاهم أن لا يعملوا ، بما يبقى لهم مني على وجه الصلاح ( وَكانَتِ امْرَأَتِي عاقِراً ) أي لا تلد ، فليس لي منها أولاد حتى يقوموا بواجب تراثي من بعدي من الصلاح والإصلاح ( فَهَبْ لِي ) يا رب ( مِنْ لَدُنْكَ ) أي من عندك ( وَلِيًّا ) ولدا يلي أموري من بعدي ، ويكون هو الأولى بميراثي.` },
            { text: "وَإِنِّى خِفْتُ ٱلْمَوَٰلِىَ مِن وَرَآءِى وَكَانَتِ ٱمْرَأَتِى عَاقِرًا فَهَبْ لِى مِن لَّدُنكَ وَلِيًّا", tafsir: `` },
            { text: "يَرِثُنِى وَيَرِثُ مِنْ ءَالِ يَعْقُوبَ وَٱجْعَلْهُ رَبِّ رَضِيًّا", tafsir: `ذلك الولي ( وَيَرِثُ مِنْ آلِ يَعْقُوبَ ) لعل ذلك باعتبار أم الولد ، أي زوجة زكريا ، فقد كانت خالة « مريم » من نسل يعقوب بن إسحاق بن إبراهيم الخليل عليهم‌السلام . ولذا كان عيسى عليه‌السلام ، من نسل وَاجْعَلْهُ رَبِّ رَضِيًّا (6) يا زَكَرِيَّا إِنَّا نُبَشِّرُكَ بِغُلامٍ اسْمُهُ يَحْيى لَمْ نَجْعَلْ لَهُ مِنْ قَبْلُ سَمِيًّا (7) قالَ رَبِّ أَنَّى يَكُونُ لِي غُلامٌ وَكانَتِ امْرَأَتِي عاقِراً وَقَدْ بَلَغْتُ مِنَ الْكِبَرِ عِتِيًّا (8) إبراهيم ، وقال « آل يعقوب » لاحترامهم بكون الأنبياء فيهم ( وَاجْعَلْهُ ) أي اجعل ذلك الولد يا ( رَبِّ رَضِيًّا ) مرضيا عندك ، ممثلا لأمرك ، فلا يكن فاسدا ، لا يصلح لإرثي ، والرضى صفة لنفس الولد ، لكنها تلازم كونه مرضيا. [8] وقد استجاب الله دعاءه فناداه ( يا زَكَرِيَّا إِنَّا نُبَشِّرُكَ بِغُلامٍ ) ولد ( اسْمُهُ يَحْيى ) ولعله سماه سبحانه بهذا الاسم ، كناية عن أنه يحيى حياة صالحة ( لَمْ نَجْعَلْ لَهُ مِنْ قَبْلُ سَمِيًّا ) فلم يسمي أحد ولده بهذا الاسم ، وإنما ابتكر هذا الاسم لولدك تكريما لك ، فإن لكل جديد لذة ولكل تخصيص كرامة. [9] ولقد فوجئ زكريا بهذه الاستجابة المسرة ، كيف يكون له ولد ، وهو شيخ ، وامرأته عاقر لم تلد في شبابها ، فكيف وأنها شاخت وهرمت ؟ ولذا أراد السؤال عن الكيفية ( قالَ ) زكريا يا ( رَبِّ أَنَّى يَكُونُ لِي غُلامٌ ) أي كيف يكون لي غلام ، ولعل سؤاله كان حول رجوعه شابا ، أو عن امرأة جديدة ، أو بهذه الحالة عن هذه المرأة العاقر ؟ ( وَكانَتِ امْرَأَتِي عاقِراً ) لا تلد ( وَقَدْ بَلَغْتُ ) أنا ( مِنَ الْكِبَرِ ) في العمر ( عِتِيًّا ) العتي هو الذي بلغ به طول العمر إلى حالة اليبس والجفاف ، كأنه ليس فيه مادة صالحة لنشأة الولد ؟ قالَ كَذلِكَ قالَ رَبُّكَ هُوَ عَلَيَّ هَيِّنٌ وَقَدْ خَلَقْتُكَ مِنْ قَبْلُ وَلَمْ تَكُ شَيْئاً (9) قالَ رَبِّ اجْعَلْ لِي آيَةً قالَ آيَتُكَ أَلاَّ تُكَلِّمَ النَّاسَ ثَلاثَ لَيالٍ سَوِيًّا (10)` },
            { text: "يَٰزَكَرِيَّآ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ ٱسْمُهُۥ يَحْيَىٰ لَمْ نَجْعَل لَّهُۥ مِن قَبْلُ سَمِيًّا", tafsir: `` },
            { text: "قَالَ رَبِّ أَنَّىٰ يَكُونُ لِى غُلَٰمٌ وَكَانَتِ ٱمْرَأَتِى عَاقِرًا وَقَدْ بَلَغْتُ مِنَ ٱلْكِبَرِ عِتِيًّا", tafsir: `` },
            { text: "قَالَ كَذَٰلِكَ قَالَ رَبُّكَ هُوَ عَلَىَّ هَيِّنٌ وَقَدْ خَلَقْتُكَ مِن قَبْلُ وَلَمْ تَكُ شَيْـًٔا", tafsir: `سبحانه في جوابه ( كَذلِكَ ) أي بهذه الحالة نعطيكما الولد ( قالَ رَبُّكَ هُوَ ) أي إعطاء الولد في هذه الحال ـ حال كبرك ، وكون زوجك عاقرا ـ ( عَلَيَّ هَيِّنٌ ) أي سهل يسير ، والقائل هو الله سبحانه ، وقد جرت العادة أن يذكر الشخص اسمه ، فيقول محمد لأولاده مثلا : يقول لكم محمد ، أن لا تجالسوا الأشرار ، يريد نفسه ( وَقَدْ خَلَقْتُكَ ) يا زكريا ( مِنْ قَبْلُ ) أي سابقا ( وَلَمْ تَكُ شَيْئاً ) أصلا فإعطاء الولد من كبيرين أهون من خلق الإنسان من العدم ، فإن من قدر على ذلك الأصعب ـ في نظرك ـ يقدر على هذا الأسهل.` },
            { text: "قَالَ رَبِّ ٱجْعَل لِّىٓ ءَايَةً قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَ لَيَالٍ سَوِيًّا", tafsir: `زكريا عليه‌السلام يا ( رَبِّ اجْعَلْ لِي آيَةً ) أي علامة دالة على وقت صيرورة الولد الذي بشرتني به ( قالَ ) الله تعالى ( آيَتُكَ ) علامتك التي تدلك على وقت صيرورة الولد ( أَلَّا تُكَلِّمَ النَّاسَ ) أي لا تتمكن من الكلام مع الناس ( ثَلاثَ لَيالٍ ) وفي سورة آل عمران ثلاثة أيام ، ومن ذلك يظهر أن عدم تمكنه عليه‌السلام من التكلم مع الناس ، كان ثلاثة أيام بلياليها ( سَوِيًّا ) في حال كونك سوي الخلق ليس بك خرس أو آفة ، فإذا أردت التسبيح والذكر تمكنت من ذلك ، وإذا أردت التكلم مع الناس ، لم تتمكن ، وقد كان هذا يناسب حال زكريا المقتضي للانقطاع إلى الله سبحانه يذكره ، ويشكره ، على أن أنعم عليه بهذه النعمة. [12] وكأن زكريا عليه‌السلام كانت له غرفة خاصة في بيت المقدس ، وكان قد فَخَرَجَ عَلى قَوْمِهِ مِنَ الْمِحْرابِ فَأَوْحى إِلَيْهِمْ أَنْ سَبِّحُوا بُكْرَةً وَعَشِيًّا (11) يا يَحْيى خُذِ الْكِتابَ بِقُوَّةٍ وَآتَيْناهُ الْحُكْمَ صَبِيًّا (12) وَحَناناً مِنْ لَدُنَّا وَزَكاةً بشر العباد بما بشر به ، وذكر لهم العلامة ، فلما اعتقل لسانه ، أراد أن يفهمهم الأمر ليشاركوا معه في الذكر والتسبيح ، فإن الإنسان يذكر الله عند ما يرى من العجائب ( فَخَرَجَ عَلى قَوْمِهِ مِنَ ) غرفته المسماة ب ( الْمِحْرابِ ) ، ويسمى محل الصلاة محرابا ، لأنه محل محاربة الإنسان مع الشيطان ، يريد الشيطان أن يصده عن الصلاة ، وهو يحاربه حتى يصلي ( فَأَوْحى ) أي أشار زكريا عليه‌السلام ( إِلَيْهِمْ ) بدون أن يتكلم ، لأنه لم يكن يقدر على الكلام مع الناس ( أَنْ سَبِّحُوا ) الله سبحانه ( بُكْرَةً ) أي صباحا ( وَعَشِيًّا ) أي مساء. [13] فولد يحيى وكبر حتى صار صبيا ، وإذا به يسمع النداء من قبل الله سبحانه ( يا يَحْيى خُذِ الْكِتابَ ) أي التوراة ( بِقُوَّةٍ ) بأن تعمل بها بكل استقامة ، والمراد بالقوة ، القوة النفسية ، التي لا يقف دونها شيء لمن عزم وصمم ( وَآتَيْناهُ الْحُكْمَ ) النبوة ، لأنها توجب أن يحكم الشخص بين الناس ، فيأمرهم ، وينهاهم ، ويفصل قضاياهم ( صَبِيًّا ) في حال كونه صبيا ، فإن الله كما قدر على أن يمنحه لوالديه بعد الهرم ، قدر على أن يتفضل عليه بمؤهلات النبوة.` },
            { text: "فَخَرَجَ عَلَىٰ قَوْمِهِۦ مِنَ ٱلْمِحْرَابِ فَأَوْحَىٰٓ إِلَيْهِمْ أَن سَبِّحُوا۟ بُكْرَةً وَعَشِيًّا", tafsir: `` },
            { text: "يَٰيَحْيَىٰ خُذِ ٱلْكِتَٰبَ بِقُوَّةٍ وَءَاتَيْنَٰهُ ٱلْحُكْمَ صَبِيًّا", tafsir: `` },
            { text: "وَحَنَانًا مِّن لَّدُنَّا وَزَكَوٰةً وَكَانَ تَقِيًّا", tafsir: `آتيناه ( حَناناً ) وعطفا وشفقة على الناس ، كما هو من لوازم النبوة ، حتى يتمكن من إرشاد الناس ، فإن أول مؤهلات المرشد ، أن يكون ذا حنان وعطف ( مِنْ لَدُنَّا ) أي من عندنا ، والإضافة إليه سبحانه ـ وإن كان كل حنان من عنده ـ للتشريف ( وَ ) آتيناه ( زَكاةً ) وَكانَ تَقِيًّا (13) وَبَرًّا بِوالِدَيْهِ وَلَمْ يَكُنْ جَبَّاراً عَصِيًّا (14) وَسَلامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ أي طهارة وعفة ونموا ( وَكانَ تَقِيًّا ) يتقي المحارم والآثام.` },
            { text: "وَبَرًّۢا بِوَٰلِدَيْهِ وَلَمْ يَكُن جَبَّارًا عَصِيًّا", tafsir: `آتيناه ( بَرًّا ) وإحسانا ( بِوالِدَيْهِ ) فكان بارا بهما محسنا إليهما ( وَلَمْ يَكُنْ جَبَّاراً ) أي متكبرا متطاولا على الناس يجبرهم على حسب شهواته ، وهذه الصفة « الجبار » ليست حسنة ، إلا من الله سبحانه ، ومعناها فيه ، إنه يأمر الخلق وينهاهم حسب المصلحة ، وهو القاهر فوقهم يميتهم ويحييهم حسب الحكمة ، كما تطلق عليه سبحانه بمعنى جبر الكسر ، ومن هذا قال العباس بن علي عليه‌السلام ، لما قطعوا يساره : يا نفس لا تخشي من الكفار و أبشري برحمة الجبار (1) جبر الكسر ، مع قطع اليد وكسرها ( عَصِيًّا ) أي عاصيا لربه ، فإن فعيل قد يأتي للفاعل ، وقد يأتي للمفعول نحو جريح بمعنى المجروح.` },
            { text: "وَسَلَٰمٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا", tafsir: `أي على يحيى ، والمراد بالسلام السلامة ، في هذه الأيام الثلاثة ، التي نقرر كل يوم منها مصيرا طويلا ( يَوْمَ وُلِدَ ) فإن يوم الولادة يقرر مصير الحياة ، فإذا ولد الإنسان سالما من العيوب ، كان سالما ما دام العمر ، ـ إلا أن يحدث حدث عليه ـ وإن ولد معيوبا كأن كان أعمى أو أعرج أو ما أشبه ، تكبد طول حياته ذلك ( وَيَوْمَ يَمُوتُ ) فإن الإنسان إذا سلم هذا اليوم من عذاب الله سبحانه ، كان سالما في ( 1) بحار الأنوار : ج 45 ص 40. وَيَوْمَ يُبْعَثُ حَيًّا (15) وَاذْكُرْ فِي الْكِتابِ مَرْيَمَ إِذِ انْتَبَذَتْ مِنْ أَهْلِها مَكاناً شَرْقِيًّا (16) فَاتَّخَذَتْ مِنْ دُونِهِمْ حِجاباً فَأَرْسَلْنا إِلَيْها رُوحَنا فَتَمَثَّلَ لَها بَشَراً سَوِيًّا (17) البرزخ الطويل الأمد ( وَيَوْمَ يُبْعَثُ حَيًّا ) أي يحيى للحساب والجزاء ، فإذا سلم في ذلك اليوم ، كان سالما من العذاب والشقاء أبد الدهر ، وهذا هو معنى السلام على الميت ، يعني لتكن سالما من العذاب هناك في قبرك وآخرتك.` },
            { text: "وَٱذْكُرْ فِى ٱلْكِتَٰبِ مَرْيَمَ إِذِ ٱنتَبَذَتْ مِنْ أَهْلِهَا مَكَانًا شَرْقِيًّا", tafsir: `يا رسول الله ( فِي الْكِتابِ ) أي القرآن ( مَرْيَمَ ) أي قصة مريم الطاهرة ، وولادتها لعيسى عليه‌السلام من غير أب ( إِذِ ) حين ( انْتَبَذَتْ ) النبذ أصله الطرح ، والانتباذ منه ، إلا أنه يستعمل بمعنى التنحي يقال : انتبذ فلان ناحية أي تنحى ناحية ، كأنه طرح فيها ، والمراد أن مريم انفردت وتنحت ( مِنْ أَهْلِها ) أبويها ، وسائر قراباتها ( مَكاناً شَرْقِيًّا ) طرف مشرق الأهل ، بحيث كان أهلها في طرف الغرب ، وهي في وجهة شرقهم ، ولعلها أرادت الاغتسال ، ولذا اختارت هذا الطرف ، حتى لا تتأذى بالبرد ، بل تشرق الشمس عليها ـ وهذا هو المستفاد من كلام بعض المفسرين ـ.` },
            { text: "فَٱتَّخَذَتْ مِن دُونِهِمْ حِجَابًا فَأَرْسَلْنَآ إِلَيْهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرًا سَوِيًّا", tafsir: `دون الأهل ( حِجاباً ) سترا ضربته ليحجبها عن أهلها ، وهذا يؤيد الاحتمال السابق ( فَأَرْسَلْنا إِلَيْها رُوحَنا ) أي روحا من طرفنا ـ والإضافة للتشرف ـ وكان ذلك الروح جبرائيل عليه‌السلام ، وقد كان استحاش مريم شديدا حين رأت الروح ( فَتَمَثَّلَ ) الروح ( لَها ) لمريم عليه‌السلام ( بَشَراً سَوِيًّا ) أي شابا مكتملا غير ناقص الخلق. [19] واضطربت مريم عليها‌السلام لهذا الحادث المدهش ، فاستعاذت بالله من شر قالَتْ إِنِّي أَعُوذُ بِالرَّحْمنِ مِنْكَ إِنْ كُنْتَ تَقِيًّا (18) قالَ إِنَّما أَنَا رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلاماً زَكِيًّا (19) قالَتْ أَنَّى يَكُونُ لِي غُلامٌ وَلَمْ يَمْسَسْنِي بَشَرٌ وَلَمْ أَكُ بَغِيًّا (20) قالَ كَذلِكِ قالَ رَبُّكِ هُوَ عَلَيَّ هَيِّنٌ وَلِنَجْعَلَهُ آيَةً لِلنَّاسِ الرجل ، لأنها لم تعرفه ، وقد جرت العادة ، أن مثل هذا الرجل يقصد السوء ( قالَتْ ) مريم عليها‌السلام ( إِنِّي أَعُوذُ بِالرَّحْمنِ مِنْكَ ) أيها الرجل ( إِنْ كُنْتَ تَقِيًّا ) فإن التقي إذا خوف خاف بخلاف الشقي الذي لا يرعوي ، ولو بألف تخويف وإنذار ، كما تقول إن كنت مؤمنا لا تفعل كذا.` },
            { text: "قَالَتْ إِنِّىٓ أَعُوذُ بِٱلرَّحْمَٰنِ مِنكَ إِن كُنتَ تَقِيًّا", tafsir: `` },
            { text: "قَالَ إِنَّمَآ أَنَا۠ رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلَٰمًا زَكِيًّا", tafsir: `جبرائيل عليه‌السلام في جوابها يعرفها بنفسه ، لست أنا إنسانا تخافين منه ( إِنَّما أَنَا رَسُولُ رَبِّكِ ) مرسل من طرفه إليك يا مريم ( لِأَهَبَ لَكِ غُلاماً زَكِيًّا ) ولدا طاهرا طيبا. [21] فازداد تحير مريم عليها‌السلام ، فسألت ( قالَتْ أَنَّى ) كيف ( يَكُونُ لِي غُلامٌ ) ولد ( وَ ) الحال أنه ( لَمْ يَمْسَسْنِي ) على وجه الزوجية ( بَشَرٌ ) وهل الغلام ، إلا من الزوجين بعد الملامسة ( وَلَمْ أَكُ بَغِيًّا ) أي زانية ، فإن الولد في العادة يكون بأحد هذين الطريقين ، ولم يك أحدهما.` },
            { text: "قَالَتْ أَنَّىٰ يَكُونُ لِى غُلَٰمٌ وَلَمْ يَمْسَسْنِى بَشَرٌ وَلَمْ أَكُ بَغِيًّا", tafsir: `` },
            { text: "قَالَ كَذَٰلِكِ قَالَ رَبُّكِ هُوَ عَلَىَّ هَيِّنٌ وَلِنَجْعَلَهُۥٓ ءَايَةً لِّلنَّاسِ وَرَحْمَةً مِّنَّا وَكَانَ أَمْرًا مَّقْضِيًّا", tafsir: `جبرائيل عليه‌السلام في جواب سؤال مريم عليها‌السلام ( كَذلِكِ ) أي كذا الذي ذكرت لك ف « الكاف » حرف جر للتشبيه و « ذا » للإشارة و « لك » للخطاب ( قالَ رَبُّكِ هُوَ ) أي إعطاء الولد من غير أب ( عَلَيَّ هَيِّنٌ ) سهل لا يحتاج إلى الكلفة ( وَلِنَجْعَلَهُ ) نجعل هذا الولد ( آيَةً لِلنَّاسِ ) حجة من عندنا على الناس ، فإن عيسى عليه‌السلام كان حجة الله على البشر وَرَحْمَةً مِنَّا وَكانَ أَمْراً مَقْضِيًّا (21) فَحَمَلَتْهُ فَانْتَبَذَتْ بِهِ مَكاناً قَصِيًّا (22) فَأَجاءَهَا الْمَخاضُ إِلى جِذْعِ النَّخْلَةِ قالَتْ يا لَيْتَنِي مِتُّ قَبْلَ هذا وَكُنْتُ نَسْياً مَنْسِيًّا (23) ( وَرَحْمَةً مِنَّا ) على البشر نرحمهم به ونهديهم إلى الطريق بسببه ( وَكانَ ) إعطاؤك الولد ( أَمْراً مَقْضِيًّا ) أي كائنا مفروغا منه محتوما ، فلا ينفع التكلّم لدفع هذا القضاء. [23] فنفخ جبرائيل في جيب مريم عليها‌السلام ، فاكتمل عيسى في بطنها في الساعة بقدرة الله تعالى ( فَحَمَلَتْهُ ) أي حملت مريم بعيسى عليه‌السلام ( فَانْتَبَذَتْ بِهِ ) تنحت مريم بالولد ـ أي معه ـ ( مَكاناً قَصِيًّا ) أي محلا بعيدا عن أهلها ، لئلّا يروها على حالة الحمل ، ولقد كانت مدة حملها تسع ساعات ، وفي بعض الروايات ، أنها جاءت إلى كربلاء من بيت المقدس ، بقدرة الله تعالى ، وهو المراد بالمكان القصي (1) .` },
            { text: "فَحَمَلَتْهُ فَٱنتَبَذَتْ بِهِۦ مَكَانًا قَصِيًّا", tafsir: `` },
            { text: "فَأَجَآءَهَا ٱلْمَخَاضُ إِلَىٰ جِذْعِ ٱلنَّخْلَةِ قَالَتْ يَٰلَيْتَنِى مِتُّ قَبْلَ هَٰذَا وَكُنتُ نَسْيًا مَّنسِيًّا", tafsir: `أي ألجأها الطلق ، وهو وجع الولادة ( إِلى جِذْعِ النَّخْلَةِ ) لتستند إليها ، والجذع ساق النخلة ، وحيث فكرت في حالتها أخذت الدهشة منها كل مأخذ ، ولذا ( قالَتْ يا لَيْتَنِي مِتُّ قَبْلَ هذا ) الحادث قالت ذلك حياء وخجلا وتحيرا ، و « مت » بكسر الميم من « مات يميت » على وزن « تعب » ومن أخذه من « مات يموت » احتاج إلى التكلف ( وَكُنْتُ نَسْياً ) أي ما من شأنه أن ينسى ( مَنْسِيًّا ) ذكري عند الناس لا يذكرني أحد ، وهناك جاءت بعيسى عليه‌السلام وليدا كاملا جميلا. ( 1) وسائل الشيعة : ج 14 ص 517. فَناداها مِنْ تَحْتِها أَلاَّ تَحْزَنِي قَدْ جَعَلَ رَبُّكِ تَحْتَكِ سَرِيًّا (24) وَهُزِّي إِلَيْكِ بِجِذْعِ النَّخْلَةِ تُساقِطْ عَلَيْكِ رُطَباً جَنِيًّا (25) فَكُلِي وَاشْرَبِي وَقَرِّي عَيْناً فَإِمَّا تَرَيِنَّ مِنَ الْبَشَرِ أَحَداً فَقُولِي` },
            { text: "فَنَادَىٰهَا مِن تَحْتِهَآ أَلَّا تَحْزَنِى قَدْ جَعَلَ رَبُّكِ تَحْتَكِ سَرِيًّا", tafsir: `عيسى عليه‌السلام ، أو جبرائيل ، ( مِنْ تَحْتِها ) أي أسفل منها ، فإنها كانت على أكمة ، ولعل هذا يرجح كون المراد بالمنادي عيسى عليه‌السلام ـ كما اختاره سعيد بن جبير ـ ( أَلَّا تَحْزَنِي ) من هذه الحادثة ، والحزن هو الغم الكامن في النفس ( قَدْ جَعَلَ رَبُّكِ ) يا مريم ( تَحْتَكِ ) أي الأسفل منك ( سَرِيًّا ) أي جدولا ساريا ، و قد قال الإمام الباقر عليه‌السلام إن عيسى عليه‌السلام ضرب برجله الأرض ، فسار الماء (1) .` },
            { text: "وَهُزِّىٓ إِلَيْكِ بِجِذْعِ ٱلنَّخْلَةِ تُسَٰقِطْ عَلَيْكِ رُطَبًا جَنِيًّا", tafsir: `يا مريم ( إِلَيْكِ ) أي اجذبي نحو نفسك ( بِجِذْعِ النَّخْلَةِ ) ليقع فيها الهز ( تُساقِطْ ) النخلة ( عَلَيْكِ رُطَباً ) جديدا ( جَنِيًّا ) طريا ، قد جني الساعة ، والحلو خصوصا الرطب من أفضل ما تتغذى به المرأة التي ولدت.` },
            { text: "فَكُلِى وَٱشْرَبِى وَقَرِّى عَيْنًا فَإِمَّا تَرَيِنَّ مِنَ ٱلْبَشَرِ أَحَدًا فَقُولِىٓ إِنِّى نَذَرْتُ لِلرَّحْمَٰنِ صَوْمًا فَلَنْ أُكَلِّمَ ٱلْيَوْمَ إِنسِيًّا", tafsir: `من الرطب ( وَاشْرَبِي ) من ماء الجدول ( وَقَرِّي عَيْناً ) طيبي نفسا بهذا الولد ، وذلك ، لأن الإنسان المذهول تطير عينه هنا وهناك ، أما مطمئن النفس فإنه تقر وتستقر عينه ، حسب الموازين العقلانية ( فَإِمَّا ) أصلها « إن » الشرطية و « ما » الزائدة للتجميل ، ثم أدغمت النون في الميم ( تَرَيِنَ ) مضارع ، من رأى مؤكد بالنون الثقيلة ( مِنَ الْبَشَرِ أَحَداً ) فسألك عن الولد ، من أين أتيت به ، وأنت غير متزوجة ؟ ( فَقُولِي ) الظاهر ، أن المراد الإشارة بهذا المعنى ، لا لفظ القول ، فإن ( 1) بحار الأنوار : ج 226. إِنِّي نَذَرْتُ لِلرَّحْمنِ صَوْماً فَلَنْ أُكَلِّمَ الْيَوْمَ إِنْسِيًّا (26) فَأَتَتْ بِهِ قَوْمَها تَحْمِلُهُ قالُوا يا مَرْيَمُ لَقَدْ جِئْتِ شَيْئاً فَرِيًّا (27) يا أُخْتَ هارُونَ ما كانَ أَبُوكِ امْرَأَ سَوْءٍ القول يستعمل للعمل والإشارة ، كما يستعمل اللفظ ( إِنِّي نَذَرْتُ لِلرَّحْمنِ صَوْماً ) وقد كان الصوم بمعنى الكف عن الكلام ، كما كان كفا عن الطعام ، وأمره سبحانه ب « قولي » يفيد لزوم أن تنذر هذا الصوم ، ولذا نذرت ذلك ( فَلَنْ أُكَلِّمَ الْيَوْمَ إِنْسِيًّا ) منسوب إلى الإنس ، لإفادة الوحدة ، ولعل ذلك ، لأجل أن لا تقع في المجادلة مع الناس ، والاكتفاء بكلام عيسى الرضيع. [28] وهنا وقد رأت مريم عليها‌السلام ، المعجزات الباهرات ، وها هو وليدها الذي يتكلم على خلاف العادة ، معها حجة قاطعة على براءتها ( فَأَتَتْ ) مريم عليها‌السلام ( بِهِ ) أي بعيسى عليه‌السلام ( قَوْمَها ) أي إلى قومها ( تَحْمِلُهُ ) على يديها ، ولما رآها القوم ، استنكروا طفلها ف ( قالُوا يا مَرْيَمُ لَقَدْ جِئْتِ شَيْئاً فَرِيًّا ) أي أمرا عظيما عجيبا ، من فرى بمعنى قطع ، كأن من يأتي بشيء عجيب ، قد قطع مدهشا ، لا يلائم سائر الأشياء ، ومنه الافتراء.` },
            { text: "فَأَتَتْ بِهِۦ قَوْمَهَا تَحْمِلُهُۥ قَالُوا۟ يَٰمَرْيَمُ لَقَدْ جِئْتِ شَيْـًٔا فَرِيًّا", tafsir: `` },
            { text: "يَٰٓأُخْتَ هَٰرُونَ مَا كَانَ أَبُوكِ ٱمْرَأَ سَوْءٍ وَمَا كَانَتْ أُمُّكِ بَغِيًّا", tafsir: `روي عن النبي صلى‌الله‌عليه‌وآله‌وسلم أن هارون كان رجلا صالحا في بني إسرائيل ، ينسب إليه كل من عرف بالصلاح (1) ، وعلى هذا كان المعنى يا شبيهة هارون في الصلاح ، كيف أتيت بهذا الولد ، من غير زواج ولا نكاح ( ما كانَ أَبُوكِ ) عمران ( امْرَأَ سَوْءٍ ) يعمل القبيح ( 1) بحار الأنوار : ج 14 ص 226. وَما كانَتْ أُمُّكِ بَغِيًّا (28) فَأَشارَتْ إِلَيْهِ قالُوا كَيْفَ نُكَلِّمُ مَنْ كانَ فِي الْمَهْدِ صَبِيًّا (29) قالَ إِنِّي عَبْدُ اللهِ آتانِيَ الْكِتابَ وَجَعَلَنِي نَبِيًّا (30) وَجَعَلَنِي مُبارَكاً أَيْنَ ما كُنْتُ وَأَوْصانِي بِالصَّلاةِ وَالزَّكاةِ ما دُمْتُ حَيًّا (31) ( وَما كانَتْ أُمُّكِ بَغِيًّا ) أي زانية ، فأنت من أبوين صالحين ، فكيف جئت بهذا الولد من غير أب ؟ [30] فلم تجب مريم عليها‌السلام لكلامهم وإنما ( فَأَشارَتْ إِلَيْهِ ) أي إلى عيسى عليه‌السلام ، وأومأت بأن كلموه ، واسألوا منه ما شئتم ، فتعجبوا من إشارتها ، و ( قالُوا كَيْفَ نُكَلِّمُ مَنْ كانَ فِي الْمَهْدِ صَبِيًّا ) وقولهم في المهد ، يراد الشأنية ، لا الفعلية ، وهل طفل شأنه أن يوضع في المهد يتكلم ؟ [31] وهنا أنطق الله عيسى ليدافع عن أمه ، ويبرئ ساحتها ، ويقطع الجدال ف ( قالَ إِنِّي عَبْدُ اللهِ ) وقد كان أول ما تكلم هذا ، ليفند مزاعم الذين يأتون ويقولون إنه الله ( آتانِيَ الْكِتابَ ) أي أعطاني الإنجيل ( وَجَعَلَنِي نَبِيًّا ) ظاهر اللفظ أنه قد أوتي الكتاب والنبوة ، وهو في ذلك السن ، وهذا غير غريب ، فقد وردت أحاديث ، إن الأنبياء ، كانوا أنوارا ، قبل أن يأتوا إلى هذه الدنيا.` },
            { text: "فَأَشَارَتْ إِلَيْهِ قَالُوا۟ كَيْفَ نُكَلِّمُ مَن كَانَ فِى ٱلْمَهْدِ صَبِيًّا", tafsir: `` },
            { text: "قَالَ إِنِّى عَبْدُ ٱللَّهِ ءَاتَىٰنِىَ ٱلْكِتَٰبَ وَجَعَلَنِى نَبِيًّا", tafsir: `` },
            { text: "وَجَعَلَنِى مُبَارَكًا أَيْنَ مَا كُنتُ وَأَوْصَٰنِى بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمْتُ حَيًّا", tafsir: `ذا بركة وخير ( أَيْنَ ما كُنْتُ ) فليس كالثري ، أو ذي الجاه الذي لا خير له ، إذا لم يكن عند ثروته ، وفي محل منصبه ، بل يعلم الخير ويشفي المرضى ، أينما كان ( وَأَوْصانِي ) الله سبحانه ( بِالصَّلاةِ وَالزَّكاةِ ) بأن أصلي وأنفق ( ما دُمْتُ حَيًّا ) ما بقيت مكلفا. وَبَرًّا بِوالِدَتِي وَلَمْ يَجْعَلْنِي جَبَّاراً شَقِيًّا (32) وَالسَّلامُ عَلَيَّ يَوْمَ وُلِدْتُ وَيَوْمَ أَمُوتُ وَيَوْمَ أُبْعَثُ حَيًّا (33) ذلِكَ عِيسَى ابْنُ مَرْيَمَ قَوْلَ الْحَقِّ الَّذِي فِيهِ يَمْتَرُونَ (34)` },
            { text: "وَبَرًّۢا بِوَٰلِدَتِى وَلَمْ يَجْعَلْنِى جَبَّارًا شَقِيًّا", tafsir: `جعلني ( بَرًّا ) أي بارا ( بِوالِدَتِي ) مريم الطاهرة ( وَلَمْ يَجْعَلْنِي جَبَّاراً ) متجبرا طاغيا ( شَقِيًّا ) من الأشقياء ، فإني بلطفه وكرمه كنت هكذا ، وليس معنى ذلك أن الله يجعل الجبابرة الأشقياء كذلك ، بل إن الله سبحانه يتركهم ، إذا رأى منهم الانحراف ، حتى يضلهم الشيطان ، وترديهم النفس الأمارة بالسوء.` },
            { text: "وَٱلسَّلَٰمُ عَلَىَّ يَوْمَ وُلِدتُّ وَيَوْمَ أَمُوتُ وَيَوْمَ أُبْعَثُ حَيًّا", tafsir: `أي السلامة من العاهات الجسمية والروحية ( عَلَيَّ يَوْمَ وُلِدْتُ ، وَيَوْمَ أَمُوتُ ) بعد ما ما أنزل من السماء ( وَيَوْمَ أُبْعَثُ حَيًّا ) في القيامة ، وقد مر وجه ذلك في قصة يحيى عليه‌السلام . [35] وإذ أتم السياق قصة عيسى عليه‌السلام ، فيما هو محل الحاجة ، عطف على النصارى الذين يقولون إنه الله ، أو ابن الله أو شريك الله ، واليهود الذين يقولون فيه السوء ، فقال سبحانه ( ذلِكَ ) الذي تقدم أحواله ( عِيسَى ابْنُ مَرْيَمَ ) الذي جاء إلى الدنيا ، وكان صاحب شريعة ، ثم رفع إلى السماء ( قَوْلَ الْحَقِ ) أي أقول قول الحق ، أو خذه قول الحق ( الَّذِي فِيهِ يَمْتَرُونَ ) أي يشكّون ، فزعمت اليهود أنه لغير رشده ، وكان ساحرا كذابا ، وزعمت النصارى أنه ابن الله ، وأمه ثالث الأقانيم ، فإن كلا القولين باطل ، لا يدل عليهما دليل ، بل العقل دل على خلاف هذين القولين الزائفين ، وقوله « يمترون » من المرية ، وهو الشك وإنما سمي شكا مع أنهم بحسب الظاهر يوقنون بذلك ، لأن ما خالف الواقع كان بالشك أشبه. ما كانَ لِلَّهِ أَنْ يَتَّخِذَ مِنْ وَلَدٍ سُبْحانَهُ إِذا قَضى أَمْراً فَإِنَّما يَقُولُ لَهُ كُنْ فَيَكُونُ (35) وَإِنَّ اللهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هذا صِراطٌ مُسْتَقِيمٌ (36) فَاخْتَلَفَ الْأَحْزابُ مِنْ بَيْنِهِمْ فَوَيْلٌ لِلَّذِينَ كَفَرُوا` },
            { text: "ذَٰلِكَ عِيسَى ٱبْنُ مَرْيَمَ قَوْلَ ٱلْحَقِّ ٱلَّذِى فِيهِ يَمْتَرُونَ", tafsir: `` },
            { text: "مَا كَانَ لِلَّهِ أَن يَتَّخِذَ مِن وَلَدٍ سُبْحَٰنَهُۥٓ إِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ", tafsir: `فإن اتخاذ الولد حقيقة محال ، والولد تشريفا ، بأن يتبنى ، خلاف شأنه سبحانه ، و « من » لإفادة النفي مطلقا ، واحدا كان الولد أم متعددا ( سُبْحانَهُ ) أي أنزهه عن اتخاذ الولد تنزيها ، وليس أمر عجيب ولادة عيسى عليه‌السلام من غير أب ، فإنه تعالى ( إِذا قَضى أَمْراً ) وأراد شيئا ( فَإِنَّما يَقُولُ لَهُ ) للشيء الذي أراده ( كُنْ ) إما لفظا ، أو ذلك حكاية عن إرادته تعالى ( فَيَكُونُ ) ذلك الشيء. [37] ثم أتم الكلام سبحانه حول قصة عيسى عليه‌السلام بقوله ( وَ ) أوصاني ( إِنَّ اللهَ رَبِّي وَرَبُّكُمْ ) أيها البشر ، فلست أنا إلها ، وهل يبقى بعد شهادة عيسى كلام ؟ ( فَاعْبُدُوهُ ) وحده ( هذا صِراطٌ مُسْتَقِيمٌ ) لا عوج فيه ، ولا انحراف ، ومن الظريف أن كتاب « العهدين » مشتمل على تصريح عيسى ، بأن الله ربه ، بل لقد زاد النصارى ، أن لمريم أم عيسى زوجا يسمى « يوسف » ومع ذلك ، قالوا بأنه الله ، أو أنه ابن الله. [38] ومع هذه الحجج عقليها ، وشرعيها ، لم يقنع النصارى ( فَاخْتَلَفَ الْأَحْزابُ مِنْ بَيْنِهِمْ ) الأحزاب جمع حزب ، وهو الفئة من الناس ، ذات لون واحد في العقيدة ، أو العمل ، أي من بين أهل الكتاب ، فقالت اليعقوبية منهم ، هو الله ، وقالت النسطورية منهم هو ابن الله ، وقالت الإسرائيلية منهم ثالث ثلاثة ( فَوَيْلٌ ) أي شدة العذاب ، فإن ويل كلمة وعيد ( لِلَّذِينَ كَفَرُوا ) بالله ، واتخذوا عيسى ربا ، مِنْ مَشْهَدِ يَوْمٍ عَظِيمٍ (37) أَسْمِعْ بِهِمْ وَأَبْصِرْ يَوْمَ يَأْتُونَنا لكِنِ الظَّالِمُونَ الْيَوْمَ فِي ضَلالٍ مُبِينٍ (38) وَأَنْذِرْهُمْ يَوْمَ الْحَسْرَةِ إِذْ قُضِيَ الْأَمْرُ وَهُمْ فِي غَفْلَةٍ وَهُمْ لا يُؤْمِنُونَ (39) إِنَّا نَحْنُ نَرِثُ أو شريكا ، أو ابنا له ( مِنْ مَشْهَدِ يَوْمٍ عَظِيمٍ ) ، أي من محضر ، أو هو مصدر ميمي ، أي من حضورهم في يوم عظيم هو يوم القيامة ، فإنهم يفضحون ويعاقبون على رؤوس الأشهاد. [39] إن الكافرين في يوم القيامة ، حيث لا ينفعهم السمع والبصر ، يكونون أقوى الناس سماعا وإبصارا ، أما في الدنيا ، وحيث أن السمع والبصر وسيلة الهداية والسعادة ، فإنهم لا يسمعون ، ولا يبصرون ( أَسْمِعْ بِهِمْ وَأَبْصِرْ ) بهم ، أي ما أسمعهم وأبصرهم ، وذلك صيغة التعجب على معنى ما أسمعهم وأبصرهم ( يَوْمَ يَأْتُونَنا ) أي في القيامة ( لكِنِ الظَّالِمُونَ الْيَوْمَ ) في الدنيا ( فِي ضَلالٍ مُبِينٍ ) لا يسمعون الهدى ، ولا يبصرون الطريق.` },
            { text: "وَإِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ", tafsir: `` },
            { text: "فَٱخْتَلَفَ ٱلْأَحْزَابُ مِنۢ بَيْنِهِمْ فَوَيْلٌ لِّلَّذِينَ كَفَرُوا۟ مِن مَّشْهَدِ يَوْمٍ عَظِيمٍ", tafsir: `` },
            { text: "أَسْمِعْ بِهِمْ وَأَبْصِرْ يَوْمَ يَأْتُونَنَا لَٰكِنِ ٱلظَّٰلِمُونَ ٱلْيَوْمَ فِى ضَلَٰلٍ مُّبِينٍ", tafsir: `` },
            { text: "وَأَنذِرْهُمْ يَوْمَ ٱلْحَسْرَةِ إِذْ قُضِىَ ٱلْأَمْرُ وَهُمْ فِى غَفْلَةٍ وَهُمْ لَا يُؤْمِنُونَ", tafsir: `أي أنذر يا رسول الله الناس ، ( يَوْمَ الْحَسْرَةِ ) يوم يتحسر الإنسان ، ويندم على ما فات منه من السعادة ( إِذْ قُضِيَ الْأَمْرُ ) حين فرغ من الأمور ، وانقطعت الآمال ، فالمؤمن يتحسر على أنه لم لم يعمل أكثر ؟ والكافر والعاصي يتحسران ، على أنه لم كفر وعصى ، حتى يلقى العذاب والهوان ( وَهُمْ فِي غَفْلَةٍ ) الآن في الدنيا عن ذلك ( وَهُمْ لا يُؤْمِنُونَ ) حتى لا يتحسروا هناك حسرة الكافر على ما قدمت يداه. [41] إنه لا بد وأن يأتي ذلك اليوم حين ( إِنَّا نَحْنُ نَرِثُ الْأَرْضَ وَمَنْ عَلَيْها وَإِلَيْنا يُرْجَعُونَ (40) وَاذْكُرْ فِي الْكِتابِ إِبْراهِيمَ إِنَّهُ كانَ صِدِّيقاً نَبِيًّا (41 ) إِذْ قالَ لِأَبِيهِ يا أَبَتِ الْأَرْضَ وَمَنْ عَلَيْها ) فكل ما في الأرض ما ليس ملكا لإنسان ، وكل ما فيها مما هو ملك البشر ، يبقى هنا بدون مالك ، ولفظة « نحن » للتأكيد ، كما إن إرث الأرض كناية عن عدم وجود إنسان فيها ، حتى تكون الأرض محتملة لحيازته ( وَإِلَيْنا يُرْجَعُونَ ) بأعمالهم ، حيث لا يملك الأمر والنهي غيرنا ، فنجازيهم عليها.` },
            { text: "إِنَّا نَحْنُ نَرِثُ ٱلْأَرْضَ وَمَنْ عَلَيْهَا وَإِلَيْنَا يُرْجَعُونَ", tafsir: `` },
            { text: "وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِبْرَٰهِيمَ إِنَّهُۥ كَانَ صِدِّيقًا نَّبِيًّا", tafsir: `يا رسول الله ( فِي الْكِتابِ ) أي في القرآن ( إِبْراهِيمَ ) وليس الذكر إنشاء الإنسان الكلام ، حتى يقال إن الله هو الذاكر لا الرسول ، بل الذكر هو أن يذكر شيئا سواء كان منشئا له أم ناقلا ، وقد جاءت قصة إبراهيم لتفنيد مزاعم العرب الذين عبدوا الشركاء ، وتذكيرهم ، بأن إبراهيم جدهم هو الذي حارب الشرك ، كما جاءت قصة عيسى عليه‌السلام من قبل لتفنيد مزاعم النصارى ، حيث يجعلون لله ولدا ، وبيان أن عيسى المسيح عليه‌السلام لم يكن ابنا لله ، وإنما كان عبدا رسولا ( إِنَّهُ كانَ صِدِّيقاً ) كثير التصديق لله سبحانه في جميع الأمور أو كثير الصدق ( نَبِيًّا ) مرسلا من قبل الله سبحانه ، وهو من النبوة بمعنى الرفعة ، أو من النبأ بمعنى الخبر ، لأن النبي رفيع الشأن مخبر عن الله سبحانه. [43] اذكره ( إِذْ قالَ ) حين قوله ( لِأَبِيهِ ) أي لعمه آزر ، فإن العادة أن يسمى العم أبا ، كما تسمى الخالة أما ( يا أَبَتِ ) أي يا أبي والتاء عوض عن الياء ، كما قال ابن مالك : و في النداء أبت ، أمت عرض و اكسر أو افتح ومن اليا التاء عوض لِمَ تَعْبُدُ ما لا يَسْمَعُ وَلا يُبْصِرُ وَلا يُغْنِي عَنْكَ شَيْئاً (42) يا أَبَتِ إِنِّي قَدْ جاءَنِي مِنَ الْعِلْمِ ما لَمْ يَأْتِكَ فَاتَّبِعْنِي أَهْدِكَ صِراطاً سَوِيًّا (43) يا أَبَتِ لا تَعْبُدِ الشَّيْطانَ إِنَّ الشَّيْطانَ كانَ لِلرَّحْمنِ عَصِيًّا (44) يا أَبَتِ إِنِّي أَخافُ أَنْ يَمَسَّكَ عَذابٌ مِنَ الرَّحْمنِ ( لِمَ تَعْبُدُ ) أي لماذا تعبد ( ما لا يَسْمَعُ ) أي الصنم الذي لا يسمع الكلام ( وَلا يُبْصِرُ ) شيئا ( وَلا يُغْنِي عَنْكَ شَيْئاً ) أي لا يكفيك حاجة من حوائجك يقال أغنى عنه ، إذا جلب إليه نفعا ، أو دفع عنه ضررا ؟` },
            { text: "إِذْ قَالَ لِأَبِيهِ يَٰٓأَبَتِ لِمَ تَعْبُدُ مَا لَا يَسْمَعُ وَلَا يُبْصِرُ وَلَا يُغْنِى عَنكَ شَيْـًٔا", tafsir: `` },
            { text: "يَٰٓأَبَتِ إِنِّى قَدْ جَآءَنِى مِنَ ٱلْعِلْمِ مَا لَمْ يَأْتِكَ فَٱتَّبِعْنِىٓ أَهْدِكَ صِرَٰطًا سَوِيًّا", tafsir: `بالله سبحانه ، وبالأمور الكونية ( ما لَمْ يَأْتِكَ ) فلست أنت تعلم حول المبدأ ، والمعاد والكون ما أعلمه أنا ( فَاتَّبِعْنِي ) فيما أدعوك إليه ( أَهْدِكَ صِراطاً سَوِيًّا ) أي مستقيما لا عوج فيه ولا انحراف وهو صراط الحقيقة في باب المبدأ ، وسائر الشؤون لا الضلال ، كما عليه عبدة الأصنام.` },
            { text: "يَٰٓأَبَتِ لَا تَعْبُدِ ٱلشَّيْطَٰنَ إِنَّ ٱلشَّيْطَٰنَ كَانَ لِلرَّحْمَٰنِ عَصِيًّا", tafsir: `لا تطعه ، فإن من يطيع أحدا يكون كالعابد له ، إذ العابد يطيع المعبود ، فهو مجاز من باب التشبيه ، ومثله اتخذوا أحبارهم ورهبانهم أربابا من دون الله ( إِنَّ الشَّيْطانَ كانَ لِلرَّحْمنِ عَصِيًّا ) أي عاصيا ، فكيف تطيع من يعصي إلهك وخالقك ؟ ومن المحتمل أن يكون آزر معترفا بالإله ، وإنما يعبد الأصنام تقربا إليه ، ولذا نفّره إبراهيم عن عبادة الشيطان بأنه عاص لله.` },
            { text: "يَٰٓأَبَتِ إِنِّىٓ أَخَافُ أَن يَمَسَّكَ عَذَابٌ مِّنَ ٱلرَّحْمَٰنِ فَتَكُونَ لِلشَّيْطَٰنِ وَلِيًّا", tafsir: `أي يلامسك ( عَذابٌ مِنَ الرَّحْمنِ ) الرحمن الذي هو مصدر الرحمة والتفضل ، يعذبك ، بما تخالفه ، فَتَكُونَ لِلشَّيْطانِ وَلِيًّا (45) قالَ أَ راغِبٌ أَنْتَ عَنْ آلِهَتِي يا إِبْراهِيمُ لَئِنْ لَمْ تَنْتَهِ لَأَرْجُمَنَّكَ وَاهْجُرْنِي مَلِيًّا (46) قالَ سَلامٌ عَلَيْكَ سَأَسْتَغْفِرُ لَكَ رَبِّي إِنَّهُ كانَ بِي حَفِيًّا (47) وتطيع الشيطان ، وتعبد الأصنام ( فَتَكُونَ لِلشَّيْطانِ وَلِيًّا ) بأن يكلك الله إلى الشيطان ، حتى تكون وليا وتابعا له ، لا وليا لله وتابعا إياه ، والشيطان لا يغني عن وليه شيئا ، فتخسر الدنيا والآخرة.` },
            { text: "قَالَ أَرَاغِبٌ أَنتَ عَنْ ءَالِهَتِى يَٰٓإِبْرَٰهِيمُ لَئِن لَّمْ تَنتَهِ لَأَرْجُمَنَّكَ وَٱهْجُرْنِى مَلِيًّا", tafsir: `آزر ، مجيبا لإبراهيم في دعوته ( أَ راغِبٌ ) أي هل تنفر ( أَنْتَ عَنْ آلِهَتِي ) معرض عنها ( يا إِبْراهِيمُ ) فإن رغب ، إذا عدي ب « عن » كان بمعنى النفرة ، وإذا عدي ب « في » كان بمعنى الطلب ، والاستفهام إنكاري ( لَئِنْ لَمْ تَنْتَهِ ) عن دعوتك ، وإعراضك عن الأصنام ( لَأَرْجُمَنَّكَ ) بالحجارة ، فابتعد عني ( وَاهْجُرْنِي مَلِيًّا ) أي فارقني وتنح عني دهرا طويلا ، فإن الملي بمعنى الدهر الطويل ، من ملو ، يقال كنت عنده ملوا أي زمانا طويلا.` },
            { text: "قَالَ سَلَٰمٌ عَلَيْكَ سَأَسْتَغْفِرُ لَكَ رَبِّىٓ إِنَّهُۥ كَانَ بِى حَفِيًّا", tafsir: `إبراهيم عليه‌السلام في جواب آزر ( سَلامٌ عَلَيْكَ ) أي كن سالما ، وهذه كلمة يقولها الإنسان الحليم عند ملاقاة الجاهل ، كما قال سبحانه ( وَإِذا خاطَبَهُمُ الْجاهِلُونَ قالُوا سَلاماً ) (1) وذلك من باب ترقيق الجو ، ولتلطيف نفس الجاهل العاتية ، حتى لا تزيده الدعوة والكلام بغضا وعنادا فوق ما كان ( سَأَسْتَغْفِرُ لَكَ رَبِّي ) أي أطلب منه الغفران لك ، وذلك بأن يهديك حتى تستحق الغفران ( إِنَّهُ ) سبحانه ( كانَ بِي حَفِيًّا ) لطيفا بارا ، فلعله يقبل استغفاري ويهديك الصراط. ( 1) الفرقان : 64. وَأَعْتَزِلُكُمْ وَما تَدْعُونَ مِنْ دُونِ اللهِ وَأَدْعُوا رَبِّي عَسى أَلاَّ أَكُونَ بِدُعاءِ رَبِّي شَقِيًّا (48) فَلَمَّا اعْتَزَلَهُمْ وَما يَعْبُدُونَ مِنْ دُونِ اللهِ وَهَبْنا لَهُ إِسْحاقَ وَيَعْقُوبَ وَكُلاًّ جَعَلْنا نَبِيًّا (49) وَوَهَبْنا لَهُمْ مِنْ رَحْمَتِنا` },
            { text: "وَأَعْتَزِلُكُمْ وَمَا تَدْعُونَ مِن دُونِ ٱللَّهِ وَأَدْعُوا۟ رَبِّى عَسَىٰٓ أَلَّآ أَكُونَ بِدُعَآءِ رَبِّى شَقِيًّا", tafsir: `أتنحى عنكم ـ أنت والقوم ـ وقد سبق أن دعا إبراهيم القوم ، فلم ينفع فيهم الدعاء ، ولذا قرر أن يعتزلهم إلى مكان آخر يدعو فيه ، لعلهم يجيبون الدعوة ، فقد طاف إبراهيم عليه‌السلام ـ لتركيز دعوة التوحيد ـ العراق والشام ومصر والحجاز ( وَ ) أعتزل ( ما تَدْعُونَ مِنْ دُونِ اللهِ ) أي أتنحى عن أصنامكم ، إذ المبتعد عن بلد ، يبتعد عن كل شيء فيه ( وَأَدْعُوا رَبِّي ) لكم بالهداية ( عَسى أَلَّا أَكُونَ بِدُعاءِ رَبِّي ) لهدايتكم ( شَقِيًّا ) فيستجب دعائي في هدايتكم ، أي لعله سبحانه يقبل الدعاء ، ويردكم عن الضلال إلى الهدى ، وليس هذا تكرارا ، فإن ما سبق ، كان خاصا بآزر ، وهذا عام لكل القوم.` },
            { text: "فَلَمَّا ٱعْتَزَلَهُمْ وَمَا يَعْبُدُونَ مِن دُونِ ٱللَّهِ وَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ وَكُلًّا جَعَلْنَا نَبِيًّا", tafsir: `إبراهيم ( وَ ) اعتزل ( ما يَعْبُدُونَ مِنْ دُونِ اللهِ ) بأن فارقهم ، وهاجر إلى الأرض المقدسة ، لم نتركه وحده يقاسي الوحدة ، والغربة ، بل تفضلنا عليه بما يؤنس وحشته ، ويجمع شمله ( وَهَبْنا لَهُ إِسْحاقَ ) ولدا صلبيا ( وَيَعْقُوبَ ) ولد الولد ( وَكُلًّا جَعَلْنا نَبِيًّا ) يهدي الناس إلى الحق ، فقد كثرنا إبراهيم عددا ، كما كثرنا الدعوة التي دعا بها إلى الله سبحانه ، فشددنا أزره بالأنبياء عليهم‌السلام ، الذين ينتهجون نهجه في الدعوة.` },
            { text: "وَوَهَبْنَا لَهُم مِّن رَّحْمَتِنَا وَجَعَلْنَا لَهُمْ لِسَانَ صِدْقٍ عَلِيًّا", tafsir: `لإبراهيم وإسحاق ويعقوب عليهم‌السلام ( مِنْ رَحْمَتِنا ) وَجَعَلْنا لَهُمْ لِسانَ صِدْقٍ عَلِيًّا (50) وَاذْكُرْ فِي الْكِتابِ مُوسى إِنَّهُ كانَ مُخْلَصاً وَكانَ رَسُولاً نَبِيًّا (51) وَنادَيْناهُ مِنْ جانِبِ الطُّورِ الْأَيْمَنِ وتفضلنا عليه ( وَجَعَلْنا لَهُمْ ) لإبراهيم وإسحاق ويعقوب عليهم‌السلام ( لِسانَ صِدْقٍ ) فقد كانوا صادقين في دعوتهم يصدقهم الناس ، جزاء لاستقامتهم في الدعوة ، في قبال ذلك التكذيب الذي واجه القوم به إبراهيم ، قبل الاعتزال ( عَلِيًّا ) أي في حال كون ذلك اللسان عليا رفيعا ، ينظر إليه الناس برفعة ، حتى إذا قال شيئا أطاعوه ، وسمعوا منه. [52] ثم يأتي السياق ، ليبين دعوة الأنبياء عليهم‌السلام ، وتفضل الله عليهم ، إجمالا بدون تفصيل ، إذ المقصود بيان الدعاة والدعوة ( وَاذْكُرْ فِي الْكِتابِ ) أي اذكر يا رسول الله في القرآن ( مُوسى إِنَّهُ كانَ مُخْلَصاً ) قد أخلصه الله سبحانه لنفسه ، كما قال سبحانه ( وَاصْطَنَعْتُكَ لِنَفْسِي ) (1) ف « مخلص » اسم مفعول من أخلص ( وَكانَ رَسُولاً ) إلى فرعون وملأه ، وإلى سائر البشر ( نَبِيًّا ) يأتيه الوحي من قبل الله سبحانه.` },
            { text: "وَٱذْكُرْ فِى ٱلْكِتَٰبِ مُوسَىٰٓ إِنَّهُۥ كَانَ مُخْلَصًا وَكَانَ رَسُولًا نَّبِيًّا", tafsir: `` },
            { text: "وَنَٰدَيْنَٰهُ مِن جَانِبِ ٱلطُّورِ ٱلْأَيْمَنِ وَقَرَّبْنَٰهُ نَجِيًّا", tafsir: `الطور اسم جبل كان يناجي عليه موسى عليه‌السلام ربه ، أي ناديناه من طرف ذلك الجبل ، طرفه الأيمن لا الأيسر ، وذلك حين أقبل من « مدين » ورأى النار في الشجرة ، ولما دنا منها سمع الصوت ( يا مُوسى إِنِّي أَنَا اللهُ رَبُّ الْعالَمِينَ ) (2) ( 1) طه : 42. ( 2) القصص : 31. وَقَرَّبْناهُ نَجِيًّا (52) وَوَهَبْنا لَهُ مِنْ رَحْمَتِنا أَخاهُ هارُونَ نَبِيًّا (53) وَاذْكُرْ فِي الْكِتابِ إِسْماعِيلَ إِنَّهُ كانَ صادِقَ الْوَعْدِ وَكانَ رَسُولاً نَبِيًّا (54) ( وَقَرَّبْناهُ ) إلينا في حال كونه ( نَجِيًّا ) نناجيه بكلام خفي لا يسمعه غيره ، فقد كان القرب إلى هذا الحد حد المناجاة والإسرار في الأذن ، لكن المراد ليس القرب المكاني ـ فإنه سبحانه منزه عن المكان ـ وإنما القرب المعنوي الذي هو عبارة عن جعل نفس موسى عليه‌السلام بحيث يتمكن من تلقي كلام الله سبحانه ، ثم إن من المعلوم ، إن الله لا يكلم باللسان ـ لأنه منزه عن الجسم وعوارضه ـ وإنما يخلق الصوت ، فيسمعه من كملت نفسه ، وأراد سبحانه إسماعه.` },
            { text: "وَوَهَبْنَا لَهُۥ مِن رَّحْمَتِنَآ أَخَاهُ هَٰرُونَ نَبِيًّا", tafsir: `أي لموسى ( مِنْ رَحْمَتِنا ) وتفضلنا عليه ( أَخاهُ هارُونَ نَبِيًّا ) فأنعمنا على موسى بجعل هارون نبيا ، يشد أزره ويساعده في الدعوة ، إجابة لدعائه ، حيث قال ( وَاجْعَلْ لِي وَزِيراً مِنْ أَهْلِي* هارُونَ أَخِي* اشْدُدْ بِهِ أَزْرِي* وَأَشْرِكْهُ فِي أَمْرِي ) (1) .` },
            { text: "وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِسْمَٰعِيلَ إِنَّهُۥ كَانَ صَادِقَ ٱلْوَعْدِ وَكَانَ رَسُولًا نَّبِيًّا", tafsir: `يا رسول الله ( فِي الْكِتابِ ) أي القرآن ( إِسْماعِيلَ ) بن حزقيل ، كما ورد في الأحاديث ، لا إسماعيل بن إبراهيم الخليل ( إِنَّهُ كانَ صادِقَ الْوَعْدِ ) إذا وعد وفي ، ولو طالت المدة ، فقد ورد عن الصادق عليه‌السلام إنه إنما سمي صادق الوعد ، لأنه وعد رجلا في مكان ، فانتظره في ذلك المكان سنة ، فسماه الله عزوجل صادق الوعد ثم إن الرجل أتاه بعد ذلك ، فقال له إسماعيل ما زلت منتظرا لك (2) . أقول : ليس معنى ذلك إن إسماعيل لم يعمل عملا في تلك ( 1) طه : 30 ـ 33. ( 2) الكافي : ج 2 ص 105. وَكانَ يَأْمُرُ أَهْلَهُ بِالصَّلاةِ وَالزَّكاةِ وَكانَ عِنْدَ رَبِّهِ مَرْضِيًّا (55) وَاذْكُرْ فِي الْكِتابِ إِدْرِيسَ المدة ، فلعله كان مشتغلا بأمره ـ التبليغ ـ أو العمل أو نحوهما ، فلا يقال : كيف يترك الإنسان عمله سنة لوعد ، أليس عدم مجيء الصاحب دليل على خلفه ، حتى يكون إسماعيل في حل منه ؟ ( وَكانَ رَسُولاً ) إلى قومه ( نَبِيًّا ) يوحى إليه ، من قبل الله سبحانه ، و قد ورد أن الله عزوجل بعثه إلى قومه ، فأخذوه فسلخوا فروة رأسه ووجهه فأتاه ملك ، فقال : إن الله جل جلاله بعثني إليك فمرني بما شئت فقال لي أسوة بما يصنع بالأنبياء (1) .` },
            { text: "وَكَانَ يَأْمُرُ أَهْلَهُۥ بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ وَكَانَ عِندَ رَبِّهِۦ مَرْضِيًّا", tafsir: `إسماعيل ( يَأْمُرُ أَهْلَهُ ) أي عائلته ، أو عشيرته ، أو قومه ـ فإن الأهل يطلق على كل واحد من هؤلاء ـ وإن كان الأنسب بمقام النبوة إرادة المعنى الثالث ( بِالصَّلاةِ وَالزَّكاةِ ) المراد بهذين اللفظين الخضوع لله سبحانه ، وإعطائه الفقراء وإن كان بغير صورة الصلاة والزكاة في هذه الشريعة فإن الصلاة بمعنى العطف ، والزكاة بمعنى النمو ، وفي الصلاة عطف نحوه سبحانه ، وفي الزكاة نمو للمال ( وَكانَ ) إسماعيل ( عِنْدَ رَبِّهِ مَرْضِيًّا ) رضي سبحانه عن أعماله وأخلاقه وسيرته.` },
            { text: "وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِدْرِيسَ إِنَّهُۥ كَانَ صِدِّيقًا نَّبِيًّا", tafsir: `يا رسول الله ( فِي الْكِتابِ ) أي القرآن ( إِدْرِيسَ ) سمي بذلك لكثرة دراسته للكتب ، وقد أنزل عليه ثلاثون صحيفة ، وهو أول من خط بالقلم وخاط ، ونظر في الحساب ، وقد كان الناس قبله ( 1) راجع القصص للجزائري : ص 316. إِنَّهُ كانَ صِدِّيقاً نَبِيًّا (56) وَرَفَعْناهُ مَكاناً عَلِيًّا (57) أُولئِكَ الَّذِينَ أَنْعَمَ اللهُ عَلَيْهِمْ مِنَ النَّبِيِّينَ مِنْ ذُرِّيَّةِ آدَمَ وَمِمَّنْ حَمَلْنا مَعَ نُوحٍ وَمِنْ ذُرِّيَّةِ إِبْراهِيمَ وَإِسْرائِيلَ وَمِمَّنْ هَدَيْنا وَاجْتَبَيْنا إِذا تُتْلى عَلَيْهِمْ آياتُ الرَّحْمنِ خَرُّوا سُجَّداً وَبُكِيًّا (58) يلبسون الجلود ـ كما روي ـ ( إِنَّهُ كانَ صِدِّيقاً ) كثير الصدق ، أو كثير التصديق لله سبحانه ( نَبِيًّا ) يوحى إليه من قبله سبحانه.` },
            { text: "وَرَفَعْنَٰهُ مَكَانًا عَلِيًّا", tafsir: `أي إلى مكان عليّ رفيع ، إما رتبة بأن كانت رتبته ، ومنزلته عند الله رفيعة ، وإما محلا ، فقد ورد أنه رفع إلى السماء ، وهناك قبض روحه ملك الموت.` },
            { text: "أُو۟لَٰٓئِكَ ٱلَّذِينَ أَنْعَمَ ٱللَّهُ عَلَيْهِم مِّنَ ٱلنَّبِيِّـۧنَ مِن ذُرِّيَّةِ ءَادَمَ وَمِمَّنْ حَمَلْنَا مَعَ نُوحٍ وَمِن ذُرِّيَّةِ إِبْرَٰهِيمَ وَإِسْرَٰٓءِيلَ وَمِمَّنْ هَدَيْنَا وَٱجْتَبَيْنَآ إِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُ ٱلرَّحْمَٰنِ خَرُّوا۟ سُجَّدًا وَبُكِيًّا", tafsir: `الذين تقدم أسماءهم ( الَّذِينَ أَنْعَمَ اللهُ عَلَيْهِمْ ) بالنبوة ، والمنزلة الرفيعة ( مِنَ النَّبِيِّينَ مِنْ ذُرِّيَّةِ آدَمَ ) أبو البشر عليه‌السلام . ( وَ ) من ذرية ( مِمَّنْ حَمَلْنا مَعَ نُوحٍ ) في السفينة ( وَمِنْ ذُرِّيَّةِ إِبْراهِيمَ وَإِسْرائِيلَ ) يعني يعقوب عليه‌السلام ، وإنما ذكر سبحانه هذا التفصيل مع إن الجميع من ذرية آدم ، لبيان ذكر مراتبهم في شرف الانتساب ، أو شرف التفضل ، فمن كان منسوبا إلى إبراهم أشرف نسبا ممن لا ينتسب إليه ، وإنما ينتسب إلى آدم عليه‌السلام فقط ، كما أن من حمل أبوه في السفينة كان التفضل عليه أكثر ممن لم يحمل ، بأن كان قبل الطوفان ( وَمِمَّنْ هَدَيْنا وَاجْتَبَيْنا ) أي أنعمنا عليهم ، في جملة من هديناهم إلى الحق ، واخترناهم للنبوة والإرشاد ، إن أولئك كلهم ( إِذا تُتْلى عَلَيْهِمْ ) وتقرأ عندهم ( آياتُ الرَّحْمنِ ) الدالة على وجوده وصفاته ( خَرُّوا سُجَّداً ) جمع ساجد ، أي ساجدين لله سبحانه ، تعظيما له ولكلامه وآياته ( وَبُكِيًّا ) باكين ، فإن « بكى » على فَخَلَفَ مِنْ بَعْدِهِمْ خَلْفٌ أَضاعُوا الصَّلاةَ وَاتَّبَعُوا الشَّهَواتِ فَسَوْفَ يَلْقَوْنَ غَيًّا (59) إِلاَّ مَنْ تابَ وَآمَنَ وَعَمِلَ صالِحاً فَأُولئِكَ يَدْخُلُونَ الْجَنَّةَ وَلا يُظْلَمُونَ شَيْئاً (60) جَنَّاتِ عَدْنٍ الَّتِي وَعَدَ الرَّحْمنُ عِبادَهُ « فعول » جمع « باك » ونصب سجدا وبكي على الحال عن ضمير « خروا » . [60] فأولئك الأنبياء المختارون ، الذين يسجدون لتلاوة آيات الله ، وتفيض أعينهم من الدمع عند قراءة كتابه ( فَخَلَفَ مِنْ بَعْدِهِمْ خَلْفٌ ) جماعة من نسلهم وذريتهم ( أَضاعُوا الصَّلاةَ ) كاليهود خلف إسرائيل ، والمشركين من خلف إبراهيم عليه‌السلام ، وهكذا ( وَاتَّبَعُوا الشَّهَواتِ ) الملذات الزائلة ، إذا رأوها ذهبوا وراءها ، ليتبعوها ، أولئك الأخيار جاء من بعدهم هؤلاء الأشرار ( فَسَوْفَ يَلْقَوْنَ ) أي يلقى هذا الخلف ( غَيًّا ) ضلالا ، وضياعا في الدنيا بالعيش الضنك ، وفي الآخرة بالعذاب والنار ، أو المراد يلقون جزاء غيهم ، يقال فلان يرى عمله ، أي يرى جزاء عمله.` },
            { text: "فَخَلَفَ مِنۢ بَعْدِهِمْ خَلْفٌ أَضَاعُوا۟ ٱلصَّلَوٰةَ وَٱتَّبَعُوا۟ ٱلشَّهَوَٰتِ فَسَوْفَ يَلْقَوْنَ غَيًّا", tafsir: `` },
            { text: "إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًا فَأُو۟لَٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ وَلَا يُظْلَمُونَ شَيْـًٔا", tafsir: `عما سلف منه من المعاصي ( وَآمَنَ ) إيمانا صحيحا صادقا ( وَعَمِلَ صالِحاً ) في مقابل العمل السيئ ، الذي كان يعمله ( فَأُولئِكَ ) التائبون ( يَدْخُلُونَ الْجَنَّةَ وَلا يُظْلَمُونَ شَيْئاً ) لا يبخسون من جزاء أعمالهم الحسنة ، وإنما يعطى جزاؤهم كاملا غير منقوص. [62] ثم وصف سبحانه الجنة بقوله ( جَنَّاتِ عَدْنٍ ) والمراد بالجنة هناك الجنس ، ولذا صح وصفها بالجمع والعدن بمعنى الإقامة ، من عدن بالمكان ، إذا أقام فيه ( الَّتِي وَعَدَ الرَّحْمنُ ) المتفضل الراحم ( عِبادَهُ ) بِالْغَيْبِ إِنَّهُ كانَ وَعْدُهُ مَأْتِيًّا (61) لا يَسْمَعُونَ فِيها لَغْواً إِلاَّ سَلاماً وَلَهُمْ رِزْقُهُمْ فِيها بُكْرَةً وَعَشِيًّا (62) تِلْكَ المطيعين ( بِالْغَيْبِ ) أي وعدهم ، بما هو غائب عن حواسهم ، ولعل ذكر هذا الوصف ، لمدح المؤمنين بالجنة حيث أن العامل للغيب أكثر تحسينا من العامل لما يراه حاضر عنده ، أو لوصف الجنة ، كأنه يقال ، إن ما وعدتم به غائب لا تدرون ما هو ؟ ( إِنَّهُ ) تعالى ( كانَ وَعْدُهُ مَأْتِيًّا ) يأتي بالتأكيد ، ولا خلف فيه ، والمراد ب « وعده » أي ما وعد به ، أقيم المصدر مقام المفعول ، أو المراد وقت وعده.` },
            { text: "جَنَّٰتِ عَدْنٍ ٱلَّتِى وَعَدَ ٱلرَّحْمَٰنُ عِبَادَهُۥ بِٱلْغَيْبِ إِنَّهُۥ كَانَ وَعْدُهُۥ مَأْتِيًّا", tafsir: `` },
            { text: "لَّا يَسْمَعُونَ فِيهَا لَغْوًا إِلَّا سَلَٰمًا وَلَهُمْ رِزْقُهُمْ فِيهَا بُكْرَةً وَعَشِيًّا", tafsir: `أي لا يسمع المؤمنون ( فِيها ) في تلك الجنات ( لَغْواً ) كلاما بلا ثمر ، سواء كان من قبيل السب والاستهزاء ، أم من قبيل الكلمات التي لا فائدة فيها ( إِلَّا سَلاماً ) حيث يسلم الملائكة عليهم ، ويسلم بعضهم على بعض ، وهذا الاستثناء منقطع ، كأنه قال « لا يسمعون فيها شيئا إلا سلاما ولا يسمعون اللغو » والاستثناء من باب المثال ، وإلا فهناك يتكلم بعضهم مع بعض ، أو المراد بالسلام كل كلام فيه سلامة من الباطل واللغو والإيذاء وما أشبه ، فالمراد « السلام » وصفا ، لا لفظا ( وَلَهُمْ رِزْقُهُمْ فِيها ) في تلك الجنات ( بُكْرَةً ) صباحا ( وَعَشِيًّا ) مساء ، فإن ذينك الوقتين ، يتعارف فيهما الأكل لهم ، وإلا فلهم ما يشتهون في كل وقت ( أُكُلُها دائِمٌ ) (1) ثم إنه لا عشاء هناك ، إذ لا ليل ، وإنما ذلك من باب التشبيه.` },
            { text: "تِلْكَ ٱلْجَنَّةُ ٱلَّتِى نُورِثُ مِنْ عِبَادِنَا مَن كَانَ تَقِيًّا", tafsir: `التي ذكرت أوصافها ، بالخلود ، والتعدد ، والسلام ، ووفرة ( 1) الرعد : 36. الْجَنَّةُ الَّتِي نُورِثُ مِنْ عِبادِنا مَنْ كانَ تَقِيًّا (63) وَما نَتَنَزَّلُ إِلاَّ بِأَمْرِ رَبِّكَ لَهُ ما بَيْنَ أَيْدِينا وَما خَلْفَنا وَما بَيْنَ ذلِكَ وَما كانَ رَبُّكَ نَسِيًّا (64) رَبُّ السَّماواتِ وَالْأَرْضِ وَما بَيْنَهُما فَاعْبُدْهُ الأرزاق ، هي ( الْجَنَّةُ الَّتِي نُورِثُ مِنْ عِبادِنا ) أي نعطيه إرثا بعض عبادنا من ( مَنْ كانَ تَقِيًّا ) يتقي الكفر والآثام ، التي قلنا عنها ( فَأُولئِكَ يَدْخُلُونَ الْجَنَّةَ ) وإنما سمي إرثا ، لأنه يأتي الإنسان بعقب أعماله في الدنيا ، كما أن الإرث يأتي الإنسان بعقب موت قريب له ، أما النسب فلا يجدي إرثه في دخول الجنة فقد ورث أولئك الأنبياء خلف أضاعوا الصلاة فلم ينفعهم النسب في إرث الجنة.` },
            { text: "وَمَا نَتَنَزَّلُ إِلَّا بِأَمْرِ رَبِّكَ لَهُۥ مَا بَيْنَ أَيْدِينَا وَمَا خَلْفَنَا وَمَا بَيْنَ ذَٰلِكَ وَمَا كَانَ رَبُّكَ نَسِيًّا", tafsir: `نحن أهل الجنة محلا من الجنان ( إِلَّا بِأَمْرِ رَبِّكَ ) فالمواضع هناك معينة ، لأصحابها ، لا يتمكن أحد من التخلف عن موضعه ، وهذا من باب الالتفات من الغيبة إلى التكلم ـ حيث إن الكلام كان حول أهل الجنة ، وإن المتقين هم الوارثون لها ـ وما ذكرناه من أن الآية من كلام أهل الجنة هو الأنسب بالسياق ، وهناك قول آخر ، إن الآية حكاية عن كلام جبرائيل للرسول صلى‌الله‌عليه‌وآله‌وسلم حين قال له : ما منعك أن تزورنا أكثر مما تزورنا ؟ ( لَهُ ما بَيْنَ أَيْدِينا ) أي أمامنا ( وَما خَلْفَنا ) أي ورائنا ( وَما بَيْنَ ذلِكَ ) أي المحل الذي نحن فيه ، فإنه المالك المطلق للجنة ، ولا ينزل أحد في موضع منها ، إلا بإذنه وأمره ( وَما كانَ رَبُّكَ نَسِيًّا ) ينسى لأحد مقامه ، وما يستحقه ، بل يعطي كل واحد من الجنة المكان الذي هو بقدر عمله. [66] إنه ( رَبُّ السَّماواتِ وَالْأَرْضِ وَما بَيْنَهُما ) كما كان رب أمام الجنة وخلفها ، وما بينهما فهو المالك المطلق للكونين ( فَاعْبُدْهُ ) أيها وَاصْطَبِرْ لِعِبادَتِهِ هَلْ تَعْلَمُ لَهُ سَمِيًّا (65) وَيَقُولُ الْإِنْسانُ أَ إِذا ما مِتُّ لَسَوْفَ أُخْرَجُ حَيًّا (66) أَ وَلا يَذْكُرُ الْإِنْسانُ أَنَّا خَلَقْناهُ مِنْ قَبْلُ وَلَمْ يَكُ شَيْئاً (67) فَوَ رَبِّكَ لَنَحْشُرَنَّهُمْ وَالشَّياطِينَ ثُمَّ لَنُحْضِرَنَّهُمْ حَوْلَ جَهَنَّمَ جِثِيًّا (68) الإنسان ، أو أيها الرسول ( وَاصْطَبِرْ لِعِبادَتِهِ ) على تحمل المشاق ، ولا تكن كمن أضاع الصلاة ، واتبع الشهوات ، ( هَلْ تَعْلَمُ لَهُ سَمِيًّا ) أي من يسمى بكونه إلها ـ عن استحقاق ـ بمعنى أنه لا مثل له ، حتى يعلم ذلك ويعبد معه شريكا له. [67] إنه هو الله الواحد الذي لا شريك له ، له الأرض والسماء والجنة ، لكن الإنسان العاتي ، لا يعترف بالمعاد ، ويتعجب من أنه كيف يمكن إعادة الإنسان بعد الممات ! ( وَيَقُولُ الْإِنْسانُ ) والمراد به هذا النوع ، لأكل فرد منه ( أَ إِذا ما مِتُ ) « ما » زائدة ، لتزيين الكلام ( لَسَوْفَ أُخْرَجُ ) من قبري ( حَيًّا ) على نحو الاستفهام الإنكاري. [68] فرد عليه سبحانه بقوله ( أَ وَلا يَذْكُرُ الْإِنْسانُ ) المنكر للمعاد ( أَنَّا خَلَقْناهُ مِنْ قَبْلُ ) أي سابقا ـ قبل أن يكون هذا الكلام ـ ( وَ ) الحال أنه ( لَمْ يَكُ شَيْئاً ) فإن من يقدر على الابتداء يقدر على الإعادة.` },
            { text: "رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا فَٱعْبُدْهُ وَٱصْطَبِرْ لِعِبَٰدَتِهِۦ هَلْ تَعْلَمُ لَهُۥ سَمِيًّا", tafsir: `` },
            { text: "وَيَقُولُ ٱلْإِنسَٰنُ أَءِذَا مَا مِتُّ لَسَوْفَ أُخْرَجُ حَيًّا", tafsir: `` },
            { text: "أَوَلَا يَذْكُرُ ٱلْإِنسَٰنُ أَنَّا خَلَقْنَٰهُ مِن قَبْلُ وَلَمْ يَكُ شَيْـًٔا", tafsir: `` },
            { text: "فَوَرَبِّكَ لَنَحْشُرَنَّهُمْ وَٱلشَّيَٰطِينَ ثُمَّ لَنُحْضِرَنَّهُمْ حَوْلَ جَهَنَّمَ جِثِيًّا", tafsir: `يا رسول الله ( لَنَحْشُرَنَّهُمْ ) نجمعهم للحساب يوم القيامة ( وَالشَّياطِينَ ) نحشر الشياطين معهم ، لنجمع بين القادة والأتباع ، بين من كان يوسوس في صدورهم بعدم البعث ، والذين اتبعوهم في الإنكار ( ثُمَ ) بعد الحشر ( لَنُحْضِرَنَّهُمْ حَوْلَ جَهَنَّمَ ) في أطرافها ، في حال كونهم ( جِثِيًّا ) جمع جاثي ، وهو الذي برك على ركبتيه ، فإنهم ثُمَّ لَنَنْزِعَنَّ مِنْ كُلِّ شِيعَةٍ أَيُّهُمْ أَشَدُّ عَلَى الرَّحْمنِ عِتِيًّا (69) ثُمَّ لَنَحْنُ أَعْلَمُ بِالَّذِينَ هُمْ أَوْلى بِها صِلِيًّا (70) وَإِنْ مِنْكُمْ إِلاَّ وارِدُها هناك في صور مزرية مهانة مقترنين مع الشياطين ، جاثين على الركب ، تلفحهم نار الجحيم ، كالمجرم الذي يجثو مع سائر المجرمين حول السجن ، يرى الذل والصفاد ، وقد كان هذا جزائهم ، حيث تكبروا في الدنيا ، ولم يطيعوا الأوامر ، وأنكروا المعاد.` },
            { text: "ثُمَّ لَنَنزِعَنَّ مِن كُلِّ شِيعَةٍ أَيُّهُمْ أَشَدُّ عَلَى ٱلرَّحْمَٰنِ عِتِيًّا", tafsir: `لنستخرجن ( مِنْ كُلِّ شِيعَةٍ ) من كل جماعة ، شايعوا طريقة خاصة ( أَيُّهُمْ أَشَدُّ عَلَى الرَّحْمنِ عِتِيًّا ) « العتي » مصدر « كالعتو » وهو التمرد والعصيان ، أي نبدأ بالأعتى ، فالأعتى ، لنقلهم في جهنم أولا فأولا.` },
            { text: "ثُمَّ لَنَحْنُ أَعْلَمُ بِٱلَّذِينَ هُمْ أَوْلَىٰ بِهَا صِلِيًّا", tafsir: `هذا للتراخي في الكلام ، لا في الزمان ، وكأنه يأتى به للسياق والتناسب ( لَنَحْنُ أَعْلَمُ بِالَّذِينَ هُمْ أَوْلى بِها ) أي بالنار ( صِلِيًّا ) الصلي مصدر صلى يصلي ، يقال صلى اللحم يصليه صليا شواه وألقاه في النار للطبخ والإحراق ، ومثله أصلاه وصلّاه ، والمعنى أنه لا يجار على أحد هناك ، بل إنما يصلى الكافر والعاصي حسب عملهما.` },
            { text: "وَإِن مِّنكُمْ إِلَّا وَارِدُهَا كَانَ عَلَىٰ رَبِّكَ حَتْمًا مَّقْضِيًّا", tafsir: `أي ما منكم أحد أيها البشر ( إِلَّا وارِدُها ) أي مشرف عليها ، كما قال سبحانه : ( وَلَمَّا وَرَدَ ماءَ مَدْيَنَ ) (1) ، أي أشرف ، قال الصادق عليه‌السلام : أما تسمع الرجل يقول ، وردنا ماء بني فلان ، فهو الورود ولم يدخل (2) ، أقول : ولعل ذلك باعتبار العبور من جهنم على ( 1) القصص : 24. ( 2) بحار الأنوار : ج 8 ص 291. كانَ عَلى رَبِّكَ حَتْماً مَقْضِيًّا (71) ثُمَّ نُنَجِّي الَّذِينَ اتَّقَوْا وَنَذَرُ الظَّالِمِينَ فِيها جِثِيًّا (72) وَإِذا تُتْلى عَلَيْهِمْ آياتُنا بَيِّناتٍ قالَ الَّذِينَ كَفَرُوا لِلَّذِينَ آمَنُوا أَيُّ الْفَرِيقَيْنِ خَيْرٌ مَقاماً وَأَحْسَنُ نَدِيًّا (73) الصراط ، فإن العابر يقال له الوارد ، فمن عبر المدينة على مركوب له ، يقال : ورد بلدة فلان ( كانَ عَلى رَبِّكَ ) ورود الجميع ( حَتْماً ) لازما ( مَقْضِيًّا ) قد قضاه وقدره.` },
            { text: "ثُمَّ نُنَجِّى ٱلَّذِينَ ٱتَّقَوا۟ وَّنَذَرُ ٱلظَّٰلِمِينَ فِيهَا جِثِيًّا", tafsir: `الشرك والمعاصي ( وَنَذَرُ الظَّالِمِينَ ) الذين ظلموا أنفسهم بالكفر والمعاصي ، أو ظلموا غيرهم ( فِيها ) أي في النار ( جِثِيًّا ) باركين على ركبهم ، يريدون النهوض ، فلا يتمكنون ، كما لا يقدرون على الاستراحة ، فهم دائمو العذاب ، والمراد ب « نذر » نلقيهم فيها ، حتى يبقون في جهنم. [74] إن الظالمين هناك مصيرهم النار ، كما عرفنا ، فما كان عملهم ، حتى استحقوا هذه النار ؟ ( وَإِذا تُتْلى عَلَيْهِمْ آياتُنا ) أي الأدلة المنزلة في القرآن ، أو مطلقا ( بَيِّناتٍ ) في حال كونها واضحات الدلالة ( قالَ الَّذِينَ كَفَرُوا ) بالله والرسول ، وما جاء به ( لِلَّذِينَ آمَنُوا أَيُّ الْفَرِيقَيْنِ ) من المؤمنين والكافرين ( خَيْرٌ مَقاماً ) فهل مقامنا ، ومالنا من الدنيا خير أم مقامكم ومالكم في الدنيا ؟ ( وَ ) أينا ( أَحْسَنُ نَدِيًّا ) أي مجلسا ، فإن الكفار يتفاخرون على المسلمين ، بأنهم أحسن منهم حالا ، فما حصل المؤمنون من إيمانهم ؟ فلو كان الإيمان يقود الإنسان إلى السعادة فلما ذا نرى أن المؤمنين في ضنك وضيق والكفار في سعة وَكَمْ أَهْلَكْنا قَبْلَهُمْ مِنْ قَرْنٍ هُمْ أَحْسَنُ أَثاثاً وَرِءْياً (74) قُلْ مَنْ كانَ فِي الضَّلالَةِ فَلْيَمْدُدْ لَهُ الرَّحْمنُ مَدًّا حَتَّى إِذا رَأَوْا ما يُوعَدُونَ إِمَّا الْعَذابَ وَإِمَّا السَّاع َةَ ورفاه ؟ لكن هذه مغالطة ، فالمؤمنون إنما هم في ضيق لمدة يسيرة ومن جراء عدم تكالبهم على الدنيا ، مع إن من المؤمنين منعمين في الدنيا ، كما يرينا التاريخ ، وسيجزون هنالك بأحسن وأفضل من دنيا الكافرين ـ بالنسبة إلى هذه الفترة الضيقة أيضا ـ. [75] إن عاقبة الكفر لا بد وأن تكون الهلاك والدمار ، وأن تمشي في أيام قليلة على زخارف الدنيا وبهرجها ( وَكَمْ أَهْلَكْنا قَبْلَهُمْ ) أي قبل هؤلاء الكفار المعاصرين للرسول ( مِنْ قَرْنٍ ) من الأجيال البشرية ( هُمْ أَحْسَنُ ) من هؤلاء المتبجحون القائلون ( أَيُّ الْفَرِيقَيْنِ خَيْرٌ مَقاماً وَأَحْسَنُ نَدِيًّا ) ( أَثاثاً ) أي متاعا وزينة ( وَرِءْياً ) أي منظرا وهيئة ، فإن الله الذي أهلك الأمم ، التي كانت أكثر جمالا ومالا ، قادر على هلاك هؤلاء ، فليحدوا من كفرهم وكبرهم ، وإلا كان مصيرهم مصير أولئك.` },
            { text: "وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوٓا۟ أَىُّ ٱلْفَرِيقَيْنِ خَيْرٌ مَّقَامًا وَأَحْسَنُ نَدِيًّا", tafsir: `` },
            { text: "وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هُمْ أَحْسَنُ أَثَٰثًا وَرِءْيًا", tafsir: `` },
            { text: "قُلْ مَن كَانَ فِى ٱلضَّلَٰلَةِ فَلْيَمْدُدْ لَهُ ٱلرَّحْمَٰنُ مَدًّا حَتَّىٰٓ إِذَا رَأَوْا۟ مَا يُوعَدُونَ إِمَّا ٱلْعَذَابَ وَإِمَّا ٱلسَّاعَةَ فَسَيَعْلَمُونَ مَنْ هُوَ شَرٌّ مَّكَانًا وَأَضْعَفُ جُندًا", tafsir: `يا رسول الله لهؤلاء المتبجحين ( مَنْ كانَ فِي الضَّلالَةِ ) والكفر ( فَلْيَمْدُدْ لَهُ الرَّحْمنُ مَدًّا ) أي فدعه لأن يسعفه الله سبحانه بالمال والعمر وسائر الأمور المرتبطة بالدنيا ، وهذا تهديد في صورة الأمر ، كما نقول « دع الله يمهل الظالم » نريد أنه وإن أمهل لمصلحة ، فإن عاقبته لا بد وأن تكون إلى الخسار والفناء ، ( حَتَّى إِذا رَأَوْا ما يُوعَدُونَ ) أي أمهلهم سبحانه ، حتى جاء الوقت المقدر لأخذهم ( إِمَّا الْعَذابَ ) الذي يجعل لهم في الدنيا ( وَإِمَّا السَّاعَةَ ) بأن ماتوا فقامت فَسَيَعْلَمُونَ مَنْ هُوَ شَرٌّ مَكاناً وَأَضْعَفُ جُنْداً (75) وَيَزِيدُ اللهُ الَّذِينَ اهْتَدَوْا هُدىً وَالْباقِياتُ الصَّالِحاتُ خَيْرٌ عِنْدَ رَبِّكَ ثَواباً وَخَيْرٌ مَرَدًّا (76) قيامتهم ، وعذبوا في الآخرة ( فَسَيَعْلَمُونَ ) حين أخذ الله لهم ، إما بعذاب الدنيا أو عذاب الآخرة ( مَنْ هُوَ شَرٌّ مَكاناً ) هل مكان المؤمنين الناجين شرا أم مكانهم في العذاب ( وَ ) من هو ( أَضْعَفُ جُنْداً ) هل جند المؤمنين أضعف أم الكافرين ؟ إنهم هنالك يعرفون أيهما كان خير مقاما وأحسن نديا ، وهذا كما تقول للطالب الكسول ـ الذي يضحك من جدك في الدرس ـ ستعرف لدى الامتحان أينا أحسن ؟ [77] إن للمؤمنين العاقبة الحسنى ، إما في الدنيا ، أو في الآخرة ، وللكافرين العاقبة السيئة ، إما في الدنيا أو في الآخرة ، وبالإضافة إلى العاقبة الحسنى ، فالمؤمن يزداد هدى في هذه النشأة ، وله الباقيات في تلك النشأة ، فله ثلاث أقسام من الخير ، بينما ليس للكافر إلا الدنيا المنغصة لذاتها فقط ، ( وَيَزِيدُ اللهُ الَّذِينَ اهْتَدَوْا ) إلى الإيمان والإسلام ( هُدىً ) ورشادا ، فإن الإنسان في الدنيا يحتاج في كل خطوة هداية ورشادا ، وهكذا يأخذ الله بيد المهتدي في كل خطوة خطوة ، ليزيده هداية ( وَالْباقِياتُ ) أي الأعمال التي تبقى ( الصَّالِحاتُ ) مما قدمها الإنسان إلى آخرته ( خَيْرٌ عِنْدَ رَبِّكَ ثَواباً ) مما يصرفه الكفار في هذه الحياة من الملذات ( وَخَيْرٌ مَرَدًّا ) أي عاقبة ومنفعة ، من رد بمعنى رجع ، فإن ثواب ذلك أحسن من لذة الكفار ، وإن ما يرجع الإنسان المؤمن إليه في الآخرة من عمله خير مما يرجع الكافر ، والحاصل أن الكافر إذا أنفق درهما في الخمر التذ هنا ، وجوزي بالنار هناك ، وإن أَ فَرَأَيْتَ الَّذِي كَفَرَ بِآياتِنا وَقالَ لَأُوتَيَنَّ مالاً وَوَلَداً (77) أَطَّلَعَ الْغَيْبَ أَمِ اتَّخَذَ عِنْدَ الرَّحْمنِ عَهْداً (78) كَلاَّ المؤمن إذا أنفق درهما في الصدقة ، كان ثواب درهم أكثر لذة من لذة الخمر للكافر ، وجوزي هناك بالنعيم.` },
            { text: "وَيَزِيدُ ٱللَّهُ ٱلَّذِينَ ٱهْتَدَوْا۟ هُدًى وَٱلْبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيْرٌ عِندَ رَبِّكَ ثَوَابًا وَخَيْرٌ مَّرَدًّا", tafsir: `` },
            { text: "أَفَرَءَيْتَ ٱلَّذِى كَفَرَ بِـَٔايَٰتِنَا وَقَالَ لَأُوتَيَنَّ مَالًا وَوَلَدًا", tafsir: `، فنزلت هذه الآيات ( أَ فَرَأَيْتَ ) يا رسول الله ، وهذه الجملة تستعمل للتعجب ، أي هل رأيت كذا حتى تتعجب ( الَّذِي كَفَرَ بِآياتِنا ) وهو العاص ( وَقالَ لَأُوتَيَنَ ) في الجنة ( مالاً وَوَلَداً ) فقد كان الكفار يزعمون أنهم أهدى من الذين آمنوا سبيلا ، فإن كانت هناك جنة فلهم النصيب الأوفر فيها.` },
            { text: "أَطَّلَعَ ٱلْغَيْبَ أَمِ ٱتَّخَذَ عِندَ ٱلرَّحْمَٰنِ عَهْدًا", tafsir: `أي هل اطلع هذا القائل على الغيب ، فعرف أنه هناك ، يعطى الأموال والأولاد ؟ والأصل « أ أطلع » فلما دخلت همزة الاستفهام على الفعل الماضي من باب « الافتعال » ـ إذ الأصل « أتطلع » فأدغمت التاء في الطاء ـ سقطت همزة الوصل تخفيفا ( أَمِ اتَّخَذَ عِنْدَ الرَّحْمنِ عَهْداً ) بأن صارت بينه وبين الله معاهدة ، بأن له المال والولد هناك ؟ وإذا لم يكن أحد الأمرين ، فمن أين يقول : « لأوتين مالا وولدا » ؟` },
            { text: "كَلَّا سَنَكْتُبُ مَا يَقُولُ وَنَمُدُّ لَهُۥ مِنَ ٱلْعَذَابِ مَدًّا", tafsir: `ليس الأمر على ما زعم ، فإنه لا يعطى هناك مالا وولدا ، ( 1) المناقب : ج 1 ص 53. سَنَكْتُبُ ما يَقُولُ وَنَمُدُّ لَهُ مِنَ الْعَذابِ مَدًّا (79) وَنَرِثُهُ ما يَقُولُ وَيَأْتِينا فَرْداً (80) وَاتَّخَذُوا مِنْ دُونِ اللهِ آلِهَةً لِيَكُونُوا لَهُمْ عِزًّا (81) كَلاَّ و ( سَنَكْتُبُ ما يَقُولُ ) لنجازيه به في القيامة ، والمراد أمر الحفظة بكتابة مقاله ( وَنَمُدُّ لَهُ ) في الآخرة ( مِنَ الْعَذابِ مَدًّا ) فلا ينقطع عذابه ، وإنما يمتد أبد الدهر. [81] إنه هنالك لا يظفر بالمال والولد ، وماله وولده هنا أيضا ، يترك لنا ، فلا ينتفع بهما ( وَنَرِثُهُ ما يَقُولُ ) أي ما يتلفظ به من المال والولد ، إذ هو قال : « لأوتين مالا وولدا » ( وَيَأْتِينا فَرْداً ) هو وحده ، بلا شيء يفيده مما جمعه واتخذه هنا من أموال وأولاد ، إن العاص مثال الإنسان العاتي ، فكم له من أمثال من الكفار والمردة في هذه الحياة ، أرأيتهم حتى تأخذ العبرة منهم ، وتقف على عقولهم المتحجرة وأدمغتهم البليدة ؟ [82] ومن نقل كلامهم السخيف يعطف السياق نحو عقائدهم السخيفة ( وَاتَّخَذُوا مِنْ دُونِ اللهِ ) أي غير الله وسواه ( آلِهَةً ) المراد بذلك الجنس ، أي اتخذوا هذا الجنس ، حتى يشمل الفرد أيضا ، فإن كلا من الجنس والجمع ، ينوب مقام الآخر ـ كما سبق ـ ( لِيَكُونُوا ) أي تلك الآلهة ، وإنما جاء بلفظ العاقل ، جريا على مزاعم القوم ، فإنهم كانوا يطلقون عليها لفظ العاقل ( لَهُمْ ) أي لهؤلاء الكفار ( عِزًّا ) فقد كانوا يعتزون بالآلهة في الدنيا ، ويظنون أنهم شفعاء لهم في الآخرة.` },
            { text: "وَنَرِثُهُۥ مَا يَقُولُ وَيَأْتِينَا فَرْدًا", tafsir: `` },
            { text: "وَٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ ءَالِهَةً لِّيَكُونُوا۟ لَهُمْ عِزًّا", tafsir: `` },
            { text: "كَلَّا سَيَكْفُرُونَ بِعِبَادَتِهِمْ وَيَكُونُونَ عَلَيْهِمْ ضِدًّا", tafsir: `ليس الأمر كما ظنوا ، فليست الأصنام ، إلا سبب ذلهم سَيَكْفُرُونَ بِعِبادَتِهِمْ وَيَكُونُونَ عَلَيْهِمْ ضِدًّا (82) أَ لَمْ تَرَ أَنَّا أَرْسَلْنَا الشَّياطِينَ عَلَى الْكافِرِينَ تَؤُزُّهُمْ أَزًّا (83) فَلا تَعْجَلْ عَلَيْهِمْ إِنَّما نَعُدُّ لَهُمْ عَدًّا (84) وانحطاطهم في الدنيا ، وفي الآخرة ، أما في الدنيا فقد كشفت عن سخافة عقولهم ، وأما في الآخرة ف ( سَيَكْفُرُونَ بِعِبادَتِهِمْ ) لهذه الآلهة ، فإنهم هناك يحلفون ( وَاللهِ رَبِّنا ما كُنَّا مُشْرِكِينَ ) (1) ( وَيَكُونُونَ ) هؤلاء المشركون ( عَلَيْهِمْ ) أي على تلك الآلهة ( ضِدًّا ) ومعارضا ، أو المراد أن الآلهة تكون جاحدة للمشركين ، حيث يقولون : ( تَبَرَّأْنا إِلَيْكَ ما كانُوا إِيَّانا يَعْبُدُونَ ) (2) وأنهم يكونون ضدا للمشركين ، كما قال سبحانه : ( إِذْ تَبَرَّأَ الَّذِينَ اتُّبِعُوا مِنَ الَّذِينَ اتَّبَعُوا ) (3) .` },
            { text: "أَلَمْ تَرَ أَنَّآ أَرْسَلْنَا ٱلشَّيَٰطِينَ عَلَى ٱلْكَٰفِرِينَ تَؤُزُّهُمْ أَزًّا", tafsir: `يا رسول الله ( أَنَّا أَرْسَلْنَا الشَّياطِينَ عَلَى الْكافِرِينَ ) أي خلينا بينهم وبين الكفار ليسيئوا إليهم ما يشاءون ، يقال لمن خلى بين كلبه وبين عدوه ليؤذيه : أرسل كلبه عليه ، حيث كان بإمكانه أن يمنعه ، فلم يمنعه ( تَؤُزُّهُمْ ) أي تزعجهم ( أَزًّا ) إزعاجا وتغريهم بالشر والعصيان ، فكما قد فعلنا هذا بالكفار ـ جزاء إعراضهم عن الحق ـ كذلك نفعل بهم في الآخرة ، ونمدهم من العذاب مدا.` },
            { text: "فَلَا تَعْجَلْ عَلَيْهِمْ إِنَّمَا نَعُدُّ لَهُمْ عَدًّا", tafsir: `يا رسول الله ( عَلَيْهِمْ ) بأن تطلب لهم من الله العذاب ، فإنهم مأخوذون لا محالة ، وإنما التأخير ليزدادوا إثما ( إِنَّما نَعُدُّ لَهُمْ ) أي نحسب أعمالهم ( عَدًّا ) تأكيد في العد ، حتى نعطيهم جزاء عملهم في الآخرة. ( 1) الأنعام : 24. ( 2) القصص : 64. ( 3) البقرة : 167. يَوْمَ نَحْشُرُ الْمُتَّقِينَ إِلَى الرَّحْمنِ وَفْداً (85) وَنَسُوقُ الْمُجْرِمِينَ إِلى جَهَنَّمَ وِرْداً (86) لا يَمْلِكُونَ الشَّفاعَةَ إِلاَّ مَنِ اتَّخَذَ عِنْدَ الرَّحْمنِ عَهْداً (87) وَقالُوا اتَّخَذَ الرَّحْمنُ وَلَداً (88) [86] وسيرون جزاؤهم في يوم القيامة ( يَوْمَ نَحْشُرُ الْمُتَّقِينَ ) أي نجمع المتقين الذين اتقوا الكفر والآثام ( إِلَى الرَّحْمنِ وَفْداً ) ومعنى إلى الرحمن إلى دار كرامته وفضله ، والوفد جمع وافد ، بمعنى المشرف ، ويستعمل في الجماعة التي تذهب من مكان إلى مكان.` },
            { text: "يَوْمَ نَحْشُرُ ٱلْمُتَّقِينَ إِلَى ٱلرَّحْمَٰنِ وَفْدًا", tafsir: `` },
            { text: "وَنَسُوقُ ٱلْمُجْرِمِينَ إِلَىٰ جَهَنَّمَ وِرْدًا", tafsir: `كالدواب التي تساق من خلفها ، والمراد بالمجرم الذي أتى بالجريمة ( إِلى جَهَنَّمَ وِرْداً ) حال من المجرمين ، والورد هي الجماعة التي ترد الماء ، أي أنهم يردون جهنم ، كالإبل العطاش التي ترد الماء.` },
            { text: "لَّا يَمْلِكُونَ ٱلشَّفَٰعَةَ إِلَّا مَنِ ٱتَّخَذَ عِندَ ٱلرَّحْمَٰنِ عَهْدًا", tafsir: `أي لا يملك المجرمون ( الشَّفاعَةَ ) فلا يتمكنون أن يشفعون لغيرهم ، ولا يتمكن أحد أن يشفع لهم ( إِلَّا مَنِ اتَّخَذَ عِنْدَ الرَّحْمنِ عَهْداً ) يعني إلا الذين كانت بينهم وبين الله سبحانه ، معاهدة ، بأن يطيعه ويعطيه الجزاء الحسن ، فإنه هو الذي يملك أن يشفع إذا كان صالحا ، أو يشفع له إذا صدرت منه زلات ، والاستثناء منقطع ، والتقدير لا يملك أحد الشفاعة إلا هؤلاء ، أما المجرمون فلا يملكونها. [89] وكيف يملك الشفاعة من جاهر الله بالكفر والعصيان ( وَقالُوا اتَّخَذَ الرَّحْمنُ وَلَداً ) بأن جعل المسيح ، أو العزير ، أو الملائكة ولدا له ، كما تقول النصارى واليهود والمشركون. لَقَدْ جِئْتُمْ شَيْئاً إِدًّا (89) تَكادُ السَّماواتُ يَتَفَطَّرْنَ مِنْهُ وَتَنْشَقُّ الْأَرْضُ وَتَخِرُّ الْجِبالُ هَدًّا (90) أَنْ دَعَوْا لِلرَّحْمنِ وَلَداً (91) وَما يَنْبَغِي لِلرَّحْمنِ أَنْ يَتَّخِذَ وَلَداً (92) إِنْ كُلُّ مَنْ فِي السَّماواتِ وَالْأَرْضِ إِلاَّ آتِي الرَّحْمنِ عَبْداً (93)` },
            { text: "وَقَالُوا۟ ٱتَّخَذَ ٱلرَّحْمَٰنُ وَلَدًا", tafsir: `` },
            { text: "لَّقَدْ جِئْتُمْ شَيْـًٔا إِدًّا", tafsir: `أيها القائلون بهذه المقالات ( شَيْئاً إِدًّا ) الإد الأمر العظيم ، أي لقد قلتم بمقالة عظيمة القبح منكرة ، فكيف يتخذ الله ولدا ؟` },
            { text: "تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرْنَ مِنْهُ وَتَنشَقُّ ٱلْأَرْضُ وَتَخِرُّ ٱلْجِبَالُ هَدًّا", tafsir: `أي يتشققن ( مِنْهُ ) من هذا الكلام ، والمعنى لو كانت السماوات تنشق ، وتخرق من قول منكر لكانت تنشق من هذا الكلام ( وَ ) كادت ( تَنْشَقُّ الْأَرْضُ ) تفطر وتتشقق ( وَ ) كادت ( تَخِرُّ الْجِبالُ ) أي تسقط على الأرض ( هَدًّا ) أي كسرا شديدا ، فإن الهد الهدم بصوت شديد. [92] كاد كل ذلك ل ( أَنْ دَعَوْا ) هؤلاء الكفار ( لِلرَّحْمنِ وَلَداً ) ومعنى دعوا ، أي سموا وجعلوا.` },
            { text: "أَن دَعَوْا۟ لِلرَّحْمَٰنِ وَلَدًا", tafsir: `` },
            { text: "وَمَا يَنۢبَغِى لِلرَّحْمَٰنِ أَن يَتَّخِذَ وَلَدًا", tafsir: `الحال أنه ( ما يَنْبَغِي ) أي لا يمكن ( لِلرَّحْمنِ أَنْ يَتَّخِذَ وَلَداً ) فإن الولد الحقيقي غير معقول ، والولد بالتبني لا يصلح لأنه عبث لغو ، والحكيم منزه عن ذلك.` },
            { text: "إِن كُلُّ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ إِلَّآ ءَاتِى ٱلرَّحْمَٰنِ عَبْدًا", tafsir: `، ما ( كُلُّ مَنْ فِي السَّماواتِ وَالْأَرْضِ ) من الأنس والجن والملائكة ( إِلَّا آتِي الرَّحْمنِ عَبْداً ) فكيف يمكن للعبد أن يكون ولدا ؟ و « آتي » هنا مثل قوله : ( قالَتا أَتَيْنا طائِعِينَ ) (1) أي أنهم عبيد لله سبحانه ( 1) فصلت : 12. لَقَدْ أَحْصاهُمْ وَعَدَّهُمْ عَدًّا (94) وَكُلُّهُمْ آتِيهِ يَوْمَ الْقِيامَةِ فَرْداً (95) إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ سَيَجْعَلُ لَهُمُ الرَّحْمنُ وُدًّا (96) تكوينا وخلقة ، فليس له منهم أولاد. [95] إن الجميع يأتون الله عبيدا ف ( لَقَدْ أَحْصاهُمْ ) الله سبحانه ( وَعَدَّهُمْ عَدًّا ) فلا أحد منهم يتمكن أن لا يأتيه ، ولعل الفرق بين الإحصاء والعد ، إن الأول الحساب والإحاطة بهم في الجملة ، فإن الإحصاء بمعنى الضبط ، وذلك لا يلازم التعداد الدقيق.` },
            { text: "لَّقَدْ أَحْصَىٰهُمْ وَعَدَّهُمْ عَدًّا", tafsir: `` },
            { text: "وَكُلُّهُمْ ءَاتِيهِ يَوْمَ ٱلْقِيَٰمَةِ فَرْدًا", tafsir: `أي كل من في السماوات والأرض ( آتِيهِ ) يأتيه ( يَوْمَ الْقِيامَةِ فَرْداً ) غير متصل بعشيرته ، وخدمه وأصدقائه ، ممن كان كذلك ، كيف يمكن أن يكون ابنا لله سبحانه ، وهل الابن ، إلا مكرم محترم ، لا يعد في جملة العبيد ، ولا يساق مساقهم ؟ [97] إن الهول ليأخذ بنواد الإنسان حين يسمع هذا العد والإتيان ، فهل المؤمنون أيضا يقاسون هذا الهول والوحشة ؟ كلا ! ف ( إِنَّ الَّذِينَ آمَنُوا ) إيمانا صحيحا بالأصول العقائدية ( وَعَمِلُوا الصَّالِحاتِ ) أي الأعمال الصالحة ، وقد ذكرنا سابقا أن ذلك يلازم ـ عرفا ـ عدم الإتيان بالسيئات ( سَيَجْعَلُ لَهُمُ الرَّحْمنُ وُدًّا ) أي سيحيطهم بالمودة والحب ، ففي الدنيا يحبهم الناس ، وفي الآخرة يحاطون بود الله سبحانه لهم ، وود الملائكة إياهم ، وود الشفعاء والأنبياء والأئمة لهم ، وهل يستوحش من يحاط بمثل هذا الود ؟ وما ورد من تفسير الآية من ( إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ ) ، هو الإمام المرتضى ، فهو من باب بيان المصداق فَإِنَّما يَسَّرْناهُ بِلِسانِكَ لِتُبَشِّرَ بِهِ الْمُتَّقِينَ وَتُنْذِرَ بِهِ قَوْماً لُدًّا (97) وَكَمْ أَهْلَكْنا قَبْلَهُمْ مِنْ قَرْنٍ هَلْ تُحِسُّ مِنْهُمْ مِنْ أَحَدٍ أَوْ تَسْمَعُ لَهُمْ رِكْزاً (98) البارز ، وإلا فالرسول ، وسائر الأئمة ، والصديقة ، والمؤمنون كلهم داخلون في هذا العموم. [98] إن هذه البشرى للمؤمنين ، وذلك الإنذار للكافرين والقرآن ميسر بلسان العرب ، ليعرفه من حول الرسول صلى‌الله‌عليه‌وآله‌وسلم أولا ، ثم يحملوه إلى سائر الناس ثانيا ( فَإِنَّما يَسَّرْناهُ ) أي سهلنا القرآن لك حيث إنه ( بِلِسانِكَ ) وعلى لغتك ، حتى تتمكن من التفهيم له بالنسبة إلى العرب المحيطين بك ( لِتُبَشِّرَ بِهِ ) بهذا القرآن ( الْمُتَّقِينَ ) تبشرهم بالجنة والثواب ( وَتُنْذِرَ بِهِ ) بسبب القرآن ( قَوْماً لُدًّا ) اللد جمع ألد ، وهو المخاصم الشديد الخصومة ، والقرآن مبشر لكل مؤمن ، وإن لم يكن متقيا ، ومنذر لكل كافر ، وإن لم يكن لدا ، إلا أن البشارة الكاملة ، والإنذار الشديد للطائفتين.` },
            { text: "إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَيَجْعَلُ لَهُمُ ٱلرَّحْمَٰنُ وُدًّا", tafsir: `` },
            { text: "فَإِنَّمَا يَسَّرْنَٰهُ بِلِسَانِكَ لِتُبَشِّرَ بِهِ ٱلْمُتَّقِينَ وَتُنذِرَ بِهِۦ قَوْمًا لُّدًّا", tafsir: `` },
            { text: "وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هَلْ تُحِسُّ مِنْهُم مِّنْ أَحَدٍ أَوْ تَسْمَعُ لَهُمْ رِكْزًۢا", tafsir: `` }
        ]
    },
    20: { // سورة طه
        name: "طه",
        basmalaTafsir: ``,
        verses: [
            { text: "طه", tafsir: `فيه أقوال : منها أنه رمز بين الله والرسول ، ومنها أن المراد : أن القرآن المعجز مؤلف من « طاء » و « هاء » وسائر حروف الهجاء ، التي هي من جنسهما ، ومنها أنه اسم للرسول الأكرم صلى‌الله‌عليه‌وآله‌وسلم قال الصادق عليه‌السلام : « وأما طه : فاسم من أسماء النبي صلى‌الله‌عليه‌وآله‌وسلم ومعناه : يا طالب الحق الهادي إليه » (1) .` },
            { text: "مَآ أَنزَلْنَا عَلَيْكَ ٱلْقُرْءَانَ لِتَشْقَىٰٓ", tafsir: `يا رسول الله ( الْقُرْآنَ لِتَشْقى ) الشقاء استمرار ما يشق على النفس ، والسعادة عكسه ، أي لم يكن نزول القرآن عليك لأجل شقائك وإنما لأجل سعادتك وراحتك. فقد روي عن الإمام الكاظم عن آبائه عن أمير المؤمنين عليهم‌السلام أنه قال : لقد قام رسول الله صلى‌الله‌عليه‌وآله‌وسلم عشر سنين على أطراف أصابعه حتى تورمت قدماه واصفر وجهه ، يقوم الليل أجمع ، فقال الله عزوجل : ( طه ما أَنْزَلْنا عَلَيْكَ الْقُرْآنَ لِتَشْقى ) بل لتسعد به (2) .` },
            { text: "إِلَّا تَذْكِرَةً لِّمَن يَخْشَىٰ", tafsir: `أي إنما هو تذكرة وذكرى ( لِمَنْ يَخْشى ) الله سبحانه ، والتذكرة والتذكير مصدران لباب التفعيل ، وإنما كان تذكرة لأن الأصول والفروع بصورتها الإجمالية كامنة في نفس كل إنسان. [5] وقد نزل ( تَنْزِيلاً مِمَّنْ خَلَقَ الْأَرْضَ ) وإنما كان تنزيلا لأن الله سبحانه أعلى مرتبة عن البشر فما يأتي منه تنزيل وإن لم يكن علو خارجي ، أو باعتبار إتيان جبرائيل به من السماء ( وَالسَّماواتِ الْعُلى ) أي الرفيعة ( 1) بحار الأنوار : ج 16 ص 86. ( 2) المستدرك : ج 4 ص 118. الرَّحْمنُ عَلَى الْعَرْشِ اسْتَوى (5) لَهُ ما فِي السَّماواتِ وَما فِي الْأَرْضِ وَما بَيْنَهُما وَما تَحْتَ الثَّرى (6) وَإِنْ تَجْهَرْ بِالْقَوْلِ فَإِنَّهُ يَعْلَمُ السِّرَّ وَأَخْفى (7) العالية ، وهو جمع العلياء ، كالدنى جمع الدنيا ، مؤنث الأعلى والأدنى ، فالذي خلق الكون هو الذي أرسل هذا المنهاج ، فما أجدر به أن يتبع منهاج المالك العالم. [6] وهو ( الرَّحْمنُ ) الذي يترحم ويتفضل فله الخلق والرحم ( عَلَى الْعَرْشِ اسْتَوى ) أي استولى وهو كناية عن المالكية المطلقة ، يقال جلس الملك على العرش أي استولى وسيطر على المملكة.` },
            { text: "تَنزِيلًا مِّمَّنْ خَلَقَ ٱلْأَرْضَ وَٱلسَّمَٰوَٰتِ ٱلْعُلَى", tafsir: `` },
            { text: "ٱلرَّحْمَٰنُ عَلَى ٱلْعَرْشِ ٱسْتَوَىٰ", tafsir: `` },
            { text: "لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَمَا بَيْنَهُمَا وَمَا تَحْتَ ٱلثَّرَىٰ", tafsir: `ظرفا ومظروفا ، وقد تقدم أنه قد يطلق أحدهما ويراد به الأمران ( وَما فِي الْأَرْضِ ) مما قرب منهما كالإنسان والحيوان والنبات والأنهار وغيرهما ( وَما بَيْنَهُما ) من الفضاء ، والهواء ، وسائر الأشياء المتوسطة بينهما ( وَما تَحْتَ الثَّرى ) وهو التراب ، وما تحته كالمعادن والكنوز وهذا لتأكيد كونه مالكا مطلقا لكل شيء. [8] وهو بالإضافة إلى كونه خالقا مالكا راحما مستوليا ، عالما بكل شيء ( وَإِنْ تَجْهَرْ ) يا رسول الله أو كل من يأتي منه الجهر ( بِالْقَوْلِ ) بأن ترفع صوتك بما تقول ، وقد أطلق « تجهر » وأريد منه « إرادة الجهر » أي لا حاجة إلى الجهر في الدعاء ( فَإِنَّهُ ) سبحانه ( يَعْلَمُ السِّرَّ ) الذي يناجي به أحدنا غيره ( وَأَخْفى ) من السر كالذي في الصدور من الأفكار والوساوس ، فقد خلق هو سبحانه جهر الكون وسره « وهو ما تحت الثرى » ويعلم جهر الصوت وسره والأخفى من السر ، و قد روي اللهُ لا إِلهَ إِلاَّ هُوَ لَهُ الْأَسْماءُ الْحُسْنى (8) وَهَلْ أَتاكَ حَدِيثُ مُوسى (9) إِذْ رَأى ناراً فَقالَ لِأَه ْلِهِ امْكُثُوا عن الإمامين الباقر والصادق عليهما‌السلام : إن السر ما أخفيته من نفسك وأخفى منه ما خطر ببالك ثم نسيته (1) . [9] إن هذه كلها صفات ل ( اللهُ ) الذي ( لا إِلهَ إِلَّا هُوَ ) فلا شريك له ( لَهُ الْأَسْماءُ الْحُسْنى ) أي الأسماء الحسنة كالخالق والرازق ، والمنعم وما أشبه ، مقابل أسماء السوء كالظالم والفاسق والجائر ونحوها ، و « حسنى » مؤنث أحسن ، جيء مؤنثا باعتبار الجمع. [10] ثم يأتي السياق لعرض جانب من جوانب قصة موسى ، فإن هذه القصة توافق المسلمين من بدء ولادة الإسلام إلى يوم الرجعة ، فما أحوجهم بالتملي منها ، والاعتبار بها ، وقد تكررت هذه القصة في القرآن بأساليب مختلفة وصور متنوعة ، والغالب الإشارة في كل قصة منها إلى جانب من الجوانب وبمناسبة من المناسبات ( وَهَلْ أَتاكَ ) يا رسول الله ( حَدِيثُ مُوسى ) ؟ وهذا استفهام تقريري ، نحو قول أحدنا لغيره هل سمعت بخبر فلان ؟` },
            { text: "وَإِن تَجْهَرْ بِٱلْقَوْلِ فَإِنَّهُۥ يَعْلَمُ ٱلسِّرَّ وَأَخْفَى", tafsir: `` },
            { text: "ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ لَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ", tafsir: `` },
            { text: "وَهَلْ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ", tafsir: `` },
            { text: "إِذْ رَءَا نَارًا فَقَالَ لِأَهْلِهِ ٱمْكُثُوٓا۟ إِنِّىٓ ءَانَسْتُ نَارًا لَّعَلِّىٓ ءَاتِيكُم مِّنْهَا بِقَبَسٍ أَوْ أَجِدُ عَلَى ٱلنَّارِ هُدًى", tafsir: `فإن موسى عليه‌السلام لما فر من فرعون جاء إلى مدين وتزوج هناك بابنة شعيب ، ثم استأذن شعيب في الخروج إلى أمه فخرج بأهله فلما وافى وادي طور وفيه الطور ولد له ابن في ليلة شاتية مظلمة مثلجة ، وقد أضل الطريق وتفرقت ماشيته فرأى من جانب الطور ما يشبه النار حتى ظنها نارا ( فَقالَ لِأَهْلِهِ امْكُثُوا ) أي الزموا مكانكم ( 1) راجع بحار الأنوار : ج 4 ص 79. إِنِّي آنَسْتُ ناراً لَعَلِّي آتِيكُمْ مِنْها بِقَبَسٍ أَوْ أَجِدُ عَلَى النَّارِ هُدىً (10) فَلَمَّا أَتاها نُودِيَ يا مُوسى (11) إِنِّي أَنَا رَبُّكَ فَاخْلَعْ نَعْلَيْكَ إِنَّكَ بِالْوادِ الْمُقَدَّسِ طُوىً (12) وَأَنَا اخْتَرْتُكَ فَاسْتَمِعْ قليلا ( إِنِّي آنَسْتُ ناراً ) أي أبصرت نارا هناك ، فإن الإيناس وجدان الشيء الذي يؤنس به ( لَعَلِّي آتِيكُمْ مِنْها ) من تلك النار ( بِقَبَسٍ ) شعلة أقتبسها وآخذها لندفأ ونصطلي ( أَوْ أَجِدُ عَلَى النَّارِ هُدىً ) أي أجد على النار هاديا يدلني على الطريق ، فإن النار غالبا لا تخلو من أهل عند ما أشعلوها.` },
            { text: "فَلَمَّآ أَتَىٰهَا نُودِىَ يَٰمُوسَىٰٓ", tafsir: `أي جاء موسى إلى النار وجدها تتقد في شجرة ( نُودِيَ ) من طرف الشجرة ( يا مُوسى ) .` },
            { text: "إِنِّىٓ أَنَا۠ رَبُّكَ فَٱخْلَعْ نَعْلَيْكَ إِنَّكَ بِٱلْوَادِ ٱلْمُقَدَّسِ طُوًى", tafsir: `المتكلم معك ( أَنَا رَبُّكَ ) وقد علم موسى صدق الكلام لخوارق ظهرت عند ذلك مما دلت على أن النداء ليس إلا من جانبه سبحانه ( فَاخْلَعْ نَعْلَيْكَ ) أي انزعهما ، فإن الإنسان إذا أراد أن يمشي في محل مقدس كان من الاحترام أن يمشي حافيا ( إِنَّكَ ) يا موسى ( بِالْوادِ الْمُقَدَّسِ ) أي المنزه عن الأنجاس ( طُوىً ) اسم الوادي ، أو لأنه طوي بالقدس مرتين ، مرة بتقديس الأرواح واصطفاء الملائكة ، ومرة باصطفاء موسى ، وتكليم الله معه ، فقد روي عن النبي صلى‌الله‌عليه‌وآله‌وسلم إنه سئل عن الوادي المقدس ؟ فقال : لأنه قدست فيه الأرواح واصطفيت فيه الملائكة ، وكلّم الله عزوجل موسى تكليما (1) .` },
            { text: "وَأَنَا ٱخْتَرْتُكَ فَٱسْتَمِعْ لِمَا يُوحَىٰٓ", tafsir: `أي اصطفيتك للرسالة ( فَاسْتَمِعْ ) يا موسى ( 1) بحار الأنوار : ج 13 ص 66. لِما يُوحى (13) إِنَّنِي أَنَا اللهُ لا إِلهَ إِلاَّ أَنَا فَاعْبُدْنِي وَأَقِمِ الصَّلاةَ لِذِكْرِي (14) إِنَّ السَّاعَةَ آتِيَةٌ أَكادُ أُخْفِيها لِتُجْزى كُلُّ نَفْسٍ بِما تَسْعى (15) ( لِما يُوحى ) إليك من كلامه ، فاصغه واعمل به. [15] ولما استعد موسى عليه‌السلام للاستماع أوحى إليه الله قائلا : ( إِنَّنِي ) المتكلم معك ( أَنَا اللهُ لا إِلهَ إِلَّا أَنَا ) فلا شريك لي ولا مثيل ( فَاعْبُدْنِي ) أي ائت برسوم العبودية لأجلي خالصا ( وَأَقِمِ الصَّلاةَ ) ائت بها كاملة بآدابها وشروطها ( لِذِكْرِي ) لأن تذكرني بالتسبيح والتحميد والتكبير والتهليل والتمجيد ، فإن الصلاة إنما شرعت لكونها ذكر الله سبحانه. [16] هذا حول المبدأ ، أما المعاد ( إِنَّ السَّاعَةَ ) يوم القيامة الذي يحشر فيه الخلائق ( آتِيَةٌ ) لا محالة ( أَكادُ أُخْفِيها ) قد يعبر بهذا التعبير لبيان أن الشيء ظاهر ولكن المتكلم يريد إخفاءه ، يقول أكاد أخفي قلمي ـ فيما إذا كان ظاهرا ـ وقد يعبر لبيان أن الشيء ظاهر قريب بإخفاء ، فهو كالشيء الذي يراد إخفاءه ، ليس ظاهرا كل الظهور ، ولا مخفيا كل الإخفاء ، والظاهر أن هذا المعنى هو المراد هنا ، إذ الساعة بين الظهور والخفاء ، فأصلها ظاهر ، ووقتها مخفي ، وإنما يراد إخفاءها بهذا المقدار ( لِتُجْزى كُلُّ نَفْسٍ بِما تَسْعى ) فإن الساعة لو كانت ظاهرة لكل أحد لم يكن سعي الناس في الطاعة إلا خوفا من العاقبة الحتمية المعلومة لديهم ، أما إذا كانت مخفية ـ ولو في الجملة ـ كان الجزاء حسب السعي الطبيعي ، لا السعي الجبري ، وقد كان من حكم إخفاء الساعة إن الإنسان لا يدري متى تأتي فهو بين خوف ورجاء ، ألا ترى فَلا يَصُدَّنَّكَ عَنْها مَنْ لا يُؤْمِنُ بِها وَاتَّبَعَ هَواهُ فَتَرْدى (16) وَما تِلْكَ بِيَمِينِكَ يا مُوسى (17) قالَ هِيَ عَصايَ أَتَوَكَّؤُا عَلَيْها وَأَهُشُّ بِها عَلى غَنَمِي وَلِيَ فِيها مَآرِبُ أُخْرى (18) أن الموت لو كان معلوم الوقت ، كان هذا العالم بغير هذا الشكل الذي نراه إذ وقف من قرب أجله عن العمل ، وغلا من بعد في الإسراف والتبذير ، وهكذا ، ومعنى بما تسعى : ما تعمل من خير أو شر.` },
            { text: "إِنَّنِىٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعْبُدْنِى وَأَقِمِ ٱلصَّلَوٰةَ لِذِكْرِىٓ", tafsir: `` },
            { text: "إِنَّ ٱلسَّاعَةَ ءَاتِيَةٌ أَكَادُ أُخْفِيهَا لِتُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا تَسْعَىٰ", tafsir: `` },
            { text: "فَلَا يَصُدَّنَّكَ عَنْهَا مَن لَّا يُؤْمِنُ بِهَا وَٱتَّبَعَ هَوَىٰهُ فَتَرْدَىٰ", tafsir: `لا يمنعنك يا موسى ( عَنْها ) عن الساعة ، والمراد عن الاستعداد والتهيؤ لها ( مَنْ لا يُؤْمِنُ بِها ) بأن يوسوس إليك لتترك التهيؤ والعمل لأجلها ( وَاتَّبَعَ هَواهُ ) بأن عمل حسب ما يشتهيه لا حسب ما ينقذه عند الساعة ( فَتَرْدى ) أي تهلك كما هلك الذي لا يؤمن. [18] ثم خاطبه سبحانه بقوله : ( وَما تِلْكَ ) ما هذا الشيء الذي ( بِيَمِينِكَ ) في يدك اليمنى ( يا مُوسى ) ؟ وقد علم الله ما في يده ، ولذا قال ( ما تِلْكَ ) بالإشارة إلى المؤنث رعاية لكون العصا مؤنثة ، وإنما أراد توجيه موسى عليه‌السلام إليها ، ليوقع المعجز بها.` },
            { text: "وَمَا تِلْكَ بِيَمِينِكَ يَٰمُوسَىٰ", tafsir: `` },
            { text: "قَالَ هِىَ عَصَاىَ أَتَوَكَّؤُا۟ عَلَيْهَا وَأَهُشُّ بِهَا عَلَىٰ غَنَمِى وَلِىَ فِيهَا مَـَٔارِبُ أُخْرَىٰ", tafsir: `موسى عليه‌السلام في الجواب ( هِيَ عَصايَ أَتَوَكَّؤُا عَلَيْها ) أعتمد عليها في مشيي ، فإن التوكؤ بمعنى التحامل على العصا في المشي ، والتوكؤ والاتكاء بمعنى واحد ، كالتوقي والاتقاء ( وَأَهُشُّ بِها ) والهش ضرب ورق الشجر ليتساقط ، أي أسقط بها ورق الشجر ( عَلى غَنَمِي ) أي لغنمي ، وحيث إن الورق يقع من فوق على الغنم جيء ب «على » ( وَلِيَ فِيها ) في العصا ( مَآرِبُ ) جمع مأرب وهي الحاجة ( أُخْرى ) قالَ أَلْقِها يا مُوسى (19) فَأَلْقاها فَإِذا هِيَ حَيَّةٌ تَسْعى (20) قالَ خُذْها وَلا تَخَفْ سَنُعِيدُها سِيرَتَهَا الْأُولى (21) وَاضْمُمْ يَدَكَ إِلى جَناحِكَ تَخْرُجْ بَيْضاءَ مِنْ غَيْرِ سُوءٍ آيَةً أُخْرى (22) وإنما جاء المفرد صفة الجمع ، باعتبار الجماعة ، كصرد السباع ، ومحاربة اللصوص ، وتركيزها لإلقاء شيء عليها وقاية من الشمس وغيرها.` },
            { text: "قَالَ أَلْقِهَا يَٰمُوسَىٰ", tafsir: `الله سبحانه ( أَلْقِها ) أي اطرح العصا ( يا مُوسى ) .` },
            { text: "فَأَلْقَىٰهَا فَإِذَا هِىَ حَيَّةٌ تَسْعَىٰ", tafsir: `موسى ( فَإِذا هِيَ حَيَّةٌ تَسْعى ) أي فإذا بها انقلبت حية وأخذت تمشي سريعا. [22] ولما رأى موسى عليه‌السلام إنها انقلبت حية خاف منها خوفا شديدا ف ( قالَ ) الله سبحانه ( خُذْها ) أي الحية ( وَلا تَخَفْ ) منها أن تلدغك ( سَنُعِيدُها سِيرَتَهَا الْأُولى ) سنرجعها إلى حالتها المتقدمة ، فتقلب عصا كما كانت ، والسيرة : الطريقة ، واستعمالها بمعنى الحالة مجاز من باب التشبيه. فإن الحالة للشيء كالطريقة المستمرة له.` },
            { text: "قَالَ خُذْهَا وَلَا تَخَفْ سَنُعِيدُهَا سِيرَتَهَا ٱلْأُولَىٰ", tafsir: `` },
            { text: "وَٱضْمُمْ يَدَكَ إِلَىٰ جَنَاحِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ ءَايَةً أُخْرَىٰ", tafsir: `يا موسى ( إِلى جَناحِكَ ) الجناح هو اليد ، سميت به تشبيها بجناح الطائر ، أي ضع يدك تحت إبطك ، ثم أخرجها فإنها ( تَخْرُجْ بَيْضاءَ ) تشرق ( مِنْ غَيْرِ سُوءٍ ) أي من غير عاهة ومرض فليس بياضها من قبيل بياض البرص ، ففعل موسى عليه‌السلام ذلك ، وإذا بيده كالشمس الطالعة تضيء لها الدنيا ، وكان إذا أراد إرجاعها كالسابق ، أدخلها تحت إبطه ثانيا فإذا أخرجها كانت كالحالة السابقة ( آيَةً أُخْرى ) لِنُرِيَكَ مِنْ آياتِنَا الْكُبْرى (23) اذْهَبْ إِلى فِرْعَوْنَ إِنَّهُ طَغى (24) قالَ رَبِّ اشْرَحْ لِي صَدْرِي (25) وَيَسِّرْ لِي أَمْرِي (26) وَاحْلُلْ عُقْدَةً مِنْ لِسانِي (27) يَفْقَهُوا قَوْلِي (28) أي علامة ثانية على صدق دعواك النبوة ونصب « آية » على تقدير : نزيدك بها ، أو تقدير تخرج بها.` },
            { text: "لِنُرِيَكَ مِنْ ءَايَٰتِنَا ٱلْكُبْرَى", tafsir: `يا موسى في المستقبل ، أي نجري يديك ( مِنْ آياتِنَا ) حججنا وبراهيننا ( الْكُبْرى ) أي الآية الكبرى. [25] وإذ زودناك بهذه الآيات ف ( اذْهَبْ إِلى فِرْعَوْنَ ) فادعه إلي ( إِنَّهُ طَغى ) تجبر وتجاوز الحد ، من الطغيان.` },
            { text: "ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ", tafsir: `` },
            { text: "قَالَ رَبِّ ٱشْرَحْ لِى صَدْرِى", tafsir: `موسى عليه‌السلام عند ذلك يا ( رَبِّ اشْرَحْ لِي صَدْرِي ) وشرح الصدر توسعته ، وهو كناية عن عدم الضجر بالتكذيب ، وذلك لأن المتضجر تشتد فيه الحرارة ، فتنتفخ رئته أكثر من المعتاد لتجذب الهواء المبرد للقلب أكثر ، وبانتفاخها يضيق الصدر ، لأنها فيه.` },
            { text: "وَيَسِّرْ لِىٓ أَمْرِى", tafsir: `أي سهل لي أمر التبليغ ، حتى لا يكون عسيرا لدي.` },
            { text: "وَٱحْلُلْ عُقْدَةً مِّن لِّسَانِى", tafsir: `أي فك ( عُقْدَةً مِنْ لِسانِي ) فقد كان موسى عليه‌السلام يعقد لسانه في الكلام ، فدعا الله سبحانه أن يحل هذه العقدة من لسانه لئلا يقع في معرض الاستهزاء. [29] ول ( يَفْقَهُوا ) أي يفهم فرعون وحاشيته ( قَوْلِي ) كلامي. و قد روي عن الباقر عليه‌السلام أن فرعون كان يقتل أولاد بني إسرائيل كلما يلدون ويربي موسى عليه‌السلام ويكرمه ولا يعلم أن هلاكه على يديه ، ولما درج وَاجْعَلْ لِي وَزِيراً مِنْ أَهْلِي (29) هارُونَ أَخِي (30) اشْدُدْ بِهِ أَزْرِي (31) وَأَشْرِكْهُ فِي أَمْرِي (32) موسى كان يوما عند فرعون فعطس ، فقال : الحمد لله رب العالمين فأنكر فرعون ذلك عليه ولطمه ، وقال : ما هذا الذي تقول ؟ فوثب موسى على لحيته وكان طويل اللحية فهبلها ، أي قلعها فآلمه ألما شديدا ، فهمّ فرعون لقتله ، فقالت له امرأته : هذا غلام حدث لا يدري ما يقول فقال فرعون : بلى يدري ، فقالت له : ضع بين يديك تمرا وجمرا فإن ميز بين التمر والجمر فهو الذي تقول ، فوضع بين يديه تمرا وجمرا وقال له : كل فمد يده إلى التمر فجاء جبرائيل فصرفها إلى الجمر فأخذ الجمر في فيه فاحترق لسانه وصاح وبكى ، فقالت آسية لفرعون : ألم أقل لك إنه لم يعقل ؟ فعفا عنه. أقول : ومن هنا كان في لسان موسى شبه العقدة ، فلا يتمكن أن يتكلم إلا ويعقد لسانه ، حتى دعا الله ، فرفع عنه.` },
            { text: "يَفْقَهُوا۟ قَوْلِى", tafsir: `` },
            { text: "وَٱجْعَل لِّى وَزِيرًا مِّنْ أَهْلِى", tafsir: `يا رب ( وَزِيراً مِنْ أَهْلِي ) يعاضدني ويساعدني في الدعوة ، وليكن من أهلي ، لأن الأهل أعطف على الإنسان من الأجنبي وأقرب إلى الانسجام والألفة.` },
            { text: "هَٰرُونَ أَخِى", tafsir: `أي ليكن ذلك الوزير هارون ( أَخِي ) وكان أخاه لأبيه وأمه ، وكان بمصر.` },
            { text: "ٱشْدُدْ بِهِۦٓ أَزْرِى", tafsir: `أي قوّ بسبب هارون ( أَزْرِي ) أي ظهري ، ومنه المئزر لما يشد على الظهر.` },
            { text: "وَأَشْرِكْهُ فِىٓ أَمْرِى", tafsir: `أي اجمع بيني وبينه في النبوة ليكون هو نبيا أيضا ، وهذا غير كونه وزيرا له ، وإنما طلبه لأن النبي له أقوى داع إلى كَيْ نُسَبِّحَكَ كَثِيراً (33) وَنَذْكُرَكَ كَثِيراً (34) إِنَّكَ كُنْتَ بِنا بَصِيراً (35) قالَ قَدْ أُوتِيتَ سُؤْلَكَ يا مُوسى (36) وَلَقَدْ مَنَنَّا عَلَيْكَ مَرَّةً أُخْرى (37) إِذْ أَوْحَيْنا إِلى أُمِّكَ ما يُوحى (38) الهداية بخلاف مجرد الوزير. [34] إن الدعوة تحتاج إلى عبادة كثيرة توجب قوة الصلة بالله سبحانه حتى يتمكن الإنسان بتلك الصلة القوية أن يحمل المشاق ، وكثرة العبادة تتأتى لمن له معاون وشريك ، لأن النفس تنشط عند الاجتماع في العمل بما لا تنشط عند الانفراد ، فمهمة الدعوة تحتاج إلى شريك يقوم بمساعدة الإنسان لتهيئة النفس وتربية الروح ، ولذا قال عليه‌السلام : ( كَيْ نُسَبِّحَكَ ) يا رب ( كَثِيراً ) فننزهك عما لا يليق بك.` },
            { text: "كَىْ نُسَبِّحَكَ كَثِيرًا", tafsir: `` },
            { text: "وَنَذْكُرَكَ كَثِيرًا", tafsir: `كي ( نَذْكُرَكَ كَثِيراً ) حتى تشتد الصلة ويكون الله هو المتجلي الوحيد في النفس.` },
            { text: "إِنَّكَ كُنتَ بِنَا بَصِيرًا", tafsir: `يا رب ( كُنْتَ بِنا بَصِيراً ) فتعلم احتياجنا إلى هذه الأشياء ، مما لا تتأتى إلا بالوزير الظهير.` },
            { text: "قَالَ قَدْ أُوتِيتَ سُؤْلَكَ يَٰمُوسَىٰ", tafsir: `الله سبحانه ، في جواب طلبات موسى عليه‌السلام ( قَدْ أُوتِيتَ سُؤْلَكَ ) أي سؤالك وطلبك ( يا مُوسى ) فقد حلت عقدة لسانك ، وجعلنا هارون نبيا ووزيرا لك.` },
            { text: "وَلَقَدْ مَنَنَّا عَلَيْكَ مَرَّةً أُخْرَىٰٓ", tafsir: `يا موسى ( مَرَّةً أُخْرى ) غير هذه المرة التي مننا عليك فيها بالنبوة وإجابة الدعاء. [39] وتلك المنة والنعمة عليك كانت في حال صغرك ( إِذْ أَوْحَيْنا إِلى أُمِّكَ ) ألهمناها ( ما يُوحى ) أي المطلب الذي كان من شأنه أن يلهم أَنِ اقْذِفِيهِ فِي التَّابُوتِ فَاقْذِفِيهِ فِي الْيَمِّ فَلْيُلْقِهِ الْيَمُّ بِالسَّاحِلِ يَأْخُذْهُ عَدُوٌّ لِي وَعَدُوٌّ لَهُ وَأَلْقَيْتُ عَلَيْكَ مَحَبَّةً مِنِّي وَلِتُصْنَعَ عَلى عَيْنِي (39) إليها لنجاتك. [40] وكان الإلهام ( أَنِ اقْذِفِيهِ ) أي اطرحي أيتها الأم ولدك موسى ( فِي التَّابُوتِ ) وهو صندوق من خشب ، ثم سدي رأس التابوت حتى لا يدخل فيه الماء ( فَاقْذِفِيهِ ) اطرحي التابوت ( فِي الْيَمِ ) أي البحر ، وهو البحر الأحمر الموجود في مصر ، ثم يحمل التابوت الماء ، حتى يصل قرب الساحل ( فَلْيُلْقِهِ الْيَمُّ بِالسَّاحِلِ ) وهو شاطئ البحر ، ثم ماذا ؟ ( يَأْخُذْهُ ) أي يأخذ التابوت ( عَدُوٌّ لِي وَعَدُوٌّ لَهُ ) وهو فرعون فقد كان عدوا لله سبحانه وعدوا لموسى بالذات ، حيث إنه قرأ وعلم إن مولودا يولد في بني إسرائيل يكون على يده ذهاب ملكه ، فأمر أن يقتل الأولاد الذين يولدون في بني إسرائيل ، ومن خوف القتل ، صنعت أم موسى تابوتا ، وجعلته فيه ، وقذفته في البحر ، لئلا ترى قتل ولدها ، وليصنع معه ما شاء ( وَأَلْقَيْتُ عَلَيْكَ ) يا موسى ( مَحَبَّةً مِنِّي ) أي من جانبي ، حتى أن كل من يراك أحبك حتى أن فرعون بمجرد ما رآه أحبه ، ولم يقتله ( وَلِتُصْنَعَ ) اللام جارة ، لا لام الأمر ، وإن مقدّرة ، ولذا نصب الفعل ، أي ولعة أن تصنع وتربى ( عَلى عَيْنِي ) تحت رقابتي وبمرأى مني ، ألقيت عليك محبة ، فإن المحبة موجبة للرعاية التي كنى عنها ب ( لِتُصْنَعَ عَلى عَيْنِي ) إذ بين العناية والرعاية وبين النظر تلازم السبب والمسبب ، إذ رؤية الإنسان لأحد وكونه تحت نظره ، موجب لرعايته ، وكلمة « على عيني » تشمل على الاحترام ، إِذْ تَمْشِي أُخْتُكَ فَتَقُولُ هَلْ أَدُلُّكُمْ عَلى مَنْ يَكْفُلُهُ فَرَجَعْناكَ إِلى أُمِّكَ كَيْ تَقَرَّ عَيْنُها وَلا تَحْزَنَ والحفظ في أعز الأماكن ، فإن الاحترام مستفاد من لفظة « على » وبناء على ما ذكر فجواب « لتصنع » محذوف لدلالة الجملة السابقة عليه.` },
            { text: "إِذْ أَوْحَيْنَآ إِلَىٰٓ أُمِّكَ مَا يُوحَىٰٓ", tafsir: `` },
            { text: "أَنِ ٱقْذِفِيهِ فِى ٱلتَّابُوتِ فَٱقْذِفِيهِ فِى ٱلْيَمِّ فَلْيُلْقِهِ ٱلْيَمُّ بِٱلسَّاحِلِ يَأْخُذْهُ عَدُوٌّ لِّى وَعَدُوٌّ لَّهُۥ وَأَلْقَيْتُ عَلَيْكَ مَحَبَّةً مِّنِّى وَلِتُصْنَعَ عَلَىٰ عَيْنِىٓ", tafsir: `` },
            { text: "إِذْ تَمْشِىٓ أُخْتُكَ فَتَقُولُ هَلْ أَدُلُّكُمْ عَلَىٰ مَن يَكْفُلُهُۥ فَرَجَعْنَٰكَ إِلَىٰٓ أُمِّكَ كَىْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ وَقَتَلْتَ نَفْسًا فَنَجَّيْنَٰكَ مِنَ ٱلْغَمِّ وَفَتَنَّٰكَ فُتُونًا فَلَبِثْتَ سِنِينَ فِىٓ أَهْلِ مَدْيَنَ ثُمَّ جِئْتَ عَلَىٰ قَدَرٍ يَٰمُوسَىٰ", tafsir: `الظرف متعلق بتصنع ، أي كان ذلك في زمان مشي أختك ، أو لأجل أن تصنع على عيني قدرنا مشي أختك ( فَتَقُولُ ) أختك لآل فرعون ، حيث أرادوا لك مرضعة ( هَلْ أَدُلُّكُمْ عَلى مَنْ يَكْفُلُهُ ) يقوم بشؤونه ؟ ( فَرَجَعْناكَ ) يا موسى ( إِلى أُمِّكَ كَيْ تَقَرَّ عَيْنُها ) برؤيتك وحياطتك ، وقرار العين كناية عن السرور ، مقابل الواله الذي تطير عينه هنا وهناك ( وَلا تَحْزَنَ ) لا يحزن قلبها ، فيضفي رجوعك عليها الهدوء والسكينة في ظاهرها وباطنها. ورد أن موسى لما حملت به أمه لم يظهر حملها إلا عند وضعه ، وكان فرعون قد وكل بنساء بني إسرائيل نساء من القبط تحفظهن ، وذلك لما كان بلغه عن بني إسرائيل قولهم : أنه يولد فينا رجل يقال له موسى بن عمران يكون هلاك فرعون وأصحابه على يديه ، فقال فرعون عند ذلك : لأقتلن ذكور أولادهم حتى لا يكون ما يريدون ، وفرق بين الرجال والنساء وحبس الرجال في المحابس ، فلما وضعت أم موسى بموسى ، نظرت إليه وحزنت واغتمت وبكت ، وقالت : يذبح الساعة فعطف الله بقلب الموكلة بها عليه ، فقالت لأم موسى : ما لك قد اصفر لونك ؟ فقالت : أخاف أن يذبح ولدي ، فقالت : لا تخافي ، وكان موسى لا يراه أحد إلا أحبه وهو قوله « وألقيت عليك محبة مني » فأحبته القبطية الموكلة به ، وأنزل الله على أم موسى التابوت ، ونوديت : ضعيه في التابوت فاقذفيه في اليم ، وهو البحر ولا تخافي و لا تحزني إنا رادوه إليك وجاعلوه من المرسلين ، فوضعته في التابوت وأطبقت عليه وألقته في النيل ، وكان لفرعون قصور على شط النيل منزهات ، فنظر من قصره ومعه آسية امرأته إلى سواد في النيل ترفعه الأمواج ، والرياح تضربه حتى جاءت به إلى باب قصره ، فأمر فرعون بأخذه فأخذ التابوت ورفع إليه ، فلما فتحه وجد فيه صبيا ، فقال : هذا إسرائيلي ، فألقى الله في قلب فرعون لموسى محبة شديدة وكذلك في قلب آسية ، وأراد فرعون أن يقتله فقالت آسية : لا تقتلوه عسى أن ينفعنا أو نتخذه ولدا وهم لا يشعرون أنه موسى ، ولم يكن لفرعون ولد فقال : ادنوا له ظئرا لتربيته ، فجاءوا بعدة نساء قد قتل أولادهن فلم يشرب لبن أحد من النساء وهو قول الله تعالى : ( وَحَرَّمْنا عَلَيْهِ الْمَراضِعَ مِنْ قَبْلُ ) (1) وبلغ أمه أن فرعون قد أخذه فحزنت وبكت كما قال الله تعالى : ( وَأَصْبَحَ فُؤادُ أُمِّ مُوسى فارِغاً إِنْ كادَتْ لَتُبْدِي بِهِ ) ، قال : كادت أن تخبر بخبره أو تموت ثم حفظت نفسها فكانت كما قال الله : لو لا أن ربطنا على قلبها لتكون من المؤمنين ، ثم قالت لأخته : قصيه ، أي اتبعيه ، فجاءت أخت موسى إلى قصر فرعون ، فبصرت به عن جنب أي عن بعد وهم لا يشعرون ، فلما لم يقبل موسى بأخذ ثدي أحد من النساء اغتم فرعون غما شديدا ، فقالت أخت موسى : هل أدلكم على أهل بيت يكفلونه لكم وهم له ناصحون ؟ فقالوا : نعم. فجاءت بأمه فلما أخذته بحجرها ، وألقمته ثدييها التقمه وشرب ، ففرح فرعون وأهله وأكرموا أمه ، فقال لها : ربيه لنا فإنا نجزيك خيرا ، وقد كان الفصل بين إلقاء الأم لموسى في البحر ورده إليها ( 1) القصص : 13. وَقَتَلْتَ نَفْساً فَنَجَّيْناكَ مِنَ الْغَمِّ وَفَتَنَّاكَ فُتُوناً فَلَبِثْتَ سِنِينَ فِي أَهْلِ مَدْيَنَ ثُمَّ جِئْتَ عَلى قَدَرٍ يا مُوسى (40) وَاصْطَنَعْتُكَ لِنَفْسِي (41) ثلاثة أيام (1) ( وَقَتَلْتَ ) يا موسى ( نَفْساً ) من القبط ، فقد كان في مصر طائفتان ، القبط وهم قوم فرعون ، والإسرائيليون وهم أحفاد يعقوب ، وكان القبط كفارا والإسرائيليون مسلمون حيث ورثوا الدين والإسلام عن آبائهم ، فقد قال لهم يعقوب حين موته : ( إِنَّ اللهَ اصْطَفى لَكُمُ الدِّينَ فَلا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ ) (2) فمر موسى ذات يوم على رجلين أحدهما قبطي والآخر إسرائيلي يتشاجران فاستغاث بموسى الإسرائيلي ، وهناك تقدم موسى وضرب القبطي ضربة مات منها ( فَنَجَّيْناكَ مِنَ الْغَمِ ) حيث أمرناك وألهمنا إليك أن تفر من مصر لئلا يقتلك فرعون ، فقد جاءه آت ليقول له : ( إِنَّ الْمَلَأَ يَأْتَمِرُونَ بِكَ لِيَقْتُلُوكَ ) (3) ( وَفَتَنَّاكَ فُتُوناً ) أي اختبرناك اختبارا ، وابتليناك ابتلاء من الخوف في مصر ، ثم قتل القبطي ، ثم الفرار من الوطن واجلا خائفا ثم غير ذلك من أنواع المصائب ، التي تؤهل الإنسان للقيام بالمهام فبعد ذلك كله ( فَلَبِثْتَ ) وبقيت ( سِنِينَ ) عشرة ( فِي أَهْلِ مَدْيَنَ ) عند شعيب النبي عليه‌السلام حيث تزوج موسى بابنته ، ومدين على ثمان مراحل من مصر ـ كما في الصافي ـ ( ثُمَ ) بعد تلك الامتحانات والمشاق ( جِئْتَ عَلى قَدَرٍ ) بتقدير من الله ، لإنجاز المهمة وأداء الرسالة ( يا مُوسى ) فلتتذكر النعم ، ولتستعد للرسالة.` },
            { text: "وَٱصْطَنَعْتُكَ لِنَفْسِى", tafsir: `فأنت مصنوع لأجل العمل لله وحده ، فلا شيء ( 1) بحار الأنوار : ج 13 ص 25. ( 2) البقرة : 133. ( 3) القصص : 21. اذْهَبْ أَنْتَ وَأَخُوكَ بِآياتِي وَلا تَنِيا فِي ذِكْرِي (42) اذْهَبا إِلى فِرْعَوْنَ إِنَّهُ طَغى (43) فَقُولا لَهُ قَوْلاً لَيِّناً لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشى (44) قالا رَبَّنا إِنَّنا نَخافُ أَنْ يَفْرُطَ عَلَيْنا أَوْ أَنْ يَطْغى (45) منك للدنيا أو لأهلك. وإنما خالص محض للرسالة والتبليغ.` },
            { text: "ٱذْهَبْ أَنتَ وَأَخُوكَ بِـَٔايَٰتِى وَلَا تَنِيَا فِى ذِكْرِى", tafsir: `يا موسى ( أَنْتَ وَأَخُوكَ ) أي وليذهب أخوك هارون ، مثل «نحن بما عندنا وأنت بما عندك راض » أي نحن بما عندنا راضون ، وأنت بما عندك راض ( بِآياتِي ) أي مصاحبين للأدلة والبراهين الدالة على صدقكما في دعوى النبوة ( وَلا تَنِيا ) من ونى يني ، بمعنى الضعف والفتور ( فِي ذِكْرِي ) أي لا تضعفا في أداء رسالتي ، بل بلغا بكل جد واهتمام.` },
            { text: "ٱذْهَبَآ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ", tafsir: `كرر الأمر بالذهاب ، توطئة لذكر المتعلق ـ وهو فرعون ـ ( إِنَّهُ طَغى ) تجاوز الحد في الظلم والاعتداء.` },
            { text: "فَقُولَا لَهُۥ قَوْلًا لَّيِّنًا لَّعَلَّهُۥ يَتَذَكَّرُ أَوْ يَخْشَىٰ", tafsir: `أي أرفقا به في الدعوة ولا تغلظا له في البلاغ والإرشاد ( لَعَلَّهُ يَتَذَكَّرُ ) نعم الله عليه التي قد نساها ( أَوْ يَخْشى ) عذاب الله ، فيؤمن شكرا ، أو حذرا ، والرفق واللين يؤثران بما لا يؤثر الغلظة والخشونة.` },
            { text: "قَالَا رَبَّنَآ إِنَّنَا نَخَافُ أَن يَفْرُطَ عَلَيْنَآ أَوْ أَن يَطْغَىٰ", tafsir: `أي قال موسى وهارون عليه‌السلام يا ( رَبَّنا إِنَّنا نَخافُ أَنْ يَفْرُطَ عَلَيْنا ) أي يتقدم فينا بعذاب ويعجل علينا ، من فرط بمعنى تقدم ، ومنه يسمى الإسراف إفراطا لأنه تقدم على الحق ( أَوْ أَنْ يَطْغى ) بأن تصير دعوتنا له سببا لطغيانه بأن يكثر من الاجرام ، كما هو عادة المتجبرين قالَ لا تَخافا إِنَّنِي مَعَكُما أَسْمَعُ وَأَرى (46) فَأْتِياهُ فَقُولا إِنَّا رَسُولا رَبِّكَ فَأَرْسِلْ مَعَنا بَنِي إِسْرائِيلَ وَلا تُعَذِّبْهُمْ قَدْ جِئْناكَ بِآيَةٍ مِنْ رَبِّكَ وَالسَّلامُ عَلى مَنِ اتَّبَعَ الْهُدى (47) إِنَّا قَدْ أُوحِيَ إِلَيْنا أَنَّ الْعَذابَ عَلى مَنْ كَذَّبَ إذا ذكّروا بالحق ازدادوا تجبرا وعتوا.` },
            { text: "قَالَ لَا تَخَافَآ إِنَّنِى مَعَكُمَآ أَسْمَعُ وَأَرَىٰ", tafsir: `الله عزوجل لهما ( لا تَخافا ) من فرطه أو طغيانه ( إِنَّنِي مَعَكُما ) بالعلم والاطلاع أسندكما وأحفظكما ( أَسْمَعُ ) حواركما وإياه ( وَأَرى ) مجلسكما ومجلسه ، فألهمكما مما لا يسبب طغيانه وغلوائه ، وأمنعه من أن يطغى.` },
            { text: "فَأْتِيَاهُ فَقُولَآ إِنَّا رَسُولَا رَبِّكَ فَأَرْسِلْ مَعَنَا بَنِىٓ إِسْرَٰٓءِيلَ وَلَا تُعَذِّبْهُمْ قَدْ جِئْنَٰكَ بِـَٔايَةٍ مِّن رَّبِّكَ وَٱلسَّلَٰمُ عَلَىٰ مَنِ ٱتَّبَعَ ٱلْهُدَىٰٓ", tafsir: `أي اذهبا إليه ( فَقُولا إِنَّا رَسُولا رَبِّكَ ) أرسلنا إليك خالقك وإلهك ( فَأَرْسِلْ مَعَنا بَنِي إِسْرائِيلَ ) أي بلغاه هذه الرسالة من طرفي ، وهي أن يطلق سراح بني إسرائيل ، ويجعلهم أحرارا كما يشاءون حتى ب تحت لواء موسى وهارون ( وَلا تُعَذِّبْهُمْ ) بالاستعمال في الأعمال الشاقة ، فقد كانت بنو إسرائيل تحت تعذيب فرعون وأسره ، فكان منهم الأسراء في السجون ، ومنهم المسخر في أعمال البناء ، ومنهم المسخر في سائر الشؤون الشاقة المتعبة ( قَدْ جِئْناكَ ) أي أتينا إليك يا فرعون ( بِآيَةٍ ) حجة وبرهان ( مِنْ رَبِّكَ ) تدل على صدقنا وصحة دعوانا النبوة ، والمراد بالآية الجنس لتشمل العصا واليد وغيرهما ( وَالسَّلامُ ) أي السلامة من عذاب الله ( عَلى مَنِ اتَّبَعَ الْهُدى ) ولم يتبع الهوى ، فإن اهتديت سلمت من بأس الله وإلا كنت معرضا للخطر.` },
            { text: "إِنَّا قَدْ أُوحِىَ إِلَيْنَآ أَنَّ ٱلْعَذَابَ عَلَىٰ مَن كَذَّبَ وَتَوَلَّىٰ", tafsir: `من قبل الله سبحانه ( أَنَّ الْعَذابَ عَلى مَنْ كَذَّبَ ) وَتَوَلَّى (48) قالَ فَمَنْ رَبُّكُما يا مُوسى (49) قالَ رَبُّنَا الَّذِي أَعْطى كُلَّ شَيْءٍ خَلْقَهُ ثُمَّ هَدى (50) قالَ فَما بالُ الْقُرُونِ الْأُولى (51) بآيات الله ( وَتَوَلَّى ) أي أعرض عن الهداية ، فإن كذبت وتوليت كان لك العذاب والنكال ، وإلا آمنت وسلمت.` },
            { text: "قَالَ فَمَن رَّبُّكُمَا يَٰمُوسَىٰ", tafsir: `فرعون لهما ( فَمَنْ رَبُّكُما ) ولم يقل ربي لأنه لم يكن يعترف به ( يا مُوسى ) ؟ وجعل الخطاب لموسى لأنه هو المتكلم ، وقد أراد فرعون السؤال عن جنس الله هل هو بشر أو غيره ؟ لكن موسى أجاب ببيان صفات الله سبحانه ، لأن الله لا يعرف كنهه.` },
            { text: "قَالَ رَبُّنَا ٱلَّذِىٓ أَعْطَىٰ كُلَّ شَىْءٍ خَلْقَهُۥ ثُمَّ هَدَىٰ", tafsir: `فخلق هذه الأشياء كلها منه ، والمراد بالخلق الوجود ، لأنه سبب للوجود ( ثُمَّ هَدى ) أي هداه طريقه في الحياة كيف يبقى ويعيش ، فقد هدى الله الأشياء إلى طرقها الفطرية الطبيعية إنسانا كان أم حيوانا أم نباتا أم جمادا ، وإن كانت الهداية في النبات والجماد على ضرب من التوسع.` },
            { text: "قَالَ فَمَا بَالُ ٱلْقُرُونِ ٱلْأُولَىٰ", tafsir: `فرعون ، موجها لموسى عليه‌السلام سؤالا ثانيا ( فَما بالُ الْقُرُونِ الْأُولى ) أي ما شأن الأمم الماضية ، فأين ذهبت ؟ وماذا مصيرها ؟ ومن كان ربها فقد هلكت ، ولا تعرف لها ربا ؟ ولعله أراد بذلك أن يقول أن هذا القرن كتلك القرون ، فهي كما عاشت لا تعترف بالرب كذلك هذا القرن ، فما هذا الذي جئتم به ؟ [53] لكن موسى عليه‌السلام لم يكن ليشغل نفسه بالبحث حول أولئك ، فإنه أمر لا يرتبط بالدعوة فعلا ، وقال أرباب المناظرة ، أن من عدم الفطنة أن قالَ عِلْمُها عِنْدَ رَبِّي فِي كِتابٍ لا يَضِلُّ رَبِّي وَلا يَنْسى (52) الَّذِي جَعَلَ لَكُمُ الْأَرْضَ مَهْداً وَسَلَكَ لَكُمْ فِيها سُبُلاً وَأَنْزَلَ مِنَ السَّماءِ ماءً فَأَخْرَجْنا بِهِ أَزْواجاً مِنْ نَباتٍ شَتَّى (53) يشغل الإنسان نفسه بما لا يرتبط بمبحثه في الصميم ، ولذا ( قالَ ) عليه‌السلام ( عِلْمُها ) أي علم تلك القرون ( عِنْدَ رَبِّي فِي كِتابٍ لا يَضِلُّ رَبِّي ) لذلك الكتاب ، أو لا يخطئ في أمر تلك القرون ( وَلا يَنْسى ) ما فيه ، يعني أن الله سبحانه هو العالم بشؤون تلك الأمم وقد أثبت شؤونها في كتاب خاص لا يتطرق إليه الضلال ، ولا الغلط. [54] ثم رجع موسى عليه‌السلام إلى صميم الموضوع وهو التعريف بإله الكون بذكر صفاته وآثاره ، فإن ربي هو ( الَّذِي جَعَلَ لَكُمُ الْأَرْضَ مَهْداً ) كالمهد للطفل الذي يستقر فيه ويكون سببا لراحته وصحته ( وَسَلَكَ لَكُمْ ) السلك هو إدخال الشيء في الشيء أي أدخل لأجلكم ( فِيها ) أي في الأرض ( سُبُلاً ) جمع سبيل ، أي طرقا لسيركم من محلكم إلى مقصدكم. ( وَأَنْزَلَ مِنَ السَّماءِ ماءً ) لشربكم والتمتع به في سائر حوائجكم ، ثم التفت السياق من الغيبة إلى التكلم ، بإتيان جملة خارجة عن كلام موسى ، لينتقل بالناس من محيط القصة إلى المشافهة والمشاهدة ، وذلك أبلغ تأثيرا في نفس السامع ، كما وقع مثله في سورة الحمد ( فَأَخْرَجْنا بِهِ ) أي بذلك الماء ( أَزْواجاً ) أصنافا ( مِنْ نَباتٍ شَتَّى ) جمع شتيت ، كمرضى جمع مريض ، والمراد بالنبات الجنس ولذا وصف بالجمع ، نحو « الدرهم البيض » والنباتات مختلفة الأشكال والألوان والطعوم والروائح والخواص والأوزان وغير ذلك ، فمن يا كُلُوا وَارْعَوْا أَنْعامَكُمْ إِنَّ فِي ذلِكَ لَآياتٍ لِأُولِي النُّهى (54) مِنْها خَلَقْناكُمْ وَفِيها نُعِيدُكُمْ وَمِنْها نُخْرِجُكُمْ تارَةً أُخْرى (55) وَلَقَدْ أَرَيْناهُ آياتِنا كُلَّها فَكَذَّبَ وَأَبى (56) ترى جعل كل ذلك ؟ أم من يقدر على أن يخرج هذا المختلف العجيب الاختلاف من أرض واحدة وماء واحد.` },
            { text: "قَالَ عِلْمُهَا عِندَ رَبِّى فِى كِتَٰبٍ لَّا يَضِلُّ رَبِّى وَلَا يَنسَى", tafsir: `` },
            { text: "ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ مَهْدًا وَسَلَكَ لَكُمْ فِيهَا سُبُلًا وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦٓ أَزْوَٰجًا مِّن نَّبَاتٍ شَتَّىٰ", tafsir: `` },
            { text: "كُلُوا۟ وَٱرْعَوْا۟ أَنْعَٰمَكُمْ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّأُو۟لِى ٱلنُّهَىٰ", tafsir: `أيها البشر من هذا النبات المختلف ( وَارْعَوْا ) فيها ( أَنْعامَكُمْ ) أي أسيموهم حيواناتكم ( إِنَّ فِي ذلِكَ ) الذي ذكر من آيات الله سبحانه ( لَآياتٍ ) دلالات على وجود الله وعلمه وقدرته ( لِأُولِي النُّهى ) جمع نهية وهي العقل ، وإنما قيل له نهية ، لأنه ينهى الإنسان عن الفساد ، أي أن أصحاب العقول يعتبرون بهذه الآيات ويستدلون بها على وجود الله سبحانه.` },
            { text: "مِنْهَا خَلَقْنَٰكُمْ وَفِيهَا نُعِيدُكُمْ وَمِنْهَا نُخْرِجُكُمْ تَارَةً أُخْرَىٰ", tafsir: `من الأرض المتقدمة في قوله ( جَعَلَ لَكُمُ الْأَرْضَ مَهْداً ) ( خَلَقْناكُمْ ) فإن كل إنسان أوله تراب ثم ينقلب نباتا يأكله الإنسان ـ أو الحيوان الذي يأكله الإنسان أيضا ـ فيصير منيا ثم إنسانا ( وَفِيها نُعِيدُكُمْ ) إعادة ، إذ الإنسان بعد ما يبلى ينقلب ترابا ( وَمِنْها ) من الأرض ( نُخْرِجُكُمْ تارَةً ) أي مرة ( أُخْرى ) للحساب والجزاء وذلك يوم القيامة.` },
            { text: "وَلَقَدْ أَرَيْنَٰهُ ءَايَٰتِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ", tafsir: `أرينا فرعون ( آياتِنا ) الدالة على صدق موسى وهي المعجزات التسع ( كُلَّها ) كل الآيات التي زود بها موسى دلالة لصدقه ( فَكَذَّبَ ) فرعون بجميعها ( وَأَبى ) أي امتنع أن يؤمن ويصدق. [58] ولما أفحم فرعون لم يجد بدا من أن يتوسل بالكذب والافتراء قالَ أَ جِئْتَنا لِتُخْرِجَنا مِنْ أَرْضِنا بِسِحْرِكَ يا مُوسى (57) فَلَنَأْتِيَنَّكَ بِسِحْرٍ مِثْلِهِ فَاجْعَلْ بَيْنَنا وَبَيْنَكَ مَوْعِداً لا نُخْلِفُهُ نَحْنُ وَلا أَنْتَ مَكاناً سُوىً (58) قالَ مَوْعِدُكُمْ يَوْمُ الزّ ِينَةِ وَأَنْ يُحْشَرَ النَّاسُ والجدال بالباطل ، كما هو عادة كل مبطل ( قالَ ) مخاطبا لموسى ( أَ جِئْتَنا لِتُخْرِجَنا مِنْ أَرْضِنا بِسِحْرِكَ يا مُوسى ) هل تريد أن تخرجنا من أرض مصر ؟ ولم يرد موسى ذلك وإنما أراد أن يبهته فرعون ليجلب أهواء الناس إلى نفسه ، مبينا أن موسى لو سيطر أخرجنا من بلادنا ليعطي أزمتها بيد قومه بني إسرائيل.` },
            { text: "قَالَ أَجِئْتَنَا لِتُخْرِجَنَا مِنْ أَرْضِنَا بِسِحْرِكَ يَٰمُوسَىٰ", tafsir: `` },
            { text: "فَلَنَأْتِيَنَّكَ بِسِحْرٍ مِّثْلِهِۦ فَٱجْعَلْ بَيْنَنَا وَبَيْنَكَ مَوْعِدًا لَّا نُخْلِفُهُۥ نَحْنُ وَلَآ أَنتَ مَكَانًا سُوًى", tafsir: `أي مثل سحرك ليعرف الناس إنك كاذب ، وإنما تريد أن تتوصل بواسطة السحر إلى الملك والرئاسة ( فَاجْعَلْ بَيْنَنا وَبَيْنَكَ مَوْعِداً ) وقتا خاصا ومكانا خاصا ليأتي كل فريق بسحره حتى يظهر لمن الغلبة في ذلك ( لا نُخْلِفُهُ نَحْنُ وَلا أَنْتَ ) أي لا يقع من أحد منا خلف في حضور ذلك المكان ( مَكاناً سُوىً ) أي منتصفا بيننا وبينك فلا يكون أقرب إليك ولا إلينا ، وكأنه كان لموسى مكانا خاصا في مصر يقاس المحل بالنسبة إليه كما يقاس بالنسبة إلى قصر فرعون ، و « مكانا » إما عطف بتقدير الواو ، لو أريد من الموعد الزمان ، وإما بدل بعض عن كل لو أريد من الموعد الأعم.` },
            { text: "قَالَ مَوْعِدُكُمْ يَوْمُ ٱلزِّينَةِ وَأَن يُحْشَرَ ٱلنَّاسُ ضُحًى", tafsir: `موسى عليه‌السلام ( مَوْعِدُكُمْ يَوْمُ الزِّينَةِ ) فقد كان لهم يوم يسمى يوم الزينة ، لأن الناس يتزينون فيه ويزينون الأسواق ( وَأَنْ يُحْشَرَ النَّاسُ ) أي يجمع الناس ليشاهدوا أينا أصدق ، قالوا وقد جرت عادتهم ضُحًى (59) فَتَوَلَّى فِرْعَوْنُ فَجَمَعَ كَيْدَهُ ثُمَّ أَتى (60) قالَ لَهُمْ مُوسى وَيْلَكُمْ لا تَفْتَرُوا عَلَى اللهِ كَذِباً فَيُسْحِتَكُمْ بِعَذابٍ وَقَدْ خابَ مَنِ افْتَرى (61) أن يجمع الناس في يوم الزينة في محل خاص ، ولذا لم يتعرض للمكان لمعلومية المحل من حشر الناس ( ضُحًى ) أي وقت ارتفاع الشمس في ذلك اليوم لئلا يلتبس عليهم الأمر بواسطة الظلمة ، وقد جعل يوم الزينة ، لأن الناس فيه مستعدون ولا يشتبه من لا يعرف الحساب وقته.` },
            { text: "فَتَوَلَّىٰ فِرْعَوْنُ فَجَمَعَ كَيْدَهُۥ ثُمَّ أَتَىٰ", tafsir: `انصرف عن المجلس على هذا الموعد ( فَجَمَعَ كَيْدَهُ ) أي كل ما قدر عليه من المكر ، وذلك بجمع السحرة من أطراف مملكته ( ثُمَّ أَتى ) إلى الموعد ، في يوم الزينة. [62] ولما اصطف الجانبان ، فرعون والسحرة وملأه ، وموسى وهارون ومن معهما ( قالَ لَهُمْ ) أي لأولئك الذين جاءوا لمبارزته ( مُوسى وَيْلَكُمْ ) هي كلمة وعيد وتهديد أي ألزمكم الله العذاب والنكال بسبب ما قصدتم من إبطال آيات الله ، وما جئتم به من السحر ( لا تَفْتَرُوا عَلَى اللهِ كَذِباً ) بأن تجعلوا له شريكا ، أو تنسبوا معجزاته إلى السحر ، فإنه افتراء على الله الذي زودني بهذه المعجزات. ( فَيُسْحِتَكُمْ ) أي يهلككم ، فإن سحت وأسحت بمعنى أهلك ( بِعَذابٍ ) من عنده يأخذكم ويفنيكم ( وَقَدْ خابَ ) أي خسر ( مَنِ افْتَرى ) على الله الكذب ونسب إليه باطلا ، وإنما يخسر دنياه وآخرته. [63] وقد ألقى موسى عليه‌السلام هذا الكلام مقدمة للشروع في المباراة ، لعلهم فَتَنازَعُوا أَمْرَهُمْ بَيْنَهُمْ وَأَسَرُّوا النَّجْوى (62) قالُوا إِنْ هذانِ لَساحِرانِ يُرِيدانِ أَنْ يُخْرِجاكُمْ مِنْ أَرْضِكُمْ بِسِحْرِهِما وَيَذْهَبا بِطَرِيقَتِكُمُ الْمُثْلى (63) فَأَجْمِعُوا كَيْدَكُمْ ثُمَّ ائْتُوا صَفًّا يتعظون ولا يعرضون أنفسهم للخطر والهلاك ، وقد أحدث هذا الكلام بين صفوف القوم شقا وتنازعا فصار بعضهم مع موسى وبعضهم مع فرعون ، وأخذوا يتناجون بينهم هل يصدق موسى عليه‌السلام أم لا ؟ وهكذا تأخذ البليغة مكانتها في النفوس ، وإن لم تؤثر في الإتباع حالا ( فَتَنازَعُوا ) أي تنازع أصحاب فرعون ، في ( أَمْرَهُمْ ) وأخذ كل قسم منهم طرفا من طرفي موسى وفرعون ( بَيْنَهُمْ ) جيء بهذه اللفظة ، لئلا يسبق إلى الذهن كون التنازع كان بين الجانبين ( وَأَسَرُّوا النَّجْوى ) أي أخذ بعضهم يناجي الآخر سرا حول موسى وأنه هو صادق أم لا ؟ [64] وأخيرا أخذ أصحاب فرعون يؤيدون كلام فرعون ويحركون الناس من جهة العاطفة ليقووا به قلوب المترددين ( قالُوا إِنْ ) أي نعم ـ كما قال فرعون : أ جئتنا لتخرجنا من أرضنا بسحرك ـ ( هذانِ ) موسى وهارون ( لَساحِرانِ ) فما العصي واليد إلا سحرا ( يُرِيدانِ أَنْ يُخْرِجاكُمْ ) أيها الأقباط ( مِنْ أَرْضِكُمْ بِسِحْرِهِما ) فإنهم لو غلبوا أخرجوا كل مخالف لهم عن البلاد المصرية ( وَ ) يريدان أن ( يَذْهَبا بِطَرِيقَتِكُمُ الْمُثْلى ) أي طريقة دينكم ، لتكونوا متدينين مثلهما وتتركوا طريقة آبائكم و « المثلى » مؤنث الأمثل ، أي الأفضل والأحسن. [65] ثم قالوا للمترددين منهم ( فَأَجْمِعُوا كَيْدَكُمْ ) فلا تدعوا شيئا منه إلا جئتم به ( ثُمَّ ائْتُوا صَفًّا ) واحدا ، بلا تفرق ، وليس المراد الإتيان في وَقَدْ أَفْلَحَ الْيَوْمَ مَنِ اسْتَعْلى (64) قالُوا يا مُوسى إِمَّا أَنْ تُلْقِيَ وَإِمَّا أَنْ نَكُونَ أَوَّلَ مَنْ أَلْقى (65) قالَ بَلْ أَلْقُوا فَإِذا حِبالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّها تَسْعى (66) المستقبل وإنما المراد أن يكونوا صفا واحدا وقت المباراة ، فإن التفرقة تضر الحركة بقدر ما تنفع الطرف المقاتل ( وَقَدْ أَفْلَحَ ) وفاز ( الْيَوْمَ مَنِ اسْتَعْلى ) أي من قد غلب وعلا من جانبنا أو جانب موسى عليه‌السلام فلا تفوتنكم الفرصة. [66] وبعد توحيد الصفوف ، وتقوية قلوب المترددين بهذه الكلمات وأمثالها ، توجهت السحرة نحو موسى عليه‌السلام ( قالُوا يا مُوسى إِمَّا أَنْ تُلْقِيَ ) عصاك ( وَإِمَّا أَنْ نَكُونَ ) نحن ( أَوَّلَ مَنْ أَلْقى ) سحره ثم تلقي أنت ؟` },
            { text: "قَالَ لَهُم مُّوسَىٰ وَيْلَكُمْ لَا تَفْتَرُوا۟ عَلَى ٱللَّهِ كَذِبًا فَيُسْحِتَكُم بِعَذَابٍ وَقَدْ خَابَ مَنِ ٱفْتَرَىٰ", tafsir: `` },
            { text: "فَتَنَٰزَعُوٓا۟ أَمْرَهُم بَيْنَهُمْ وَأَسَرُّوا۟ ٱلنَّجْوَىٰ", tafsir: `` },
            { text: "قَالُوٓا۟ إِنْ هَٰذَٰنِ لَسَٰحِرَٰنِ يُرِيدَانِ أَن يُخْرِجَاكُم مِّنْ أَرْضِكُم بِسِحْرِهِمَا وَيَذْهَبَا بِطَرِيقَتِكُمُ ٱلْمُثْلَىٰ", tafsir: `` },
            { text: "فَأَجْمِعُوا۟ كَيْدَكُمْ ثُمَّ ٱئْتُوا۟ صَفًّا وَقَدْ أَفْلَحَ ٱلْيَوْمَ مَنِ ٱسْتَعْلَىٰ", tafsir: `` },
            { text: "قَالُوا۟ يَٰمُوسَىٰٓ إِمَّآ أَن تُلْقِىَ وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنْ أَلْقَىٰ", tafsir: `` },
            { text: "قَالَ بَلْ أَلْقُوا۟ فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِن سِحْرِهِمْ أَنَّهَا تَسْعَىٰ", tafsir: `موسى عليه‌السلام ( بَلْ أَلْقُوا ) أنتم ما معكم ولعل أمره بابتدائهم لإشعار المجتمع بعدم الاكتراث بهم ، فإن الإنسان الذي يطمئن من نفسه ، لا يهمه تقدم غيره عليه ، وامتثل السحرة وألقوا ما معهم ( فَإِذا حِبالُهُمْ ) جمع حبل ( وَعِصِيُّهُمْ ) جمع عصي ( يُخَيَّلُ إِلَيْهِ ) أي إلى موسى ( مِنْ سِحْرِهِمْ ) أي من أهل سحر السحرة ( أَنَّها تَسْعى ) فكان سعيها خيالا لا حقيقة ، وفي آية أخرى ( سَحَرُوا أَعْيُنَ النَّاسِ وَاسْتَرْهَبُوهُمْ وَجاؤُ بِسِحْرٍ عَظِيمٍ ) (1) وكان الإتيان ب « يخيل إليه » نسبة إلى موسى عليه‌السلام بيان عظمة السحر ، حتى أنه أثر في موسى النبي عليه‌السلام ، وخيل إليه كما تريد ذلك الآية التالية أيضا. ( 1) الأعراف : 117. فَأَوْجَسَ فِي نَفْسِهِ خِيفَةً مُوسى (67) قُلْنا لا تَخَفْ إِنَّكَ أَنْتَ الْأَعْلى (68) وَأَلْقِ ما فِي يَمِينِكَ تَلْقَفْ ما صَنَعُوا إِنَّما صَنَعُوا كَيْدُ ساحِرٍ وَلا يُفْلِحُ السَّاحِرُ حَيْثُ أَتى (69) فَأُلْقِيَ السَّحَرَةُ سُجَّداً` },
            { text: "فَأَوْجَسَ فِى نَفْسِهِۦ خِيفَةً مُّوسَىٰ", tafsir: `فأحس ( فِي نَفْسِهِ خِيفَةً ) خوفا من تلك الحبال والعصي ( مُوسى ) فاعل أوجس ، و روي عن الإمام المرتضى عليه‌السلام : لم يوجس موسى خيفة على نفسه بل أشفق من غلبة الجهال ودول الضلال (1) .` },
            { text: "قُلْنَا لَا تَخَفْ إِنَّكَ أَنتَ ٱلْأَعْلَىٰ", tafsir: `لموسى حين خاف ( لا تَخَفْ إِنَّكَ أَنْتَ الْأَعْلى ) عليهم فإن عصاك تبطل سحرهم وتظهر زيفهم.` },
            { text: "وَأَلْقِ مَا فِى يَمِينِكَ تَلْقَفْ مَا صَنَعُوٓا۟ إِنَّمَا صَنَعُوا۟ كَيْدُ سَٰحِرٍ وَلَا يُفْلِحُ ٱلسَّاحِرُ حَيْثُ أَتَىٰ", tafsir: `أي اطرح إلى الأرض ( ما فِي يَمِينِكَ ) أي العصا ( تَلْقَفْ ) تبتلع ( ما صَنَعُوا ) من الحبال والعصي ( إِنَّما صَنَعُوا كَيْدُ ساحِرٍ ) خبر « ما » أي إن الذي صنعوه هو كيد الساحر ومكره وتدبيره الخفي ، وليس له حقيقة يخشى منها ( وَلا يُفْلِحُ السَّاحِرُ ) أي لا يفوز الساحر ببغيته ومطلبه ، ومن عجيب الأمر أن السحرة دائما مهانون ، لا يتمكنون من إدارة أمورهم مع ما يصنعون من الأمور المدهشة الجالبة ( حَيْثُ أَتى ) أي أنى وجد ، أو حيث أتى بسحره. [71] فألقى موسى عليه‌السلام عصاه ، وإذا بها ثعبان مبين تبتلع عصي السحرة وحبالهم ، وفر الناس ذعرا من خوفها ( فَأُلْقِيَ السَّحَرَةُ سُجَّداً ) أي أنهم ألقوا أنفسهم على الأرض ساجدين خاضعين لله الذي يدعو إليه ( 1) بحار الأنوار : ج 13 ص 141. قالُوا آمَنَّا بِرَبِّ هارُونَ وَمُوسى (70) قالَ آمَنْتُمْ لَهُ قَبْلَ أَنْ آذَنَ لَكُمْ إِنَّهُ لَكَبِيرُكُمُ الَّذِي عَلَّمَكُمُ السِّحْرَ فَلَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُمْ م ِنْ خِلافٍ وَلَأُصَلِّبَنَّكُمْ موسى عليه‌السلام وكان الإتيان بالمجهول « ألقى » لإفادة أن عملهم هذا كان باندفاع وانهيار ، لا كسجدة الإنسان الهادئ ( قالُوا ) للملأ حوله ( آمَنَّا بِرَبِّ هارُونَ وَمُوسى ) ولعل تقدم هارون لكونه الأخ الأكبر ـ كما في بعض التفاسير أنه كان أكبر الأخوين ـ أو للقافية. [72] وقد أحدث إيمان السحرة اضطرابا عجيبا في صف فرعون حتى خاف فرعون أن يتبعه الناس ولم ير عاجلا إلا اللجوء إلى القوة فتوجه إلى السحرة مهددا ( قالَ آمَنْتُمْ لَهُ ) أي كيف آمنتم بموسى ، وإنما عدي باللام لاشتماله على معنى التصديق ( قَبْلَ أَنْ آذَنَ لَكُمْ ) ؟ فكيف خالفتم طريقتي بدون الإذن وتحصيل الرخصة ؟ ثم أراد أن يعمي على الناس قصة كون العصا إعجازا ، فأتى بالكذب والمغالطة ، تبريرا لموقفه من موسى عليه‌السلام ومن السحرة الذين اتبعوه لكي لا يلام بأنه لما ظهر الحق أعرض عنه ( إِنَّهُ ) أي موسى عليه‌السلام ( لَكَبِيرُكُمُ الَّذِي عَلَّمَكُمُ السِّحْرَ ) فإنه أستاذكم في علم السحر ، وقد تواطأتم على أن يأتي هو بأعظم أقسام السحر ، وتأتون أنتم ببعض أقسامه الأدنى ، لتروا للناس غلبته ثم تؤمنون به ليؤمن الناس ـ خدعة منكم للجماهير ـ تريدون السيطرة على البلاد ، ثم أخذ يهددهم كما هو دأب الطغاة حيث يعجزون عن القلوب يلجئون إلى تعذيب الأبدان ( فَلَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُمْ مِنْ خِلافٍ ) فتقطع اليد اليمنى والرجل اليسرى ، أو بالعكس ، ليختل توازن البدن ، ويكون عذابه أكثر ما دام الإنسان حيا ( وَلَأُصَلِّبَنَّكُمْ ) الصلب هو فِي جُذُوعِ النَّخْلِ وَلَتَعْلَمُنَّ أَيُّنا أَشَدُّ عَذاباً وَأَبْقى (71) قالُوا لَنْ نُؤْثِرَكَ عَلى ما جاءَنا مِنَ الْبَيِّناتِ وَالَّذِي فَطَرَنا فَاقْضِ ما أَنْتَ قاضٍ إِنَّما تَقْضِي هذِهِ الْحَياةَ الدُّنْيا (72) إِنَّا آمَنَّا بِرَبِّنا لِيَغْفِرَ لَنا خَطايانا وَما أَكْرَهْتَنا عَلَيْهِ مِنَ السِّحْرِ الشنق ، وله أقسام منها أن يدق يدا المصلوب بجذع أفقي نصب على جذع عمودي ، فيبقى المصلوب في أذية يوما أو أياما حتى يموت ( فِي جُذُوعِ النَّخْلِ ) وإنما عدي بعلى لإشراب الصلب معنى الرفع ، أي أرفعنكم للصلب على أصول نخل التمر. ( وَلَتَعْلَمُنَ ) أيها السحرة ( أَيُّنا ) أيّ منا ومن موسى فيما يدعي ويقول ( فَيُسْحِتَكُمْ بِعَذابٍ )( أَشَدُّ عَذاباً ) من الآخر ( وَأَبْقى ) أي أدوم عذابا ؟ وقد كان ظن أن عذابه أشد وأبقى من عذاب الله سبحانه.` },
            { text: "فَأُلْقِىَ ٱلسَّحَرَةُ سُجَّدًا قَالُوٓا۟ ءَامَنَّا بِرَبِّ هَٰرُونَ وَمُوسَىٰ", tafsir: `` },
            { text: "قَالَ ءَامَنتُمْ لَهُۥ قَبْلَ أَنْ ءَاذَنَ لَكُمْ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِى عَلَّمَكُمُ ٱلسِّحْرَ فَلَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍ وَلَأُصَلِّبَنَّكُمْ فِى جُذُوعِ ٱلنَّخْلِ وَلَتَعْلَمُنَّ أَيُّنَآ أَشَدُّ عَذَابًا وَأَبْقَىٰ", tafsir: `` },
            { text: "قَالُوا۟ لَن نُّؤْثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ ٱلْبَيِّنَٰتِ وَٱلَّذِى فَطَرَنَا فَٱقْضِ مَآ أَنتَ قَاضٍ إِنَّمَا تَقْضِى هَٰذِهِ ٱلْحَيَوٰةَ ٱلدُّنْيَآ", tafsir: `أي قالت السحرة في جواب تهديد فرعون ( لَنْ نُؤْثِرَكَ ) أي لن نفضلك ونختارك يا فرعون ( عَلى ما جاءَنا مِنَ الْبَيِّناتِ ) أي الأدلة الواضحة ، فإن البقاء في طريقتك معناه إنا رجحناك على الأدلة التي دلتنا على صحة طريقة موسى عليه‌السلام ( وَ ) على ( الَّذِي فَطَرَنا ) أي لن نختارك ربا ـ بعد هذا ـ على الله الذي فطرنا وخلقنا ( فَاقْضِ ما أَنْتَ قاضٍ ) أي فاصنع ما أنت صانعه بنا من التعذيب ( إِنَّما تَقْضِي ) أي تحكم علينا في ( هذِهِ الْحَياةَ الدُّنْيا ) وهي دار زائلة لا يهمنا ما يصنع بنا فيها.` },
            { text: "إِنَّآ ءَامَنَّا بِرَبِّنَا لِيَغْفِرَ لَنَا خَطَٰيَٰنَا وَمَآ أَكْرَهْتَنَا عَلَيْهِ مِنَ ٱلسِّحْرِ وَٱللَّهُ خَيْرٌ وَأَبْقَىٰٓ", tafsir: `أي معاصينا التي سلفت منا من الكفر والآثام ( وَما أَكْرَهْتَنا عَلَيْهِ مِنَ السِّحْرِ ) فإن السحر خصوصا وَاللهُ خَيْرٌ وَأَبْقى (73) إِنَّهُ مَنْ يَأْتِ رَبَّهُ مُجْرِماً فَإِنَّ لَهُ جَهَنَّمَ لا يَمُوتُ فِيها وَلا يَحْيى (74) وَمَنْ يَأْتِهِ مُؤْمِناً قَدْ عَمِلَ الصَّالِحاتِ فَأُولئِكَ لَهُمُ الدَّرَجاتُ الْعُلى (75) جَنَّاتُ عَدْنٍ إذا كان لإبطال نبوة من أعظم الآثام ، ولا يرتفع إثمه بالإكراه إذا كان في مقابلة النبي ، وقد كان فرعون أكرههم على السحر في مقابل موسى ، فقد روي أن السحرة قالوا لفرعون أرنا موسى إذا نام فأراهم إياه فإذا هو نائم وعصاه تحرسه فقالوا ليس هذا بسحر إن الساحر إذا نام بطل سحره فأبى عليهم إلا أن يعملوا فذلك إكراههم للسحر (1) ( وَاللهُ خَيْرٌ ) لنا منك ( وَ ) هو ( أَبْقى ) أي أكثر بقاء ، فإذا آمنا به كان أحسن لنا من بقائنا في طريقتك ، وإن خيرك ليسير وبقائك لقليل.` },
            { text: "إِنَّهُۥ مَن يَأْتِ رَبَّهُۥ مُجْرِمًا فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ", tafsir: `الضمير للشأن ( مَنْ يَأْتِ رَبَّهُ مُجْرِماً ) كافرا أو عاصيا ( فَإِنَّ لَهُ جَهَنَّمَ لا يَمُوتُ فِيها ) فيستريح من العذاب ( وَلا يَحْيى ) حياة فيها راحة ، أي لا يبقى حيا في راحة ، وإنما هو حي في أنواع الشدائد والآلام.` },
            { text: "وَمَن يَأْتِهِۦ مُؤْمِنًا قَدْ عَمِلَ ٱلصَّٰلِحَٰتِ فَأُو۟لَٰٓئِكَ لَهُمُ ٱلدَّرَجَٰتُ ٱلْعُلَىٰ", tafsir: `أي يذهب إلى الله سبحانه حينما يموت ( مُؤْمِناً ) مصدقا بالله ورسله وما جاءوا به و ( قَدْ عَمِلَ ) الأعمال ( الصَّالِحاتِ ) فكان صحيح العقيدة والعمل ( فَأُولئِكَ لَهُمُ الدَّرَجاتُ الْعُلى ) جمع عليا ، تأنيث أعلى ، أي له درجات رفيعة في الجنة. [77] ثم بين الدرجات بأنها في ( جَنَّاتُ عَدْنٍ ) أي بساتين إقامة وبقاء ، من ( 1) بحار الأنوار : ج 13 96. تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ خالِدِينَ فِيها وَذلِكَ جَزاءُ مَنْ تَزَكَّى (76) وَلَقَدْ أَوْحَيْنا إِلى مُوسى أَنْ أَسْرِ بِعِبادِي فَاضْرِبْ لَهُمْ طَرِيقاً فِي الْبَحْرِ يَبَساً لا تَخافُ دَرَكاً وَلا تَخْشى (77) عدن بالمكان إذا أقام ( تَجْرِي مِنْ تَحْتِهَا ) أي تحت قصورها وأشجارها ( الْأَنْهارُ ) في حال كونهم ( خالِدِينَ فِيها ) إلى الأبد ( وَذلِكَ ) الثواب ( جَزاءُ مَنْ تَزَكَّى ) أي تطهر بالإيمان والطاعة. [78] ولما أتمت الحجة على فرعون وملأه ، ولم يؤمنوا ، صار القرار من الله سبحانه أن يهلكه مع حاشيته إنجازا لما وعد به موسى ، وقال موسى عليه‌السلام لقومه ( عَسى رَبُّكُمْ أَنْ يُهْلِكَ عَدُوَّكُمْ ) (1) ( وَلَقَدْ أَوْحَيْنا إِلى مُوسى أَنْ أَسْرِ بِعِبادِي ) بني إسرائيل والذين آمنوا بك ، ليلا وإنما أمروا بالسير ليلا لئلا يراهم فرعون فيمنعهم من المسير مع موسى عليه‌السلام ( فَاضْرِبْ لَهُمْ ) أي لمن معك ( طَرِيقاً ) أي اضرب بعصاك ( فِي الْبَحْرِ ) يوجد لسيرهم في وسط البحر طريق ( يَبَساً ) أي يابسا ( لا تَخافُ ) نهي في صيغة الخبر ، تأكيد لعدم الخوف ( دَرَكاً ) أي إدراك فرعون لك ( وَلا تَخْشى ) من الغرق ، ففعل موسى ما أمره الله سبحانه ، فإنهم لما وصلوا إلى البحر الأحمر متجهين نحو الشام ، ضرب بعصاه على البحر ، فانفلق الماء ، وانفتحت لهم اثنتي عشرة طريقا ، ليسير كل قبيلة من القبائل الإسرائيلية من طريق خاص بهم ، ولما عرف فرعون بفرار بني إسرائيل بقيادة موسى جهز الجيش ليتبعهم ويردهم. ( 1) الأعراف : 130. فَأَتْبَعَهُمْ فِرْعَوْنُ بِجُنُودِهِ فَغَشِيَهُمْ مِنَ الْيَمِّ ما غَشِيَهُمْ (78) وَأَضَلَّ فِرْعَوْنُ قَوْمَهُ وَما هَدى (79) يا بَنِي إِسْرائِيلَ قَدْ أَنْجَيْناكُمْ مِنْ عَدُوِّكُمْ وَواعَدْناكُمْ جانِبَ الطُّورِ الْأَيْمَنَ` },
            { text: "جَنَّٰتُ عَدْنٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَذَٰلِكَ جَزَآءُ مَن تَزَكَّىٰ", tafsir: `` },
            { text: "وَلَقَدْ أَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَسْرِ بِعِبَادِى فَٱضْرِبْ لَهُمْ طَرِيقًا فِى ٱلْبَحْرِ يَبَسًا لَّا تَخَٰفُ دَرَكًا وَلَا تَخْشَىٰ", tafsir: `` },
            { text: "فَأَتْبَعَهُمْ فِرْعَوْنُ بِجُنُودِهِۦ فَغَشِيَهُم مِّنَ ٱلْيَمِّ مَا غَشِيَهُمْ", tafsir: `أي اتبع موسى عليه‌السلام وبني إسرائيل ( فِرْعَوْنُ بِجُنُودِهِ ) مع جنوده ، أي ذهبوا خلفهم ، حتى وصلوا إلى البحر ورأوا أنهم قد دخلوا البحر يريدون العبور ، وهنا توقف فرعون أولا ، وخاف من الغرق إن دخل سكك البحر التي انشق الماء عنها بقدرة الله عزوجل ، لكنه أخيرا دخل مع جيشه ، فلما توسطوه ، وخرج أصحاب موسى من البحر انطبق الماء على آل فرعون ( فَغَشِيَهُمْ مِنَ الْيَمِّ ما غَشِيَهُمْ ) أي جاءهم الماء حتى غطاهم وأحاط بهم ، وقوله « ما غشيهم » للتهويل كي يبقى من النفس منه هول وخوف.` },
            { text: "وَأَضَلَّ فِرْعَوْنُ قَوْمَهُۥ وَمَا هَدَىٰ", tafsir: `في هذه الحياة بسوقهم إلى البحر الذي لم يكن طريقا ، حتى سبب هلاكهم ، وفي الحياة الآخرة بأن أراهم طريقة منحرفة لا تصل إلا إلى النار ( وَما هَدى ) إلى طريق الحق ، فقد بقي في الإضلال إلى آخر عمره ، وكان الإتيان بجملة « ما هدى » لإفادة أنه لم يرجع عن إضلاله ، فإن « أضل » إنما يدل على الابتداء في الإضلال ، أما البقاء فيه فإنه لا يفيده.` },
            { text: "يَٰبَنِىٓ إِسْرَٰٓءِيلَ قَدْ أَنجَيْنَٰكُم مِّنْ عَدُوِّكُمْ وَوَٰعَدْنَٰكُمْ جَانِبَ ٱلطُّورِ ٱلْأَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ", tafsir: `فرعون ، وقد رأيتم كيف أنجيناكم ، بعبوركم من البحر بالإعجاز ، وإهلاك فرعون وجنوده هناك ( وَواعَدْناكُمْ ) أي واعدنا الكليم موسى عليه‌السلام أن يأتي ( جانِبَ الطُّورِ الْأَيْمَنَ ) أي الطرف الأيمن من الجبل المسمى بالطور ، لإعطاء التوراة ، وحيث إن الوعد لرئيس القوم وعد لكل القوم قال سبحانه : وَنَزَّلْنا عَلَيْكُمُ الْمَنَّ وَالسَّلْوى (80) كُلُوا مِنْ طَيِّباتِ ما رَزَقْناكُمْ وَلا تَطْغَوْا فِيهِ فَيَحِلَّ عَلَيْكُمْ غَضَبِي وَمَنْ يَحْلِلْ عَلَيْهِ غَضَبِي فَقَدْ هَوى (81) وَإِنِّي لَغَفَّارٌ لِمَنْ تابَ وَآمَنَ وَعَمِلَ صالِحاً ثُمَّ اهْتَدى (82) « وواعدناكم » والإتيان من باب المفاعلة كأنه لا بد كون الوعد من الطرفين الإعطاء والأخذ بخلاف مثل وعدته أي المتكلم له مع الأمر فإنه وعد ، لا مواعدة ( وَنَزَّلْنا عَلَيْكُمُ الْمَنَ ) وهو نوع من الصمغ الحلو ( وَالسَّلْوى ) وهو طير لذيذ يسمى السماني ، وذلك حين كنتم في التيه ـ كما مر تفصيله في سورة البقرة ـ. [82] وقلنا لكم ( كُلُوا مِنْ طَيِّباتِ ما رَزَقْناكُمْ ) المراد بالأمر الإباحة ، أي أبحنا لكم أكل الطيبات ( وَلا تَطْغَوْا فِيهِ ) فيما رزقناكم ، بأن تستعملوه في الحرام ، كالربا والاحتكار والغش وأشباهها ، فإنها طغيان وتعد عن الحد في الرزق الحلال ( فَيَحِلَّ عَلَيْكُمْ غَضَبِي ) لو طغيتم في رزقي والفعل مجزوم ـ بالفتحة ـ لكونه في جواب النهي ( وَمَنْ يَحْلِلْ عَلَيْهِ غَضَبِي ) بأنه عمل بالمعاصي فاستحق العقاب ( فَقَدْ هَوى ) أي هلك ، كالذي يهوي من السطح إلى الأسفل. [83] ثم بينا لكم أن من هوى لا ينقطع عن الله إلى الأبد ، بل باب التوبة مفتوح أمامه ( وَإِنِّي لَغَفَّارٌ ) مبالغة من الغفران ( لِمَنْ تابَ ) عن معاصيه السابقة التي أظهرها الشرك ( وَآمَنَ ) بالله ورسوله وما أنزل ( وَعَمِلَ صالِحاً ) بأن صحت عقيدته وعمله ( ثُمَّ اهْتَدى ) أي بقي على الهداية إلى أن يموت ، أو المراد بيان أن الاهتداء ليس عقيدة في وَما أَعْجَلَكَ عَنْ قَوْمِكَ يا مُوسى (83) قالَ هُمْ أُولاءِ عَلى أَثَرِي وَعَجِلْتُ إِلَيْكَ رَبِّ لِتَرْضى (84) قالَ فَإِنَّا قَدْ فَتَنَّا قَوْمَكَ مِنْ بَعْدِكَ وَأَضَلَّهُمُ السَّامِرِيُّ (85) القلب ، وعملا بالجوارح ، وإنما يحتاج إلى رسوخ الإيمان والتحلي بنور الهداية ، وإنما العقيدة والعمل مقدمتان له ومهيئان الجو لإشراقه. [84] ثم إن الله سبحانه إنجازا لما وعد به موسى عليه‌السلام ، من إعطائه الكتاب الذي فيه أحكامه ، فقد انقطع القوم عن أحكام فرعون وأنظمته ، واحتاجوا إلى أنظمة لحياتهم ، ودستور لعملهم ، أمر موسى عليه‌السلام أن يأتي إلى الطور مع جماعة من قومه ، وصام موسى أربعين يوما مقدمة لذلك ، حتى تصفو نفسه ، وتستعد لهذا اللقاء ، ولما أتم الصيام تعجل للذهاب إلى الجبل ، في حين كان القوم بعد في سفح الجبل ، فقال له سبحانه ( وَما أَعْجَلَكَ عَنْ قَوْمِكَ يا مُوسى ) أيّ شيء صار سببا لأن تتقدم على القوم وتصعد قبلهم ؟ وحيث أن عجل أشرب معنى التجاوز عدي ب « عن » .` },
            { text: "كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَلَا تَطْغَوْا۟ فِيهِ فَيَحِلَّ عَلَيْكُمْ غَضَبِى وَمَن يَحْلِلْ عَلَيْهِ غَضَبِى فَقَدْ هَوَىٰ", tafsir: `` },
            { text: "وَإِنِّى لَغَفَّارٌ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًا ثُمَّ ٱهْتَدَىٰ", tafsir: `` },
            { text: "وَمَآ أَعْجَلَكَ عَن قَوْمِكَ يَٰمُوسَىٰ", tafsir: `` },
            { text: "قَالَ هُمْ أُو۟لَآءِ عَلَىٰٓ أَثَرِى وَعَجِلْتُ إِلَيْكَ رَبِّ لِتَرْضَىٰ", tafsir: `موسى عليه‌السلام في الجواب ( هُمْ ) القوم ( أُولاءِ ) جمع الذي ، أي هم الذين ( عَلى أَثَرِي ) من ورائي يدركونني عن قريب ( وَعَجِلْتُ إِلَيْكَ ) يا ( رَبِّ لِتَرْضى ) أي لتزداد رضا عني أو لتعجل الرضى عني.` },
            { text: "قَالَ فَإِنَّا قَدْ فَتَنَّا قَوْمَكَ مِنۢ بَعْدِكَ وَأَضَلَّهُمُ ٱلسَّامِرِىُّ", tafsir: `الله تعالى ( فَإِنَّا قَدْ فَتَنَّا قَوْمَكَ ) أي امتحناهم ليظهر قدرهم ، فإن الإنسان إذا ألف عادة أشكل عليه الإقلاع عنها ( مِنْ بَعْدِكَ ) أي من بعد مجيئك إلى الطور ، وقد كان غياب موسى عليه‌السلام عن قومه أربعين ليلة ( وَأَضَلَّهُمُ السَّامِرِيُ ) فقد كانت نفوس القوم تألف الوثن ، ولذا لما جاوزوا البحر أتوا على قوم يعكفون على أصنام لهم ، قالوا : يا موسى فَرَجَعَ مُوسى إِلى قَوْمِهِ غَضْبانَ أَسِفاً قالَ يا قَوْمِ أَ لَمْ يَعِدْكُمْ رَبُّكُمْ وَعْداً حَسَناً أَ فَطالَ عَلَيْكُمُ الْعَهْدُ أَمْ أَرَدْتُمْ أَنْ يَحِلَّ عَلَيْكُمْ غَضَبٌ مِنْ رَبِّكُمْ فَأَخْلَفْتُمْ مَوْعِدِي (86) اجعل لنا إلها كما لهم آلهة ولما غاب موسى انتهز السامري الفرصة ، فأمرهم بجمع حليهم وصنع منها عجلا جسدا وقال هذا إلهكم وإله موسى ، وعبده بنو إسرائيل ، وهذا كان إضلال السامري ، كما أنه كان امتحان الله لهم ، وقد خلي بين السامري وبين ما يفعل ليظهر دفائن قلوبهم. [87] فلما أخذ موسى عليه‌السلام الكتاب من الله سبحانه ( فَرَجَعَ مُوسى إِلى قَوْمِهِ غَضْبانَ أَسِفاً ) في حالة غضب على ما اقترفوا من الإثم ، وأسف أي حزن وتحسر عليهم ، كيف أنهم ضلوا بعد تلك المصاعب والأتعاب ، ولما وصل إلى القوم ( قالَ يا قَوْمِ أَ لَمْ يَعِدْكُمْ رَبُّكُمْ وَعْداً حَسَناً ) بإعطائكم الكتاب وجعلكم ورثة الأرض وإدخالكم الجنة ؟ فلم انصرفتم عن وعد الله سبحانه إلى عبادة العجل الذي لا يعقل ولا ينفعكم أبدا ؟ ( أَ فَطالَ عَلَيْكُمُ الْعَهْدُ ) الذي عهدتكم بإتيان التوراة حتى تعتذرون بأنك أخلفت العهد ، ولذا عدلنا عنك وعن إلهك إلى هذا العجل ؟ ( أَمْ ) لم يطل العهد وإنما ( أَرَدْتُمْ أَنْ يَحِلَّ عَلَيْكُمْ غَضَبٌ مِنْ رَبِّكُمْ ) ؟ فإن فعلكم هذا فعل من يريد إحلال العقاب به ، وإلا فما هو السبب لذلك ؟ ( فَأَخْلَفْتُمْ مَوْعِدِي ) الذي وعدتموني بأن تكونوا على عهدكم باقين حتى آتيكم بالكتاب ، فقد أمرهم موسى عليه‌السلام أن يعملوا تحت إمرة هارون أخيه ، حتى يرجع إليهم ، ولكنهم خرجوا عن قالُوا ما أَخْلَفْنا مَوْعِدَكَ بِمَلْكِنا وَلكِنَّا حُمِّلْنا أَوْزاراً مِنْ زِينَةِ الْقَوْمِ فَقَذَفْناها فَكَذلِكَ أَلْقَى السَّامِرِيُّ (87) فَأَخْرَجَ لَهُمْ عِجْلاً جَسَداً لَهُ خُوارٌ فَقالُوا هذا إِلهُكُمْ طاعته ، فأخلفوا موعد موسى عليه‌السلام .` },
            { text: "فَرَجَعَ مُوسَىٰٓ إِلَىٰ قَوْمِهِۦ غَضْبَٰنَ أَسِفًا قَالَ يَٰقَوْمِ أَلَمْ يَعِدْكُمْ رَبُّكُمْ وَعْدًا حَسَنًا أَفَطَالَ عَلَيْكُمُ ٱلْعَهْدُ أَمْ أَرَدتُّمْ أَن يَحِلَّ عَلَيْكُمْ غَضَبٌ مِّن رَّبِّكُمْ فَأَخْلَفْتُم مَّوْعِدِى", tafsir: `` },
            { text: "قَالُوا۟ مَآ أَخْلَفْنَا مَوْعِدَكَ بِمَلْكِنَا وَلَٰكِنَّا حُمِّلْنَآ أَوْزَارًا مِّن زِينَةِ ٱلْقَوْمِ فَقَذَفْنَٰهَا فَكَذَٰلِكَ أَلْقَى ٱلسَّامِرِىُّ", tafsir: `أي قال بنو إسرائيل في جواب اعتراضه وتوبيخه ( ما أَخْلَفْنا مَوْعِدَكَ بِمَلْكِنا ) أي ونحن نملك من أمرنا شيئا ، فإن الملك مثلث الميم بمعنى ما يملك الإنسان ، يعني لم يكن ملكنا وباختيارنا الوفاء والخلف حتى نفي ، وإنما أجبرنا على خلف الوعد ( وَلكِنَّا حُمِّلْنا أَوْزاراً مِنْ زِينَةِ الْقَوْمِ ) أي حملنا ـ من مصر ـ أثقالا من الذهب من حلي آل فرعون ، فقد كانت لديهم حلي من القبط قد استعاروها منهم وما ألقاه البحر على الساحل بعد غرقهم ، والأوزار جمع وزر ، بمعنى الثقل ، وسمي الحلي وزرا لثقله جسما أو رتبة ( فَقَذَفْناها ) أي تلك الأوزار ألقيناها في البوتقة في النار ( فَكَذلِكَ أَلْقَى السَّامِرِيُ ) ما معه في النار ، ليسبك الجميع عجلا ، أو المراد قذفوها ليتخلصوا منها حيث كانت محرمة وكذلك قذف ما معه السامري ثم جمعها وجعلها عجلا.` },
            { text: "فَأَخْرَجَ لَهُمْ عِجْلًا جَسَدًا لَّهُۥ خُوَارٌ فَقَالُوا۟ هَٰذَآ إِلَٰهُكُمْ وَإِلَٰهُ مُوسَىٰ فَنَسِىَ", tafsir: `السامري ، وهو رجل منهم يلقب بهذا اللقب ـ ولعل اللفظ معرب وإلا فأصله في التوراة يلفظ بشكل آخر ـ ( لَهُمْ عِجْلاً ) وهو ولد البقر ( جَسَداً ) لا روح فيه ، ويقال الجسد لما لا روح فيه ـ غالبا ـ ( لَهُ خُوارٌ ) كخوار العجل قال بعض المفسرين إنه جعل من العجل منافذ إذا هب الريح فيها خرج من العجل صوت يشبه صوت العجل ( فَقالُوا ) السامري وأعوانه ( هذا ) العجل ( إِلهُكُمْ ) يا بني إسرائيل وَإِلهُ مُوسى فَنَسِيَ (88) أَ فَلا يَرَوْنَ أَلاَّ يَرْجِعُ إِلَيْهِمْ قَوْلاً وَلا يَمْلِكُ لَهُمْ ضَرًّا وَلا نَفْعاً (89) وَلَقَدْ قالَ لَهُمْ هارُونُ مِنْ قَبْلُ يا قَوْمِ إِنَّما فُتِنْتُمْ بِهِ وَإِنَّ رَبَّكُمُ الرَّحْمنُ فَاتَّبِعُونِي وَأَطِيعُوا أَمْرِي (90) ( وَإِلهُ مُوسى ) فقد نسي موسى عليه‌السلام أن إلهه هنا ، فذهب إلى الطور يطلبه.` },
            { text: "أَفَلَا يَرَوْنَ أَلَّا يَرْجِعُ إِلَيْهِمْ قَوْلًا وَلَا يَمْلِكُ لَهُمْ ضَرًّا وَلَا نَفْعًا", tafsir: `ألا يرى بنو إسرائيل ( أَلَّا يَرْجِعُ إِلَيْهِمْ ) « أن » مخففة من الثقيلة ، واسمه ضمير محذوف ، أي أن العجل « لا يرجع » فاعله محذوف يرجع إلى العجل و ( قَوْلاً ) تميز ، أي لا يرجع إليهم رجوعا قوليا ، كما تقول « لا يأتي قولا » أي لا يقول القول ، فكأن من يقول ، يرجع هو إلى الطرف ، وهو من باب علاقة العلة والمعلول ، فقد عبر عن إرجاع القول برجوع النفس ، والمعنى أ فلا يرى بنو إسرائيل أن العجل الذي عبدوه لا يرد عليهم جوابا ( وَلا يَمْلِكُ لَهُمْ ضَرًّا وَلا نَفْعاً ) وكيف يتمكن أن يضرهم أو ينفعهم ذهب مصوغ ؟` },
            { text: "وَلَقَدْ قَالَ لَهُمْ هَٰرُونُ مِن قَبْلُ يَٰقَوْمِ إِنَّمَا فُتِنتُم بِهِۦ وَإِنَّ رَبَّكُمُ ٱلرَّحْمَٰنُ فَٱتَّبِعُونِى وَأَطِيعُوٓا۟ أَمْرِى", tafsir: `أي لبني إسرائيل ( هارُونُ ) أخو موسى عليه‌السلام المخلف عندهم ( مِنْ قَبْلُ ) عود موسى إليهم حينما اتخذوا العجل ( يا قَوْمِ إِنَّما فُتِنْتُمْ بِهِ ) أي امتحنتم بهذا العجل ، ليعلم أيكم يعبده وأيكم يتركه ، بل يبقى على عبادة ربه ، فلا تعبدوا العجل ( وَإِنَّ رَبَّكُمُ الرَّحْمنُ ) الذي رحمكم بنجاتكم من آل فرعون وتفضل عليكم بكل شيء ( فَاتَّبِعُونِي ) فيما أدعوكم إليه ( وَأَطِيعُوا أَمْرِي ) في عبادة الله سبحانه. قالُوا لَنْ نَبْرَحَ عَلَيْهِ عاكِفِينَ حَتَّى يَرْجِعَ إِلَيْنا مُوسى (91) قالَ يا هارُونُ ما مَنَعَكَ إِذْ رَأَيْتَهُمْ ضَلُّوا (92) أَلاَّ تَتَّبِعَنِ أَ فَعَصَيْتَ أَمْرِي (93)` },
            { text: "قَالُوا۟ لَن نَّبْرَحَ عَلَيْهِ عَٰكِفِينَ حَتَّىٰ يَرْجِعَ إِلَيْنَا مُوسَىٰ", tafsir: `أي الذين عبدوا العجل ( لَنْ نَبْرَحَ عَلَيْهِ عاكِفِينَ ) لا نزال مقيمين على عبادته ، فإن برح بمعنى زال ، وعكف بمعنى أقام ( حَتَّى يَرْجِعَ إِلَيْنا مُوسى ) فننظر هل يعبده كما عبدناه ، وكما أخبرنا السامري قائلا : هذا إلهكم وإله موسى ، أم لا يعبده ؟ [93] ولما رجع موسى عليه‌السلام ورأى أنهم عبدوا العجل كما أخبره سبحانه من الطور ، توجه إلى هارون و ( قالَ يا هارُونُ ما مَنَعَكَ إِذْ رَأَيْتَهُمْ ضَلُّوا ) بعبادة العجل ، عن اتباعي ، وقوله :` },
            { text: "قَالَ يَٰهَٰرُونُ مَا مَنَعَكَ إِذْ رَأَيْتَهُمْ ضَلُّوٓا۟", tafsir: `` },
            { text: "أَلَّا تَتَّبِعَنِ أَفَعَصَيْتَ أَمْرِى", tafsir: `أي في الغضب الشديد لله ومقاتلة عبّاد العجل أو الخروج من بينهم ، متعلق بمحذوف أي ما هو السبب في أن لا تتبعن ، كما أن متعلق « ما منعك » محذوف ، وكثيرا ما يستعمل البلغاء مثل هذا تأكيدا للنفي ، فإن حذف المتعلق في « ما منعك » يحدث في الذهن فجوة وسيعة وهولا ، كما أن حذف الفعل في « ألا تتبعن » يوهم ابتداء الإنكار ، ومثله شائع كما قال سبحانه : ( ما مَنَعَكَ أَلَّا تَسْجُدَ ) (1) وقوله : « ما يمنع القوم أن لا يعملوا حسنا » وقوله : « وقد رأى المنع في أن لا يجاريهم » ولذا كان « ألا تتبعن » أول الآية. ( أَ فَعَصَيْتَ أَمْرِي ) هل عصيت أمري الذي أمرتك ؟ كما قال سبحانه : ( وَقالَ مُوسى لِأَخِيهِ هارُونَ اخْلُفْنِي فِي قَوْمِي وَأَصْلِحْ وَلا تَتَّبِعْ ( 1) الأعراف : 13. قالَ يَا بْنَ أُمَّ لا تَأْخُذْ بِلِحْيَتِي وَلا بِرَأْسِي إِنِّي خَشِيتُ أَنْ تَقُولَ فَرَّقْتَ بَيْنَ بَنِي إِسْرائِيلَ سَبِيلَ الْمُفْسِدِينَ ) (1) فكيف لم تصلح ؟ ثم أخذ موسى بلحية أخيه ورأسه يجره إليه ، وألقى الألواح من يده تضجرا ، ولم يك هذا العمل من موسى لأنه شديد الغضب ، كما يقول البعض ، كما أنه لم يك ذلك لأنه ظن بهارون سوءا وإنما جرت عادة العقلاء على أن يبدوا استنكارهم الشديد لغير المجرم ، في أقوال وأعمال ، ليعرف المجرم وقع الجرم ، ولا يكون هو المعتب الأول ، لئلا يثأر نفسه ، فإنك إذا أردت أن تفهم جارك سوء عمله من إلقاء القمامة على باب البيت ، تقول لولدك : « لماذا يصب القذارة على باب دارنا ؟ هل أنت أعمى حتى لا تمنع الصاب ؟ ولو رأيت القمامة بعد هذا لضربتك » وإنما الولد بريء مثلك وأنت تعلم ذلك ، وإنما تريد إفهام الجار ، على طريقة « إياك أعني واسمعي يا جارة » وهذا من فنون الأدب والبلاغة.` },
            { text: "قَالَ يَبْنَؤُمَّ لَا تَأْخُذْ بِلِحْيَتِى وَلَا بِرَأْسِىٓ إِنِّى خَشِيتُ أَن تَقُولَ فَرَّقْتَ بَيْنَ بَنِىٓ إِسْرَٰٓءِيلَ وَلَمْ تَرْقُبْ قَوْلِى", tafsir: `هارون مخاطبا لموسى ( يَا بْنَ أُمَ ) وإنما خص الأم بالذكر ، استعطافا وترقيقا ليسكن الغضب المشتعل في موسى على عبّاد العجل ( لا تَأْخُذْ بِلِحْيَتِي وَلا بِرَأْسِي ) ولم يقل هارون ذلك ، إلا لكي يعرف بنو إسرائيل أنه لم يكن المذنب في القصة ، لا لأنه رأى موسى غضبان عليه ( إِنِّي خَشِيتُ ) لو فارقتهم وخرجت من بينهم ( أَنْ تَقُولَ ) أنت ( فَرَّقْتَ بَيْنَ بَنِي إِسْرائِيلَ ) إذ خروج الزعيم من بين القوم يؤدي إلى تفرقهم ، كما أن محاربته لهم تؤدي إلى التفرقة ، وقد كان عذر هارون عليه‌السلام صحيحا ، فإن الناس لا يتبعون الخلف كما يتبعون ( 1) الأعراف : 143. وَلَمْ تَرْقُبْ قَوْلِي (94) قالَ فَما خَطْبُكَ يا سامِرِيُّ (95) قالَ بَصُرْتُ بِما لَمْ يَبْصُرُوا بِهِ فَقَبَضْتُ قَبْضَةً مِنْ أَثَرِ الرَّسُولِ فَنَبَذْتُها وَكَذلِكَ سَوَّلَتْ لِي نَفْسِي (96) الرئيس ، وبأدنى شيء يتفرقون عليه ( وَ ) تقول ( لَمْ تَرْقُبْ ) يا هارون ( قَوْلِي ) أي لم تحفظ وصيتي في ما أوصيتك به أن أصلح ولا تتبع سبيل المفسدين ، فتقول لي إنك لم تصلح حين سببت التفرقة بين القوم ، بغضبك الشديد عليهم ، أو مقاتلتك لهم ، أو خروجك من بينهم. [96] ولما أظهر موسى عليه‌السلام براءة ساحة أخيه ، وأبدى لومه الشديد وغضبه على عبّاد العجل في هذه الصورة ، وبهذا القالب توجه إلى السامري رأس الفتنة ( قالَ ) موسى عليه‌السلام ( فَما خَطْبُكَ ) أي ما شأنك وما الذي دعاك إلى ما صنعت ( يا سامِرِيُ ) حيث أضللت الناس ؟` },
            { text: "قَالَ فَمَا خَطْبُكَ يَٰسَٰمِرِىُّ", tafsir: `` },
            { text: "قَالَ بَصُرْتُ بِمَا لَمْ يَبْصُرُوا۟ بِهِۦ فَقَبَضْتُ قَبْضَةً مِّنْ أَثَرِ ٱلرَّسُولِ فَنَبَذْتُهَا وَكَذَٰلِكَ سَوَّلَتْ لِى نَفْسِى", tafsir: `السامري ( بَصُرْتُ بِما لَمْ يَبْصُرُوا بِهِ ) أي رأيت ما لم يروه أو فطنت بما لم يفطنوا به ، فقد رأيت جبرائيل على فرس ـ في صورته البشرية ـ ( فَقَبَضْتُ قَبْضَةً مِنْ ) تراب ( أَثَرِ الرَّسُولِ ) تحت قوائم فرسه ( فَنَبَذْتُها ) طرحت تلك النبذة في العجل الذي صنعته من الذهب فكان له هذا الخوار من أثر ذلك التراب ( وَكَذلِكَ ) الذي حدثتك يا موسى ( سَوَّلَتْ لِي نَفْسِي ) أي زينته لي حتى أوجه بني إسرائيل إلى نفسي ، وقد احتمل بعض المفسرين أن هذا الكلام كان كذبا من السامري أراد به أن يبرر ساحته ويظهر فضله في أنه فطن بما لم يفطن به بنو إسرائيل ، ولو ورد بما ذكره أثر صحيح لم يك مخالفا للمقاييس إذ رؤية الإنسان للملك ممكن ، كما إن الخوار لأجل الأثر ممكن ، قالَ فَاذْهَبْ فَإِنَّ لَكَ فِي الْحَياةِ أَنْ تَقُولَ لا مِساسَ وَإِنَّ لَكَ مَوْعِداً لَنْ تُخْلَفَهُ وَانْظُرْ إِلى إِلهِكَ الَّذِي ظَلْتَ عَلَيْهِ عاكِفاً لَنُحَرِّقَنَّهُ ثُمَّ لَنَنْسِفَنَّهُ فِي الْيَمِّ نَسْفاً (97) ولا يوجب عذر من يعبد العجل ، إذ لا عذر بعد تمام الحجة ، أ رأيت لو جاء أحد الآن وقال : إن هذه الفأرة إلهكم ، وعلى يده فأرة مصنوعة من النحاس لكنها تتحرك ، هل يكون المعترف بكونها إلها معذورا ؟ [98] ثم أعلن موسى عليه‌السلام طرد السامري عن جماعة بني إسرائيل إلى الأبد ( قالَ ) للسامري ( فَاذْهَبْ ) من بيننا ( فَإِنَّ لَكَ فِي الْحَياةِ أَنْ تَقُولَ لا مِساسَ ) فقد كان إذا مسه أحد أخذته الحمى عقوبة لما اقترف من صنع العجل ، كما أن الماس كانت تأخذه الحمى بمسه السامري ، فمعنى لا مساس : لا أمس أحدا ولا يمسني أحد. وقد ورد في الحديث أن السامري كان سخيا ولذا لم يقتله موسى عليه‌السلام ( وَإِنَّ لَكَ مَوْعِداً ) لعذابك الشديد في يوم القيامة ( لَنْ تُخْلَفَهُ ) أي لن تخلف ذلك الوعد ، بل يأتيك بالقطع واليقين ( وَانْظُرْ ) يا سامري ( إِلى إِلهِكَ ) أي العجل الذي كنت تسميه إلها ( الَّذِي ظَلْتَ عَلَيْهِ عاكِفاً ) أي مقيما تعبده وترشد الناس إلى عبادته ( لَنُحَرِّقَنَّهُ ) بالنار حتى يذوب ( ثُمَ ) لنبردنه بالمبرد حتى يصير كالتراب ثم ( لَنَنْسِفَنَّهُ فِي الْيَمِ ) أي البحر ( نَسْفاً ) أي لنذريه ، وقد أراد عليه‌السلام بذلك بيان أن الشيء الذي يحرق بالنار ، ويبرد ، وينسف في البحر لا يكون إلها ، فإن بني إسرائيل قد علقت نفوسهم بما تنظر إليه عيونهم ، فكان هذا العمل أدعى لردعهم عن عبادة العجل ـ وهذا العمل ، من قبيل ما ذكرنا أن البليغ قد يظهر ما ينويه في العمل لتقريع المجرم ، فإن العجل لم يكن مذنبا ، أو يفهم إِنَّما إِلهُكُمُ اللهُ الَّذِي لا إِلهَ إِلاَّ هُوَ وَسِعَ كُلَّ شَيْءٍ عِلْماً (98) كَذلِكَ نَقُصُّ عَلَيْكَ مِنْ أَنْباءِ ما قَدْ سَبَقَ وَقَدْ آتَيْناكَ مِنْ لَدُنَّا ذِكْراً (99) مَنْ أَعْرَضَ عَنْهُ فَإِنَّهُ يَحْمِلُ يَوْمَ الْقِيامَةِ وِزْراً (100) خالِد ِينَ فِيهِ وَساءَ لَهُمْ يَوْمَ هذا العمل ، وإنما أريد بذلك تقريع غيره ـ.` },
            { text: "قَالَ فَٱذْهَبْ فَإِنَّ لَكَ فِى ٱلْحَيَوٰةِ أَن تَقُولَ لَا مِسَاسَ وَإِنَّ لَكَ مَوْعِدًا لَّن تُخْلَفَهُۥ وَٱنظُرْ إِلَىٰٓ إِلَٰهِكَ ٱلَّذِى ظَلْتَ عَلَيْهِ عَاكِفًا لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِى ٱلْيَمِّ نَسْفًا", tafsir: `` },
            { text: "إِنَّمَآ إِلَٰهُكُمُ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ وَسِعَ كُلَّ شَىْءٍ عِلْمًا", tafsir: `يا بني إسرائيل ( اللهُ الَّذِي لا إِلهَ إِلَّا هُوَ ) فهو المستحق للعبادة ، لا العجل المصنوع من الذهب ( وَسِعَ كُلَّ شَيْءٍ عِلْماً ) أي أن علمه وسع كل شيء ، فهو عالم بكل شيء ، وإنما جيء بهذه الصفة لبيان أن أعمالكم كلها معلومة لديه ، فلا يعمل الإنسان ما ينافي أمره ورضاه ، كما أنه تعريض بالعجل الذي لا يعلم شيئا ، كيف يكون إلها ؟` },
            { text: "كَذَٰلِكَ نَقُصُّ عَلَيْكَ مِنْ أَنۢبَآءِ مَا قَدْ سَبَقَ وَقَدْ ءَاتَيْنَٰكَ مِن لَّدُنَّا ذِكْرًا", tafsir: `الذي قصصنا عليك يا رسول الله نبأ موسى ( نَقُصُّ عَلَيْكَ مِنْ أَنْباءِ ما قَدْ سَبَقَ ) من أخبار الأنبياء عليهم‌السلام السابقين وأممهم وما فيه عبرة وعظة ( وَقَدْ آتَيْناكَ ) أي أعطيناك يا رسول الله ( مِنْ لَدُنَّا ) من عندنا ، فنحن المصدر ، لا إنا واسطة ( ذِكْراً ) أي القرآن الذي يذكر الناس بالمبدأ والمعاد ، وسائر المعارف ، مما هي مفطورة في خلقتهم ، وإنما القرآن يذكرهم بها.` },
            { text: "مَّنْ أَعْرَضَ عَنْهُ فَإِنَّهُۥ يَحْمِلُ يَوْمَ ٱلْقِيَٰمَةِ وِزْرًا", tafsir: `أي عن هذا الذكر ( فَإِنَّهُ يَحْمِلُ يَوْمَ الْقِيامَةِ وِزْراً ) حملا ثقيلا من الآثام والمعاصي. [102] في حال كونهم ( خالِدِينَ فِيهِ ) في ثقل ذلك الحمل ، والمراد الخلود في جزائه ، وهو النار ـ بعلاقة السبب والمسبب ـ ( وَساءَ لَهُمْ يَوْمَ الْقِيامَةِ حِمْلاً (101) يَوْمَ يُنْفَخُ فِي الصُّورِ وَنَحْشُرُ الْمُجْرِمِينَ يَوْمَئِذٍ زُرْقاً (102) يَتَخافَتُونَ بَيْنَهُمْ إِنْ لَبِثْتُمْ إِلاَّ عَشْراً (103) نَحْنُ أَعْلَمُ بِما يَقُولُونَ إِذْ يَقُولُ أَمْثَلُهُمْ طَرِيقَةً إِنْ لَبِثْتُمْ إِلاَّ يَوْماً (104) الْقِيامَةِ حِمْلاً ) أي بئس الحمل حملهم ، في ذلك اليوم المهول ، فإنه حمل يوجب إدخالهم النار. [103] ثم بين يوم القيامة بأنه ( يَوْمَ يُنْفَخُ فِي الصُّورِ ) والصور هو : البوق الذي ينفخ ويصيح فيه إسرافيل مخاطبا الأرواح لتلتحق بأجسادها ، قائلا للناس : أحيوا بأمر الله سبحانه ، وهي النفخة الثانية ( وَنَحْشُرُ ) نجمع ( الْمُجْرِمِينَ ) الذين أجرموا بالكفر والعصيان ( يَوْمَئِذٍ ) أي من يوم النفخ ( زُرْقاً ) جمع أزرق ، فإن الإنسان المكدر المهموم تعلو وجهه زرقة.` },
            { text: "خَٰلِدِينَ فِيهِ وَسَآءَ لَهُمْ يَوْمَ ٱلْقِيَٰمَةِ حِمْلًا", tafsir: `` },
            { text: "يَوْمَ يُنفَخُ فِى ٱلصُّورِ وَنَحْشُرُ ٱلْمُجْرِمِينَ يَوْمَئِذٍ زُرْقًا", tafsir: `` },
            { text: "يَتَخَٰفَتُونَ بَيْنَهُمْ إِن لَّبِثْتُمْ إِلَّا عَشْرًا", tafsir: `أي يتكلمون بإخفات وسر ، فإن الإنسان إذا أخذته الدهشة أو الجلال لا يتكلم إلا خفية و نجوى ، يقول بعضهم لبعض : ( إِنْ لَبِثْتُمْ ) ما بقيتم ومكثتم في الدنيا ( إِلَّا عَشْراً ) عشرة ليالي ، فإنهم يقللون مدة لبثهم في الدنيا ، وهكذا الإنسان يقلل ما مضى من عمره ، كأنه شيء يسير.` },
            { text: "نَّحْنُ أَعْلَمُ بِمَا يَقُولُونَ إِذْ يَقُولُ أَمْثَلُهُمْ طَرِيقَةً إِن لَّبِثْتُمْ إِلَّا يَوْمًا", tafsir: `لا يغيب عنا شيء ، والمراد أن سرهم لا يخفى علينا ( إِذْ يَقُولُ أَمْثَلُهُمْ طَرِيقَةً ) أي أرشدهم في الحساب ، وأصوبهم في الرأي ( إِنْ لَبِثْتُمْ إِلَّا يَوْماً ) أي ما بقيتم في الدنيا إلا يوما واحدا ، وإنما كان أرشدهم لأن من كان أرشد يرى عمر الدنيا وَيَسْئَلُونَكَ عَنِ الْجِبالِ فَقُلْ يَنْسِفُها رَبِّي نَسْفاً (105) فَيَذَرُها قاعاً صَفْصَفاً (106) لا تَرى فِيها عِوَجاً وَلا أَمْتاً (107) يَوْمَئِذٍ يَتَّبِعُونَ الدَّاعِيَ لا عِوَجَ لَهُ وَخَشَعَتِ الْأَصْواتُ لِلرَّحْمنِ فَلا أقل ، لما يرى من زوالها بسرعة.` },
            { text: "وَيَسْـَٔلُونَكَ عَنِ ٱلْجِبَالِ فَقُلْ يَنسِفُهَا رَبِّى نَسْفًا", tafsir: `يا رسول الله ( عَنِ الْجِبالِ ) ما حالها يوم القيامة ( فَقُلْ ) يا رسول الله ( يَنْسِفُها ) أي يقلعها ويدكها ( رَبِّي نَسْفاً ) ودكا ، فقد جاء رجل من ثقيف سائلا الرسول صلى‌الله‌عليه‌وآله‌وسلم كيف تكون الجبال يوم القيامة مع عظمتها ؟ فقال صلى‌الله‌عليه‌وآله‌وسلم : إن الله يسوقها بأن يجعلها كالرمال ، ثم يرسل عليها الرياح فتفرقها (1) .` },
            { text: "فَيَذَرُهَا قَاعًا صَفْصَفًا", tafsir: `أي يذر الجبال ويجعلها ( قاعاً ) أي أرضا ملساء منكشفة ( صَفْصَفاً ) أي مستوية لا علو فيها ولا نتوء ، والصفصف هو : المستوي من الأرض.` },
            { text: "لَّا تَرَىٰ فِيهَا عِوَجًا وَلَآ أَمْتًا", tafsir: `في تلك القاع المصفصف المكون من الجبال ، حيث انتثرت على الأرض ( عِوَجاً ) اعوجاجا بالعلو والانخفاض ( وَلا أَمْتاً ) أي أكمة ، قالوا : العوج الانخفاض ، والأمت الارتفاع.` },
            { text: "يَوْمَئِذٍ يَتَّبِعُونَ ٱلدَّاعِىَ لَا عِوَجَ لَهُۥ وَخَشَعَتِ ٱلْأَصْوَاتُ لِلرَّحْمَٰنِ فَلَا تَسْمَعُ إِلَّا هَمْسًا", tafsir: `أي في يوم القيامة ( يَتَّبِعُونَ ) يتبع الناس ( الدَّاعِيَ ) الذي يدعوهم للحياة وللجمع في المحشر ( لا عِوَجَ لَهُ ) أي لا اعوجاج للداعي بحيث يدعو بعضا ويذر بعضا ، وإنما دعوة عامة شاملة للجميع ( وَخَشَعَتِ ) خضعت ( الْأَصْواتُ ) فلا ترتفع ( لِلرَّحْمنِ ) الذي يتفضل عليهم هناك كما تفضل عليهم هنا ( فَلا ( 1) بحار الأنوار : ج 7 ص 74. تَسْمَعُ إِلاَّ هَمْساً (108) يَوْمَئِذٍ لا تَنْفَعُ الشَّفاعَةُ إِلاَّ مَنْ أَذِنَ لَهُ الرَّحْمنُ وَرَضِيَ لَهُ قَوْلاً (109) يَعْلَمُ ما بَيْنَ أَيْدِيهِمْ وَما خَلْفَهُمْ وَلا يُحِيطُونَ بِهِ عِلْماً (110) وَعَنَتِ الْوُجُوهُ لِلْحَيِّ الْقَيُّومِ وَقَدْ خابَ مَنْ حَمَلَ ظُلْماً (111) تَسْمَعُ ) من الناس ، أيها السامع ( إِلَّا هَمْساً ) صوتا خفيا.` },
            { text: "يَوْمَئِذٍ لَّا تَنفَعُ ٱلشَّفَٰعَةُ إِلَّا مَنْ أَذِنَ لَهُ ٱلرَّحْمَٰنُ وَرَضِىَ لَهُۥ قَوْلًا", tafsir: `في يوم القيامة ( لا تَنْفَعُ الشَّفاعَةُ ) لأحد من المجرمين ( إِلَّا مَنْ أَذِنَ لَهُ الرَّحْمنُ ) بأن يشفع له ، أو يشفع ، فهناك كل من الشافع والمشفوع له يلزم أن يكون بتعيين الله سبحانه ( وَرَضِيَ ) الرحمن ( لَهُ ) لذلك الشافع أو المشفوع له ( قَوْلاً ) أي من كان مرضي القول ، بأن كان مؤمنا له مقام الشفاعة بالنسبة إلى الشافع ـ ومؤمنا غير مستحق للعقاب القطعي ـ بالنسبة إلى المشفوع له. [111] وليس هناك الأمر اعتباطا ، كالدنيا التي لا يعلم الحاكم فيها ، ما يستحق المحكوم له ، إن هناك في معرض الإله العالم بكل شيء فإنه سبحانه ( يَعْلَمُ ما بَيْنَ أَيْدِيهِمْ ) ما عمل الإنسان وقدمه إلى الآخرة ـ في حياته ـ ( وَما خَلْفَهُمْ ) أي ما خلفوه في الدنيا من الآثار الصالحة أو الفاسدة ( وَلا يُحِيطُونَ ) أولئك ( بِهِ ) أي بالله ( عِلْماً ) فهو يعلمهم ، وهم لا يعلمون منه إلا بقدر ما شاء.` },
            { text: "يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِهِۦ عِلْمًا", tafsir: `` },
            { text: "وَعَنَتِ ٱلْوُجُوهُ لِلْحَىِّ ٱلْقَيُّومِ وَقَدْ خَابَ مَنْ حَمَلَ ظُلْمًا", tafsir: `هناك ( عَنَتِ ) أي خضعت وذلت ( الْوُجُوهُ ) وإنما نسب الخضوع إلى الوجوه لأنها يظهر فيها أثر الخضوع ( لِلْحَيِّ الْقَيُّومِ ) فليس ميتا لا يعلم ، ولا غائبا لا يدرك ، وإنما هو حي قائم على كل الأمور مطلع عليها ( وَقَدْ خابَ ) خسر ( مَنْ حَمَلَ ظُلْماً ) أي نوع من وَمَنْ يَعْمَلْ مِنَ الصَّالِحاتِ وَهُوَ مُؤْمِنٌ فَلا يَخافُ ظُلْماً وَلا هَضْماً (112) وَكَذلِكَ أَنْزَلْناهُ قُرْآناً عَرَبِيًّا وَصَرَّفْنا فِيهِ مِنَ الْوَعِيدِ لَعَلَّهُمْ يَتَّقُونَ أَوْ يُحْدِثُ لَهُمْ ذِكْراً (113) فَتَعالَى اللهُ الْمَلِكُ الْحَقُّ الظلم كان شركا ، أو عصيانا ، فإنه يخسر ثواب الله سبحانه ، ويخسر نفسه فيما لو أدخل النار.` },
            { text: "وَمَن يَعْمَلْ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤْمِنٌ فَلَا يَخَافُ ظُلْمًا وَلَا هَضْمًا", tafsir: `أما ( مَنْ يَعْمَلْ مِنَ ) الأعمال ( الصَّالِحاتِ ) مقابل من عمل ظلما ( وَهُوَ مُؤْمِنٌ ) في العقيدة بما يلزم الإيمان به ( فَلا يَخافُ ) من الآخرة ( ظُلْماً ) إذ لا ظلم هناك على أحد ، بل عدل وفضل ( وَلا هَضْماً ) بأن يهضم من حقوقه وينقص من ثوابه ، والظلم أن يعاقب بلا سبب ، والهضم أن ينقص من حسناته.` },
            { text: "وَكَذَٰلِكَ أَنزَلْنَٰهُ قُرْءَانًا عَرَبِيًّا وَصَرَّفْنَا فِيهِ مِنَ ٱلْوَعِيدِ لَعَلَّهُمْ يَتَّقُونَ أَوْ يُحْدِثُ لَهُمْ ذِكْرًا", tafsir: `الذي أخبرناك من القصص وأخبار القيامة ( أَنْزَلْناهُ ) أي أنزلنا هذا الكتاب ( قُرْآناً عَرَبِيًّا ) ليعرفه قومك ، فإنه بلسانهم ولغتهم ، لئلا يقولوا لم نكن نعلم ( وَصَرَّفْنا فِيهِ مِنَ الْوَعِيدِ ) أي كررنا فيه من جنس الوعيد ، والتصريف هو تحويل المعنى الواحد في قوالب متعددة للفائدة ، والوعيد هو الإيعاد بالنار والعقاب ( لَعَلَّهُمْ يَتَّقُونَ ) أي لكي يتقي هؤلاء المعاصي والآثام ( أَوْ يُحْدِثُ لَهُمْ ذِكْراً ) بأن يذكرهم القرآن بمصائر الأمم المكذبة فيتذكرون وينقطعون عن الكفر والآثام ، والفرق بين الأمرين إن إحداث الذكر ، مقدمة للتقوى ، فإن الإنسان إذا تذكر كان معرضا لأن يتقي حيث يجيش في نفسه الخوف وينتهي بالآخرة إلى التقوى.` },
            { text: "فَتَعَٰلَى ٱللَّهُ ٱلْمَلِكُ ٱلْحَقُّ وَلَا تَعْجَلْ بِٱلْقُرْءَانِ مِن قَبْلِ أَن يُقْضَىٰٓ إِلَيْكَ وَحْيُهُۥ وَقُل رَّبِّ زِدْنِى عِلْمًا", tafsir: `الذي عنت له الوجوه ، ويعاقب وَلا تَعْجَلْ بِالْقُرْآنِ مِنْ قَبْلِ أَنْ يُقْضى إِلَيْكَ وَحْيُهُ وَقُلْ رَبِّ زِدْنِي عِلْماً (114) وَلَقَدْ عَهِدْنا إِلى آدَمَ مِنْ قَبْلُ فَنَسِيَ المجرمين ، ويثبت المطيعين ، الذي أنزل القرآن ليكون درسا وتذكرة ( وَ ) قد كان الرسول صلى‌الله‌عليه‌وآله‌وسلم إذا نزل عليه القرآن بادر بقراءته قبل تمام نزول الآية ، فأنزل سبحانه ( لا تَعْجَلْ بِالْقُرْآنِ ) قراءة ( مِنْ قَبْلِ أَنْ يُقْضى إِلَيْكَ وَحْيُهُ ) أي يتم الوحي ، بل أصبر حتى يتم جبرائيل ما جاء به ثم اقرأ ما جاء ، وقضى بمعنى تم ، كما قال سبحانه : ( فَإِذا قَضَيْتُمُ الصَّلاةَ ) (1) ( وَقُلْ ) يا رسول الله ، يا ( رَبِّ زِدْنِي عِلْماً ) فإن العلم هو الاطلاع على الكون ما سبق وما حضر وما يأتي ، وذلك من أوسع الأمور ، فالإحاطة به غير ميسور لغير الله سبحانه ، وهو الذي هيأ الأسباب للبشر لتعلم بعضها ، ولذا يأمر الله الرسول ، بأن يدعو للزيادة في العلم ، فإنه كلما زاد علم الإنسان ، زادت قيمته وأجره وقربه من الله سبحانه ـ فيما لو عمل بما علم ـ [116] وبمناسبة مبادرة الرسول في تلاوة القرآن قبل أن يقضى إليه وحيه خوف النسيان ، كما في سورة أخرى : ( سَنُقْرِئُكَ فَلا تَنْسى ) (2) يأتي الكلام حول نسيان آدم عليه‌السلام ما عهد الله معه ، ( وَلَقَدْ عَهِدْنا إِلى آدَمَ ) بأن لا يأكل من الشجرة إن أحب البقاء في الجنة ، وقلنا له : ( إِ نَّ لَكَ أَلَّا تَجُوعَ فِيها وَلا تَعْرى * وَأَنَّكَ لا تَظْمَؤُا فِيها وَلا تَضْحى ) (3) ( مِنْ قَبْلُ ) أي سابقا ( فَنَسِيَ ) العهد ، إما حقيقة ، أو المراد أنه ترك العهد ، فكان كالناسي ، من قبيل ( نَسُوا اللهَ فَنَسِيَهُمْ ) (4) وهذا أقرب إلى الاعتقاد بأن ( 1) النساء : 104. ( 2) الأعلى : 7. ( 3) طه : 119 و 120. ( 4) التوبة : 67. وَلَمْ نَجِدْ لَهُ عَزْماً (115) وَإِذْ قُلْنا لِلْمَلائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلاَّ إِبْلِيسَ أَبى (116) فَقُلْنا يا آدَمُ إِنَّ هذا عَدُوٌّ لَكَ وَلِزَوْجِكَ فَلا يُخْرِجَنَّكُما مِنَ الْجَنَّةِ فَتَشْقى (117) الأنبياء معصومون عن كل الخطأ والنسيان ( وَلَمْ نَجِدْ لَهُ عَزْماً ) أي تصميم رأي وثبات أمر ، أو المراد أنه لم يكن من الأنبياء أولي العزم ، وهم خمسة : نوح ، وإبراهيم ، وموسى ، وعيسى ، ومحمد عليهم‌السلام . [117] وإذ جاء ذكر من آدم عليه‌السلام ناسب السياق بيان قصته ، كما قال سبحانه : ( كَذلِكَ نَقُصُّ عَلَيْكَ مِنْ أَنْباءِ ما قَدْ سَبَقَ ) (1) ولأنه بدء الخلقة ، وبعد ذلك يأتي الختام ، ليناسب الجو العام للسورة ، التي هي حول العقيدة. ( وَ ) اذكر يا رسول الله ( إِذْ قُلْنا لِلْمَلائِكَةِ ) قولا لفظيا ، بخلق صوت سمعوه ، أو إلهاما ونقرا في القلب ، والملائكة مشتقة من « ألك » بمعنى الرسالة ، وسموا بذلك لأنهم رسل الله سبحانه في أوامره وتبليغاته ( اسْجُدُوا لِآدَمَ ) إذا سويته ونفخت فيه من روحي ( فَسَجَدُوا إِلَّا إِبْلِيسَ ) فإنه ( أَبى ) وامتنع من السجود كبرا وطغيانا.` },
            { text: "وَلَقَدْ عَهِدْنَآ إِلَىٰٓ ءَادَمَ مِن قَبْلُ فَنَسِىَ وَلَمْ نَجِدْ لَهُۥ عَزْمًا", tafsir: `` },
            { text: "وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ", tafsir: `` },
            { text: "فَقُلْنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوٌّ لَّكَ وَلِزَوْجِكَ فَلَا يُخْرِجَنَّكُمَا مِنَ ٱلْجَنَّةِ فَتَشْقَىٰٓ", tafsir: `أي قلنا لآدم بعد كبر الشيطان عن سجدته ( إِنَّ هذا ) الشيطان ( عَدُوٌّ لَكَ وَلِزَوْجِكَ ) حواء ، يريد بكما الشر والخديعة فلا تغترا به واحفظا أنفسكما عن كيده ومكره ( فَلا يُخْرِجَنَّكُما مِنَ الْجَنَّةِ ) أي لا يكون سبب خروجكما من الجنة بأن تطيعاه فيما نهى الله سبحانه ـ نهي تنزيه ـ ليكون مصيركما الخروج ( فَتَشْقى ) أي فتقع في ( 1) طه : 100. إِنَّ لَكَ أَلاَّ تَجُوعَ فِيها وَلا تَعْرى (118) وَأَنَّكَ لا تَظْمَؤُا فِيها وَلا تَضْحى (119) فَوَسْوَسَ إِلَيْهِ الشَّيْطانُ قالَ يا آدَمُ هَلْ أَدُلُّكَ عَلى شَجَرَةِ الْخُلْدِ وَمُلْكٍ لا يَبْلى (120) تعب العمل وكد الاكتساب وزحمات الدنيا ، فإن الشقاء التعب ، كما تقدم في قوله : ( طه* ما أَنْزَلْنا عَلَيْكَ الْقُرْآنَ لِتَشْقى ) (1) وإنما جاء بالمفرد لأن المخاطب آدم ، ورعاية لرؤوس الآي ، وإلا فالمراد شقاء كليهما. [119] ثم بين سبحانه محاسن البقاء في الجنة التي تزول بالخروج منها ، وقد كان الأمر للإرشاد كأوامر الطبيب الذي يقول إن عملت بهذه الوصفة ، لم تمرض ، فإن أمره إرشادي ليس بواجب وإنما تعود الفائدة إلى المريض بذاته ( إِنَّ لَكَ ) يا آدم ( أَلَّا تَجُوعَ فِيها ) أي في الجنة لسعة طعامها وعدم التعب في تناوله ( وَلا تَعْرى ) لكثرة ثياب الجنة ، فلا يبقى الإنسان فيها عاريا ، وبحاجة إلى الكد والعمل لتحصيل الثياب.` },
            { text: "إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعْرَىٰ", tafsir: `` },
            { text: "وَأَنَّكَ لَا تَظْمَؤُا۟ فِيهَا وَلَا تَضْحَىٰ", tafsir: `يا آدم ( لا تَظْمَؤُا فِيها ) أي لا تعطش في الجنة لوفرة مياهها ( وَلا تَضْحى ) يقال ضحى الرجل إذا برز للشمس ، أي لا يصيبك حر الشمس.` },
            { text: "فَوَسْوَسَ إِلَيْهِ ٱلشَّيْطَٰنُ قَالَ يَٰٓـَٔادَمُ هَلْ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلْخُلْدِ وَمُلْكٍ لَّا يَبْلَىٰ", tafsir: `أي ألقى في نفس آدم ( الشَّيْطانُ ) إلقاء خفية ( قالَ يا آدَمُ ) إنك لا تبقى في الجنة أبدا إلا أن تعمل بوصيتي وتأخذ بإرشادي ف ( هَلْ أَدُلُّكَ ) وأعرفك ( عَلى شَجَرَةِ الْخُلْدِ ) الشجرة التي من أكل منها خلد في الجنة ولم يخرج منها أبدا ( وَمُلْكٍ لا يَبْلى ) لا ( 1) طه : 2 و 3. فَأَكَلا مِنْها فَبَدَتْ لَهُما سَوْآتُهُما وَطَفِقا يَخْصِفانِ عَلَيْهِما مِنْ وَرَقِ الْجَنَّةِ وَعَصى آدَمُ رَبَّهُ فَغَوى (121) يفنى ولا يزول ؟ [122] وقد مال آدم إلى كلامه ، إذ أقسم له أنه ناصح مشفق ، ولم يكن آدم سمع أحدا يحلف بالله كاذبا وحيث أمرهما بالأكل من الشجرة المنهية ، تذكر آدم نهي الله سبحانه بقوله لهما : ( وَلا تَقْرَبا هذِهِ الشَّجَرَةَ ) (1) لكن الشيطان تدارك الأمر وقال ( ما نَهاكُما رَبُّكُما عَنْ هذِهِ الشَّجَرَةِ إِلَّا أَنْ تَكُونا مَلَكَيْنِ أَوْ تَكُونا مِنَ الْخالِدِينَ ) (2) يعني أن النهي إنما هو لأجل أن تبقيان على حالتكما الإنسانية ، فإذا أكلتما أصبحتما ملكين ، وبالنتيجة نفذت المكيدة فيهما ( فَأَكَلا ) آدم وحواء ( مِنْها ) من تلك الشجرة ( فَبَدَتْ لَهُما سَوْآتُهُما ) أي ظهرت لهما عورتهما ، حيث أن بمجرد الأكل ، سقطت ملابسهما عن أبدانهما ، كما قال سبحانه : ( يَنْزِعُ عَنْهُما لِباسَهُما ) (3) والسوءة هي العورة ( وَطَفِقا ) أي شرع آدم وحواء ( يَخْصِفانِ عَلَيْهِما ) يلصقان على أنفسهما ـ ليخرجا من العري وظهور السوءة ـ ( مِنْ وَرَقِ الْجَنَّةِ ) من أوراق أشجارها. ( وَعَصى آدَمُ رَبَّهُ ) خالف أمره الإرشادي ، فإن الأمر على ثلاثة أقسام : الوجوبي ، والندبي ، والإرشادي ، وفي مخالفة كل منها يستعمل لفظ العصيان ، يقول الطبيب لمريضه المخالف لإرشاده : لم عصيتني حتى يدوم مرضك ؟ ( فَغَوى ) أي ضل الطريق المسعد له. ( 1) البقرة : 36. ( 2) الأعراف : 21. ( 3) الأعراف : 28. ثُمَّ اجْتَباهُ رَبُّهُ فَتابَ عَلَيْهِ وَهَدى (122) قالَ اهْبِطا مِنْها جَمِيعاً بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ فَإِمَّا يَأْتِيَنَّكُمْ مِنِّي هُدىً فَمَنِ اتَّبَعَ هُدايَ فإن الغواية ضلال الطريق ، وهو كما يصح في مخالفة الوجوب ، يصح في مخالفة الإرشاد ، فإن الأكل من الشجرة سبب أن يخرج من الجنة ، وأي ضلال عن السعادة أكبر من هذا ؟ [123] فندم آدم مما فعله وعرف أن الشيطان غره وحلف بالله كاذبا ، فأخذ يتوب ويبكي ( ثُمَّ اجْتَباهُ رَبُّهُ ) أي اصطفاه واختاره لأن يكون نبيا وغفر ذنبه في مخالفته للأمر الإرشادي ( فَتابَ عَلَيْهِ ) التوبة هي الرجوع ، فإن الإنسان العاصي يبتعد عن الله ، والله سبحانه يعرض عنه ، فإذا ندم الإنسان واستغفر ، وتاب إلى الله ، تاب الله عليه ورجع إليه ( وَهَدى ) أي هداه لمصالحه ، وأراه الطريق الموجب لعودته إلى الجنة ، بعد ما غوى وضل الطريق.` },
            { text: "فَأَكَلَا مِنْهَا فَبَدَتْ لَهُمَا سَوْءَٰتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ ٱلْجَنَّةِ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ", tafsir: `` },
            { text: "ثُمَّ ٱجْتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيْهِ وَهَدَىٰ", tafsir: `` },
            { text: "قَالَ ٱهْبِطَا مِنْهَا جَمِيعًۢا بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ فَإِمَّا يَأْتِيَنَّكُم مِّنِّى هُدًى فَمَنِ ٱتَّبَعَ هُدَاىَ فَلَا يَضِلُّ وَلَا يَشْقَىٰ", tafsir: `الله سبحانه ( اهْبِطا ) أيها الفريقان فريق آدم وحواء ، وفريق الشيطان ( مِنْها ) أي اخرجا من الجنة ( جَمِيعاً ) كلكم ، والهبوط إما باعتبار علو الجنة حسا عن الأرض ، وإما باعتبار علوها رتبة ( بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ ) فإن الشيطان عدو لآدم وحواء ، وهما عدوان له ، وباعتبار آخر ، أن الرجل والمرأة أيضا عدو بعضهم لبعض ( فَإِمَّا يَأْتِيَنَّكُمْ مِنِّي هُدىً ) « إن » للشرط و « ما » زائدة لتجميل الكلام ، أي إن أتاكم من طرفي أسباب الهداية ، بأن أمرتكم بأوامر تهديكم إلى طريق الحق في الدنيا ، والسعادة في الآخرة ( فَمَنِ اتَّبَعَ هُدايَ ) وأخذ فَلا يَضِلُّ وَلا يَشْقى (123) وَمَنْ أَعْرَضَ عَنْ ذِكْرِي فَإِنَّ لَهُ مَعِيشَةً ضَنْكاً وَنَحْشُرُهُ يَوْمَ الْقِيامَةِ أَعْمى (124) قالَ رَبِّ لِمَ حَشَرْتَنِي أَعْمى وَقَدْ كُنْتُ بَصِيراً (125) قالَ كَذلِكَ بأوامري وإرشاداتي ( فَلا يَضِلُ ) طريق السعادة ، كما غوى آدم ( وَلا يَشْقى ) لا يبقى في تعب ونصب كما شقي آدم أي وقع في النصب والتعب ـ وهذا خطاب عام لكل البشر ، وإن كان طرف الخطاب هم الثلاثة ـ.` },
            { text: "وَمَنْ أَعْرَضَ عَن ذِكْرِى فَإِنَّ لَهُۥ مَعِيشَةً ضَنكًا وَنَحْشُرُهُۥ يَوْمَ ٱلْقِيَٰمَةِ أَعْمَىٰ", tafsir: `بأن لم يتبع أوامري ، التي ذكرته بها ، وسميت الأوامر ذكرا ، لما أودع في فطرة الإنسان من أصولها وجذورها ( فَإِنَّ لَهُ ) في الدنيا ( مَعِيشَةً ضَنْكاً ) ضيقة ، وذلك لأن أوامر الله سبحانه أكثر ملائمة للحياة ، فالإعراض عنها يوجب ضيق العيش ماديا أو روحيا ولذا نرى أن الكفار حتى في أوج ماديتهم الظاهرية في أضنك الحالات الروحية وأضيق المجالات النفسية ( وَنَحْشُرُهُ ) نحشر المعرض ، ومعنى الحشر جمعه مع سائر بني نوعه في ( يَوْمَ الْقِيامَةِ أَعْمى ) العين ، لا يرى شيئا ، [126] وكم يتأذى الإنسان في ساحة مهولة مدتها خمسون ألف سنة ، وفيها من الأهوال ما تذهل البصير فكيف بالأعمى ، ولذا يسأل الكافر ( قالَ رَبِّ لِمَ حَشَرْتَنِي أَعْمى ) أي لماذا أحضرتني في هذا الموقف أعمى البصر ( وَ ) الحال أني في الدنيا ( قَدْ كُنْتُ بَصِيراً ) أرى الأشياء ؟` },
            { text: "قَالَ رَبِّ لِمَ حَشَرْتَنِىٓ أَعْمَىٰ وَقَدْ كُنتُ بَصِيرًا", tafsir: `` },
            { text: "قَالَ كَذَٰلِكَ أَتَتْكَ ءَايَٰتُنَا فَنَسِيتَهَا وَكَذَٰلِكَ ٱلْيَوْمَ تُنسَىٰ", tafsir: `الله في جوابه ( كَذلِكَ ) العمى الذي أصابك هنا. كما كنت في الدنيا ، فقد كنت في الدنيا أعمى البصيرة ، ولذا ابتليت هنا بعمي أَتَتْكَ آياتُنا فَنَسِيتَها وَكَذلِكَ الْيَوْمَ تُنْسى (126) وَكَذلِكَ نَجْزِي مَنْ أَسْرَفَ وَلَمْ يُؤْمِنْ بِآياتِ رَبِّهِ وَلَعَذابُ الْآخِرَةِ أَشَدُّ وَأَبْقى (127) أَ فَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنا قَبْلَهُمْ مِنَ الْقُر ُونِ يَمْشُونَ فِي مَساكِنِهِمْ البصر فقد ( أَتَتْكَ ) وجاءتك ( آياتُنا ) الدالة على وجودنا وسائر صفاتنا ( فَنَسِيتَها ) تركتها فعل الناسي بالمنسي ، وأعرضت عنها وأغفلت بصيرتك دونها ( وَكَذلِكَ ) أي كنسيانك عن الآيات ( الْيَوْمَ ) في القيامة ( تُنْسى ) تهمل ولا يعتنى بشأنك ، بل تبقى في تعب العمى ونصب الأهوال المتراكمة التي تلقفك من هنا وهناك.` },
            { text: "وَكَذَٰلِكَ نَجْزِى مَنْ أَسْرَفَ وَلَمْ يُؤْمِنۢ بِـَٔايَٰتِ رَبِّهِۦ وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَشَدُّ وَأَبْقَىٰٓ", tafsir: `أي كما جزينا من نسي الآيات بالضنك والعمى والنسيان له ( نَجْزِي ) كل ( مَنْ أَسْرَفَ ) جاوز الحد بالكفر والعصيان ( وَلَمْ يُؤْمِنْ بِآياتِ رَبِّهِ ) بيان لقوله « من أسرف » أو لأن عدم الإيمان تسبقه حالة نفسية تجاوز به عن الحد ( وَلَعَذابُ الْآخِرَةِ ) للمسرف ( أَشَدُّ ) من الضنك في الدنيا ( وَأَبْقى ) أكثر بقاء ، فإن الضنك في الدنيا هين زائل ، أما عذاب الآخرة فهو شديد باق. [129] ثم بين سبحانه أن الكفار في ضلالة حيث لم يعتبروا بما مضى من عذاب الله للأمم السالفة ( أَ فَلَمْ يَهْدِ لَهُمْ ) استفهام إنكاري توبيخي ، أي ألم يرشد هؤلاء ( كَمْ أَهْلَكْنا قَبْلَهُمْ مِنَ الْقُرُونِ ) هذا فاعل يهد ، أي إهلاكنا للقرون السابقة ، لم يصر سببا لهداية هؤلاء إلى الحق ، وخوفهم من العقاب في الدنيا أن تمادوا في غيهم وكفرهم ( يَمْشُونَ ) هؤلاء الكفار المعاصرين لك يا رسول الله ( فِي مَساكِنِهِمْ ) فقد كان إِنَّ فِي ذلِكَ لَآياتٍ لِأُولِي النُّهى (128) وَلَوْ لا كَلِمَةٌ سَبَقَتْ مِنْ رَبِّكَ لَكانَ لِزاماً وَأَجَلٌ مُسَمًّى (129) فَاصْبِرْ كفار مكة يمرون بمساكن عاد وثمود وقوم لوط عند ذهابهم إلى الشام ، ويرون آثارهم وعلاماتهم ، كما قال سبحانه : ( وَإِنَّكُمْ لَتَمُرُّونَ عَلَيْهِمْ مُصْبِحِينَ* وَبِاللَّيْلِ ) (1) أ فلا يخافون أن يصيبهم ما أصاب أولئك ( إِنَّ فِي ذلِكَ ) الإهلاك لأولئك ( لَآياتٍ ) لعبر ودلالات ( لِأُولِي النُّهى ) النهى جمع نهية ، وهو العقل أي لأصحاب العقول ، يعتبروا بها ولا يعملوا مثل أعمال أولئك حتى يبتلوا بمثل مصيرهم.` },
            { text: "أَفَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا قَبْلَهُم مِّنَ ٱلْقُرُونِ يَمْشُونَ فِى مَسَٰكِنِهِمْ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّأُو۟لِى ٱلنُّهَىٰ", tafsir: `` },
            { text: "وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَكَانَ لِزَامًا وَأَجَلٌ مُّسَمًّى", tafsir: `في تأخير العذاب عن الكفار في الدنيا ، فقد أراد الله سبحانه ، وإرادته كلمته ، أن لا يعذب هؤلاء في الدنيا بمثل عذاب الأمم السابقة ، ولعل ذلك لأجل أن هذه الأمة تأتي بأولاد وذراري صالحين ، كما صار من أبي عامر « حنظلة » ومن أبي سفيان « أم حبيبة » وهكذا ، والله سبحانه لا يعذب إلا إذا لم يكن صالح في ذرية الكافر كما قال سبحانه : ( لَوْ تَزَيَّلُوا لَعَذَّبْنَا ) (2) وقال ( وَلا يَلِدُوا إِلَّا فاجِراً كَفَّاراً ) (3) ( لَكانَ ) العذاب ( لِزاماً ) لهم ، واللزام مصدر ، وصف به كقولك زيد عدل ( وَأَجَلٌ مُسَمًّى ) عطف على « كلمة » أي لو لا الكلمة والأجل المسمى أي المدة التي سميت لهؤلاء الكفار لكان العذاب لازما لهم. [131] وإذ كان لهؤلاء الكفار مدة لا بد أن يقضوها حتى يأتيهم الموت ، وإن الله لم يشأ هلاكهم مثل إهلاكه للأمم السابقة ( فَاصْبِرْ ) يا رسول الله ( 1) الصافات : 138 و 139. ( 2) الفتح : 26. ( 3) نوح : 28. عَلى ما يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِها وَمِنْ آناءِ اللَّيْلِ فَسَبِّحْ وَأَطْرافَ النَّهارِ لَعَلَّكَ تَرْضى (130) وَلا تَمُدَّنَّ عَيْنَيْكَ ( عَلى ما يَقُولُونَ ) في شأن التوحيد والرسالة وسائر أنواع أذاهم ( وَسَبِّحْ بِحَمْدِ رَبِّكَ ) أي نزه الله بالحمد ، فإن الحمد ثناء وتنزيه ـ كما تقدم ـ ( قَبْلَ طُلُوعِ الشَّمْسِ ) صباحا ( وَقَبْلَ غُرُوبِها ) أي عصرا ( وَمِنْ آناءِ اللَّيْلِ فَسَبِّحْ ) آناء الليل ساعاته ، وهو جمع « إنى » على وزن « إلى » ولعل الإتيان ب « من » دون « في » لإفادة الابتداء والشروع أي أشرع بالتسبيح من ساعات الليل ( وَ ) سبح ( أَطْرافَ النَّهارِ ) بالإضافة إلى قبل الغروب والطلوع ، كما بعد الطلوع ووقت الضحى ، وأول الظهر وعند وقت العصر ( لَعَلَّكَ ) يا رسول الله ( تَرْضى ) فإن الإنسان الدائم الاتصال بالله ، الذي يذكره صباحا ومساء وفي ساعات الليل وساعات النهار ، تطمئن نفسه بالله ، ويرضى لمقدراته وأحكامه وسنته لأن يكون عارفا بالله هادئا إلى ما قضى وقدر ، فالرضا من ثمار التسبيح ، كما قال سبحانه : ( وَمَنْ يُؤْمِنْ بِاللهِ يَهْدِ قَلْبَهُ ) (1) و ( أَلا بِذِكْرِ اللهِ تَطْمَئِنُّ الْقُلُوبُ ) (2) ثم إن تكرار التسبيح لتعلق أحدهما بالصباح والمساء ، وأحدهما بآناء الليل وأطراف النهار. [132] اتصل بالله سبحانه وقر نفسا بفضله ولطفه وذكره ( وَلا تَمُدَّنَّ عَيْنَيْكَ ) أي لا تنظر نظر رغبة وميل ـ فإن الرؤية قسم من إمداد العين ( 1) التغابن : 12. ( 2) الرعد : 29. إِلى ما مَتَّعْنا بِهِ أَزْواجاً مِنْهُمْ زَهْرَةَ الْحَياةِ الدُّنْيا لِنَفْتِنَهُمْ فِيهِ وَرِزْقُ رَبِّكَ خَيْرٌ وَأَبْقى (131) نحو الشيء لأن الإنسان يتصل بذلك الشيء بواسطة إلقاء شعاع عينه عليه ، وإن قلنا في مسألة الرؤية بالانطباع ـ ( إِلى ما مَتَّعْنا بِهِ ) الضمير يعود إلى « ما » ( أَزْواجاً ) أصنافا ( مِنْهُمْ ) من البشر أو من الكفار ، والمعنى لا ترغب في الجاه والمال والبنين التي متع بها الناس ، فإنها أمور زائلة فانية ، ولا ينبغي للإنسان أن يرغب فيها ، فإنما هي ( زَهْرَةَ الْحَياةِ الدُّنْيا ) الزهرة هي النور الذي يرون عند الرؤية ، ولذا يقال لكل شيء مستنير زاهر ، ونصبها على كونها حالا من « ما » أي أن ما متعنا القوم ، إنما هي بهجة الحياة العاجلة ونضارتها ( لِنَفْتِنَهُمْ فِيهِ ) أي نمتحنهم بسببه ، والضمير يعود إلى « ما » وجيء ب « في » لأن الإنسان يعيش في وسط تلك البهجة والنضارة. وليس المعنى أن لا يرغب الإنسان في الحياة ، بل المعنى أن لا يجعل الحياة منتهى نظره ـ بل ينظر إليها نظرا عرضيا ، ولذا قال سبحانه : ( وَمِنْهُمْ مَنْ يَقُولُ رَبَّنا آتِنا فِي الدُّنْيا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً ) (1) ( وَرِزْقُ رَبِّكَ ) الذي وعدك في الآخرة ( خَيْرٌ ) من متعة الحياة الدنيا ( وَأَبْقى ) أي أكثر بقاء لأن الحياة الدنيا فانية ، وتلك الحياة باقية ، أو أن المراد ، أن متع الكفار من الحرام ، ورزق الله من الحلال خير لعدم العقاب فيه ، وأبقى لأنه ذو بركة وبقاء بخلاف الحرام الذي لا بركة فيه ، كما قال سبحانه : ( يَمْحَقُ اللهُ الرِّبا وَيُرْبِي الصَّدَقاتِ ) (2) ( 1) البقرة : 202. ( 2) البقرة : 277. وَأْمُرْ أَهْلَكَ بِالصَّلاةِ وَاصْطَبِرْ عَلَيْها لا نَسْئَلُكَ رِزْقاً نَحْنُ نَرْزُقُكَ وَالْعاقِبَةُ لِلتَّقْوى (132) وَقالُوا لَوْ لا يَأْتِينا بِآيَةٍ مِنْ رَبِّهِ أَ وَلَمْ تَأْتِهِمْ [133] وإذا توجهت أنت إلى الله سبحانه ولم تمد عينيك إلى زهرة الحياة ، فاللازم أن توجه عائلتك إلى الله سبحانه ، كما توجهت أنت ( وَأْمُرْ أَهْلَكَ بِالصَّلاةِ ) فإنها عمود الدين ، والصلة بين الله وبين العبد ( وَاصْطَبِرْ ) أي اصبر ، وكأن الاصطبار أقوى دلالة من الصبر. لأن زيادة المبنى تدل على زيادة المعنى. ( عَلَيْها ) على الصلاة فإن فيها صعوبة التكرار كل يوم خمس مرات ، مما لا يتأتى إلا بصبر طويل ، ولعل تخصيص الأهل ، لكونهم الأسوة ، ولفرض تعليم المسلمين فإن الواجب على المسلم أن يبدأ بأهله ، ثم بين سبحانه أن هذا التكليف ليس مستلزما للمشقة كطلب سائر الموالي من عبيدهم أن يكتسبوا لهم ويأتوا لهم بالرزق ( لا نَسْئَلُكَ ) يا رسول الله ( رِزْقاً ) بل عبادة وطاعة ( نَحْنُ نَرْزُقُكَ ) فإن من يرزق لا يطلب الرزق ( وَالْعاقِبَةُ لِلتَّقْوى ) فرزقك في الحياة علينا ، وعاقبتك في الآخرة على التقوى ، وفي الأحاديث ما حاصله أن الله وكل أمر الدنيا إلى نفسه ، وأمر الآخرة إلى الناس ، فاللازم أن يعمل الإنسان حتى ينال سعادة الآخرة. [134] وفي ختام السورة يأتي الحديث عن المتكبرين والكفار الذين لا يؤمنون ويأتون بحجج واهية ، حيث أن الجو العام للسورة كان حول العقيدة ، والمؤمنين والمكذبين ( وَقالُوا ) يعني الكفار ( لَوْ لا ) أي لماذا لا ( يَأْتِينا ) الرسول ( بِآيَةٍ مِنْ رَبِّهِ ) أي بخارقة نقترحها عليه ؟ فقد كانوا يقترحون خوارق تعنتا لا حقيقة واستظهارا ( أَ وَلَمْ تَأْتِهِمْ ) بَيِّنَةُ ما فِي الصُّحُفِ الْأُولى (133) وَلَوْ أَنَّا أَهْلَكْناهُمْ بِعَذابٍ مِنْ قَبْلِهِ لَقالُوا رَبَّنا لَوْ لا أَرْسَلْتَ إِلَيْنا رَسُولاً فَنَتَّبِعَ آياتِكَ مِنْ قَبْلِ أَنْ نَذِلَّ وَنَخْزى (134) قُلْ ألم تصل إليهم ( بَيِّنَةُ ما فِي الصُّحُفِ الْأُولى ) ؟ بيان ما في الكتب الأولى من أخبار الأمم التي أهلكناهم لما اقترحوا الآيات ثم كفروا بها فما ذا يؤمنهم أن يكون حالهم كحال أولئك الأمم ، إذا جئناهم بآية كفروا ، فتحل عليهم العقوبة ؟ أو المراد إنا جئناهم بآية ، وهي القرآن الذي هو مشتمل على الحجج التي كانت في الصحف السابقة ، وهل من بينة وحجة بعد القرآن ؟ و « بينة » صفة « آية » المقدرة ، أي الآية البينة ـ بمعنى الواضحة ـ. [135] لقد تمت على هؤلاء الحجة بنزول القرآن ، فإن يهلكوا بعد ذلك ، ويدخلوا النار ، فليس إلا من أنفسهم ولسوء تلقيهم للآيات ( وَلَوْ أَنَّا أَهْلَكْناهُمْ ) أي أهلكنا هؤلاء الكفار ( بِعَذابٍ مِنْ قَبْلِهِ ) من قبل القرآن أو من قبل الرسول ـ أهلكناهم بأعمالهم السيئة ، وبكفرهم ـ ( لَقالُوا ) واحتجوا على الله سبحانه يا ( رَبَّنا لَوْ لا أَرْسَلْتَ إِلَيْنا رَسُولاً ) أي لماذا لم ترسل إلينا من يبين لنا أوامرك ( فَنَتَّبِعَ آياتِكَ ) ونعمل بما فيها ( مِنْ قَبْلِ أَنْ نَذِلَ ) بالعذاب ( وَنَخْزى ) من النار ؟ وقد كان حينذاك الحق معهم ، فكيف يعذب من لم يتم عليه الحجة ؟ أما وقد أرسلنا الرسول وعصوا ، فإنهم قد استحقوا العذاب ولو عذبناهم لا مجال لهم للاحتجاج. [136] وإذ قد تمت الحجة عليهم ، ولم يؤمنوا ، فلينتظروا العذاب ( قُلْ ) كُلٌّ مُتَرَبِّصٌ فَتَرَبَّصُوا فَسَتَعْلَمُونَ مَنْ أَصْحابُ الصِّراطِ السَّوِيِّ وَمَنِ اهْتَدى (135) يا رسول الله لهم ( كُلٌ ) أيّ واحد منا ومنكم ( مُتَرَبِّصٌ ) منتظر ليرى المصير ، وينظر لمن الغلب ، وأينا يعذب وأينا ينعم ؟ ( فَتَرَبَّصُوا ) أي فانتظروا أيها الكفار ـ وهذا أمر للتهديد ـ ( فَسَتَعْلَمُونَ ) إذا متّم ( مَنْ ) منا ومنكم ( أَصْحابُ الصِّراطِ السَّوِيِ ) أي الطريق المستقيم ، والدين الصحيح ( وَمَنِ اهْتَدى ) إلى الحق ، هل نحن أم أنتم ؟ تقريب القران الى الأذهان من آية ( 1) سورة الأنبياء إلى آية ( 79) سورة الحج بسم الله الرّحمن الرّحيم الحمد لله رب العالمين والصلاة والسلام على أشرف الأنبياء والمرسلين محمد المصطفى وعترته الطاهرين (21)` },
            { text: "فَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ ٱلشَّمْسِ وَقَبْلَ غُرُوبِهَا وَمِنْ ءَانَآئِ ٱلَّيْلِ فَسَبِّحْ وَأَطْرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرْضَىٰ", tafsir: `` },
            { text: "وَلَا تَمُدَّنَّ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِهِۦٓ أَزْوَٰجًا مِّنْهُمْ زَهْرَةَ ٱلْحَيَوٰةِ ٱلدُّنْيَا لِنَفْتِنَهُمْ فِيهِ وَرِزْقُ رَبِّكَ خَيْرٌ وَأَبْقَىٰ", tafsir: `` },
            { text: "وَأْمُرْ أَهْلَكَ بِٱلصَّلَوٰةِ وَٱصْطَبِرْ عَلَيْهَا لَا نَسْـَٔلُكَ رِزْقًا نَّحْنُ نَرْزُقُكَ وَٱلْعَٰقِبَةُ لِلتَّقْوَىٰ", tafsir: `` },
            { text: "وَقَالُوا۟ لَوْلَا يَأْتِينَا بِـَٔايَةٍ مِّن رَّبِّهِۦٓ أَوَلَمْ تَأْتِهِم بَيِّنَةُ مَا فِى ٱلصُّحُفِ ٱلْأُولَىٰ", tafsir: `` },
            { text: "وَلَوْ أَنَّآ أَهْلَكْنَٰهُم بِعَذَابٍ مِّن قَبْلِهِۦ لَقَالُوا۟ رَبَّنَا لَوْلَآ أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ ءَايَٰتِكَ مِن قَبْلِ أَن نَّذِلَّ وَنَخْزَىٰ", tafsir: `` },
            { text: "قُلْ كُلٌّ مُّتَرَبِّصٌ فَتَرَبَّصُوا۟ فَسَتَعْلَمُونَ مَنْ أَصْحَٰبُ ٱلصِّرَٰطِ ٱلسَّوِىِّ وَمَنِ ٱهْتَدَىٰ", tafsir: `` }
        ]
    },
    21: { // سورة الأنبياء
        name: "الأنبياء",
        basmalaTafsir: ``,
        verses: [
            { text: "ٱقْتَرَبَ لِلنَّاسِ حِسَابُهُمْ وَهُمْ فِى غَفْلَةٍ مُّعْرِضُونَ", tafsir: `الاقتراب : افتعال من القرب ، يعني قرب وقت حساب الناس ، والمراد به إما القبر ، وإما الموت فإن كليهما قريب وإن ظن الإنسان بعدهما ، ولذا قال الرسول : بعثت أنا والساعة كهاتين ـ وأشار بإصبعيه ـ ( وَهُمْ فِي غَفْلَةٍ ) عن الساعة لا يستعدون لها ولأهوالها بالأعمال الصالحة ( مُعْرِضُونَ ) عن التذكر والاستعداد.` },
            { text: "مَا يَأْتِيهِم مِّن ذِكْرٍ مِّن رَّبِّهِم مُّحْدَثٍ إِلَّا ٱسْتَمَعُوهُ وَهُمْ يَلْعَبُونَ", tafsir: `أي جديد ، كالآيات التي تنزل ، والأحكام التي توحى ، لأجل تذكيرهم وإرشادهم ( إِلَّا اسْتَمَعُوهُ ) مجرد سماع بآذانهم ( وَهُمْ يَلْعَبُونَ ) مشغولون باللعب ، لا يبالون بالذكر ، فإن الدنيا لعب ولهو. [4] في حال كونهم ( لاهِيَةً قُلُوبُهُمْ ) أي أن قلوبهم في لهو ، وهو مقابل الجد ، فآذانهم تسمع ، وقلوبهم لا تطيع ( وَأَسَرُّوا النَّجْوَى الَّذِينَ ظَلَمُوا ) أي إن الذين ظلموا أنفسهم بالكفر والعصيان ، أخذ يناجي بعضهم بعضا في شأن القرآن والرسول يقولون ( هَلْ هذا ) النبي صلى‌الله‌عليه‌وآله‌وسلم ( إِلَّا بَشَرٌ مِثْلُكُمْ ) ؟ استفهام إنكاري ، أي ليس الرسول إلا أحد أفراد البشر فكيف يدعي النبوة ؟ وكيف يؤمن به الناس ، والحال أنه ليس من الملائكة حتى يليق بهذا المنصب الذي يدعيه ، ثم أرادوا زيادة تنفير الناس عن الرسول صلى‌الله‌عليه‌وآله‌وسلم بقول بعضهم لبعض ( أَ فَتَأْتُونَ السِّحْرَ ) أي وَأَنْتُمْ تُبْصِرُونَ (3) قالَ رَبِّي يَعْلَمُ الْقَوْلَ فِي السَّماءِ وَالْأَرْضِ وَهُوَ السَّمِيعُ الْعَلِيمُ (4) بَلْ قالُوا أَضْغاثُ أَحْلامٍ بَلِ افْتَراهُ بَلْ هُوَ شاعِرٌ فَلْيَأْتِنا بِآيَةٍ كيف تقبلون السحر الذي أتى به محمد ، وتأتون بمعنى تذهبون إلى السحر ( وَأَنْتُمْ تُبْصِرُونَ ) والحال أنتم ترون أنه سحر.` },
            { text: "لَاهِيَةً قُلُوبُهُمْ وَأَسَرُّوا۟ ٱلنَّجْوَى ٱلَّذِينَ ظَلَمُوا۟ هَلْ هَٰذَآ إِلَّا بَشَرٌ مِّثْلُكُمْ أَفَتَأْتُونَ ٱلسِّحْرَ وَأَنتُمْ تُبْصِرُونَ", tafsir: `` },
            { text: "قَالَ رَبِّى يَعْلَمُ ٱلْقَوْلَ فِى ٱلسَّمَآءِ وَٱلْأَرْضِ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ", tafsir: `رسول الله صلى‌الله‌عليه‌وآله‌وسلم في جواب هؤلاء ، وكان الإتيان بالفعل الماضي لإشعارهم بعدم أهمية إشكالهم ، فإذا أشكل عليك إنسان تقول : قلت لك سابقا ، تريد أن هذا الإشكال ليس بالجديد ، وإنما قد أكل الدهر عليه وشرب ( رَبِّي يَعْلَمُ الْقَوْلَ ) أي يعلم كل ما يقال حول القرآن والرسول ، في جملة سائر الأقوال التي يعلمها ( فِي السَّماءِ وَالْأَرْضِ ) فأين ما كان القول يعلمه ولا يغيب عنه ، وهذا كالتهديد ، بأن أقوالهم محفوظة سيجازون عليها ( وَهُوَ السَّمِيعُ ) لأقوالهم التي يتناجون بها ( الْعَلِيمُ ) بأفعالهم وضمائرهم. [6] إنهم ما آمنوا بالرسول والقرآن ( بَلْ قالُوا ) حول القرآن إنه ( أَضْغاثُ أَحْلامٍ ) أضغاث جمع ضغث ، وهو : الخلط من الشيء ، والأحلام جمع حلم ، وهو : المنام ، يعني : إن الرسول يرى في المنام أحلاما مضطربة فيلفقها ويصنعها قرآنا ( بَلْ ) قال بعضهم ( افْتَراهُ ) فليس الله نزل شيئا وإنما هو يكذب على الله سبحانه في نسبة القرآن إليه ( بَلْ ) قال جماعة ( هُوَ ) أي الرسول صلى‌الله‌عليه‌وآله‌وسلم ( شاعِرٌ ) وأن القرآن شعر ، فقد كان القرآن بهرهم لا يدرون ماذا يقولون حوله ، فمرة يقولون حلم ، وأخرى كذب عن عمد ، وثالثة شعر ورابعة سحر وهكذا ( فَلْيَأْتِنا ) محمد صلى‌الله‌عليه‌وآله‌وسلم إن كان صادقا ( بِآيَةٍ ) خارقة تدل على صدقه ، كما زود كَما أُرْسِلَ الْأَوَّلُونَ (5) ما آمَنَتْ قَبْلَهُمْ مِنْ قَرْيَةٍ أَهْلَكْناها أَ فَهُمْ يُؤْمِنُونَ (6) وَما أَرْسَلْنا قَبْلَكَ إِلاَّ رِجالاً نُوحِي إِلَيْهِمْ فَسْئَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ (7) موسى بالعصا ، وصالح بالناقة وهكذا ( كَما أُرْسِلَ الْأَوَّلُونَ ) من الأنبياء عليهم‌السلام بمثل هذه الآيات. [7] وقد أجابهم الله سبحانه في طلبهم هذا بأنه ( ما آمَنَتْ قَبْلَهُمْ مِنْ قَرْيَةٍ ) أي أهل قرية ( أَهْلَكْناها ) لتكذيبها الأنبياء عليهم‌السلام ، بعد ما أعطيناهم الآيات المقترحة ، كما أرادوها ( أَ فَهُمْ ) أي فهل بعد أولئك هؤلاء المقترحون ( يُؤْمِنُونَ ) ؟ كلا إنهم كالأمم السابقة ، لا يؤمنون وإن أرسلنا إليهم مثل تلك الآيات ، فإن الإنسان نوع واحد ، وما كان عليه السابقون هو الذي يكون عليه اللاحقون ، فإن أرادوا الحجة فقد تمت عليهم ، وإن أرادوا العناد ، فالمعاند لا يؤمن مهما كان. [8] أما ما ذكروا من أنك بشر وكيف يكون البشر رسولا ؟ فإن الأنبياء عليهم‌السلام السابقين أيضا كانوا بشرا ( وَما أَرْسَلْنا قَبْلَكَ ) يا رسول الله ( إِلَّا رِجالاً نُوحِي إِلَيْهِمْ ) فهم بشر يمتازون عن سائر الناس بما أوحى إليهم ( فَسْئَلُوا ) أيها الكفار المجادلون ( أَهْلَ الذِّكْرِ ) أي أهل الكتاب ، ويسمون بأهل الذكر ، لأن الكتاب يسمى ذكرا ، حيث إنه يذكر الناس بما أودع في فطرتهم من المبدأ والمعاد والمعارف ( إِنْ كُنْتُمْ لا تَعْلَمُونَ ) فإنهم يجيبون بأن الأنبياء عليهم‌السلام كانوا بشرا ، وما روي من تفسير الآية بالأئمة عليهم‌السلام فإنه من باب المصداق الظاهر بالنسبة إلى هذه وَما جَعَلْناهُمْ جَسَداً لا يَأْكُلُونَ الطَّعامَ وَما كانُوا خالِدِينَ (8) ثُمَّ صَدَقْناهُمُ الْوَعْدَ فَأَنْجَيْناهُمْ وَمَنْ نَشاءُ وَأَهْلَكْنَا الْمُسْرِفِينَ (9) الأمة ، فإن الأئمة عليهم‌السلام هم أهل الكتاب الذين يعلمونه ويعرفون حدوده وأحكامه ، كما أن العلماء ومن إليهم أيضا من أهل الذكر. [9] وقد كان الكفار يقولون ( ما لِهذَا الرَّسُولِ يَأْكُلُ الطَّعامَ وَيَمْشِي فِي الْأَسْواقِ ) (1) ظانين أن الرسول يجب أن لا يأكل ولا يمشي ، فردهم الله سبحانه بأن الأنبياء عليهم‌السلام السابقين كانوا كذلك ( وَما جَعَلْناهُمْ جَسَداً ) أي أجسادا ، وإنما جيء بالمفرد باعتبار كل واحد ( لا يَأْكُلُونَ الطَّعامَ ) والجسد يطلق على الميت ، أو ما يشبهه ، كأنه أخذ فيه معنى الفراغ من الروح أو الطعام ( وَما كانُوا ) أولئك الأنبياء ( خالِدِينَ ) لا يموتون ، بل كانوا يعيشون حياة البشر ، ويموتون مماتهم ، وأنت يا رسول الله أحدهم فلا مجال لقولهم كيف يكون الرسول بشرا ؟ [10] ولا يهمك يا رسول الله تكذيب هؤلاء فإن العاقبة المنتظرة لك ، كما إن الأنبياء السابقين كانت لهم العاقبة الحميدة ( ثُمَّ صَدَقْناهُمُ الْوَعْدَ ) بأن وفينا بوعدنا لهم ، حيث وعدناهم ( إِنَّا لَنَنْصُرُ رُسُلَنا ) (2) ونصرناهم في خاتمة المطاف ( فَأَنْجَيْناهُمْ ) من كيد الأعداء ( وَ ) أنجينا ( مَنْ نَشاءُ ) من المؤمنين بهم ، كما حدث في قصة نوح وموسى وإبراهيم ولوط وعيسى وغيرهم ( وَأَهْلَكْنَا الْمُسْرِفِينَ ) الذين أسرفوا في الكفر ( 1) الفرقان : 8. ( 2) غافر : 52. لَقَدْ أَنْزَلْنا إِلَيْكُمْ كِتاباً فِيهِ ذِكْرُكُمْ أَ فَلا تَعْقِلُونَ (10) وَكَمْ قَصَمْنا مِنْ قَرْيَةٍ كانَتْ ظالِمَةً وَأَنْشَأْنا بَعْدَها قَوْماً آخَرِينَ (11) فَلَمَّا أَحَسُّوا بَأْسَنا إِذا هُمْ مِنْها يَرْكُضُونَ (12) والمعاصي ، وهذا بشارة للنبي والمؤمنين ، وتهديد للكفار ، ونحن إذ نقرأ هذه الآية نرى أن الله سبحانه صدق الرسول صلى‌الله‌عليه‌وآله‌وسلم الوعد فقد أنجاه والمؤمنين ونصره على الكفار ، وأهلك المسرفين ، كما وعده هنا ، وقد مرّ على القصة أربعة عشر قرنا ، إذ السورة مكية ـ كما سبق ـ [11] وما لهؤلاء الكفار لا يعقلون ، ؟ إنهم إن عقلوا علموا أن هذا الكتاب الذي يحاربونه أشد محاربة كتاب فيه شرف لهم إن آمنوا به ( لَقَدْ أَنْزَلْنا إِلَيْكُمْ ) أيها العرب ( كِتاباً فِيهِ ذِكْرُكُمْ ) أي شرفكم إن تمسكتم به فإنه يخلد ذكركم ومزاياكم ( أَ فَلا تَعْقِلُونَ ) هذا الأمر الواضح ؟ فتتبعون الكتاب وتتمسكون به. [12] وإن أعرضتم ولم يعظكم التبشير والتخويف فانتظروا عاقبة المكذبين ( وَكَمْ قَصَمْنا ) أي أهلكنا ، وأصل القصم كسر الظهر الذي يكون مع الصوت ( مِنْ قَرْيَةٍ كانَتْ ظالِمَةً ) أي ما أكثر ما أهلكنا وعذبنا أهل القرى الذين ظلموا أنفسهم بالكفر والمعاصي ( وَأَنْشَأْنا ) أوجدنا ( بَعْدَها ) أي بعد تلك القرية ، بمعنى بعد إهلاك أهلها ( قَوْماً آخَرِينَ ) فنحن لسنا بحاجة إلى أحد ، ولا يصعب علينا تبديل أناس بأناس. [13] وحيث أردنا إهلاك القرية فجاءهم آثار العذاب أخذوا يفرقون من العذاب ( فَلَمَّا أَحَسُّوا ) أي أدركوا بحواسهم ( بَأْسَنا ) عذابنا ( إِذا هُمْ مِنْها ) أي من العقوبة ، أو من القرية ( يَرْكُضُونَ ) هاربين من العذاب ، لا تَرْكُضُوا وَارْجِعُوا إِلى ما أُتْرِفْتُمْ فِيهِ وَمَساكِنِكُمْ لَعَلَّكُمْ تُسْئَلُونَ (13) قالُوا يا وَيْلَنا إِنَّا كُنَّا ظالِمِينَ (14) فَما زالَتْ تِلْكَ دَعْواهُمْ حَتَّى جَعَل ْناهُمْ حَصِيداً خامِدِينَ (15) كما جرت العادة بأن الإنسان إذا رأى العذاب قد جاء من ناحية يركض هاربا منه لئلا يشمله. [14] لكن هل كان فرارهم وركضهم نافعا ؟ كلا ! فقد كان لسان الحال يقول لهم ـ حين ذاك ـ ( لا تَرْكُضُوا ) فإن الفرار لا ينفع ( وَارْجِعُوا إِلى ما أُتْرِفْتُمْ فِيهِ ) أي : أسباب ترفكم من زخارف الدنيا ( وَمَساكِنِكُمْ ) ارجعوا إلى بيوتكم ، فأين تفرون وتتركون هذه الأشياء النفيسة ؟ وقد كان هذا القول لهم من باب التقريع والاستهزاء ( لَعَلَّكُمْ تُسْئَلُونَ ) فإن الإنسان المترف الذي في منزله يسأله الناس الحوائج ، فارجعوا إلى محلكم وجاهكم الذي كان يقف الناس لأجله على أبوابكم يسألون الحوائج. [15] ولم يعد عند فرارهم جواب منهم على هذا الاستهزاء ، بل ( قالُوا : يا وَيْلَنا ) أي يا سوء حالنا ، أو يا قوم ويلنا ، والويل كلمة يقولها من يطلب الهلاك تضجرا من الحالة التي هو فيها ، فالمعنى يا ويل احضر فهذا وقتك أو يا قوم إن ويلنا حضر ( إِنَّا كُنَّا ظالِمِينَ ) لأنفسنا حيث لم نؤمن وكذبنا الأنبياء.` },
            { text: "بَلْ قَالُوٓا۟ أَضْغَٰثُ أَحْلَٰمٍۭ بَلِ ٱفْتَرَىٰهُ بَلْ هُوَ شَاعِرٌ فَلْيَأْتِنَا بِـَٔايَةٍ كَمَآ أُرْسِلَ ٱلْأَوَّلُونَ", tafsir: `` },
            { text: "مَآ ءَامَنَتْ قَبْلَهُم مِّن قَرْيَةٍ أَهْلَكْنَٰهَآ أَفَهُمْ يُؤْمِنُونَ", tafsir: `` },
            { text: "وَمَآ أَرْسَلْنَا قَبْلَكَ إِلَّا رِجَالًا نُّوحِىٓ إِلَيْهِمْ فَسْـَٔلُوٓا۟ أَهْلَ ٱلذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ", tafsir: `` },
            { text: "وَمَا جَعَلْنَٰهُمْ جَسَدًا لَّا يَأْكُلُونَ ٱلطَّعَامَ وَمَا كَانُوا۟ خَٰلِدِينَ", tafsir: `` },
            { text: "ثُمَّ صَدَقْنَٰهُمُ ٱلْوَعْدَ فَأَنجَيْنَٰهُمْ وَمَن نَّشَآءُ وَأَهْلَكْنَا ٱلْمُسْرِفِينَ", tafsir: `` },
            { text: "لَقَدْ أَنزَلْنَآ إِلَيْكُمْ كِتَٰبًا فِيهِ ذِكْرُكُمْ أَفَلَا تَعْقِلُونَ", tafsir: `` },
            { text: "وَكَمْ قَصَمْنَا مِن قَرْيَةٍ كَانَتْ ظَالِمَةً وَأَنشَأْنَا بَعْدَهَا قَوْمًا ءَاخَرِينَ", tafsir: `` },
            { text: "فَلَمَّآ أَحَسُّوا۟ بَأْسَنَآ إِذَا هُم مِّنْهَا يَرْكُضُونَ", tafsir: `` },
            { text: "لَا تَرْكُضُوا۟ وَٱرْجِعُوٓا۟ إِلَىٰ مَآ أُتْرِفْتُمْ فِيهِ وَمَسَٰكِنِكُمْ لَعَلَّكُمْ تُسْـَٔلُونَ", tafsir: `` },
            { text: "قَالُوا۟ يَٰوَيْلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ", tafsir: `` },
            { text: "فَمَا زَالَت تِّلْكَ دَعْوَىٰهُمْ حَتَّىٰ جَعَلْنَٰهُمْ حَصِيدًا خَٰمِدِينَ", tafsir: `الكلمة ، أي يا ويلنا ( دَعْواهُمْ ) أي دعاءهم وذكرهم ( حَتَّى جَعَلْناهُمْ حَصِيداً ) أي محصودا قد شملهم العذاب الذي فروا منه ، حتى كأنهم السنبل المحصود الذي يقطع فلا حياة فيه ( خامِدِينَ ) ساكني الحركات ، من خمد ضد اشتعل ، فكأنهم لم يكونوا. وَما خَلَقْنَا السَّماءَ وَالْأَرْضَ وَما بَيْنَهُما لاعِبِينَ (16) لَوْ أَرَدْنا أَنْ نَتَّخِذَ لَهْواً لاتَّخَذْناهُ مِنْ لَدُنَّا إِنْ كُنَّا فاعِلِينَ (17) بَلْ [17] إن الكفار بلهوهم ولعبهم يزعمون أنهم خلقوا للهو واللعب بينما إن الكون كله خلق للجد ولغايات وحكم عالية ، فكيف يصرف هؤلاء عمرهم لهوا ، ويزعمون أن القرآن والرسالة لعب ، ما يأتيهم ذكر إلا وهم يلعبون لاهية قلوبهم ، كما قال قائلهم : لعبت هاشم بالملك فلا خبر جاء ولا وحي نزل ( وَما خَلَقْنَا السَّماءَ وَالْأَرْضَ وَما بَيْنَهُما ) من المخلوقات والموجودات ( لاعِبِينَ ) في حال كوننا لاعبين في خلقتها ، بل إنما خلقت للجد وللغرض الصحيح ، بأن تكون نعمة ودلالة ومقدمة للثواب الدائم.` },
            { text: "وَمَا خَلَقْنَا ٱلسَّمَآءَ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا لَٰعِبِينَ", tafsir: `` },
            { text: "لَوْ أَرَدْنَآ أَن نَّتَّخِذَ لَهْوًا لَّٱتَّخَذْنَٰهُ مِن لَّدُنَّآ إِن كُنَّا فَٰعِلِينَ", tafsir: `بأن أردنا أن نلعب ونلهو ـ على فرض المحال ـ ( لَاتَّخَذْناهُ ) أي جعلنا اللهو ( مِنْ لَدُنَّا ) فإن كل لاعب يكون لعبه ملائما لذات اللاعب ، فالرجل الكبير يلعب بالكرة ، لا بالدمية ، عكس الطفل الذي يلعب بالدمية ، والملك يلهو بالصيد ، لا بأخذ الذباب ، كما يلهو به الشحاذ ، وهكذا لو أراد الله سبحانه أن يتخذ اللهو لكان لهوه من جنس الروحانيات المرتبطة بعالم الله ، لا من الماديات الخارجة عن مقامه الرفيع ( إِنْ كُنَّا فاعِلِينَ ) لاتخاذ اللهو ، تأكيد لعدم أخذه اللهو ، وبعضهم جعل « إن » نافية ، أي ما كنا فاعلين.` },
            { text: "بَلْ نَقْذِفُ بِٱلْحَقِّ عَلَى ٱلْبَٰطِلِ فَيَدْمَغُهُۥ فَإِذَا هُوَ زَاهِقٌ وَلَكُمُ ٱلْوَيْلُ مِمَّا تَصِفُونَ", tafsir: `إنا نبطل اللهو والباطل ، فإن الإنسان لم يخلق لأجلها ، نَقْذِفُ بِالْحَقِّ عَلَى الْباطِلِ فَيَدْمَغُهُ فَإِذا هُوَ زاهِقٌ وَلَكُمُ الْوَيْلُ مِمَّا تَصِفُونَ (18) وَلَهُ مَنْ فِي السَّماواتِ وَالْأَرْضِ وَمَنْ عِنْدَهُ لا يَسْتَكْبِرُونَ عَنْ عِبادَتِهِ وَلا يَسْتَحْسِرُونَ (19) يُسَبِّحُونَ ولا خلقنا سائر المخلوقات للهو حتى نترك اللهو بحاله ف ( نَقْذِفُ بِالْحَقِ ) أي نرمي الحق ـ كالرامي الذي يرمي الهدف من بعيد ، وفيه دلالة على شدة الضرب ـ ( عَلَى الْباطِلِ ) أيّا ما كان لهوا أو غير لهو ( فَيَدْمَغُهُ ) يبطله ويفنيه ويمحقه ( فَإِذا هُوَ ) أي الباطل ( زاهِقٌ ) زائل مضمحل ( وَلَكُمُ ) أيها الكفار ( الْوَيْلُ ) والعذاب ( مِمَّا تَصِفُونَ ) الله به من أن يتخذ اللهو والباطل ، أو مما تصفون به القرآن من أنه سحر أو شعر أو أحلام أو ما أشبه. [20] وكيف يستكبر هؤلاء عن الخضوع لله سبحانه ، والحال أنه الملك المطلق ، وأن الذين هم أشرف منهم لا يستكبرون عن عبادته ؟ ( وَلَهُ ) سبحانه ( مَنْ فِي السَّماواتِ وَالْأَرْضِ ) من العقلاء ، فكيف بغيرهم ؟ أو غلب العقلاء على غيرهم ، فإن الإنسان في الأرض ، والملائكة في السماء له تعالى ، وكذلك سائر الأشياء ( وَمَنْ عِنْدَهُ ) أي الملائكة والمراد ب ( عِنْدَهُ ) القرب المعنوي تشبيها له بالقرب الحسي ( لا يَسْتَكْبِرُونَ عَنْ عِبادَتِهِ ) أي لا يأنفون ولا يترفعون أن يعبدوه ويطيعوا أوامره ( وَلا يَسْتَحْسِرُونَ ) الاستحسار الانقطاع من الإعياء ، يقال : استحسر فلان عن عمله ، يعني انقطع عنه إعياء ، أي إن الملائكة لا يعيون عن العبادة بل إنهم دائمو التعبد. [21] ولذا قال ( يُسَبِّحُونَ ) الله تعالى ، أي ينزهونه عما لا يليق بشأنه اللَّيْلَ وَالنَّهارَ لا يَفْتُرُونَ (20) أَمِ اتَّخَذُوا آلِهَةً مِنَ الْأَرْضِ هُمْ يُنْشِرُونَ (21) لَوْ كانَ فِيهِما آلِهَةٌ إِلاَّ اللهُ لَفَسَدَتا ( اللَّيْلَ وَالنَّهارَ ) أي فيهما ، والإسناد مجازي ، نحو « يا سارق الليلة أهل الدار » ( لا يَفْتُرُونَ ) أي لا يأخذهم الفتور والضعف عن العبادة ، هذا حال الملائكة الذين هم أشرف من هؤلاء ، فكيف يستكبر هؤلاء ؟ [22] وحيث فرغ السياق من تقريع الكفار ، حول قولهم عن القرآن والرسول ، واستكبارهم عن عبادة الله سبحانه ، أخذ في تقريعهم حول فعلتهم الأخرى ، وهي جعل الشركاء لله سبحانه ( أَمِ اتَّخَذُوا ) هذا استفهام توبيخي ، أي كيف اتخذ هؤلاء الكفار ( آلِهَةً مِنَ الْأَرْضِ ) وهي : الأصنام المنحوتة منها ، فإن كل صنم من أصل أرضي ، وهل الإله يكون من جنس الأرض ؟ فهل ( هُمْ يُنْشِرُونَ ) ؟ أي يقدرون على نشر الأموات ، وإحيائهم ، كلا ! إذن فليسوا هم آلهة ، لأن من أول صفات الإله أن يقدر على إحياء الميت ، وهذا من التهكم ، كما تقول : إن فلانا يقتدي بالعالم العامل زيد ، تريد التهكم بالمقتدي والمقتدى فتأتي بصفة العالم العامل لزيد ـ وهو خالي عنهما ـ تهكما. [23] ثم استدل سبحانه على استحالة تعدد الآلهة ( لَوْ كانَ فِيهِما آلِهَةٌ ) المراد إلهان ، فأكثر ( إِلَّا اللهُ ) أي متصفة بكونها غير الله ، والمراد انه لو كان من هذا الجنس أحد غير الله ( لَفَسَدَتا ) أي فسدت السماوات والأرض وما استقامتا ، والمراد بالظرف أعم من المظروف ـ كما تقدم ـ وحيث نرى أنهما باقيتان مستقيمتان نستدل بذلك ـ استدلالا آنيا ، أي استدلالا من المعلول إلى العلة ـ على أنه ليس في الوجود أكثر من إله واحد هو الله سبحانه ، وإنما يلازم تعدد الآلهة الفساد ، ثم إن الاستدلال على عدم التعدد من وجهين : الأول من ناحية الذات ، والثاني من ناحية اللوازم. أما الأول : وهو من ناحية الذات ، تقريره أنه لو كان إلهان لكان بينهما جامع ولكل منهما مائز ، والجامع غير المائز ، فيلزم تركب الإله ، وكل تركيب مستلزم لعدم الألوهية ، إذ المركب يحتاج إلى الأجزاء وإلى المركّب ، والمحتاج مسبوق بالغير ، والمسبوق بالغير ممكن لا واجب فليس بإله. وأما الثاني وهو من ناحية اللوازم ، تقريره أنه لو كان إلهان هل يعقل تخالفهما في الإرادة ـ كأن يريد هذا إحياء زيد والآخر عدم حياته ـ أم لا يعقل ؟ وكل من المعقولية وعدمها مستلزم لعدم التعدد ، أما لو كان تخالفهما في الإرادة معقولا فلا يخرج الحال عن ثلاثة أمور : إما أن يقع مرادها وهو محال لاستلزامه اجتماع النقيضين. وإما أن لا يقع مرادهما وهو محال لاستلزامه ارتفاع النقيضين. وإما أن يقع مراد أحدهما ، وذلك مستلزم لعدم كون الآخر إلها لأنه محدود القدرة مغلوب على أمره ، وأما لو كان تخالفهما في الإرادة غير معقول فليس ذلك لاستحالة ذاتية في مراد أحد الإلهين ـ كإحياء زيد ـ وإنما الاستحالة ناشئة من مخالفة الإله الآخر ، وذلك يستلزم العجز الملازم للإمكان ، فهذا الإله الذي لا يعقل أن يريد إحياء زيد عاجز ، والعاجز لا يكون إلها ، لما تقرر في علم الكلام من أن العاجز لا يعقل أن يكون إلها إذ بساطة الوجود في الإله ، وإمكان المهية في المقابل ، ووحدة نسبة الإله إلى جميع الممكنات ، مستلزم للقدرة المطلقة ، وبهذا التقرير تبين : أن الدليل لا يتوقف على تخالف الإرادة خارجا ، حتى يقال إنهما فَسُبْحانَ اللهِ رَبِّ الْعَرْشِ عَمَّا يَصِفُونَ (22) لا يُسْئَلُ عَمَّا يَفْعَلُ وَهُمْ يُسْئَلُونَ (23) أَمِ اتَّخَذُوا مِنْ دُونِهِ آ لِهَةً قُلْ هاتُوا بُرْهانَكُمْ حكيمان فلا يتخالفان في الإرادة. فلو فرضنا ـ مستحيلا ـ أن هناك إلهين ، كان اللازم أن يستقل كل في مراده ، وذلك مستلزم للفساد إذ يريد هذا المطر ، وذاك عدمه مثلا ، فيتنازعان مما يؤدي إلى فساد العالم ( فَسُبْحانَ ) أي أنزه ( اللهُ ) تنزيها عما لا يليق به ( رَبِّ الْعَرْشِ ) أي مالك الكون ، فإن العرش كناية عن الملك ، وهناك عرش عظيم جدا ، هو الله مالكه ، وقد جعله موضع تشريفه للملائكة ، كما جعل البيت الحرام موضع تشريفه للبشر ( عَمَّا يَصِفُونَ ) الله به ـ هؤلاء الكفار ـ من الشريك ، فيقولون إن الله متصف بأن له شريك. [24] إنه تعالى لكون جميع أفعاله عن حكمة وصواب وصلاح ( لا يُسْئَلُ عَمَّا يَفْعَلُ ) أي ليس له شأنية أن يسأل ، إذ الحكيم لا يسأل عنه : لم تفعل ؟ فهو من قبيل «لا ريب فيه » الذي كان معناه ليس بموضع ريب وإن ارتاب فيه المبطلون ( وَهُمْ ) أي البشر أو الكفار ( يُسْئَلُونَ ) عما فعلوا لأنهم عبيد مملوكون يخطئون كما يصيبون ، والمخطئ يسأل ويحاسب. [25] وبعد أن استدل القرآن على بطلان التعدد ، يأتي السياق ليسأل القائلين بذلك : ما دليلهم ؟ فمن ادعى شيئا لا بد وأن يقيم له الدليل ، وهؤلاء المشركون لا دليل لهم على ذلك ، حتى الدليل الواهي ( أَمِ اتَّخَذُوا مِنْ دُونِهِ آلِهَةً ) أي بل اتخذوا لله شركاء ( قُلْ ) يا رسول الله لهم ( هاتُوا ) أي ائتوا ( بُرْهانَكُمْ ) ودليلكم على تعدد الآلهة ، لكنهم لا يأتون هذا ذِكْرُ مَنْ مَعِيَ وَذِكْرُ مَنْ قَبْلِي بَلْ أَكْثَرُهُمْ لا يَعْلَمُونَ الْحَقَّ فَهُمْ مُعْرِضُونَ (24) وَما أَرْسَلْنا مِنْ قَبْلِكَ مِنْ رَسُولٍ إِلاَّ نُوحِي إِلَيْهِ أَنَّهُ لا إِلهَ إِلاَّ أَنَا فَاعْبُدُونِ (25) بالدليل ، إلا قولهم ( إِنَّا وَجَدْنا آباءَنا عَلى أُمَّةٍ وَإِنَّا عَلى آثارِهِمْ مُقْتَدُونَ ) (1) وهل فعل الآباء يكون دليلا وحجة ؟ ( هذا ) القرآن ( ذِكْرُ مَنْ مَعِيَ ) من المؤمنين وليس فيه دلالة على الشرك ( وَذِكْرُ مَنْ قَبْلِي ) من الأنبياء والمؤمنين وليس في ذلك ما يدل على الشرك ، فمن أين جئتم أيها المشركون بالشرك ؟ إن الذكر الذي أنزله الله على أنبيائه ، الذي هو مجموع في القرآن ، لا يشير إلى الشركاء ، فالمدعي له يدعي الباطل ، فلا دليل عقلي له ـ قل هاتوا برهانكم ـ ولا دليل شرعي له ـ فهذا ذكر من معي وذكر من قبلي وليس فيه إلا التوحيد ـ فليس اتخاذهم للشركاء عن علم ودليل ( بَلْ أَكْثَرُهُمْ ) أي أكثر البشر ( لا يَعْلَمُونَ الْحَقَ ) الذي هو التوحيد ( فَهُمْ مُعْرِضُونَ ) عن الحق مقبلون على الباطل. [26] ثم بين سبحانه كيف أنزل الله الكتب حول التوحيد ـ بيانا لقوله هذا ذكر من معي وذكر من قبلي ـ ( وَما أَرْسَلْنا مِنْ قَبْلِكَ ) يا رسول الله ( مِنْ رَسُولٍ ) « من » تفيد العموم في النفي ، وتسمى زائدة ، لصحة أن يقال « رسولا » ( إِلَّا نُوحِي إِلَيْهِ ) نحن ب ( أَنَّهُ لا إِلهَ إِلَّا أَنَا ) وحدي لا شريك لي ( فَاعْبُدُونِ ) لي فقط دون غيري. [27] وحيث بين القرآن الحكيم بعض عقائدهم الفاسدة حول التوحيد ، ( 1) الزخرف : 23. وَقالُوا اتَّخَذَ الرَّحْمنُ وَلَداً سُبْحانَهُ بَلْ عِبادٌ مُكْرَمُونَ (26) لا يَسْبِقُونَهُ بِالْقَوْلِ وَهُمْ بِأَمْرِهِ يَعْمَلُونَ (27) يَعْلَمُ ما بَيْنَ أَيْدِيهِمْ وَما خَلْفَهُمْ وَلا يَشْفَعُونَ إِلاَّ لِمَنِ ارْتَضى وَهُمْ مِنْ خَشْيَتِهِ مُشْفِقُونَ (28) وَمَنْ يَقُلْ مِنْهُمْ إِنِّي إِلهٌ مِنْ وزيف عقيدتهم تعرض إلى عقيدة أخرى زائفة كانوا يعتقدونها ، وهي أن لله سبحانه أولاد اً ( وَقالُوا ) أي بعض الكفار ( اتَّخَذَ الرَّحْمنُ وَلَداً ) أي جنس الولد ومرادهم الملائكة ( سُبْحانَهُ ) أنزهه تنزيها عن ذلك ، فإن الولادة غير معقولة في حقه ، والتبني غير صادق بالنسبة إليه ( بَلْ ) الملائكة الذين جعلوهم أولاد الله ( عِبادٌ مُكْرَمُونَ ) أكرمهم الله سبحانه وفضلهم على كثير من خلقه.` },
            { text: "وَلَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَنْ عِندَهُۥ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِۦ وَلَا يَسْتَحْسِرُونَ", tafsir: `` },
            { text: "يُسَبِّحُونَ ٱلَّيْلَ وَٱلنَّهَارَ لَا يَفْتُرُونَ", tafsir: `` },
            { text: "أَمِ ٱتَّخَذُوٓا۟ ءَالِهَةً مِّنَ ٱلْأَرْضِ هُمْ يُنشِرُونَ", tafsir: `` },
            { text: "لَوْ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَا فَسُبْحَٰنَ ٱللَّهِ رَبِّ ٱلْعَرْشِ عَمَّا يَصِفُونَ", tafsir: `` },
            { text: "لَا يُسْـَٔلُ عَمَّا يَفْعَلُ وَهُمْ يُسْـَٔلُونَ", tafsir: `` },
            { text: "أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةً قُلْ هَاتُوا۟ بُرْهَٰنَكُمْ هَٰذَا ذِكْرُ مَن مَّعِىَ وَذِكْرُ مَن قَبْلِى بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ ٱلْحَقَّ فَهُم مُّعْرِضُونَ", tafsir: `` },
            { text: "وَمَآ أَرْسَلْنَا مِن قَبْلِكَ مِن رَّسُولٍ إِلَّا نُوحِىٓ إِلَيْهِ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعْبُدُونِ", tafsir: `` },
            { text: "وَقَالُوا۟ ٱتَّخَذَ ٱلرَّحْمَٰنُ وَلَدًا سُبْحَٰنَهُۥ بَلْ عِبَادٌ مُّكْرَمُونَ", tafsir: `` },
            { text: "لَا يَسْبِقُونَهُۥ بِٱلْقَوْلِ وَهُم بِأَمْرِهِۦ يَعْمَلُونَ", tafsir: `لا يتكلمون إلا بما يأمرهم الله سبحانه ، فقولهم إثر قوله ، واتباع أمره ( وَهُمْ بِأَمْرِهِ يَعْمَلُونَ ) فأقوالهم وأفعالهم كلها بأمر الله وإذنه ، ومن هذا شأنه لا يكون ولدا. [29] وهو سبحانه محيط بهم إحاطة علم وقدرة ف ( يَعْلَمُ ما بَيْنَ أَيْدِيهِمْ ) أي أمامهم ، وما عملوه وقدموه ( وَما خَلْفَهُمْ ) أي ورائهم وما سيعملونه ـ وذلك كناية عن الإحاطة بهم ـ ( وَلا يَشْفَعُونَ إِلَّا لِمَنِ ارْتَضى ) لا يتوسط الملائكة لإنجاء المجرم من عذاب الله ، إلا لمن أراد الله أن يشفعوا له ، فحتى شفاعتهم ليست ابتدائية ، وإنما تابعة لرضى الله سبحانه ( وَهُمْ ) أولئك الملائكة ( مِنْ خَشْيَتِهِ ) من خوف الله سبحانه ( مُشْفِقُونَ ) ووجلون ، من أشفق بمعنى وجل وخاف.` },
            { text: "يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يَشْفَعُونَ إِلَّا لِمَنِ ٱرْتَضَىٰ وَهُم مِّنْ خَشْيَتِهِۦ مُشْفِقُونَ", tafsir: `` },
            { text: "وَمَن يَقُلْ مِنْهُمْ إِنِّىٓ إِلَٰهٌ مِّن دُونِهِۦ فَذَٰلِكَ نَجْزِيهِ جَهَنَّمَ كَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ", tafsir: `من أولئك الملائكة الأطهار ( إِنِّي إِلهٌ مِنْ دُونِهِ فَذلِكَ نَجْزِيهِ جَهَنَّمَ كَذلِكَ نَجْزِي الظَّالِمِينَ (29) أَ وَلَمْ يَرَ الَّذِينَ كَفَرُوا أَنَّ السَّماواتِ وَالْأَرْضَ كانَتا رَتْقاً فَفَتَقْناهُما وَجَعَلْنا مِنَ الْماءِ كُلَّ شَيْءٍ حَيٍّ أَ فَلا يُؤْمِنُونَ (30) دُونِهِ ) من دون الله ( فَذلِكَ ) القائل ( نَجْزِيهِ جَهَنَّمَ ) فهم على طهارتهم وقربهم لا فرق بينهم وبين سائر العبيد في أن المدعي منهم للألوهية نصيبه جهنم ، ولعل قسما من المشركين كانوا يعبدون الملائكة ، كما يظهر من قوله سبحانه ( إِنْ كانَ لِلرَّحْمنِ وَلَدٌ فَأَنَا أَوَّلُ الْعابِدِينَ ) (1) ولذا يأتي هذا الكلام الجازم بأنهم لا يدّعون الألوهية فكيف أنتم تقولون عنهم ذلك ، ولو ادعاها أحدهم لجوزي بالنار ( كَذلِكَ ) الذي نجزي مدعي الألوهية ( نَجْزِي الظَّالِمِينَ ) الذين يظلمون أنفسهم بالكفر والعصيان. [31] ثم يرجع السياق إلى بيان الآيات الكونية الدالة على قدرة الله وعمله وسائر صفاته فيقول سبحانه ( أَ وَلَمْ يَرَ الَّذِينَ كَفَرُوا ) استفهام تقريع وتوبيخ ( أَنَّ السَّماواتِ وَالْأَرْضَ كانَتا رَتْقاً ) أي كانت كل واحدة منهما متصلة لا تمطر السماء ولا تنبت الأرض النبات ، فحمل الرتق على السماوات والأرض من باب زيد عدل ( فَفَتَقْناهُما ) أي شققناهما بإنزال المطر من السماء ، فإن السماء ـ وهي جهة العلو ـ تشق بالمطر ، وإنبات النبات من الأرض ( وَجَعَلْنا مِنَ الْماءِ كُلَّ شَيْءٍ حَيٍ ) فإن أصل الحياة وبقائها بالماء ، وقد ناسبت هذه الجملة الجملة السابقة الدالة على فتق السماء بالمطر ( أَ فَلا يُؤْمِنُونَ ) بعد ما يرون من هذه الآيات ( 1) الزخرف : 82. وَجَعَلْنا فِي الْأَرْضِ رَواسِيَ أَنْ تَمِيدَ بِهِمْ وَجَعَلْنا فِيها فِجاجاً سُبُلاً لَعَلَّهُمْ يَهْتَدُونَ (31) وَجَعَلْنَا السَّماءَ سَقْفاً مَحْفُوظاً العظيمة ، بالله سبحانه ، فمن فتق السماء بالمطر ؟ ومن فتق الأرض بالنبات ؟ ومن أوجد الأشياء الحية من النبات ؟` },
            { text: "أَوَلَمْ يَرَ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ كَانَتَا رَتْقًا فَفَتَقْنَٰهُمَا وَجَعَلْنَا مِنَ ٱلْمَآءِ كُلَّ شَىْءٍ حَىٍّ أَفَلَا يُؤْمِنُونَ", tafsir: `` },
            { text: "وَجَعَلْنَا فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِهِمْ وَجَعَلْنَا فِيهَا فِجَاجًا سُبُلًا لَّعَلَّهُمْ يَهْتَدُونَ", tafsir: `جمع راسية ، وهي الجبال الثوابت التي تمنع الأرض عن الحركة والاضطراب ، كراهة ( أَنْ تَمِيدَ بِهِمْ ) أي لئلا تتحرك ، من ماد بمعنى تحرك ، وضمير بهم عائد إلى الناس ( وَجَعَلْنا فِيها ) في الأرض أو في الجبال ( فِجاجاً سُبُلاً ) الفجاج جمع فج ، وهو الطريق الواسع بين جبلين ، وسبلا بدل منه ، وكان تخصيص الفجاج بالذكر لأن الجبل الذي هو صلب لا يمكن قطعه إذا لم يكن فيها فجاج ، كان سببا لقطع الاتصال بين طرفيه ، فنعمته جعل الطريق فيها عظيمة ( لَعَلَّهُمْ يَهْتَدُونَ ) أي لكي يهتدي الناس إلى بلادهم ومصالحهم بسبب تلك الفجاج ، أو لكي يهتدوا إلى خالق السماء بالتذكر والاعتبار من هذه النعم والآيات.` },
            { text: "وَجَعَلْنَا ٱلسَّمَآءَ سَقْفًا مَّحْفُوظًا وَهُمْ عَنْ ءَايَٰتِهَا مُعْرِضُونَ", tafsir: `فإن طبقة الهواء التي تعلونا محفوظة عن الخلل ، وإنما جعلت بمقياس دقيق في جميع شؤونها ، وقال بعض علماء الفلك : أن الطبقة « النتروجينية » تحفظ الأرض من القذائف الجوية ، فتجعلها رمادا منثورا لئلا تصل إلى الأرض فتؤذي أهلها ، والسقف هو ما يعلو الإنسان أو المراد المحفوظ من الشياطين ، فإنهم لا يقدرون من الوصول إليها. واستراق السمع ، وقد حفظت بالشهب ، كما قال سبحانه ( إِلَّا مَنْ خَطِفَ الْخَطْفَةَ فَأَتْبَعَهُ وَهُمْ عَنْ آياتِها مُعْرِضُونَ (32) وَهُوَ الَّذِي خَلَقَ اللَّيْلَ وَالنَّهارَ وَالشَّمْسَ وَالْقَمَرَ كُلٌّ فِي فَلَكٍ يَسْبَحُونَ (33) وَما جَعَلْنا لِبَشَرٍ مِنْ قَبْلِكَ الْخُلْدَ أَ فَإِنْ مِتَّ فَهُمُ الْخالِدُونَ (34) شِهابٌ ثاقِبٌ ) (1) ( وَهُمْ ) أي البشر ( عَنْ آياتِها ) الكائنة فيها ( مُعْرِضُونَ ) فلا يستدلون بها على المؤثر العالم القدير.` },
            { text: "وَهُوَ ٱلَّذِى خَلَقَ ٱلَّيْلَ وَٱلنَّهَارَ وَٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ فِى فَلَكٍ يَسْبَحُونَ", tafsir: `الله ( الَّذِي خَلَقَ اللَّيْلَ وَالنَّهارَ ) فإن الظلمة شيء مخلوقة بنفسها أو بخلق ضدها ، وهي الضياء ( وَالشَّمْسَ وَالْقَمَرَ ) وخصصا بالذكر مع أن الشمس هي المولدة للنهار ، لعدم التلازم كما إذا سكنت الكرات فإن الشمس موجودة ولا نهار ولا ليل بهذه الكيفية الحالية ( كُلٌ ) من الشمس والقمر ( فِي فَلَكٍ ) أي مدار خاص به ( يَسْبَحُونَ ) تشبيه بالإنسان السابح في الماء ، وإنما جيء بلفظ العاقل حيث قال : يسبحون. لأنه نسب إليهم فعل العقلاء وهو السباحة ولعل لهما عقلا ، ولذا ورد في الدعاء خطابا للقمر « أيها الخلق المطيع » ـ إلى آخره ـ. [35] إن الذي خلق الكون هو الذي خلق الحياة والموت ، ولا منجي لبشر من الموت ، فليحسن البشر في حال الحياة ، حتى لا يأتيه الموت ، وقد أسرف مما يسبب له سوء العاقبة ( وَما جَعَلْنا لِبَشَرٍ مِنْ قَبْلِكَ ) يا رسول الله ( الْخُلْدَ ) أي الخلود والدوام في الدنيا ، والخضر وعيسى أيضا ليسا من الخالدين ، وإن امتدت بهما الحياة إلى مدة بعيدة ( أَ فَإِنْ مِتَ ) يا رسول الله أنت ( فَهُمُ الْخالِدُونَ ) ؟ استفهام إنكار ، يعني إن انتظار هؤلاء لموتك غير صحيح إذ أنهم يموتون فما فائدة موتك لهم ، حينما ( 1) الصافات : 11. كُلُّ نَفْسٍ ذائِقَةُ الْمَوْتِ وَنَبْلُوكُمْ بِالشَّرِّ وَالْخَيْرِ فِتْنَةً وَإِلَيْنا تُرْجَعُونَ (35) وَإِذا رَآكَ الَّذِينَ كَفَرُوا إِنْ يَتَّخِذُونَكَ إِلاَّ ه ُزُواً أَ هذَا الَّذِي يَذْكُرُ قالوا ( نَتَرَبَّصُ بِهِ رَيْبَ الْمَنُونِ ) (1) .` },
            { text: "وَمَا جَعَلْنَا لِبَشَرٍ مِّن قَبْلِكَ ٱلْخُلْدَ أَفَإِي۟ن مِّتَّ فَهُمُ ٱلْخَٰلِدُونَ", tafsir: `` },
            { text: "كُلُّ نَفْسٍ ذَآئِقَةُ ٱلْمَوْتِ وَنَبْلُوكُم بِٱلشَّرِّ وَٱلْخَيْرِ فِتْنَةً وَإِلَيْنَا تُرْجَعُونَ", tafsir: `أي حي ( ذائِقَةُ الْمَوْتِ ) أي تذوق الموت ، وتخرج عن الحياة ( وَنَبْلُوكُمْ ) نمتحنكم أيها البشر ونختبر ـ وإن كان اختبار الله ليس لأن يعلم هو ، فإنه تعالى عالم بكل شيء ، وإنما لأن يعرف نفس الشخص من هو وما أعماله ليتم على الأشقياء الحجة ، وتتم للسعداء السعادة ـ ( بِالشَّرِّ ) كالمرض والفقر وموت الأقرباء وما أشبه ( وَالْخَيْرِ ) كالصحة والغنى والجاه وما أشبه ( فِتْنَةً ) أي لأجل الامتحان ، والمعنى نختبركم بالشدة والرخاء لأجل الامتحان لنرى من يصبر عند البلاء ومن يجزع ، ومن يشكر عند النعماء ومن يبطر ( وَإِلَيْنا تُرْجَعُونَ ) إلى ثوابنا وعقابنا ، وذلك حين الموت ، لأن القبر روضة من رياض الجنة أو حفرة من حفر النيران ، أو حين البعث ، وهناك نجزي المحسن بالثواب ونعاقب المسيء بالعذاب. [37] وبعد الكلام حول الإله يأتي الكلام حول الرسالة والمعاد وبيان أنهم كيف يستقبلون هذين الأصلين من أصول الإيمان ( وَإِذا رَآكَ ) يا رسول الله ( الَّذِينَ كَفَرُوا ) وقد سبق منك أن عبت آلهتهم وسفهت أحلامهم ودعوتهم إلى التوحيد ( إِنْ يَتَّخِذُونَكَ ) أي ما يتخذونك ( إِلَّا هُزُواً ) سخرية واستهزاء ، يقول بعضهم لبعض ( أَ هذَا ) محمد ( الَّذِي يَذْكُرُ ( 1) الطور : 31. آلِهَتَكُمْ وَهُمْ بِذِكْرِ الرَّحْمنِ هُمْ كافِرُونَ (36) خُلِقَ الْإِنْسانُ مِنْ عَجَلٍ سَأُرِيكُمْ آياتِي فَلا تَسْتَعْجِلُونِ (37) و َيَقُولُونَ مَتى هذَا الْوَعْدُ آلِهَتَكُمْ ) ؟ على طريق الاستفهام الاستهزائي ، أي هل هو الشخص الذي يقول عن الآلهة إنها لا تنفع ولا تضر ( وَهُمْ ) بينما يعتقدون بالآلهة الصنمية ( بِذِكْرِ الرَّحْمنِ ) الذي خلق وتفضل بالرحم ( هُمْ كافِرُونَ ) جاحدون ، فأمرهم أدعى إلى العجب والاستهزاء حيث يؤمنون با لجماد ويكفرون بإله الكون ..؟! [38] وقد كان الكفار يقولون للرسول لو كنت صادقا في أن مصير الكفر والتكذيب العذاب والنكال ، فائتنا بذلك العذاب ( وَيَقُولُونَ مَتى هذَا الْوَعْدُ إِنْ كُنْتُمْ صادِقِينَ ) (1) ؟ ويريدون بذلك الاستهزاء كما تقول لمن يهددك ولا يقدر على شيء : افعل بما تهدد ، فأجابهم الله سبحانه عن استعجالهم العذاب بقوله ( خُلِقَ الْإِنْسانُ مِنْ عَجَلٍ ) يعني أنه من فرط استعجاله وقلة صبره كأنه خلق من جنس هو العجل ، كما قال الشاعر في عكسه : « ولله مفطور من الصبر قلبه » . وهذا من باب المبالغة وحمل المصدر على الذات ، لإفادة تلبس الذات بالمصدر دائما وتلازمه معه غالبا ( سَأُرِيكُمْ آياتِي ) والأدلة الدالة على صدق النبي في أن من لم يؤمن يؤخذ بالعذاب ، فإن العذاب آية من آيات الله ( فَلا تَسْتَعْجِلُونِ ) في طلب العذاب ، فإنه إذا نزل بكم لا مناص لكم عنه ولا خلاص.` },
            { text: "وَإِذَا رَءَاكَ ٱلَّذِينَ كَفَرُوٓا۟ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِى يَذْكُرُ ءَالِهَتَكُمْ وَهُم بِذِكْرِ ٱلرَّحْمَٰنِ هُمْ كَٰفِرُونَ", tafsir: `` },
            { text: "خُلِقَ ٱلْإِنسَٰنُ مِنْ عَجَلٍ سَأُو۟رِيكُمْ ءَايَٰتِى فَلَا تَسْتَعْجِلُونِ", tafsir: `` },
            { text: "وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ", tafsir: `الكفار ( مَتى هذَا الْوَعْدُ ) الوعد بالعذاب الذي يعدنا ( 1) يونس : 49. إِنْ كُنْتُمْ صادِقِينَ (38) لَوْ يَعْلَمُ الَّذِينَ كَفَرُوا حِينَ لا يَكُفُّونَ عَنْ وُجُوهِهِمُ النَّارَ وَلا عَنْ ظُهُورِهِمْ وَلا هُمْ يُنْصَرُونَ (39) بَلْ تَأْتِيهِمْ بَغْتَةً فَتَبْهَتُهُمْ فَلا يَسْتَطِيعُونَ رَدَّها وَلا هُمْ يُنْظَرُونَ (40) محمد صلى‌الله‌عليه‌وآله‌وسلم لو بقينا على كفرنا ( إِنْ كُنْتُمْ ) أيها المؤمنون ( صادِقِينَ ) في ادعائكم أن العذاب يأخذنا ؟.` },
            { text: "لَوْ يَعْلَمُ ٱلَّذِينَ كَفَرُوا۟ حِينَ لَا يَكُفُّونَ عَن وُجُوهِهِمُ ٱلنَّارَ وَلَا عَن ظُهُورِهِمْ وَلَا هُمْ يُنصَرُونَ", tafsir: `أي وقت العذاب ، لعلموا صدق الرسول والمؤمنين وأنهم كانوا في غفلة وغرور ، وقد حذف جواب « لو » تهويلا أن العذاب ليأخذهم من جميع جوانبهم ، في صورة فجائية ، فإذا بهم يخفون لدفع العذاب ، بلمس اليد على وجوههم وظهورهم ، كالإنسان الذي يحترق فيكرر إمرار يده على وجهه وجسمه ، ليحول دون الاحتراق ، ولكن هناك لا تفيد هذه الحركات ، فإنهم ( لا يَكُفُّونَ ) ولا يمنعون ، بإمرار اليد ( عَنْ وُجُوهِهِمُ النَّارَ ) المشتعلة فيها ( وَلا عَنْ ظُهُورِهِمْ وَلا هُمْ يُنْصَرُونَ ) كما ينصر المحترق في الدنيا حيث يجتمع الناس عليه ويطفئون النار المشتعلة فيه.` },
            { text: "بَلْ تَأْتِيهِم بَغْتَةً فَتَبْهَتُهُمْ فَلَا يَسْتَطِيعُونَ رَدَّهَا وَلَا هُمْ يُنظَرُونَ", tafsir: `النار ( بَغْتَةً ) أي فجأة ، كما كانوا يطلبون استعجال العذاب ، إنهم بمجرد الموت تحيط بهم النار ( فَتَبْهَتُهُمْ ) وتحيرهم كيف يصنعون ( فَلا يَسْتَطِيعُونَ رَدَّها ) أي لا يقدرون على دفع النار التي أتتهم بغتة ( وَلا هُمْ يُنْظَرُونَ ) لا يؤخرون لوقت آخر ليحدثوا توبة ، أو يفكروا في خلاص. [42] وقد سبق أخذ العذاب أمما استهزءوا بأنبيائهم ، بغتة ، فليخف هؤلاء عن وَلَقَدِ اسْتُهْزِئَ بِرُسُلٍ مِنْ قَبْلِكَ فَحاقَ بِالَّذِينَ سَخِرُوا مِنْهُمْ ما كانُوا بِهِ يَسْتَهْزِؤُنَ (41) قُلْ مَنْ يَكْلَؤُكُمْ بِاللَّيْلِ وَالنَّهارِ مِنَ الرَّحْمنِ بَلْ هُمْ عَنْ ذِكْرِ رَبِّهِمْ مُعْرِضُونَ (42) مثل ذلك المصير ( وَلَقَدِ اسْتُهْزِئَ ) يا رسول الله ، والمستهزئ هم الأمم ( بِرُسُلٍ مِنْ قَبْلِكَ ) كما يستهزئ هؤلاء بك ، قائلين ( أَ هذَا الَّذِي يَذْكُرُ آلِهَتَكُمْ ) (1) ( فَحاقَ ) أي حل ( بِالَّذِينَ سَخِرُوا مِنْهُمْ ) أي من تلك الأمم ـ والضمير عائد إلى مقدر معلوم من السياق ، نحو « لأبويه » ـ ( ما كانُوا ) أي وبال ما كانوا ( بِهِ يَسْتَهْزِؤُنَ ) والمراد أنه حل بهم جزاء سخريتهم. [43] إنهم قد اتخذوا الأصنام آلهة ، فهل الأصنام تحفظهم من عقاب الله إذا جاءهم ؟ ( قُلْ ) يا رسول الله لهؤلاء ( مَنْ يَكْلَؤُكُمْ ) من كلأ بمعنى حفظ ، أي من هو الذي يحفظكم ( بِاللَّيْلِ وَالنَّهارِ مِنَ الرَّحْمنِ ) أي من عذاب الله ، إذا أراد أن يعذبكم ويأخذكم في ليل أو نهار ، وهذا استفهام إنكاري ، يعني لا حافظ من بأس الله ، وكأن الإتيان بلفظ « الرحمن » لإفادة أنهم قد أغرقوا في العتو حتى استحقوا العقاب من الرحمن الذي شأنه التفضل والترحم ( بَلْ هُمْ عَنْ ذِكْرِ رَبِّهِمْ مُعْرِضُونَ ) لا يذكرون الله سبحانه حتى يخافوا عقابه ويفكروا في أنه لا عاصم منه إن أراد بهم عذابا ونكالا. [44] إن هؤلاء يعتمدون في أمورهم على آلهتهم ، فهل الآلهة تتمكن من ( 1) الأنبياء : 37. أَمْ لَهُمْ آلِهَةٌ تَمْنَعُهُمْ مِنْ دُونِنا لا يَسْتَطِيعُونَ نَصْرَ أَنْفُسِهِمْ وَلا هُمْ مِنَّا يُصْحَبُونَ (43) بَلْ مَتَّعْنا هؤُلاءِ وَآباءَهُمْ حَتَّى طالَ عَلَيْهِمُ الْعُمُرُ الوقوف أمام العذاب لتصده عن هؤلاء ؟ ( أَمْ لَهُمْ آلِهَةٌ تَمْنَعُهُمْ مِنْ دُونِنا ) أي أ فهل لهم آلهة لها شأنية الوقوف ضدا أمامهم لتمنع عذابنا عنهم ؟ كلا ! إن الآلهة ( لا يَسْتَطِيعُونَ نَصْرَ أَنْفُسِهِمْ ) فإنها إذا أراد بها أحد شرا لا تتمكن من الدفاع عن نفسها ، فكيف تدافع عن هؤلاء الذين يعبدونها ، وجيء بوصف العاقل للآلهة تمشيا مع اصطلاح القوم ، وإلا فالآلهة لا تعقل ولا تدرك ( وَلا هُمْ مِنَّا يُصْحَبُونَ ) أي أن هذه الآلهة لا قوة لها من ذاتها ، ولا أنها تستمد القوة منا حتى تتمكن من صنع العذاب بتلك القوة ، فإنها ليست بصحبتنا حتى تستمد القوى منا ، فإن الصاحب يستمد القوة من صاحبه ، وهذا جدل تهكمي مع عباد الأصنام كما كانوا يستهزئون بالرسل ـ في عين أنه تقرير للحقيقة ـ. [45] إن سبب كفران هؤلاء ليس لأجل اعتمادهم على الآلهة ( بَلْ ) لأجل إنا أنعمنا عليهم فطغوا ، و ( إِنَّ الْإِنْسانَ لَيَطْغى * أَنْ رَآهُ اسْتَغْنى ) (1) فقد ( مَتَّعْنا هؤُلاءِ ) الكفار بأنواع النعم ( وَ ) كذلك متعنا ( آباءَهُمْ ) من قبلهم ، وذلك أدعى للطغيان ، فإن الفقير البائس واعي القلب متفتح النفس ، أما من ربّي في النعيم من زمان أبيه إلى آخر عمره فإنه يطغى وينسى ( حَتَّى طالَ عَلَيْهِمُ الْعُمُرُ ) فغرهم طول العمر وأسباب الرفاه ، وقلبوا الشكر كفرا ، لكن هؤلاء يلزم أن يعتبروا بمن هو أقوى وأشد ، فهذه الدول من أطرافهم ، كل يوم تقلص بخراب أطراف بلادها ، وغزو ( 1) العلق : 7 ـ 8. أَ فَلا يَرَوْنَ أَنَّا نَأْتِي الْأَرْضَ نَنْقُصُها مِنْ أَطْرافِها أَ فَهُمُ الْغالِبُونَ (44) قُلْ إِنَّما أُنْذِرُكُمْ بِالْوَحْيِ وَلا يَسْمَعُ الصُّمُّ الدُّعاءَ إِذا ما يُنْذَرُونَ (45) وَلَئِنْ مَسَّتْهُمْ نَفْحَةٌ مِنْ عَذابِ رَبِّكَ الأعداء لها حتى تكون خرائب بعد العمران ، ومغلوبة بعد الغلبة والنصر ، أ فهل من يقدر على ذلك لا يقدر على أن يسلب النعمة والحياة من هؤلاء ؟ ( أَ فَلا يَرَوْنَ ) أي ألا يرى هؤلاء الكفار الذين أفسدهم العمر الطويل في النعمة الموروثة ( أَنَّا نَأْتِي الْأَرْضَ ) أي نتوجه إلى أرض الحكومات وبلادهم ( نَنْقُصُها مِنْ أَطْرافِها ) فمن طرف خراب للعمران ، ومن طرف ذهاب بعدوان ، وهذا كما يقال إن الدولة الإسلامية تقلصت ، أو أن المسلمين نقصوا من أرض الكفار ( أَ فَهُمُ الْغالِبُونَ ) استفهام إنكاري ، أي فهل بعد عدم قدرة الدول على أن تمنع مشيئتنا حول أراضيها ، هم يتمكنون من الامتناع عن قدرتنا ، فيغلبون علينا في إرادتنا.` },
            { text: "وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُوا۟ مِنْهُم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ", tafsir: `` },
            { text: "قُلْ مَن يَكْلَؤُكُم بِٱلَّيْلِ وَٱلنَّهَارِ مِنَ ٱلرَّحْمَٰنِ بَلْ هُمْ عَن ذِكْرِ رَبِّهِم مُّعْرِضُونَ", tafsir: `` },
            { text: "أَمْ لَهُمْ ءَالِهَةٌ تَمْنَعُهُم مِّن دُونِنَا لَا يَسْتَطِيعُونَ نَصْرَ أَنفُسِهِمْ وَلَا هُم مِّنَّا يُصْحَبُونَ", tafsir: `` },
            { text: "بَلْ مَتَّعْنَا هَٰٓؤُلَآءِ وَءَابَآءَهُمْ حَتَّىٰ طَالَ عَلَيْهِمُ ٱلْعُمُرُ أَفَلَا يَرَوْنَ أَنَّا نَأْتِى ٱلْأَرْضَ نَنقُصُهَا مِنْ أَطْرَافِهَآ أَفَهُمُ ٱلْغَٰلِبُونَ", tafsir: `` },
            { text: "قُلْ إِنَّمَآ أُنذِرُكُم بِٱلْوَحْىِ وَلَا يَسْمَعُ ٱلصُّمُّ ٱلدُّعَآءَ إِذَا مَا يُنذَرُونَ", tafsir: `يا رسول الله لهؤلاء الكفار ( إِنَّما أُنْذِرُكُمْ بِالْوَحْيِ ) أي بما يوحي إلي ، بأنكم إذا لم تؤمنوا يأخذكم العذاب ، ثم أضرب سبحانه بقوله ( وَلا يَسْمَعُ الصُّمُّ الدُّعاءَ ) الصم جمع أصم ، فإن الأصم لا يسمع نداء المنادي له ، وهؤلاء كالأصم ، فإنهم لا يسمعون الإنذار ، ولا يعيرون له الاهتمام ( إِذا ما يُنْذَرُونَ ) أي في حال إنذارهم وتخويفهم. [47] إن هؤلاء الكفار ـ اليوم ـ لا يعيرون الإنذار اهتماما ، أما إذا جاءهم شيء ضئيل من العذاب اعترفوا بأنهم كانوا في ضلالة ( وَلَئِنْ مَسَّتْهُمْ ) مجرد مس ، وهو المرور على ظاهر الجسم ( نَفْحَةٌ مِنْ عَذابِ رَبِّكَ ) لَيَقُولُنَّ يا وَيْلَنا إِنَّا كُنَّا ظالِمِينَ (46) وَنَضَعُ الْمَوازِينَ الْقِسْطَ لِيَوْمِ الْقِيامَةِ فَلا تُظْلَمُ نَفْسٌ شَيْئاً وَإِنْ كانَ مِثْقالَ حَبَّةٍ مِنْ خَرْدَلٍ أَتَيْنا بِها وَكَفى بِنا حاسِبِينَ (47) النفحة الوقعة اليسيرة كنفح الطيب الذي هو شيء يسير من ريحه ( لَيَقُولُنَّ يا وَيْلَنا ) أي يا قوم ويلنا ، أو يا ويلنا أحضر فهذا وقتك ـ كما سبق ـ ( إِنَّا كُنَّا ظالِمِينَ ) لأنفسنا حين لم نسمع دعوة الرسول.` },
            { text: "وَلَئِن مَّسَّتْهُمْ نَفْحَةٌ مِّنْ عَذَابِ رَبِّكَ لَيَقُولُنَّ يَٰوَيْلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ", tafsir: `` },
            { text: "وَنَضَعُ ٱلْمَوَٰزِينَ ٱلْقِسْطَ لِيَوْمِ ٱلْقِيَٰمَةِ فَلَا تُظْلَمُ نَفْسٌ شَيْـًٔا وَإِن كَانَ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ أَتَيْنَا بِهَا وَكَفَىٰ بِنَا حَٰسِبِينَ", tafsir: `فكأن الميزان قطعة من العدل ، من شدة أنها تعدل في الوزن و « القسط » صفة الموازين ، فإن المصدر يأتي وضعا للمفرد والتثنية والجمع ، بلفظ واحد ، والمراد من الوضع إحضار تلك الموازين ذوات القسط لوزن الأعمال ، وهل الموازين كموازين الدنيا ، أم المراد بالموازين هم الأنبياء والأئمة عليهم‌السلام ومن إليهم ، أم هو كناية عن جزاء الأعمال حسب المقاييس المقررة ـ كما نقول فلان لا ميزان لكلامه ـ احتمالات ؟ هذه الموازين هي ( لِيَوْمِ الْقِيامَةِ ) فحينئذ ( فَلا تُظْلَمُ نَفْسٌ شَيْئاً ) بأن ينقص من ثوابه ، أو يزداد في عقابه ( وَإِنْ كانَ ) عمله ـ المفهوم من السياق ـ ( مِثْقالَ حَبَّةٍ مِنْ خَرْدَلٍ ) أي بقدر ثقل حبة من الخردل ، وهو تشبيه في الصغر والخفة ( أَتَيْنا بِها ) أي أحضرنا تلك الحبة ، والمراد إدراجها في الحساب ، حسنة كانت أم سيئة ( وَكَفى بِنا حاسِبِينَ ) «بنا » فاعل « كفى » دخل فيه الباء ، لأنه في معنى متعلق الأمر ، تقول «اكتف بزيد » و « حاسبين » حال من الضمير ، أي إننا يكتفى بنا في الحساب لأعمال هؤلاء من جهة وَلَقَدْ آتَيْنا مُوسى وَهارُونَ الْفُرْقانَ وَضِياءً وَذِكْراً لِلْمُتَّقِينَ (48) الَّذِينَ يَخْشَوْنَ رَبَّهُمْ بِالْغَيْبِ وَهُمْ مِنَ السَّاعَةِ مُشْفِقُونَ (49) وَهذا ذِكْرٌ عدم نسيان أي جزء من جزئيات أعمالهم ، فلا حاجة إلى محاسب آخر ، وإنما نحسب لنجازي كل أحد قدر عمله. [49] وحيث بين السياق قصة الرسول صلى‌الله‌عليه‌وآله‌وسلم مع القوم ، ذكر بعض قصص الأنبياء مع أقوامهم تسلية للرسول صلى‌الله‌عليه‌وآله‌وسلم ، وإتماما للحجة على الكفار ، وتقريرا للأصول التي دعا إليها كل الأنبياء ( وَلَقَدْ آتَيْنا ) أي أعطينا ( مُوسى وَهارُونَ الْفُرْقانَ ) أي الكتاب والبرهان الذي يفرق بين الحق والباطل ( وَضِياءً ) أي أعطيناهما ما يضيء درب الحياة السعيدة في الدنيا والآخرة ، لئلا يقع الناس في الضلال من جراء الظلمة ( وَذِكْراً ) يذكر البشر بما أودع في فطرته من العقيدة والمعارف ( لِلْمُتَّقِينَ ) فإنهم هم الذين ينتفعون بذلك كله ، أما غير المتقي عن عذاب الله ، فإنه لا ينتفع. [50] ثم بين المتقين بأنهم هم ( الَّذِينَ يَخْشَوْنَ رَبَّهُمْ ) أي يخافون عذابه ( بِالْغَيْبِ ) فإن الإنسان لا يحس الله سبحانه بإحدى حواسه الخمسة ، ومع ذلك يخشاه ، فهو غائب عن الحواس ، ولكنه مرهوب للمتقين ( وَهُمْ مِنَ السَّاعَةِ ) أي القيامة ( مُشْفِقُونَ ) خائفون ووجلون ، لأنهم لا يدرون ماذا يصنع بهم. [51] وكما آتينا موسى وهارون الكتاب ، كذلك آتينا الرسول صلى‌الله‌عليه‌وآله‌وسلم ( وَهذا ) القرآن ( ذِكْرٌ ) مذكر للناس ما أودع في فطرتهم من الأصول والمعارف مُبارَكٌ أَنْزَلْناهُ أَ فَأَنْتُمْ لَهُ مُنْكِرُونَ (50) وَلَقَدْ آتَيْنا إِبْراهِيمَ رُشْدَهُ مِنْ قَبْلُ وَكُنَّا بِهِ عالِمِينَ (51) إِذْ قالَ لِأَبِيهِ وَقَوْمِهِ ما هذِهِ التَّماثِيلُ الَّتِي أَنْتُمْ لَها عاكِفُونَ (52) قالُوا وَجَدْنا آباءَنا لَها عابِدِينَ (53) قالَ لَقَدْ كُنْتُمْ أَنْتُمْ وَآباؤُكُمْ ( مُبارَكٌ ) يوجب البركة والنمو ، لمن أخذ به ( أَنْزَلْناهُ ) على الرسول صلى‌الله‌عليه‌وآله‌وسلم ليذكر الناس ويباركهم ( أَ فَأَنْتُمْ ) أيها الكفار ( لَهُ مُنْكِرُونَ ) ؟ تنكرون كونه من عند الله ، وهذا استفهام توبيخ وتقريع.` },
            { text: "وَلَقَدْ ءَاتَيْنَا مُوسَىٰ وَهَٰرُونَ ٱلْفُرْقَانَ وَضِيَآءً وَذِكْرًا لِّلْمُتَّقِينَ", tafsir: `` },
            { text: "ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ وَهُم مِّنَ ٱلسَّاعَةِ مُشْفِقُونَ", tafsir: `` },
            { text: "وَهَٰذَا ذِكْرٌ مُّبَارَكٌ أَنزَلْنَٰهُ أَفَأَنتُمْ لَهُۥ مُنكِرُونَ", tafsir: `` },
            { text: "وَلَقَدْ ءَاتَيْنَآ إِبْرَٰهِيمَ رُشْدَهُۥ مِن قَبْلُ وَكُنَّا بِهِۦ عَٰلِمِينَ", tafsir: `أعطينا ( إِبْراهِيمَ رُشْدَهُ ) أي الحجج والأدلة التي توجب إرشاده إلى الحق ( مِنْ قَبْلُ ) من قبل موسى وهارون ، وقبل القرآن ( وَكُنَّا بِهِ ) بإبراهيم ( عالِمِينَ ) نعلم أنه صالح للنبوة والرسالة.` },
            { text: "إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَا هَٰذِهِ ٱلتَّمَاثِيلُ ٱلَّتِىٓ أَنتُمْ لَهَا عَٰكِفُونَ", tafsir: `إبراهيم عليه‌السلام ، والظرف متعلق ب « آتينا » ( لِأَبِيهِ ) أي عمه آزر ، فقد جرت العادة بتسمية العم أبا ( وَقَوْمِهِ ) حين رآهم يعبدون الأصنام ( ما هذِهِ التَّماثِيلُ ) جمع تمثال ، وهو الشيء المصنوع الشبيه بشيء من خلق الله سبحانه ، سواء كان المشبه به إنسانا أو حيوانا أو نباتا أو غيرها ، وقد يعم فيطلق على الشبيه بخلق الإنسان ، فصنع قصر صغير للعب الأطفال أو سيارة صغيرة كذلك يسمى تمثالا ( الَّتِي أَنْتُمْ ) أيها القوم ( لَها عاكِفُونَ ) ؟ أي مستمرون دائمون على عبادتها والخضوع لها ؟` },
            { text: "قَالُوا۟ وَجَدْنَآ ءَابَآءَنَا لَهَا عَٰبِدِينَ", tafsir: `في جواب إبراهيم ( وَجَدْنا آباءَنا لَها ) أي لهذه التماثيل ـ والمراد جنسها ـ ( عابِدِينَ ) فإنا قد قلدناهم في عبادتهم لها.` },
            { text: "قَالَ لَقَدْ كُنتُمْ أَنتُمْ وَءَابَآؤُكُمْ فِى ضَلَٰلٍ مُّبِينٍ", tafsir: `إبراهيم عليه‌السلام لهم ( لَقَدْ كُنْتُمْ أَنْتُمْ ) أيها القوم ( وَآباؤُكُمْ ) فِي ضَلالٍ مُبِينٍ (54) قالُوا أَ جِئْتَنا بِالْحَقِّ أَمْ أَنْتَ مِنَ اللاَّعِبِينَ (55) قالَ بَلْ رَبُّكُمْ رَبُّ السَّماواتِ وَالْأَرْضِ الَّذِي فَطَرَهُنَّ وَأَنَا عَلى ذلِكُمْ مِنَ الشَّاهِدِينَ (56) وَتَاللهِ لَأَ كِيدَنَّ الذين عبدوها قبلكم ( فِي ضَلالٍ مُبِينٍ ) واضح إذ كيف تعبدون ما لا يسمع ولا يبصر ولا يغني عنكم شيئا ؟.` },
            { text: "قَالُوٓا۟ أَجِئْتَنَا بِٱلْحَقِّ أَمْ أَنتَ مِنَ ٱللَّٰعِبِينَ", tafsir: `أي القوم ، لما رأوا من إبراهيم الإصرار على نبذ عبادة الأصنام ( أَ جِئْتَنا بِالْحَقِ ) أي هل أنت جاد في كلامك هذا محق عند نفسك تريد بيان الحق بزعمك ( أَمْ أَنْتَ مِنَ اللَّاعِبِينَ ) تمزح وتلعب في كلامك ؟ فقد كانوا يستبعدون أن ينكر عليهم أحد عبادة الأصنام التي ألفوها منذ دهور.` },
            { text: "قَالَ بَل رَّبُّكُمْ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ٱلَّذِى فَطَرَهُنَّ وَأَنَا۠ عَلَىٰ ذَٰلِكُم مِّنَ ٱلشَّٰهِدِينَ", tafsir: `إبراهيم عليه‌السلام في جوابهم ، ما يفيد أنه جاد محق ، ولكن غير مجرى الكلام ليكون جوابه مع الدليل والبرهان فلا يبقى محل للمناقشة ( بَلْ رَبُّكُمْ رَبُّ السَّماواتِ وَالْأَرْضِ ) فليست هذه أربابا لكم ، وإنما هو الله ( الَّذِي فَطَرَهُنَ ) أي خلق السماوات والأرض ، والإتيان بضمير العاقل ، إما باعتبار تغليب العقلاء الموجودين فيهما وإما باعتبار أن لهما مرتبة من الإدراك والشعور ( وَأَنَا عَلى ذلِكُمْ ) « ذا » اشارة إلى المطلب المتقدم ، وهو أن الرب هو اله السماء والأرض و « كم » خطاب للقوم ( مِنَ الشَّاهِدِينَ ) أي أشهد بذلك ، وهذا لتأكيد الأمر ، وإلا فكل مخبر شاهد لما يخبر عنه ، وكأن المراد أن إخباري ليس تقليدا وإنما عن حضور وشهادة.` },
            { text: "وَتَٱللَّهِ لَأَكِيدَنَّ أَصْنَٰمَكُم بَعْدَ أَن تُوَلُّوا۟ مُدْبِرِينَ", tafsir: `حلف بالله لتأكيد ما يقول ، والتاء للتعجب ، وإنما جيء بها لصعوبة الأمر الذي نواه حتى أن الآتي به يستحق التعجب منه ( لَأَكِيدَنَّ أَصْنامَكُمْ بَعْدَ أَنْ تُوَلُّوا مُدْبِرِينَ (57) فَجَعَلَهُمْ جُذاذاً إِلاَّ كَبِيراً لَهُمْ لَعَلَّهُمْ إِلَيْهِ يَرْجِعُونَ (58) قالُوا مَنْ فَعَلَ هذا بِآلِهَتِنا إِنَّهُ لَمِنَ الظَّالِمِينَ (59) أَصْنامَكُمْ ) أي أدبّرن تدبيرا خفيا في باب الأصنام ، يسوؤكم ذلك ، يقال : كاده إذا دبّر تدبيرا خفيا يوجب مساءته ( بَعْدَ أَنْ تُوَلُّوا مُدْبِرِينَ ) أي تعرضوا عن المدينة جاعلين ظهوركم عليها تريدون الاجتماع في يوم عيدكم ، فقد كان لهم في كل سنة عيد يخرجون إلى خارج المدينة لأجله فيجتمعون هناك ، ثم إذا رجعوا دخلوا بيت الأصنام يسجدون لها ، ولما أرادوا الخروج دعوا إبراهيم للخروج معهم فلم يخرج ، فلما خرجوا جاء إلى بيت الأصنام وقد خلا من الناس. [59] وأخذ فأسا بيده ( فَجَعَلَهُمْ ) أي الأصنام ـ وقد مر وجه الإتيان بضمير العاقل ـ ( جُذاذاً ) أي قطعة قطعة فهو فعال بمعنى مفعول كالحطام ، وأصله من الجذ بمعنى القطع ( إِلَّا كَبِيراً لَهُمْ ) أي كبير الأصنام ، فإنه عليه‌السلام لم يكسره ، وإنما أبقاه على حاله ، والمراد أكبرهم جسما ، أو أكبرهم عظمة عند القوم ، وقد علق الفأس في عنق ذلك الكبير ، وإنما فعل ذلك ( لَعَلَّهُمْ ) أي القوم ( إِلَيْهِ ) أي إلى إبراهيم ( يَرْجِعُونَ ) فيسألون عن الفاعل للتحطيم ، فينبئهم على خطئهم في العبادة. [60] ولما رجعوا ورأوا أن الأصنام قد حطمت وكسرت ( قالُوا ) قال بعضهم لبعض ( مَنْ فَعَلَ هذا ) الكسر والتحطيم ( بِآلِهَتِنا ) ؟ على نحو الاستفهام الاستنكاري ، أو أن من مبتدأ خبره ( إِنَّهُ لَمِنَ الظَّالِمِينَ ) الذي ظلم نفسه وقومه. قالُوا سَمِعْنا فَتًى يَذْكُرُهُمْ يُقالُ لَهُ إِبْراهِيمُ (60) قالُوا فَأْتُوا بِهِ عَلى أَعْيُنِ النَّاسِ لَعَلَّهُمْ يَشْهَدُونَ (61) قالُوا أَ أَنْتَ فَعَلْتَ هذا بِآلِهَتِنا يا إِبْراهِيمُ (62) قالَ بَلْ فَعَلَهُ كَبِيرُهُمْ هذا` },
            { text: "فَجَعَلَهُمْ جُذَٰذًا إِلَّا كَبِيرًا لَّهُمْ لَعَلَّهُمْ إِلَيْهِ يَرْجِعُونَ", tafsir: `` },
            { text: "قَالُوا۟ مَن فَعَلَ هَٰذَا بِـَٔالِهَتِنَآ إِنَّهُۥ لَمِنَ ٱلظَّٰلِمِينَ", tafsir: `` },
            { text: "قَالُوا۟ سَمِعْنَا فَتًى يَذْكُرُهُمْ يُقَالُ لَهُۥٓ إِبْرَٰهِيمُ", tafsir: `أي قال بعضهم في جواب السائلين ( سَمِعْنا فَتًى يَذْكُرُهُمْ ) أي أن في المدينة شابا يذكر الأصنام بسوء لعله هو الذي صنع هذا الصنيع ( يُقالُ لَهُ إِبْراهِيمُ ) لا شأن له ولا أهمية ، ومن هذا يظهر أن إبراهيم عليه‌السلام كان شابا حينما فعل ذلك.` },
            { text: "قَالُوا۟ فَأْتُوا۟ بِهِۦ عَلَىٰٓ أَعْيُنِ ٱلنَّاسِ لَعَلَّهُمْ يَشْهَدُونَ", tafsir: `قال بعض القوم لآخرين ( فَأْتُوا بِهِ ) فجيئوا بإبراهيم عليه‌السلام ( عَلى أَعْيُنِ النَّاسِ ) بحيث يراه الناس ويكون بمشهدهم والإتيان بلفظ « على » لعله لكون العين تستوعب الشخص فكأنه عليها ( لَعَلَّهُمْ يَشْهَدُونَ ) بما قاله إبراهيم في شأن الأصنام ، فتكون شهادتهم حجة عليه لا يتمكن من الإنكار ، عند إرادة عقابه جزاء لما فعل. [63] فذهب بعض القوم ، وجاءوا بإبراهيم عند الجماهير الحاضرة ف ( قالُوا ) لإبراهيم عليه‌السلام ( أَ أَنْتَ فَعَلْتَ هذا ) الفعل الشنيع : الكسر والتحطيم ( بِآلِهَتِنا يا إِبْراهِيمُ ) ؟ على نحو الاستفهام التقريري. [64] لكن إبراهيم تهكم منهم ، وصاغ الجواب في قالب يلفتهم إلى خطأ اتخاذهم لها أربابا ( قالَ بَلْ فَعَلَهُ كَبِيرُهُمْ هذا ) الذي بقي سالما وعلى عنقه الفأس ، والكلام صدق إذ المقصود من الكلام هو الذي يجعله صادقا أو كاذبا ، لا القالب المصنوع ، ألا ترى أنك لو قلت للبخيل « إنه كريم » لم يكن كذبا ، حيث تريد بذلك التهكم ، وكذا لو قلت لرجل فَسْئَلُوهُمْ إِنْ كانُوا يَنْطِقُونَ (63) فَرَجَعُوا إِلى أَنْفُسِهِمْ فَقالُوا إِنَّكُمْ أَنْتُمُ الظَّالِمُونَ (64) ثُمَّ نُكِسُوا عَلى رُؤُسِهِمْ لَقَدْ عَلِمْتَ ما هؤُلاءِ يَنْطِقُونَ (65) شجاع « أنه أسد » لو أردت المجاز ، ثم ألفت إبراهيم ، إلى موضع العبرة والحجة بقوله ( فَسْئَلُوهُمْ ) أيها القوم ، عمن فعل بهم هذا العمل ( إِنْ كانُوا يَنْطِقُونَ ) فإنهم يخبرونكم عمن فعل بهم هذا ، وقد أراد عليه‌السلام بذلك إلفاتهم إلى أنهم كيف يتخذون الأصنام آلهة ، وهي لا تنطق ولا تعلم من فعل بهم الكسر والتحطيم ، وإلى ما ذكرنا في معنى الآية تشير الرواية الواردة في الكافي عن الصادق عليه‌السلام قال : إنما قال بل فعله كبيرهم ، إرادة الإصلاح ، ودلالة على أنهم لا يفعلون (1) . [65] وهنا أخذت الموعظة مأخذها ، وعمل التنبيه مفعوله ( فَرَجَعُوا إِلى أَنْفُسِهِمْ ) أي إلى أن القوم قال بعضهم لبعض ، أو تفكروا في نفوسهم ( فَقالُوا إِنَّكُمْ ) أيها القوم ( أَنْتُمُ الظَّالِمُونَ ) لأنفسكم حيث تعبدون هذه الأصنام التي لا تقدر على دفع العدو عن نفسها ، وحتى على النطق وإظهار من فعل الكسر بها.` },
            { text: "قَالُوٓا۟ ءَأَنتَ فَعَلْتَ هَٰذَا بِـَٔالِهَتِنَا يَٰٓإِبْرَٰهِيمُ", tafsir: `` },
            { text: "قَالَ بَلْ فَعَلَهُۥ كَبِيرُهُمْ هَٰذَا فَسْـَٔلُوهُمْ إِن كَانُوا۟ يَنطِقُونَ", tafsir: `` },
            { text: "فَرَجَعُوٓا۟ إِلَىٰٓ أَنفُسِهِمْ فَقَالُوٓا۟ إِنَّكُمْ أَنتُمُ ٱلظَّٰلِمُونَ", tafsir: `` },
            { text: "ثُمَّ نُكِسُوا۟ عَلَىٰ رُءُوسِهِمْ لَقَدْ عَلِمْتَ مَا هَٰٓؤُلَآءِ يَنطِقُونَ", tafsir: `كما هو عادة الذي قد تمت عليه الحجة فلا جواب له ، والمراد نكسوا رؤوسهم ، لكن فاعل النكس لم يظهر ، والإتيان ب « على » لإفادة أن هناك دافعا دفع الرؤوس من فوقها حتى نكست ، وأخذوا يجمجمون ـ مخاطبين إبراهيم ، أو أنفسهم ـ ( لَقَدْ عَلِمْتَ ) يا إبراهيم ( ما هؤُلاءِ يَنْطِقُونَ ) فكيف نسأل منهم ، كما قلت « فاسألوهم » ؟ ( 1) الكافي : ج 2 ص 341. قالَ أَ فَتَعْبُدُونَ مِنْ دُونِ اللهِ ما لا يَنْفَعُكُمْ شَيْئاً وَلا يَضُرُّكُمْ (66) أُفٍّ لَكُمْ وَلِما تَعْبُدُونَ مِنْ دُونِ اللهِ أَ فَلا تَعْقِلُونَ (67) قالُوا حَرِّقُوهُ وَانْصُرُوا آلِهَتَكُمْ إِنْ كُنْتُمْ فاعِلِينَ (68) [67] ولما رأى إبراهيم عليه‌السلام أنهم وصلوا إلى واقع الأمر ، وأن عظته قد أثرت ، أخذ يبث فيهم دعوته بنبذ الأصنام واتخاذ الإله معبودا دونها ( قالَ ) إبراهيم عليه‌السلام لهم ( أَ فَتَعْبُدُونَ مِنْ دُونِ اللهِ ما لا يَنْفَعُكُمْ شَيْئاً وَلا يَضُرُّكُمْ ) أي كيف تعبدون الأصنام التي هي لا تنفع ولا تضر ، ولو كانت قدرت على النفع والضرر لدفعت المكروه عن نفسها ؟ والاستفهام توبيخي تقريعي.` },
            { text: "قَالَ أَفَتَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكُمْ شَيْـًٔا وَلَا يَضُرُّكُمْ", tafsir: `` },
            { text: "أُفٍّ لَّكُمْ وَلِمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ أَفَلَا تَعْقِلُونَ", tafsir: `« أف » كلمة تضجر ، أي تبا لأعمالكم وأفعالكم ، ( وَ ) أف ( لِما تَعْبُدُونَ ) أي للأصنام التي تعبدونها ( مِنْ دُونِ اللهِ ) أي التي هي غير الله سبحانه ( أَ فَلا تَعْقِلُونَ ) تتفكرون بعقولكم إنها ليست آلهة تستحق العبادة والتعظيم. [69] وقد التجأ القوم ـ بعد تمام الحجة عليهم ـ إلى ما يلتجئ إليه كل جاهل معاند ، من التخلص عن الحق بالقوة والعقاب ف ( قالُوا ) بعضهم لبعض ( حَرِّقُوهُ ) حرقوا إبراهيم بالنار جزاء لما فعل بالأصنام ( وَانْصُرُوا آلِهَتَكُمْ ) بالتخلص من أعدائها ، وإنزال العقاب الصارم بمن أهانها ( إِنْ كُنْتُمْ فاعِلِينَ ) للنصرة لها ، فأحرقوا إبراهيم عدوها. [70] فأمر نمرود الملك الطاغي بجمع الحطب ، وقد كان يكفي الحطب القليل لهذا الأمر ، لكن الحقد أوجب أن جمعوا من الحطب قدرا مدهشا ـ بقدر حقدهم لا بقدر حرق إبراهيم ـ وصنعوا منجنيقا ، تقذف ، لأنهم لم يكونوا قُلْنا يا نارُ كُونِي بَرْداً وَسَلاماً عَلى إِبْراهِيمَ (69) وَأَرادُوا بِهِ كَيْداً فَجَعَلْناهُمُ الْأَخْسَرِينَ (70) وَنَجَّيْناهُ وَلُوطاً إِلَى الْأَرْضِ الَّتِي بارَكْنا فِيها لِلْعالَمِينَ (71) يتمكنون من اقتراب تلك النار الكثيرة المهولة ، ثم وضعوا إبراهيم في فوهة المنجنيق ، بمشهد من الملك والجماهير ، وقذفوه في النار ( قُلْنا يا نارُ كُونِي بَرْداً وَسَلاماً ) وقد كان أمرا تكوينيا ، نحو ( كُونُوا قِرَدَةً خاسِئِينَ ) (1) والسلام أعم من البرد ، فإن البرد إذا زاد لم يسلم الإنسان فيه ( عَلى إِبْراهِيمَ ) والمراد بالقول إما خلق الصوت ، أو الإرادة.` },
            { text: "قَالُوا۟ حَرِّقُوهُ وَٱنصُرُوٓا۟ ءَالِهَتَكُمْ إِن كُنتُمْ فَٰعِلِينَ", tafsir: `` },
            { text: "قُلْنَا يَٰنَارُ كُونِى بَرْدًا وَسَلَٰمًا عَلَىٰٓ إِبْرَٰهِيمَ", tafsir: `` },
            { text: "وَأَرَادُوا۟ بِهِۦ كَيْدًا فَجَعَلْنَٰهُمُ ٱلْأَخْسَرِينَ", tafsir: `أي القوم ( بِهِ ) بإبراهيم عليه‌السلام ( كَيْداً ) أي شرا وتدبيرا في هلاكه بالنار ( فَجَعَلْناهُمُ الْأَخْسَرِينَ ) إذ خسروا كيدهم ، بل فوق ذلك أن ظهرت عظمة إبراهيم عليه‌السلام ، مما سبب لنشر دعوته أكثر من ذي قبل فكأنهم جمعوا إلى خسارتهم بالنسبة إلى عقيدتهم الكافرة ، خسارة المغلوبية ، فهم الأخسرون. [72] وقد بقي إبراهيم عليه‌السلام في بابل العراق مدة يدعو فلم تنفع القوم الدعوة ، بل أرادوا حرقة فلم ينجحوا ، وسلط الله عليهم البعوض حتى أخذت لحومهم وشربت دماءهم وأهلكت واحدة منها نمرود الملك الطاغي ، ومن ثم هاجر إبراهيم عليه‌السلام إلى الشام ، لعل القوم هناك يقبلون الدعوة ( وَنَجَّيْناهُ ) أي إبراهيم عليه‌السلام ( وَلُوطاً ) وهو من أرحام إبراهيم عليه‌السلام ، وفي بعض التفاسير أنه ابن أخ إبراهيم ( إِلَى الْأَرْضِ الَّتِي بارَكْنا فِيها ) في تلك الأرض وهي الشام ( لِلْعالَمِينَ ) لجميع ( 1) البقرة : 66. وَوَهَبْنا لَهُ إِسْحاقَ وَيَعْقُوبَ نافِلَةً وَكُلاًّ جَعَلْنا صالِحِينَ (72) وَجَعَلْناهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنا وَأَوْحَيْنا إِلَيْهِمْ فِعْلَ الْخَيْراتِ وَإِقامَ الصَّلاةِ وَإِيتاءَ الزَّكاةِ وَكانُوا لَنا عابِدِينَ (73) الناس ، فقد تواترت الأنبياء هناك ، وقد كانت الشام تطلق سابقا على ما يشمل لبنان وسورية وفلسطين والأردن وحواليها.` },
            { text: "وَنَجَّيْنَٰهُ وَلُوطًا إِلَى ٱلْأَرْضِ ٱلَّتِى بَٰرَكْنَا فِيهَا لِلْعَٰلَمِينَ", tafsir: `` },
            { text: "وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ نَافِلَةً وَكُلًّا جَعَلْنَا صَٰلِحِينَ", tafsir: `لإبراهيم ( إِسْحاقَ وَيَعْقُوبَ نافِلَةً ) إسحاق بن إبراهيم من سارة وقد دعا عليه‌السلام أن يرزق ولدا فأعطاه الله إياه ، ويعقوب ولد إسحاق ، وقد وهبه الله سبحانه لإبراهيم ـ حيث إن الحفيد أيضا هبة للجد ـ ومعنى « نافلة » : « زائدة » إذ لم يكن يعقوب حسب دعاء إبراهيم ، وإنما كان لطفا محضا منه سبحانه عليه ، وتأنيث نافلة باعتبار النفس ، ولم يذكر إسماعيل عليه‌السلام لعله لكونه على مجرى الطبيعة ، إذ « سارة » كانت كبيرة وعقيمة ، أما « هاجر » فلم تكن كذلك ، وإنما هي شابة ولودة ( وَكُلًّا ) من إبراهيم وإسحاق ويعقوب ( جَعَلْنا صالِحِينَ ) للنبوة والرسالة والهداية والإرشاد وسائر الفضائل.` },
            { text: "وَجَعَلْنَٰهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا وَأَوْحَيْنَآ إِلَيْهِمْ فِعْلَ ٱلْخَيْرَٰتِ وَإِقَامَ ٱلصَّلَوٰةِ وَإِيتَآءَ ٱلزَّكَوٰةِ وَكَانُوا۟ لَنَا عَٰبِدِينَ", tafsir: `أي الثلاثة ( أَئِمَّةً ) جمع إمام ، وهو المقتدى ، أي يقتدى بهم في أمور الدين والدنيا ( يَهْدُونَ ) الناس إلى الحق ( بِأَمْرِنا ) وأرسلناهم إلى الناس ليرشدوهم ( وَأَوْحَيْنا إِلَيْهِمْ فِعْلَ الْخَيْراتِ ) أي أوحينا إليهم أن افعلوا الأفعال الخيرة الموجبة للخير والسعادة في الدنيا والآخرة ( وَإِقامَ الصَّلاةِ ) أي إقامتها ، فإن التاء في مصدر باب الأفعال جائز الحذف ( وَإِيتاءَ الزَّكاةِ ) أي إعطاءها ، وتخصيصهما بالذكر بعد دخولهما في عموم الخيرات ، لأهميتهما ( وَكانُوا لَنا عابِدِينَ ) وَلُوطاً آتَيْناهُ حُكْماً وَعِلْماً وَنَجَّيْناهُ مِنَ الْقَرْيَةِ الَّتِي كانَتْ تَعْمَلُ الْخَبائِثَ إِنَّهُمْ كانُوا قَوْمَ سَوْءٍ فاسِقِينَ (74) وَأَدْخَلْناهُ فِي رَحْمَتِنا إِنَّهُ مِنَ الصَّالِحِينَ (75) وَنُوحاً إِذْ نادى مِنْ قَبْلُ يعبدوننا ، قبال سائر الناس الذين كانوا يعبدون الأصنام.` },
            { text: "وَلُوطًا ءَاتَيْنَٰهُ حُكْمًا وَعِلْمًا وَنَجَّيْنَٰهُ مِنَ ٱلْقَرْيَةِ ٱلَّتِى كَانَت تَّعْمَلُ ٱلْخَبَٰٓئِثَ إِنَّهُمْ كَانُوا۟ قَوْمَ سَوْءٍ فَٰسِقِينَ", tafsir: `الذي سبق ذكره ، وقد كان نجي من « بابل » مع إبراهيم ، إلى الأرض المباركة ( آتَيْناهُ ) أعطيناه ( حُكْماً ) أي قضاء بين الناس وحكومة ، فإن منصب الحكم إنما هو لله سبحانه ، ثم لأنبيائه والأئمة ، بإذنه ( وَعِلْماً ) والحكم غير العلم ، وإن استلزم مقدارا منه ( وَنَجَّيْناهُ ) ؟ أنقذناه ( مِنَ الْقَرْيَةِ الَّتِي كانَتْ تَعْمَلُ الْخَبائِثَ ) وهي « سدوم » التي كان أهلها يتعاطون اللواط والسحق والكفر وسائر المنكرات والخبائث جمع خبيث ، وهو الشيء أو العمل السيئ ( إِنَّهُمْ ) أي أهل تلك القرية ( كانُوا قَوْمَ سَوْءٍ ) إضافة القوم إلى عملهم ( فاسِقِينَ ) خارجين عن طاعة الله سبحانه ، فقد أمر الله سبحانه لوطا أن يخرج من القرية ، ثم عذب أهلها بأنواع العذاب ـ كما مر تفصيله ـ.` },
            { text: "وَأَدْخَلْنَٰهُ فِى رَحْمَتِنَآ إِنَّهُۥ مِنَ ٱلصَّٰلِحِينَ", tafsir: `لوطا عليه‌السلام ( فِي رَحْمَتِنا ) بذلك الخروج عن القرية ، فكأنه كان حينذاك في العذاب ، فلما خرج دخل الرحمة ( إِنَّهُ مِنَ الصَّالِحِينَ ) ولهذا استحق الدخول في الرحمة ، ولم يبق في المدينة ليشمله العذاب والهلاك.` },
            { text: "وَنُوحًا إِذْ نَادَىٰ مِن قَبْلُ فَٱسْتَجَبْنَا لَهُۥ فَنَجَّيْنَٰهُ وَأَهْلَهُۥ مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ", tafsir: `اذكر يا رسول الله ( نُوحاً ) أو هو عطف على « لوطا » أي آتينا نوحا حكما وعلما ( إِذْ نادى ) أي زمان دعا الله سبحانه ( مِنْ قَبْلُ ) فَاسْتَجَبْنا لَهُ فَنَجَّيْناهُ وَأَهْلَهُ مِنَ الْكَرْبِ الْعَظِيمِ (76) وَنَصَرْناهُ مِنَ الْقَوْمِ الَّذِينَ كَذَّبُوا بِآياتِنا إِنَّهُمْ كانُوا قَوْمَ سَوْءٍ فَأَغْرَقْناهُمْ أَجْمَعِينَ (77) وَداوُدَ وَسُلَيْمانَ إِذْ يَحْكُمانِ فِي الْحَرْثِ إِذْ نَفَشَتْ فِيهِ غَنَمُ الْقَوْمِ من قبل إبراهيم ولوط ، فقال رب لا تذر على الأرض من الكافرين ديارا ، وإنما جيء به متأخرا مع أنه متقدم زمانا ، لأن أهل مكة كانوا أقرب إلى إبراهيم زمانا وعلما ونسبا ، فكان ذكره أجلى ، وفي مذاقهم أحلى ( فَاسْتَجَبْنا لَهُ ) دعاءه بإهلاك الكفار ( فَنَجَّيْناهُ وَأَهْلَهُ ) لعل المراد بهم المؤمنون به ( مِنَ الْكَرْبِ ) أي الحزن ( الْعَظِيمِ ) الذي لاقاه من الكفار طول تسعمائة وخمسين عاما ، فقد كانوا يضحكون منه ويؤذونه ويضربونه.` },
            { text: "وَنَصَرْنَٰهُ مِنَ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَآ إِنَّهُمْ كَانُوا۟ قَوْمَ سَوْءٍ فَأَغْرَقْنَٰهُمْ أَجْمَعِينَ", tafsir: `أي نصرنا نوحا ، بنجاته في السفينة وغرق الكفار بأجمعهم ( مِنَ الْقَوْمِ الَّذِينَ كَذَّبُوا بِآياتِنا ) وإنما عدي « نصرنا » ب « من » دون « على » لإشراب الفعل معنى « المنع » وكأنه قال : النصر بالسير من وسطهم نحو سرت من البصرة ( إِنَّهُمْ ) أي المكذبين ( كانُوا قَوْمَ سَوْءٍ ) فكأنهم كانوا قطعة من سوء ، حيث إن عقائدهم وأعمالهم وأقوالهم كانت كلها سيئة ( فَأَغْرَقْناهُمْ أَجْمَعِينَ ) بأن أنزلناه السماء مدرارا ، وفجرنا الأرض عيونا ، حتى غرق كل شيء في الماء ، فلم ينج إلا نوح ومن حمل معه في السفينة.` },
            { text: "وَدَاوُۥدَ وَسُلَيْمَٰنَ إِذْ يَحْكُمَانِ فِى ٱلْحَرْثِ إِذْ نَفَشَتْ فِيهِ غَنَمُ ٱلْقَوْمِ وَكُنَّا لِحُكْمِهِمْ شَٰهِدِينَ", tafsir: `اذكر يا رسول الله ، أو أعطينا الحكم والعلم ( داوُدَ وَسُلَيْمانَ ) وهو ابن داود ( إِذْ يَحْكُمانِ فِي الْحَرْثِ ) أي الزرع ( إِذْ نَفَشَتْ فِيهِ غَنَمُ الْقَوْمِ ) وَكُنَّا لِحُكْمِهِمْ شاهِدِينَ (78) أي في الوقت الذي تفرقت فيه الغنم ليلا ، فإن نفش بمعنى تفرق الإبل أو الغنم ليلا ليرعى بدون راع ( وَكُنَّا لِحُكْمِهِمْ شاهِدِينَ ) حاضرين ، نسمع ونرى كيف حكما ، والإتيان بالجمع « حكمهم » باعتبار الحاكمين وطرفي النزاع. روي عن الصادق عليه‌السلام أنه قال كان في بني إسرائيل رجل وكان له كرم ونفشت فيه غنم لرجل بالليل وقضمته وأفسدته ، فجاء به صاحب الكرم إلى داود فاستعدى على صاحب الغنم فقال داود عليه‌السلام : اذهبا إلى سليمان ليحكم بينكما فذهبا إليه فقال سليمان : إن كانت الغنم أكلت الأصل والفرع فعلى صاحب الغنم أن يدفع إلى صاحب الكرم الغنم وما في بطنها ، وإن كانت ذهبت بالفرع ولم تذهب بالأصل فإنه يدفع ولدها إلى صاحب الكرم ، وكان هذا حكم داود وإنما أراد أن يعرف بني إسرائيل أن سليمان وصيه بعده ولم يختلفا في الحكم ولو اختلف حكمهما لقال « كنا لحكمهما شاهدين » (1) . أقول : وكأن الحكم في تلك الأمة كان كذلك أما في شريعتنا فإن الحكم ضمان صاحب الغنم ما أتلفته لصاحب الكرم ، دون أن يكون الأرش معينا في الغنم ، وقد روي هذا الحكم بشكل آخر ، وإن داود وسليمان اختلفا في القضاء وكان حكم سليمان أقرب ، وإن كان كلاهما صحيحا ، وذلك كما لو أتاك آت فقال : إن فلانا كسر إنائي ، فقلت له : يعطيك إناء مثله ، وقال قاض آخر : يعطيك ثمنه فكلاهما جائز بالتراضي ، وإن كان المثل أقرب من القيمة ، في المثلي ، ( 1) بحار الأنوار : ج 14 ص 131. فَفَهَّمْناها سُلَيْمانَ وَكُلاًّ آتَيْنا حُكْماً وَعِلْماً وَسَخَّرْنا مَعَ داوُدَ الْجِبالَ يُسَبِّحْنَ وَالطَّيْرَ وَكُنَّا فاعِلِينَ (79) وَعَلَّمْناهُ صَنْعَةَ لَبُوسٍ لَكُمْ لِتُحْصِنَكُمْ مِنْ بَأْسِكُمْ وبالعكس في القيمي.` },
            { text: "فَفَهَّمْنَٰهَا سُلَيْمَٰنَ وَكُلًّا ءَاتَيْنَا حُكْمًا وَعِلْمًا وَسَخَّرْنَا مَعَ دَاوُۥدَ ٱلْجِبَالَ يُسَبِّحْنَ وَٱلطَّيْرَ وَكُنَّا فَٰعِلِينَ", tafsir: `أي علمنا ( سُلَيْمانَ ) كيفية الحكومة بين الراعي والزارع ( وَكُلًّا ) من داود وسليمان ( آتَيْنا ) أي أعطيناه ( حُكْماً ) في الخصومات ، أو حكما على الناس ( وَعِلْماً ) وكان تخصيص سليمان بقوله ( فَفَهَّمْناها سُلَيْمانَ ) لأن المقصود كان إظهار فضل سليمان ليعرف بنو إسرائيل من وصي داود ، كما في الأحاديث ( وَسَخَّرْنا مَعَ داوُدَ الْجِبالَ ) ومعنى التسخير السير معه في التسبيح ، فإنك إذا عودت طيرا أن يتكلم بما تكلمت به أنت ، يقال أنك سخرت ذلك الطير ، فكأنه صار طوع إرادتك يتكلم إذا تكلمت ويسكت إذا سكت ( يُسَبِّحْنَ ) الجبال معه ، والإتيان بضمير العاقل لأن التسبيح فعل العاقل ( وَالطَّيْرَ ) عطف على الجبال ، أي وسخرنا معه الطير ، فإنها كانت تسبح بتسبيحه. قال الصادق عليه‌السلام : إن داود خرج يقرأ الزبور وكان إذا قرأ الزبور لا يبقى جبل ولا حجر ولا طائر إلا جاوبه ( وَكُنَّا فاعِلِينَ ) لذلك ، وكان المراد بذلك أن هذا الأمر ليس عجيبا من قدرتنا ، وإن كان مستغربا عندكم.` },
            { text: "وَعَلَّمْنَٰهُ صَنْعَةَ لَبُوسٍ لَّكُمْ لِتُحْصِنَكُم مِّنۢ بَأْسِكُمْ فَهَلْ أَنتُمْ شَٰكِرُونَ", tafsir: `أي علمنا داود ( صَنْعَةَ لَبُوسٍ لَكُمْ ) اللبوس هو السلاح الذي يلبس كالدرع ، فإنه عليه‌السلام أول من صنع الدرع ، وقد كان الحديد لينا في يده كالعجين ، يسرد منه الدروع ( لِتُحْصِنَكُمْ ) أي تحفظكم ( مِنْ بَأْسِكُمْ ) من وقع السلاح فيكم ـ كالسيف والرمح ـ في الحرب فَهَلْ أَنْتُمْ شاكِرُونَ (80) وَلِسُلَيْمانَ الرِّيحَ عاصِفَةً تَجْرِي بِأَمْرِهِ إِلى الْأَرْضِ الَّتِي بارَكْنا فِيها وَكُنَّا بِكُلِّ شَيْءٍ عالِمِينَ (81) وَمِنَ الشَّياطِينِ ( فَهَلْ أَنْتُمْ ) أيها الناس ( شاكِرُونَ ) لهذه النعمة التي تقيكم من الأعداء ، فإن الدرع أحسن وقاية للبدن مقابل الآلات الحربية.` },
            { text: "وَلِسُلَيْمَٰنَ ٱلرِّيحَ عَاصِفَةً تَجْرِى بِأَمْرِهِۦٓ إِلَى ٱلْأَرْضِ ٱلَّتِى بَٰرَكْنَا فِيهَا وَكُنَّا بِكُلِّ شَىْءٍ عَٰلِمِينَ", tafsir: `سخرنا ( لِسُلَيْمانَ ) بن داود ( الرِّيحَ عاصِفَةً ) أي شديدة الهبوب ، فإذا أراد أن تعصف الريح عصفت ، وإذا أراد أن ترخي أرخيت ( تَجْرِي ) الريح ( بِأَمْرِهِ ) أي أمر سليمان ( إِلى الْأَرْضِ الَّتِي بارَكْنا فِيها ) وهي الشام ، التي بارك الله فيها بكثرة الأنبياء عليهم‌السلام ، وكثرة الثمار ، وطيب الهواء ، وقد سبق أن المراد بالشام ما يشمل سورية وفلسطين ولبنان والأردن ، فقد كان لسليمان عليه‌السلام بساط يجلس عليه هو وحاشيته فتحمله الريح ويسير بهم من القدس إلى الشام ـ وقد كان السير بينهما يستغرق شهرا على الماشية ـ في نصف يوم ، وكذلك ترجع بهم هذه المسافة في نصف يوم ، كما قال سبحانه في آية أخرى : ( غُدُوُّها شَهْرٌ وَرَواحُها شَهْرٌ ) (1) وحيث أن هذا كان مورد استغراب عقبه سبحانه بهذه الجملة فقال ( وَكُنَّا بِكُلِّ شَيْءٍ عالِمِينَ ) فإنما أعطيناه ما أعطينا لعلمنا بالمصالح وطرف الأمور.` },
            { text: "وَمِنَ ٱلشَّيَٰطِينِ مَن يَغُوصُونَ لَهُۥ وَيَعْمَلُونَ عَمَلًا دُونَ ذَٰلِكَ وَكُنَّا لَهُمْ حَٰفِظِينَ", tafsir: `سخرنا لسليمان ( مِنَ الشَّياطِينِ ) والمراد بالشيطان هنا الجن ، فإنهما مخلوقان أحدهما يضل البشر من نسل إبليس ، والآخر كالإنسان إلا أنه مختف ، والظاهر أنهما في الأصل كانا من جنس واحد ، ولذا ( 1) سبأ : 13. مَنْ يَغُوصُونَ لَهُ وَيَعْمَلُونَ عَمَلاً دُونَ ذلِكَ وَكُنَّا لَهُمْ حافِظِينَ (82) وَأَيُّوبَ إِذْ نادى رَبَّهُ أَنِّي مَسَّنِيَ الضُّرُّ وَأَنْتَ أَرْحَمُ الرَّاحِمِينَ (83) فَاسْت َجَبْنا لَهُ فَكَشَفْنا ما بِهِ قال سبحانه في حق إبليس « كان من الجن » ويسمى كل واحد منهما باسم الآخر « الجن » لكونهما مستترين ، « والشيطان » لكونهما ذوي تدبير وحيلة ، والظرف في موضوع حال من سخرنا ( مَنْ يَغُوصُونَ ) في البحر ، والغوص هو أن ينزل في البحر لأجل إخراج اللؤلؤ وما أشبه ( لَهُ ) أي لسليمان ( وَيَعْمَلُونَ ) له ( عَمَلاً دُونَ ذلِكَ ) أي سوى ذلك ، أو أدون من الغوص ـ من حيث الصعوبة ـ كبناء المحاريب والتماثيل وأشباههما ( وَكُنَّا لَهُمْ حافِظِينَ ) أي نحفظ الشياطين عن الإفساد والهروب ، وسائر ما ينبغي الحفظ منه.` },
            { text: "وَأَيُّوبَ إِذْ نَادَىٰ رَبَّهُۥٓ أَنِّى مَسَّنِىَ ٱلضُّرُّ وَأَنتَ أَرْحَمُ ٱلرَّٰحِمِينَ", tafsir: `اذكر يا رسول الله ( أَيُّوبَ ) حين دعا ربه لما امتدت به المحنة والبلاء ( إِذْ نادى رَبَّهُ ) مستجيرا ليشفيه قائلا في دعائه رب ( أَنِّي مَسَّنِيَ الضُّرُّ ) أي نالني الضر والمرض ( وَأَنْتَ أَرْحَمُ الرَّاحِمِينَ ) أي أكثر رحما من رحم كل راحم ، وهذا تأدب في طلب إزالة البلاء ، فقد ابتلاه الله سبحانه بهلاك أولاده وذهاب أمواله والمرض في بدنه ، كما يأتي قصته في سورة « ص » إن شاء الله تعالى.` },
            { text: "فَٱسْتَجَبْنَا لَهُۥ فَكَشَفْنَا مَا بِهِۦ مِن ضُرٍّ وَءَاتَيْنَٰهُ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةً مِّنْ عِندِنَا وَذِكْرَىٰ لِلْعَٰبِدِينَ", tafsir: `أي أجبنا دعاءه ونداءه ، وكان الإتيان من باب الاستفعال الظاهر في الطلب ، لأجل أمره سبحانه بأن يجاب دعاءه ، بما جعل من العلل الكونية والأسباب التي تترتب عليها مسبباتها ، فكأنه تعالى طلب أن يجاب أيوب ( فَكَشَفْنا ما بِهِ ) أي رفعنا وأزلنا الشيء مِنْ ضُرٍّ وَآتَيْناهُ أَهْلَهُ وَمِثْلَهُمْ مَعَهُمْ رَحْمَةً مِنْ عِنْدِنا وَذِكْرى لِلْعابِدِينَ (84) وَإِسْماعِيلَ وَإِدْرِيسَ وَذَا الْكِفْلِ كُلٌّ مِنَ الصَّابِرِينَ (85) الذي كان بأيوب ( مِنْ ضُرٍّ ) في بدنه وماله وولده ، وكأن الضر ستر يشتمل على الإنسان ، فإذا أزيل ، انكشف ما تحته ( وَآتَيْناهُ ) أي أعطيناه ورددنا إليه ( أَهْلَهُ ) أولاده الذين ماتوا ابتلاء واختبارا ( وَمِثْلَهُمْ مَعَهُمْ ) قال الإمام الصادق عليه‌السلام : إن الله سبحانه رد على أيوب أهله الذين هلكوا وأعطاه مثلهم معهم وكذلك رد الله عليه أمواله ومواشيه بأعيانها وأعطاه مثلها معها ، والله سبحانه قادر على إحياء الأموات ، كما هو قادر على أن يعطي الإنسان أولادا وأموالا (1) . ( رَحْمَةً مِنْ عِنْدِنا ) أي إن كشف ضره وإعطاء ما فقده ، ومثله معه ، كان فضلا ولطفا من لدنا لأيوب ، وكل رحمة منه سبحانه ، إلا أن التخصيص هنا للتشريف ( وَذِكْرى لِلْعابِدِينَ ) أي لأجل أن يكون ذلك موعظة وتذكيرا لمن عبدنا وأنه إذا أخذنا منه شيئا فإنا نرده إليه مع الزائد ، وإن الأخذ لمصلحة وحكمة.` },
            { text: "وَإِسْمَٰعِيلَ وَإِدْرِيسَ وَذَا ٱلْكِفْلِ كُلٌّ مِّنَ ٱلصَّٰبِرِينَ", tafsir: `اذكر يا رسول الله ( إِسْماعِيلَ ) بن إبراهيم عليه‌السلام وحيث لم يذكر هناك ، ذكره هنا مستقلا ( وَإِدْرِيسَ ) وهو أول من خاط اللباس بوحي الله سبحانه ( وَذَا الْكِفْلِ ) و قد روي عن الإمام أمير المؤمنين عليه‌السلام أنه يوشع بن نون ( كُلٌ ) أي كل هؤلاء الأنبياء ( مِنَ الصَّابِرِينَ ) أي من الأنبياء الذين صبروا على مشاق التكليف ، ولم ( 1) الخرائج : ج 2 ص 933. وَأَدْخَلْناهُمْ فِي رَحْمَتِنا إِنَّهُمْ مِنَ الصَّالِحِينَ (86) وَذَا النُّونِ إِذْ ذَهَبَ مُغاضِباً فَظَنَّ أَنْ لَنْ نَقْدِر َ عَلَيْهِ يزيغوا عن أوامره سبحانه.` },
            { text: "وَأَدْخَلْنَٰهُمْ فِى رَحْمَتِنَآ إِنَّهُم مِّنَ ٱلصَّٰلِحِينَ", tafsir: `أدخلنا هؤلاء الأنبياء عليهم‌السلام ( فِي رَحْمَتِنا ) بأن غمرناهم في الرحمة بعد أن كانوا في مشقة وأذى من قومهم ، ومن التكاليف المتوجهة إليهم ( إِنَّهُمْ مِنَ الصَّالِحِينَ ) فقد كانوا صالحين في حياتهم ، ولذا جوزوا بتلك الرحمة التي غمرتهم ، وحيث أن المقصود في سرد صبر الأنبياء أولا ثم فضل الله عليهم جزاء صبرهم ثانيا ، ألمح السياق إلى هاتين الخصوصيتين ، بالنسبة إلى هؤلاء الأنبياء بدون ذكر قصصهم ، كما أن سائر القصص قد أتيت بإيجاز وإشارة.` },
            { text: "وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبًا فَظَنَّ أَن لَّن نَّقْدِرَ عَلَيْهِ فَنَادَىٰ فِى ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبْحَٰنَكَ إِنِّى كُنتُ مِنَ ٱلظَّٰلِمِينَ", tafsir: `اذكر يا رسول الله ( ذَا النُّونِ ) « النون » هو الحوت ، أي صاحب الحوت ، وهو يونس عليه‌السلام ، الذي التقمه الحوت ( إِذْ ذَهَبَ ) أي حين فارق قومه ، وذهب عنهم ( مُغاضِباً ) من غاضب ، بمعنى غضب ، وكأنه أتى من باب المفاعلة للدلالة على كون الغضب من الطرفين أو المراد المغاضب المراغم ، يعني أنه خرج رغما على أنف قومه ، حيث أراد إهلاكهم ( فَظَنَّ أَنْ لَنْ نَقْدِرَ عَلَيْهِ ) أي لن نضيق عليه ، فقد ضاق هو بالدعوة وتكذيب القوم ، فخرج من بين القوم ظانا أن ذلك ليس بترك أولى حتى يجزيه سبحانه بضيق صدره ضيقا في مكانه ، يهون عند ضيق مكانه ضيق صدره بالمكذبين من قومه. وقد يقال : أن خروجه هل كان طاعة لله ، أم عصيانا ؟ فإن كان طاعة فلم ضيق الله عليه ؟ وإن كان عصيانا كان ذلك خلاف ما هو مسلم من عصمة الأنبياء عليهم‌السلام ؟ والجواب : أنه كان ترك أولى ، فقد كان فَنادى فِي الظُّلُماتِ أَنْ لا إِلهَ إِلاَّ أَنْتَ سُبْحانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ (87) من الأولى أن لا يخرج ، ولم يكن عصيانا ، كأكل آدم من الشجرة الذي كان ترك أولى ، وعلى أي حال فقد أرسل الله سبحانه يونس إلى قوم كان عددهم مائة ألف أو يزيدون ولبث فيهم أكثر من ثلاثين سنة ـ كما ورد ـ فلم يؤمن من القوم إلا نفران « روبيل » و « تنوخا » فخرج من القوم داعيا عليهم بالعذاب ، وكان ذلك جائزا في نفسه ، وإن كان الأولى بمقام النبوة أن يستأذن الله سبحانه لذلك ، فوصل إلى شاطئ البحر وركب سفينة كانت تريد الأبحار ـ وفي بعض التفاسير أنه عليه‌السلام أراد أن يذهب إلى قوم آخرين يدعوهم ـ ولما توسطت السفينة البحر ، جاء حوت فاتحا فاه ، بحيث لم تتمكن السفينة من المضي إلا بإطعامه ، فأقرعوا فيما بينهم من يطرحوه للحوت وخرج السهم باسم يونس ، فألقوه في فم الحوت فابتلعه ، لكن الله سبحانه حفظه عن أن يموت وهو قادر على كل شيء (1) ( فَنادى ) يونس ( فِي الظُّلُماتِ ) ظلمة البحر ، وظلمة الليل ، وظلمة بطن الحوت ( أَنْ لا إِلهَ إِلَّا أَنْتَ سُبْحانَكَ ) أي أنزهك تنزيها عن القبيح ، وكأن الإتيان بالتسبيح في هذه المقامات دفعا لتوهم متوهم يظن أن العمل الصادر منه سبحانه ليس كما ينبغي ( إِنِّي كُنْتُ مِنَ الظَّالِمِينَ ) في خروجي من المدينة ودعائي على أهلها ، والظلم هو وضع الشيء في غير موضعه ، وذلك يلائم التحريم ، وترك الأولى ، كما قال موسى عليه‌السلام ( إِنِّي ظَلَمْتُ نَفْسِي ) (2) ( 1) بحار الأنوار : ج 15 ص 126. ( 2) النمل : 45. فَاسْتَجَبْنا لَهُ وَنَجَّيْناهُ مِنَ الْغَمِّ وَكَذلِكَ نُنْجِي الْمُؤْمِنِينَ (88) وَزَكَرِيَّا إِذْ نادى رَبَّهُ رَبِّ لا تَذَرْنِي فَرْداً وَأَنْتَ خَيْرُ الْوارِثِينَ (89) فَاسْتَجَبْنا لَهُ وَوَهَبْنا لَهُ يَحْيى وَأَصْلَحْنا وقوله سبحانه لآدم وحواء : ( فَتَكُونا مِنَ الظَّالِمِينَ ) (1) .` },
            { text: "فَٱسْتَجَبْنَا لَهُۥ وَنَجَّيْنَٰهُ مِنَ ٱلْغَمِّ وَكَذَٰلِكَ نُـۨجِى ٱلْمُؤْمِنِينَ", tafsir: `أي أجبنا دعاءه ، فقد كان ذكره تعريضا بطلب خلاصه ، في أدب ولطف ( وَنَجَّيْناهُ مِنَ الْغَمِ ) الذي أخذ به ، بأن ألقاه الحوت إلى الشاطئ ، بعد أربعين يوما كان في بطنه ( وَكَذلِكَ ) أي كما أنجينا يونس ( نُنْجِي الْمُؤْمِنِينَ ) الذين يدعوننا ويستغفرون لسالف ذنوبهم` },
            { text: "وَزَكَرِيَّآ إِذْ نَادَىٰ رَبَّهُۥ رَبِّ لَا تَذَرْنِى فَرْدًا وَأَنتَ خَيْرُ ٱلْوَٰرِثِينَ", tafsir: `اذكر يا رسول الله ( زَكَرِيَّا ) النبي عليه‌السلام ( إِذْ نادى رَبَّهُ ) أي حين دعا الله سبحانه أن يعطيه الولد ، حيث لم يكن له ولد يخلفه ، فقال يا ( رَبِّ لا تَذَرْنِي ) أي لا تدعني ( فَرْداً ) وحيدا بلا أولاد ، وبدون عقب ( وَأَنْتَ خَيْرُ الْوارِثِينَ ) وقد كان هذا تأدبا من زكريا عليه‌السلام فهو لا يطلب الولد لأنه غير معترف بأن وارثة الله خير وراثة ، كما يظن بعض الناس أنهم إذا ماتوا بلا عقب لا أحد في الكون يرعى شؤونهم الدنيوية أو الدينية وإنما يطلب بعد الاعتراف لما يعرف من جريان العادة الكونية على أن الولد والعقب هو السبب العادي الذي جعله الله سبحانه للخلافة والقيام مقام الآباء في إدارة شؤونهم.` },
            { text: "فَٱسْتَجَبْنَا لَهُۥ وَوَهَبْنَا لَهُۥ يَحْيَىٰ وَأَصْلَحْنَا لَهُۥ زَوْجَهُۥٓ إِنَّهُمْ كَانُوا۟ يُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَيَدْعُونَنَا رَغَبًا وَرَهَبًا وَكَانُوا۟ لَنَا خَٰشِعِينَ", tafsir: `دعاءه ( وَوَهَبْنا لَهُ يَحْيى ) ليخلفه من بعده ( وَأَصْلَحْنا ( 1) البقرة : 36. لَهُ زَوْجَهُ إِنَّهُمْ كانُوا يُسارِعُونَ فِي الْخَيْراتِ وَيَدْعُونَنا رَغَباً وَرَهَباً وَكانُوا لَنا خاشِعِينَ (90) وَالَّتِي أَحْصَنَتْ فَرْجَها فَنَفَخْنا فِيها مِنْ رُوحِنا وَجَعَلْناها وَابْنَها آيَةً لِلْعالَمِينَ (91) لَهُ زَوْجَهُ ) إذ كانت عقيمة لا تلد وكان الإتيان ب « وهبنا » قبل « أصلحنا » مع أنه بعده خارجا ، لبيان المبادرة في استجابة دعائه عليه‌السلام ، كأنه لا فصل بين الدعاء والهبة ( إِنَّهُمْ ) أي زكريا وزوجه ويحيى ـ كما هو ظاهر السياق ـ ( كانُوا يُسارِعُونَ فِي الْخَيْراتِ ) في الأعمال الخيرية ، مقابل الذين يتلكئون ويتباطئون في عمل الخير ، وهكذا دائما أهل الآخرة إنهم يبادرون في الطاعة ، بخلاف أهل الدنيا ( وَيَدْعُونَنا رَغَباً وَرَهَباً ) راغبين في ثوابنا وخائفين من عقابنا ، وهكذا الإنسان الكامل ، إنه بين الخوف والرجاء ( وَكانُوا لَنا خاشِعِينَ ) خاضعين متواضعين لا كأهل الدنيا الذين يطغون ويستعلون عن الأوامر والزواجر. [92] وبمناسبة ذكر « زكريا » ذكر السياق « مريم » الطاهرة القريبة له ( وَ ) اذكر يا رسول الله المرأة ( الَّتِي أَحْصَنَتْ فَرْجَها ) أي حفظت نفسها عن الفساد ، وهذا لرد اليهود الذين قالوا فيهما شرا ( فَنَفَخْنا فِيها مِنْ رُوحِنا ) النافخ كان جبرائيل لكنه حيث كان بأمر الله تعالى ، نسب النفخ إليه تعالى ، والروح أضيف إليه سبحانه تشريفا ، كإضافة البيت إليه ، وقد كان النفخ في جيب ثوبها ، وتكوّن من ذلك النفخ المسيح عليه‌السلام ( وَجَعَلْناها ) أي جعلنا مريم ( وَابْنَها ) المسيح ( آيَةً لِلْعالَمِينَ ) أي : دلالة على وجود الله وقدرته ، والمراد ب « آية » الجنس ، إِنَّ هذِهِ أُمَّتُكُمْ أُمَّةً واحِدَةً وَأَنَا رَبُّكُمْ فَاعْبُدُونِ (92) وَتَقَطَّعُوا أَمْرَهُمْ بَيْنَهُمْ كُلٌّ إِلَيْنا راجِعُونَ (93) فَمَنْ يَعْمَلْ مِنَ الصَّالِحاتِ وَهُوَ مُؤْمِنٌ فَلا فلا يقال : أنهما آيتان ؟ [93] وبعد استعراض أحوال بعض الأنبياء عليهم‌السلام مع أممهم ـ إجمالا ـ يأتي السياق ليدل على وحدة العقيدة ، ووحدة الأمة ، ووحدة الإله ، ووحدة رسالة الأنبياء عليهم‌السلام ( إِنَّ هذِهِ ) البشر المتناثر في الأرض المتباعد في الزمان ( أُمَّتُكُمْ ) أيها الأنبياء ( أُمَّةً واحِدَةً ) فلا أمم تحت لواء الأنبياء وإنما أمة واحدة ، ومن خالف وآمن ببعض وكفر ببعض أو قبل حكما وأعرض عن حكم فليس من الأمة ، وليس خاضعا حتى لتنبيه الذي يزعم أنه متبع له ( وَأَنَا رَبُّكُمْ ) رب واحد ( فَاعْبُدُونِ ) أي أطيعوني واتخذوني إلها دون غيري. [94] لكن المنحرفون لم يكونوا من أنفسهم أمة واحدة ، بل خالفوا وتفرقوا ( وَتَقَطَّعُوا أَمْرَهُمْ بَيْنَهُمْ ) أي فرقوا دينهم فيما بينهم ، فإن قطّع وتقطع بمعنى واحد ، وهل انتهى الأمر عند ذلك فلا حساب ولا جزاء لما اقترفوه من تقطيع الأمة الواحدة إلى ألوان وأشكال وأمم ؟ كلا ! ( كُلٌّ إِلَيْنا راجِعُونَ ) فنجازيهم بما فعلوا من التقطيع والتفرقة ، ومعنى الرجوع إلى الله سبحانه الرجوع إلى حسابه وجزائه ، تشبيه بمن يرجع إلى المحكمة بعد الذهاب عنها.` },
            { text: "وَٱلَّتِىٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهَا مِن رُّوحِنَا وَجَعَلْنَٰهَا وَٱبْنَهَآ ءَايَةً لِّلْعَٰلَمِينَ", tafsir: `` },
            { text: "إِنَّ هَٰذِهِۦٓ أُمَّتُكُمْ أُمَّةً وَٰحِدَةً وَأَنَا۠ رَبُّكُمْ فَٱعْبُدُونِ", tafsir: `` },
            { text: "وَتَقَطَّعُوٓا۟ أَمْرَهُم بَيْنَهُمْ كُلٌّ إِلَيْنَا رَٰجِعُونَ", tafsir: `` },
            { text: "فَمَن يَعْمَلْ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤْمِنٌ فَلَا كُفْرَانَ لِسَعْيِهِۦ وَإِنَّا لَهُۥ كَٰتِبُونَ", tafsir: `الأعمال ( الصَّالِحاتِ ) أي من هذه الجنس ، دون جنس السيئات ( وَهُوَ مُؤْمِنٌ ) صحيح العقيدة ( فَلا كُفْرانَ لِسَعْيِهِ وَإِنَّا لَهُ كاتِبُونَ (94) وَحَرامٌ عَلى قَرْيَةٍ أَهْلَكْناها أَنَّهُمْ لا يَرْجِعُونَ (95) حَتَّى إِذا فُتِحَتْ يَأْجُوجُ وَمَأْجُوجُ وَهُمْ مِنْ كُلِّ حَدَبٍ يَنْسِلُونَ (96) كُفْرانَ لِسَعْيِهِ ) فلا يستر ما عمله ولا يبطل ، بل يشكر ويثاب عليه ( وَإِنَّا لَهُ ) أي لسعيه ( كاتِبُونَ ) والمعنى نأمر الملائكة أن يثبت سعيه لنجازيه عليه في الآخرة. [96] أما من كفر وعصى ، فأهلكناه في الدنيا بعذاب الاستئصال فلا يظن أحد أنه قد انتهى أمرهم ، وأنهم أهلكوا فلا حساب بعد ذلك ( وَحَرامٌ ) أي ممتنع ، في الحكمة ( عَلى قَرْيَةٍ أَهْلَكْناها ) بذنوبها ( أَنَّهُمْ ) إلينا ( لا يَرْجِعُونَ ) فإن عذابهم في الدنيا لم يكن نهاية أمرهم ، بل يرجعون إلينا في الآخرة لنحاسبهم هناك على أعمالهم ونجزيهم بالنار ، ف « حرام » مبتدأ ، خبره « أنهم » أي ممتنع عدم رجوعهم ، وقد عرفت أن تخصيصهم بالذكر دون سائر العاصين ، لدفع التوهم المذكور. [97] إن الأمر يبقى على هذا المنوال ، مؤمن وكافر ، وموت وهلاك ( حَتَّى ) يوم القيامة فينقطع التكليف وتقوم الساعة للحساب والجزاء ، وقد ذكر الله سبحانه علامة لذلك بقوله : ( إِذا فُتِحَتْ يَأْجُوجُ وَمَأْجُوجُ ) أي القبيلتان ، وفتحت باعتبار كسر سدهما الذي بناه ذو القرنين ، كما تقدم ( وَهُمْ مِنْ كُلِّ حَدَبٍ ) أي مرتفع من الأرض كالجبال والآكام ( يَنْسِلُونَ ) يسرعون في السير نحو الصحاري والبلاد للفساد والدمار. وَاقْتَرَبَ الْوَعْدُ الْحَقُّ فَإِذا هِيَ شاخِصَةٌ أَبْصارُ الَّذِينَ كَفَرُوا يا وَيْلَنا قَدْ كُنَّا فِي غَفْلَةٍ مِنْ هذا بَلْ كُنَّا ظالِمِينَ (97) إِنَّكُمْ وَما تَعْبُدُونَ مِنْ دُونِ اللهِ حَصَبُ جَهَنَّمَ` },
            { text: "وَحَرَٰمٌ عَلَىٰ قَرْيَةٍ أَهْلَكْنَٰهَآ أَنَّهُمْ لَا يَرْجِعُونَ", tafsir: `` },
            { text: "حَتَّىٰٓ إِذَا فُتِحَتْ يَأْجُوجُ وَمَأْجُوجُ وَهُم مِّن كُلِّ حَدَبٍ يَنسِلُونَ", tafsir: `` },
            { text: "وَٱقْتَرَبَ ٱلْوَعْدُ ٱلْحَقُّ فَإِذَا هِىَ شَٰخِصَةٌ أَبْصَٰرُ ٱلَّذِينَ كَفَرُوا۟ يَٰوَيْلَنَا قَدْ كُنَّا فِى غَفْلَةٍ مِّنْ هَٰذَا بَلْ كُنَّا ظَٰلِمِينَ", tafsir: `أي الموعود الذي هو حق ، لا خلف ولا كذب فيه ، وهو يوم القيامة ( فَإِذا هِيَ ) الضمير للشأن والقصة ، يؤتى بها للتهيؤ ، وليستعد السامع لاستماع ما يأتي بعده ( شاخِصَةٌ أَبْصارُ الَّذِينَ كَفَرُوا ) الشاخصة العين التي لا تطرف من شدة الهول ، ولا تسكن ، كالإنسان الشاخص الذي يسير بدون سكون وهدوء ، فإن الكفار في يوم القيامة تشخص أبصارهم من شدة الهول ، ينظرون هنا وهناك ليجدوا ملجأ أو شفيعا ينجيهم من الأهوال والكربات ، وقوله « فإذا » يتعلق ب « حتى » ومعنى « فإذا هي » أن القصة شخوص أبصار الكفار ، قائلين ( يا وَيْلَنا ) يا قوم ويلنا ، أي يا ويلنا أحضر فهذا وقتك ، والويل هو الهلاك والعذاب ( قَدْ كُنَّا فِي غَفْلَةٍ مِنْ هذا ) اليوم ، فقد كنا في الدنيا لا نأبه ولا نعتني بهذا اليوم وبما ينجي الإنسان من أهواله ( بَلْ ) لم تكن غفلة ، وإنما ( كُنَّا ظالِمِينَ ) لأنفسنا حيث نعرض عن الإيمان والعمل الصالح. [99] وما مصيرهم هناك ؟ ( إِنَّكُمْ ) أيها الكفار ( وَما تَعْبُدُونَ مِنْ دُونِ اللهِ ) أي الأصنام التي تجعلونها آلهة تعبدونها ( حَصَبُ جَهَنَّمَ ) أي حطبها ووقودها ، والحصب كل حجر يرمى به ، ولذا قيل للأحجار الصغيرة حصباء ، و « ما » لما لا يعقل ، فلا يشمل من عبده الناس من الأنبياء أَنْتُمْ لَها وارِدُونَ (98) لَوْ كانَ هؤُلاءِ آلِهَةً ما وَرَدُوها وَكُلٌّ فِيها خالِدُونَ (99) لَهُمْ فِيها زَفِيرٌ وَهُمْ فِيها لا يَسْمَعُونَ (100) إِنَّ الَّذِينَ سَبَقَتْ لَهُمْ مِنَّا الْحُسْنى أُولئِكَ عَنْها مُبْعَدُونَ (101) لا يَسْمَعُونَ حَسِيسَها وَهُمْ فِي مَا والأئمة والملائكة ، وإنما تكون الآلهة حصب جهنم مع أنها لا ذنب لها ، إهانة لعبادها وإذلالهم ( أَنْتُمْ ) أيها الكفار ( لَها ) أي لجهنم ( وارِدُونَ ) داخلون ، وذلك جزاؤكم.` },
            { text: "إِنَّكُمْ وَمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ حَصَبُ جَهَنَّمَ أَنتُمْ لَهَا وَٰرِدُونَ", tafsir: `` },
            { text: "لَوْ كَانَ هَٰٓؤُلَآءِ ءَالِهَةً مَّا وَرَدُوهَا وَكُلٌّ فِيهَا خَٰلِدُونَ", tafsir: `الأصنام ( آلِهَةً ) كما تزعمون ( ما وَرَدُوها ) ما دخلوا النار ولامتنعوا منها ( وَكُلٌ ) من العابد والمعبود ( فِيها ) أي في جهنم ( خالِدُونَ ) باقون أبد الآبدين.` },
            { text: "لَهُمْ فِيهَا زَفِيرٌ وَهُمْ فِيهَا لَا يَسْمَعُونَ", tafsir: `أي للناس الذين خلدوا ( فِيها ) لكفرهم وعصيانهم ( زَفِيرٌ ) أي صوت كصوت الحمار وهو التنفس العالي المصاحب للألم والحزن ( وَهُمْ فِيها لا يَسْمَعُونَ ) فهم صمّ ، مقابل ما كانوا في الدنيا يصمون عن الحق ، ويقولون للمرسلين : في آذاننا وقر. [102] رأينا حال الكفار في النار ، فلننظر إلى المؤمنين في الجنة ( إِنَّ الَّذِينَ سَبَقَتْ لَهُمْ مِنَّا ) الكلمة ( الْحُسْنى ) بأن قلنا إن المؤمن لا يعاقب ، بل يثاب ، نفي لهم بما وعدناه ( أُولئِكَ عَنْها ) أي عن جهنم ( مُبْعَدُونَ ) يبعدهم الله سبحانه عنها ، حتى لا يرون منظر العذاب ، ولا يستمعون لزفيرها ، ولا يحسون بحرارتها.` },
            { text: "إِنَّ ٱلَّذِينَ سَبَقَتْ لَهُم مِّنَّا ٱلْحُسْنَىٰٓ أُو۟لَٰٓئِكَ عَنْهَا مُبْعَدُونَ", tafsir: `` },
            { text: "لَا يَسْمَعُونَ حَسِيسَهَا وَهُمْ فِى مَا ٱشْتَهَتْ أَنفُسُهُمْ خَٰلِدُونَ", tafsir: `أي صوتها الذي يحس به ( وَهُمْ فِي مَا اشْتَهَتْ أَنْفُسُهُمْ خالِدُونَ (102) لا يَحْزُنُهُمُ الْفَزَعُ الْأَكْبَرُ وَتَتَلَقَّاهُمُ الْمَلائِكَةُ هذا يَوْمُكُمُ الَّذِي كُنْتُمْ تُوعَدُونَ (103) يَوْمَ نَطْوِي السَّماءَ كَطَيِّ السِّجِلِّ لِلْكُتُبِ كَما بَ دَأْنا أَوَّلَ خَلْقٍ نُعِيدُهُ اشْتَهَتْ أَنْفُسُهُمْ ) من الملذات والنعيم ( خالِدُونَ ) دائمون فلا زوال لهم عن الجنة ونعيمها ، في مقابل أهل النار الذين لا زوال لهم عن الجحيم والعذاب.` },
            { text: "لَا يَحْزُنُهُمُ ٱلْفَزَعُ ٱلْأَكْبَرُ وَتَتَلَقَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ هَٰذَا يَوْمُكُمُ ٱلَّذِى كُنتُمْ تُوعَدُونَ", tafsir: `أي الخوف الأعظم ، وهو فزع يوم القيامة المتصل بالدخول في النار ، الباقي إلى الأبد ( وَتَتَلَقَّاهُمُ الْمَلائِكَةُ ) أي تستقبلهم بالتهنئة والبشر ، قائلين لهم ( هذا يَوْمُكُمُ الَّذِي كُنْتُمْ تُوعَدُونَ ) في الدنيا ، فأبشروا بالأمن والفوز وما أحوج الإنسان هناك أن يتلقاه شخص يهديه السبيل ويرشده الطريق ، في يوم الأهوال والأحزان ، في ساحة يجتمع فيها الخلق كلهم ، في مدة تطول خمسين ألف سنة ، ووراءها إما عذاب دائم أو نعيم مقيم !.` },
            { text: "يَوْمَ نَطْوِى ٱلسَّمَآءَ كَطَىِّ ٱلسِّجِلِّ لِلْكُتُبِ كَمَا بَدَأْنَآ أَوَّلَ خَلْقٍ نُّعِيدُهُۥ وَعْدًا عَلَيْنَآ إِنَّا كُنَّا فَٰعِلِينَ", tafsir: `منصوب على الظرفية ، أي أن ذلك النعيم ، وتلك الأهوال ، إنما هي في يوم ( نَطْوِي السَّماءَ ) فيه ، ومعنى طي السماء ، محوها ، وتبديلها دخانا ( كَطَيِّ السِّجِلِّ لِلْكُتُبِ ) السجل ما يسجل فيه ، وهو قد يكون سجلا للكتاب وقد يكون سجلا في قصاص ورق ، والسجل الذي يطوى هو سجل الكتاب ، وفي بعض الروايات ، أن السجل اسم ملك يطوي صحف أعمال بني آدم ، فالتشبيه إنما هو به ، وفي ذلك اليوم ( كَما بَدَأْنا أَوَّلَ خَلْقٍ نُعِيدُهُ ) أي كما تمكنا على الابتداء نتمكن وَعْداً عَلَيْنا إِنَّا كُنَّا فاعِلِينَ (104) وَلَقَدْ كَتَبْنا فِي الزَّبُورِ مِنْ بَعْدِ الذِّكْرِ أَنَّ الْأَرْضَ يَرِثُها عِبادِيَ الصَّالِحُونَ (105) على الإعادة أو في الشكل الذي خلقنا من كون الإنسان حاف عاري غير مختون كذلك تكون الإعادة ، فالمراد بأول خلق « الخلق أولا » على التقديرين ، لا أول الخلق ـ وهو آدم عليه‌السلام ـ كما هو ظاهر ، نعدكم ذلك ( وَعْداً ) مصدر تأكيدي ( عَلَيْنا ) إنجازه وإنفاذه ( إِنَّا كُنَّا فاعِلِينَ ) إنا فاعلون لهذا الوعد ، وكان لمجرد الربط ، لا بمعنى الماضي. [106] وحيث رأينا إن العاقبة الحسنى في الآخرة لعباد الله الصالحين ، فلنرجع إلى الأرض لنرى إن الأرض لمن ؟ ( وَلَقَدْ كَتَبْنا فِي الزَّبُورِ مِنْ بَعْدِ الذِّكْرِ ) إما المراد « زبور » داود والمراد بالذكر حينئذ « التوراة » لأنها كانت قبل الزبور ، وإما المراد بالزبور الصحف المنزلة على الأنبياء ، فإنها من زبر بمعنى كتب ، والمراد بالذكر ، التذكير بالمبدأ والمعاد والمعارف ، وعلى أي حال فالآية في صدد بيان أن سنة الله جرت على ذلك ، وقد كتبها في الكتب السابقة ( أَنَّ الْأَرْضَ يَرِثُها عِبادِيَ الصَّالِحُونَ ) فإن الأرض في آخر المطاف للصالحين ، وإن سبق تملكها الفاسدون ، وقد وردت أحاديث متواترة في تفسير الآية بالإمام الحجة المهدي عليه‌السلام ، وذلك من باب أظهر المصاديق فإنه عليه‌السلام يرث الأرض كلها وإن كان الأنبياء والأئمة والصالحون ورثوا الأرض قبل ، إلى هذا الحين ، فكلما قام باطل ، قام حقه في عقبه ليرث الأرض منه والسر واضح فإن غير الصالح لا يملك إلا شقا واحدا ، والحياة لا تسير بشق واحد ، أما الصالح الذي يجمع بين المادة والمعنى ، والإيمان والنشاط إِنَّ فِي هذا لَبَلاغاً لِقَوْمٍ عابِدِينَ (106) وَما أَرْسَلْناكَ إِلاَّ رَحْمَةً لِلْعالَمِينَ (107) قُلْ إِنَّما يُوحى إِلَيَّ أَنَّما إِلهُكُمْ إِلهٌ واحِدٌ فَهَلْ أَنْتُمْ مُسْلِمُونَ (108) فإنه أصلح من الفاسد ، ولذا تزحزح الحياة الفاسد ـ وإن طال أمده ـ لتخلف الصالح مكانه ، ليكون السير عدلا متوازنا.` },
            { text: "وَلَقَدْ كَتَبْنَا فِى ٱلزَّبُورِ مِنۢ بَعْدِ ٱلذِّكْرِ أَنَّ ٱلْأَرْضَ يَرِثُهَا عِبَادِىَ ٱلصَّٰلِحُونَ", tafsir: `` },
            { text: "إِنَّ فِى هَٰذَا لَبَلَٰغًا لِّقَوْمٍ عَٰبِدِينَ", tafsir: `الذي أخبرتكم به من أن العاقبة في الدنيا والآخرة لعباد الله الصالحين ( لَبَلاغاً ) أي كفاية في البلوغ إلى القصد وهو الحق ( لِقَوْمٍ عابِدِينَ ) لله مخلصين في عبادتهم ، وإنما خص هؤلاء ، لأنهم الذين ينتفعون بالبلاغ. [108] وإنا لم نكن خصصنا أمة بالبلاغ وإنما البلاغ عام ، أما المنتفع به فهو من ألقى السمع وهو شهيد ( وَما أَرْسَلْناكَ ) يا رسول الله ( إِلَّا رَحْمَةً لِلْعالَمِينَ ) نعمة عليهم جميعا ، أما المؤمن فواضح كونه صلى‌الله‌عليه‌وآله‌وسلم رحمة بالنسبة إليه ، وأما الكافر ، فلأن الرسول صلى‌الله‌عليه‌وآله‌وسلم نظم سبل الحياة وأرشد إليها فاقتبس منه الكفار وما نرى اليوم من الحضارة والتمدن في العالم فليس إلا من هدى الرسول صلى‌الله‌عليه‌وآله‌وسلم ، وما نرى فيه من الانحراف والزيغ فذلك من تحريف مناهج الرسول ، فإن حضارة الشرق الروسي مأخوذة من حضارة الغرب ، وحضارة الغرب وليدة الحضارة الإسلامية ، حيث دخل العلم بلاد الغرب من بلاد الإسلام. [109] وقد بين سبحانه علة كون الرسول صلى‌الله‌عليه‌وآله‌وسلم رحمة ، أنه يبشر بوحدة الإله ، فإن الإذعان بذلك رأس الفضائل ، وسبب أنواع الرحمة ( قُلْ ) يا رسول الله لهؤلاء القوم ( إِنَّما يُوحى إِلَيَ ) من عالم الغيب ( أَنَّما إِلهُكُمْ ) أيها البشر ( إِلهٌ واحِدٌ ) لا شريك له ( فَهَلْ أَنْتُمْ مُسْلِمُونَ ) ؟ فَإِنْ تَوَلَّوْا فَقُلْ آذَنْتُكُمْ عَلى سَواءٍ وَإِنْ أَدْرِي أَ قَرِيبٌ أَمْ بَعِيدٌ ما تُوعَدُونَ (109) إِنَّهُ يَعْلَمُ الْجَهْرَ مِنَ الْقَوْلِ وَيَعْلَمُ ما تَكْتُمُونَ (110) وَإِنْ أَدْرِي لَعَلَّهُ فِتْنَةٌ لَكُمْ وَمَتاعٌ إِلى حِينٍ (111) استفهام تقريري ، أي مستسلمون منقادون لذلك ، فتتركوا عبادة الأصنام إلى عبادة الله الواحد الذي لا شريك له.` },
            { text: "وَمَآ أَرْسَلْنَٰكَ إِلَّا رَحْمَةً لِّلْعَٰلَمِينَ", tafsir: `` },
            { text: "قُلْ إِنَّمَا يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَهَلْ أَنتُم مُّسْلِمُونَ", tafsir: `` },
            { text: "فَإِن تَوَلَّوْا۟ فَقُلْ ءَاذَنتُكُمْ عَلَىٰ سَوَآءٍ وَإِنْ أَدْرِىٓ أَقَرِيبٌ أَم بَعِيدٌ مَّا تُوعَدُونَ", tafsir: `بأن أعرضوا ولم يقبلوا الإسلام ( فَقُلْ ) يا رسول الله ( آذَنْتُكُمْ ) أعلمتكم بالتوحيد ـ وليس وظيفتي إلا الاعلام وقد فعلت ـ ( عَلى سَواءٍ ) بدون ترجيح ، فإن الإعلان عام للجميع ، وقد أديت ما علي ، وبقي ما عليكم ، فإن لم تؤمنوا كان مصيركم الهلاك ، أما وقت هلاككم ، فعلمه عند الله سبحانه ( وَإِنْ أَدْرِي ) أي ما أدري ( أَ قَرِيبٌ أَمْ بَعِيدٌ ما تُوعَدُونَ ) من العذاب والنكال ؟ فإن علم ذلك خاص به سبحانه. [111] ولا يظنن أحد أن الله لا يعلم ما يعمل حتى يفكر الكفار ، بأنهم ينكرون ـ غدا ـ ما صدر منهم ( إِنَّهُ ) تعالى ( يَعْلَمُ الْجَهْرَ مِنَ الْقَوْلِ ) أي الكلام الظاهر ( وَيَعْلَمُ ما تَكْتُمُونَ ) أي يعلم سركم ، كما يعلم جهركم ، وسوف يجازيكم على الجميع. [112] أما تأخير العذاب فلحكمة اقتضته ( وَإِنْ أَدْرِي ) ما أدري ( لَعَلَّهُ ) لعل تأخير العذاب ( فِتْنَةٌ ) وامتحان ( لَكُمْ ) حتى تظهر نوايا كل أحد جلية ، فإن الإنسان كلما بقي ظهرت نواياه أكثر فأكثر ( وَمَتاعٌ ) لأجل تمتعكم بمتاع الحياة ( إِلى حِينٍ ) أجلكم المقرر ، فليس الإنعام إكراما ، قالَ رَبِّ احْكُمْ بِالْحَقِّ وَرَبُّنَا الرَّحْمنُ الْمُسْتَعانُ عَلى ما تَصِفُونَ (112) بل استدراجا. [113] وأخيرا ، بعد إبلاغ الرسول ، وبقاء بعض الكفار في غيهم ( قالَ ) رسول الله ، يا ( رَبِّ احْكُمْ ) بيني وبين الكفار ( بِالْحَقِ ) وهذا لإظهار إن حكم الله حق فالقيد للتوضيح والتنبيه ، لا للاحتراز ( وَرَبُّنَا الرَّحْمنُ ) الذي يرحمنا ويتفضل علينا جزاء ما تعبنا وأبلغنا ، فلم يذهب البلاغ والأتعاب سدى ( الْمُسْتَعانُ ) نستعين به على كيدكم وتكذيبكم ( عَلى ما تَصِفُونَ ) الرسول به من أنه كاذب ومفتر وساحر وشاعر ومجنون وما إلى ذلك ، فإنه تعالى لا يترك الرسول ، ليكيدوا له ما شاءوا ، بل يأخذ بيده ويعينه على أمره. (22)` },
            { text: "إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ مِنَ ٱلْقَوْلِ وَيَعْلَمُ مَا تَكْتُمُونَ", tafsir: `` },
            { text: "وَإِنْ أَدْرِى لَعَلَّهُۥ فِتْنَةٌ لَّكُمْ وَمَتَٰعٌ إِلَىٰ حِينٍ", tafsir: `` },
            { text: "قَٰلَ رَبِّ ٱحْكُم بِٱلْحَقِّ وَرَبُّنَا ٱلرَّحْمَٰنُ ٱلْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ", tafsir: `` }
        ]
    }
});
